 1      public override void OnActionFailure(CircuitState currentState, out bool shouldBreak)
 2      {
 3          switch (currentState)
 4          {
 5              case CircuitState.Closed:
 6                  _metrics.IncrementFailure();
 7                  var info = _metrics.GetHealthInfo();
 8                  shouldBreak = info.Throughput >= _minimumThroughput && info.FailureRate >= _failureRatio;
 9                  break;
10  
11              case CircuitState.Open:
12              case CircuitState.Isolated:
13                  // A failure call result may arrive when the circuit is open, if it was placed before the circuit broke.
14                  // We take no action beyond tracking the metric
15                  // We do not want to duplicate-signal onBreak
16                  // We do not want to extend time for which the circuit is broken.
17                  // We do not want to mask the fact that the call executed (as replacing its result with a Broken/IsolatedCircuitException would do).
18                  _metrics.IncrementFailure();
19                  shouldBreak = false;
20                  break;
21              default:
22                  shouldBreak = false;
23                  break;
24          }
25      }

