 2      internal static async Task<TResult> ImplementationAsync<TResult>(
 3          Func<Context, CancellationToken, Task<TResult>> action,
 4          Context context,
 5          ExceptionPredicates shouldHandleExceptionPredicates,
 6          ResultPredicates<TResult> shouldHandleResultPredicates,
 7          Func<DelegateResult<TResult>, Context, Task> onFallbackAsync,
 8          Func<DelegateResult<TResult>, Context, CancellationToken, Task<TResult>> fallbackAction,
 9          bool continueOnCapturedContext,
10          CancellationToken cancellationToken)
11      {
12          DelegateResult<TResult> delegateOutcome;
13  
14          try
15          {
16              cancellationToken.ThrowIfCancellationRequested();
17  
18              TResult result = await action(context, cancellationToken).ConfigureAwait(continueOnCapturedContext);
19  
20              if (!shouldHandleResultPredicates.AnyMatch(result))
21              {
22                  return result;
23              }
24  
25              delegateOutcome = new DelegateResult<TResult>(result);
26          }
27          catch (Exception ex)
28          {
29              Exception handledException = shouldHandleExceptionPredicates.FirstMatchOrDefault(ex);
30              if (handledException == null)
31              {
32                  throw;
33              }
34  
35              delegateOutcome = new DelegateResult<TResult>(handledException);
36          }
37  
38          await onFallbackAsync(delegateOutcome, context).ConfigureAwait(continueOnCapturedContext);
39  
40          return await fallbackAction(delegateOutcome, context, cancellationToken).ConfigureAwait(continueOnCapturedContext);
41      }

