 1      public static RateLimitPolicy RateLimit(
 2          int numberOfExecutions,
 3          TimeSpan perTimeSpan,
 4          int maxBurst)
 5      {
 6          if (numberOfExecutions < 1)
 7          {
 8              throw new ArgumentOutOfRangeException(nameof(numberOfExecutions), numberOfExecutions, $"{nameof(numberOfExecutions)} per timespan must be an integer greater than or equal to 1.");
 9          }
10  
11          if (perTimeSpan <= TimeSpan.Zero)
12          {
13              throw new ArgumentOutOfRangeException(nameof(perTimeSpan), perTimeSpan, $"{nameof(perTimeSpan)} must be a positive timespan.");
14          }
15  
16          if (maxBurst < 1)
17          {
18              throw new ArgumentOutOfRangeException(nameof(maxBurst), maxBurst, $"{nameof(maxBurst)} must be an integer greater than or equal to 1.");
19          }
20  
21          var onePer = TimeSpan.FromTicks(perTimeSpan.Ticks / numberOfExecutions);
22  
23          if (onePer <= TimeSpan.Zero)
24          {
25              throw new ArgumentOutOfRangeException(nameof(perTimeSpan), perTimeSpan, "The number of executions per timespan must be positive.");
26          }
27  
28          IRateLimiter rateLimiter = new LockFreeTokenBucketRateLimiter(onePer, maxBurst);
29  
30          return new RateLimitPolicy(rateLimiter);
31      }

