10  
11          if (GetArgs<TArgs, PipelineExecutingArguments>(args.Arguments, out _))
12          {
13              _logger.PipelineExecuting(
14                  level,
15                  pipelineName,
16                  pipelineInstanceName,
17                  operationKey);
18          }
19          else if (GetArgs<TArgs, PipelineExecutedArguments>(args.Arguments, out var pipelineExecuted))
20          {
21              _logger.PipelineExecuted(
22                  level,
23                  pipelineName,
24                  pipelineInstanceName,
25                  operationKey,
26                  result,
27                  pipelineExecuted.Duration.TotalMilliseconds,
28                  exception);
29          }
30          else if (GetArgs<TArgs, ExecutionAttemptArguments>(args.Arguments, out var executionAttempt))
31          {
32              _logger.ExecutionAttempt(
33                  level,
34                  pipelineName,
35                  pipelineInstanceName,
36                  strategyName,
37                  operationKey,
38                  result,
39                  executionAttempt.Handled,
40                  executionAttempt.AttemptNumber,
41                  executionAttempt.Duration.TotalMilliseconds,
42                  exception);
43          }
44          else
45          {
46              _logger.ResilienceEvent(
47                  level,
48                  args.Event.EventName,
49                  pipelineName,
50                  pipelineInstanceName,
51                  strategyName,
52                  operationKey,
53                  result,
