 1      public async ValueTask<TaskExecution<T>?> TryWaitForCompletedExecutionAsync(TimeSpan hedgingDelay)
 2      {
 3          // before doing anything expensive, let's check whether any existing task is already completed
 4          if (TryRemoveExecutedTask() is TaskExecution<T> execution)
 5          {
 6              return execution;
 7          }
 8  
 9          if (LoadedTasks == _maxAttempts)
10          {
11              await WaitForTaskCompetitionAsync().ConfigureAwait(ContinueOnCapturedContext);
12              var task = TryRemoveExecutedTask();
13              Debug.Assert(task != null, "There must be a completed task after awaiting for an executing task");
14              return task;
15          }
16  
17          if (hedgingDelay == TimeSpan.Zero || LoadedTasks == 0)
18          {
19              // just load the next task
20              return null;
21          }
22  
23          // Stryker disable once equality : no means to test this, stryker changes '<' to '<=' where 0 is already covered in the branch above
24          if (hedgingDelay < TimeSpan.Zero)
25          {
26              await WaitForTaskCompetitionAsync().ConfigureAwait(ContinueOnCapturedContext);
27              var task = TryRemoveExecutedTask();
28              Debug.Assert(task != null, "There must be a completed task after awaiting for an executing task");
29              return task;
30          }
31  
32  #if NET8_0_OR_GREATER
33          var whenAnyHedgedTask = WaitForTaskCompetitionAsync();
34          await whenAnyHedgedTask.WaitAsync(hedgingDelay, _timeProvider, PrimaryContext!.CancellationToken)
35              .ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing | (ContinueOnCapturedContext ? ConfigureAwaitOptions.ContinueOnCapturedContext : 0));
36  
37          if (!whenAnyHedgedTask.IsCompleted)
38          {
39              return null;
40          }
41  #else
42          using var delayTaskCancellation = CancellationTokenSource.CreateLinkedTokenSource(PrimaryContext!.CancellationToken);
43          var delayTask = _timeProvider.Delay(hedgingDelay, delayTaskCancellation.Token);
44          var whenAnyHedgedTask = WaitForTaskCompetitionAsync();
45          var completedTask = await Task.WhenAny(whenAnyHedgedTask, delayTask).ConfigureAwait(ContinueOnCapturedContext);
46  
47          if (completedTask == delayTask)
48          {
49              return null;
50          }
51  
52          delayTaskCancellation.Cancel();
53  #endif
54  
55          var completed = TryRemoveExecutedTask();
56          Debug.Assert(completed != null, "There must be a completed task after awaiting for an executing task");
57          return completed;
58      }

