 1      [DebuggerDisableUserUnhandledExceptions]
 2      internal static TResult Implementation<TResult>(
 3          Func<Context, CancellationToken, TResult> action,
 4          Context context,
 5          ExceptionPredicates shouldHandleExceptionPredicates,
 6          ResultPredicates<TResult> shouldHandleResultPredicates,
 7          Action<DelegateResult<TResult>, Context> onFallback,
 8          Func<DelegateResult<TResult>, Context, CancellationToken, TResult> fallbackAction,
 9          CancellationToken cancellationToken)
10      {
11          DelegateResult<TResult> delegateOutcome;
12  
13          try
14          {
15              cancellationToken.ThrowIfCancellationRequested();
16  
17              TResult result = action(context, cancellationToken);
18  
19              if (!shouldHandleResultPredicates.AnyMatch(result))
20              {
21                  return result;
22              }
23  
24              delegateOutcome = new DelegateResult<TResult>(result);
25          }
26          catch (Exception ex)
27          {
28              Exception handledException = shouldHandleExceptionPredicates.FirstMatchOrDefault(ex);
29              if (handledException == null)
30              {
31                  throw;
32              }
33  
34              delegateOutcome = new DelegateResult<TResult>(handledException);
35          }
36  
37          onFallback(delegateOutcome, context);
38  
39          return fallbackAction(delegateOutcome, context, cancellationToken);
40      }

