 1      public static PipelineComponent Create(
 2          IReadOnlyList<PipelineComponent> components,
 3          ResilienceStrategyTelemetry telemetry,
 4          TimeProvider timeProvider)
 5      {
 6          if (components.Count == 1)
 7          {
 8              return new CompositeComponent(components[0], components, telemetry, timeProvider);
 9          }
10  
11          // convert all components to delegating ones (except the last one as it's not required)
12          DelegatingComponent[] delegatingComponents = [.. components
13              .Take(components.Count - 1)
14              .Select(static strategy => new DelegatingComponent(strategy))];
15  
16  #if NET
17          // link the last one
18          delegatingComponents[^1].Next = components[^1];
19  #else
20          delegatingComponents[delegatingComponents.Length - 1].Next = components[components.Count - 1];
21  #endif
22  
23          // link the remaining ones
24          for (var i = 0; i < delegatingComponents.Length - 1; i++)
25          {
26              delegatingComponents[i].Next = delegatingComponents[i + 1];
27          }
28  
29          return new CompositeComponent(delegatingComponents[0], components, telemetry, timeProvider);
30      }

