 1      public bool TryGetValue<TValue>(ResiliencePropertyKey<TValue> key, [MaybeNullWhen(false)] out TValue value)
 2      {
 3          if (Options.TryGetValue(key.Key, out object? val))
 4          {
 5              if (val is TValue typedValue)
 6              {
 7                  value = typedValue;
 8                  return true;
 9              }
10              else if (val is null)
11              {
12                  // We have to use null-forgiving operator "!" here to suppress a null-state analysis warning.
13                  // The reason is the following. The output type "TValue" doesn't have any type constraints as
14                  // "notnull", "class" or "struct", therefore the analyzer considers "TValue" as non-nullable
15                  // and warns us that we're assigning "null" to it. But that's not correct, because "TValue"
16                  // could be a nullable type, e.g. "string?", and assigning "null" to it is correct. Therefore
17                  // it is reasonable to use "!" here to suppress the warning.
18                  value = default!;
19                  return true;
20              }
21          }
22  
23          value = default;
24          return false;
25      }

