 4          Guard.NotNull(context);
 5  
 6          context.CancellationToken.ThrowIfCancellationRequested();
 7  
 8          if (delay == TimeSpan.MaxValue)
 9          {
10              delay = System.Threading.Timeout.InfiniteTimeSpan;
11          }
12  
13          if (context.IsSynchronous)
14          {
15  #pragma warning disable CA1849
16              // For synchronous scenarios we want to return a completed task. We avoid
17              // the use of Thread.Sleep() here because it is not cancellable and to
18              // simplify the code. Sync-over-async is not a concern here because it
19              // only applies in the case of a resilience event and not on the hot path.
20  #if NET8_0_OR_GREATER
21              Task.Delay(delay, timeProvider, context.CancellationToken).GetAwaiter().GetResult();
22  #else
23              timeProvider.Delay(delay, context.CancellationToken).GetAwaiter().GetResult();
24  #endif
25  #pragma warning restore CA1849
26  
27              return Task.CompletedTask;
28          }
29  
30  #if NET8_0_OR_GREATER
31          return Task.Delay(delay, timeProvider, context.CancellationToken);
32  #else
33          return timeProvider.Delay(delay, context.CancellationToken);
34  #endif
35      }

