 1      public unsafe void DispatchX11Events(CancellationToken cancellationToken)
 2      {
 3          while (IsPending)
 4          {
 5              if (cancellationToken.IsCancellationRequested)
 6                  return;
 7  
 8              XNextEvent(_display, out var xev);
 9              if(XFilterEvent(ref xev, IntPtr.Zero))
10                  continue;
11  
12              if (xev.type == XEventName.GenericEvent)
13                  XGetEventData(_display, &xev.GenericEventCookie);
14              try
15              {
16                  if (EventHook?.TryHandleEvent(in xev) == true)
17                      continue;
18  
19                  if (xev.type == XEventName.GenericEvent)
20                  {
21                      if (_platform.XI2 != null && _platform.Info.XInputOpcode ==
22                          xev.GenericEventCookie.extension)
23                      {
24                          _platform.XI2.OnEvent((XIEvent*)xev.GenericEventCookie.data);
25                      }
26                  }
27                  else if (_windows.TryGetValue(xev.AnyEvent.window, out var windowInfo))
28                      windowInfo.EventHandler(ref xev);
29              }
30              finally
31              {
32                  if (xev.type == XEventName.GenericEvent && xev.GenericEventCookie.data != null)
33                      XFreeEventData(_display, &xev.GenericEventCookie);
34              }
35          }
36          Flush();
37      }

