 1          bool CallWithCast(List<FfiRecord> countGroup, IReadOnlyList<ExpressionVariant> arguments, out ExpressionVariant result, bool anyCast)
 2          {
 3              result = default;
 4              foreach (var record in countGroup)
 5              {
 6                  var match = true;
 7                  for (var c = 0; c < arguments.Count; c++)
 8                  {
 9                      var parameter = record.Types[c];
10                      var arg = arguments[c].Type;
11                      if (parameter != arg)
12                      {
13                          var canCast =  (parameter == VariantType.Vector3D && arg == VariantType.Vector3)
14                                        || (parameter == VariantType.Vector && arg == VariantType.Vector2)
15                                        || (anyCast && (
16                                            (arg == VariantType.Vector3D && parameter == VariantType.Vector3)
17                                            || (arg == VariantType.Vector && parameter == VariantType.Vector2)
18                                        ));
19                          if (!canCast)
20                          {
21                              match = false;
22                              break;
23                          }
24                      }
25                  }
26  
27                  if (match)
28                  {
29                      result = record.Delegate(arguments);
30                      return true;
31                  }
32              }
33  
34              if (anyCast == false)
35                  return CallWithCast(countGroup, arguments, out result, true);
36              return false;
37          }

