 4          // We should also document it.
 5          // https://github.com/dotnet/docs/issues/31423
 6          // For pre-breaking change values see table:
 7          // https://johnkoerner.com/csharp/special-folder-values-on-windows-versus-mac/
 8          var folderPath = wellKnownFolder switch
 9          {
10              WellKnownFolder.Desktop => GetFromSpecialFolder(Environment.SpecialFolder.Desktop),
11              WellKnownFolder.Documents => GetFromSpecialFolder(Environment.SpecialFolder.MyDocuments),
12              WellKnownFolder.Downloads => GetDownloadsWellKnownFolder(),
13              WellKnownFolder.Music => GetFromSpecialFolder(Environment.SpecialFolder.MyMusic),
14              WellKnownFolder.Pictures => GetFromSpecialFolder(Environment.SpecialFolder.MyPictures),
15              WellKnownFolder.Videos => GetFromSpecialFolder(Environment.SpecialFolder.MyVideos),
16              _ => throw new ArgumentOutOfRangeException(nameof(wellKnownFolder), wellKnownFolder, null)
17          };
18  
19          if (folderPath is null)
20          {
21              return null;
22          }
23  
24          var directory = new DirectoryInfo(folderPath);
