 1      internal static async Task SerializeForMimeAsync(IAsyncDataTransfer transfer, string mimeType, Stream stream)
 2      {
 3          var format = WaylandMimeMapper.FromMimeType(mimeType);
 4          if (format == null)
 5              return;
 6  
 7          // Files span multiple items; gather them all and serialize as a text/uri-list.
 8          if (DataFormat.File.Equals(format))
 9          {
10              if (await transfer.TryGetFilesAsync().ConfigureAwait(false) is { Length: > 0 } files)
11                  await stream.WriteAsync(UriListHelper.FileUriListToUtf8Bytes(files)).ConfigureAwait(false);
12              return;
13          }
14  
15          foreach (var item in transfer.Items)
16          {
17              var value = await item.TryGetRawAsync(format);
18              if (value == null)
19                  continue;
20  
21              if (DataFormat.Text.Equals(format))
22              {
23                  if (value is string text)
24                  {
25                      await stream.WriteAsync(Encoding.UTF8.GetBytes(text)).ConfigureAwait(false);
26                      return;
27                  }
28              }
29              else if (DataFormat.Bitmap.Equals(format))
30              {
31                  if (value is Bitmap bitmap)
32                  {
33                      // Clone the platform bitmap ref so it outlives the UI-thread retrieval, then
34                      // encode the PNG straight into the pipe from a pool thread. This avoids both
35                      // buffering the whole image as a byte[] and stalling the UI thread on pipe
36                      // backpressure during the encode.
37                      var bitmapRef = bitmap.PlatformImpl.Clone();
38                      await Task.Run(() =>
39                      {
40                          using (bitmapRef)
41                              bitmapRef.Item.Save(stream, PngBitmapEncoderOptions.Default);
42                      }).ConfigureAwait(false);
43                      return;
44                  }
45              }
46              else if (value is byte[] bytes)
47              {
48                  await stream.WriteAsync(bytes).ConfigureAwait(false);
49                  return;
50              }
51              else if (value is string strValue)
52              {
53                  await stream.WriteAsync(Encoding.UTF8.GetBytes(strValue)).ConfigureAwait(false);
54                  return;
55              }
56          }
57      }

