 1          private static void TrimOrphanedSeparatorsFromVisibleCommands(
 2              IList<ICommandBarElement> commands, HashSet<int> visibleIndices)
 3          {
 4              var toRemove = new List<int>();
 5              for (var i = 0; i < commands.Count; i++)
 6              {
 7                  if (!visibleIndices.Contains(i) || commands[i] is not CommandBarSeparator)
 8                      continue;
 9  
10                  bool hasNonSeparatorBefore = FindNonSeparatorInVisibleCommands(
11                      commands, visibleIndices, forward: false, startIndex: i - 1, out _);
12                  bool hasNonSeparatorAfter = FindNonSeparatorInVisibleCommands(
13                      commands, visibleIndices, forward: true, startIndex: i + 1, out _);
14  
15                  if (!hasNonSeparatorBefore || !hasNonSeparatorAfter)
16                      toRemove.Add(i);
17              }
18  
19              foreach (var idx in toRemove)
20                  visibleIndices.Remove(idx);
21  
22              bool previousWasSeparator = false;
23              for (var i = 0; i < commands.Count; i++)
24              {
25                  if (!visibleIndices.Contains(i))
26                      continue;
27  
28                  if (commands[i] is CommandBarSeparator)
29                  {
30                      if (previousWasSeparator)
31                          visibleIndices.Remove(i);
32                      else
33                          previousWasSeparator = true;
34                  }
35                  else
36                  {
37                      previousWasSeparator = false;
38                  }
39              }
40          }

