 1          private void NavigateOverflow(bool forward)
 2          {
 3              var items = GetFocusableOverflowItems();
 4              if (items.Count == 0)
 5                  return;
 6  
 7              int current = -1;
 8              for (int i = 0; i < items.Count; i++)
 9              {
10                  if (items[i].IsFocused || items[i].IsKeyboardFocusWithin)
11                  {
12                      current = i;
13                      break;
14                  }
15              }
16  
17              int next = current < 0
18                  ? (forward ? 0 : items.Count - 1)
19                  : (forward ? (current + 1) % items.Count : (current - 1 + items.Count) % items.Count);
20  
21              items[next].Focus(Input.NavigationMethod.Directional);
22          }

