 1      private bool X11SourceCallback(int i, GIOCondition gioCondition)
 2      {
 3          CheckSignaled();
 4          var token = CurrentLoopCancellation;
 5          try
 6          {
 7              // Completely drain X11 socket while we are at it
 8              while (_x11Events.IsPending)
 9              {
10                  // If we don't actually drain our X11 socket, GLib _will_ call us again even if
11                  // we request the run loop to quit
12                  _x11Events.DispatchX11Events(CancellationToken.None);
13                  if (!token.IsCancellationRequested)
14                  {
15                      while (_platform.EventGrouperDispatchQueue.HasJobs)
16                      {
17                          CheckSignaled();
18                          _platform.EventGrouperDispatchQueue.DispatchNext();
19                      }
20  
21                      _x11Events.Flush();
22                  }
23              }
24          }
25          catch (Exception e)
26          {
27              HandleException(e);
28          }
29  
30          return true;
31      }

