 1      private async Task<long> findCurrentMark(HighWaterStatistics statistics, DetectionType detectionType,
 2          CancellationToken token)
 3      {
 4          // #4964: only the Normal path holds before a leading gap. The SafeZone path deliberately skips
 5          // forward past a permanent hole (and records the skip), so it must keep the old skip-to-max behavior.
 6          var current = await runGapDetectorAsync(statistics.SafeStartMark,
 7              detectionType == DetectionType.Normal, token).ConfigureAwait(false);
 8  
 9          if (current.HasValue)
10          {
11              return current.Value;
12          }
13  
14          // This happens when the agent is restarted with persisted
15          // state, and has no previous current mark.
16          if (statistics is { CurrentMark: 0, LastMark: > 0 })
17          {
18              return statistics.LastMark;
19          }
20  
21          return statistics.CurrentMark;
22      }

