 1      private void recordAllocationObservation(HighWaterStatistics statistics)
 2      {
 3          // #5091: the reading has to be the highest ALLOCATED sequence number. Under per-tenant event
 4          // partitioning there is none to be had — tenants draw from their own sequences, and
 5          // HighestSequence is the committed max(seq_id) (#4712), where "committed height <= mark at
 6          // time T" says nothing about what was ALLOCATED by then. AllocatedSequenceHigh is null in
 7          // exactly those cases, so no sound fence is built from them.
 8          if (statistics is not MartenHighWaterStatistics marten || marten.AllocatedSequenceHigh is not { } allocatedHigh
 9              || statistics.Timestamp == default)
10          {
11              return;
12          }
13  
14          lock (_allocationHistoryLock)
15          {
16              var count = _allocationHistory.Count;
17              if (count > 0)
18              {
19                  var last = _allocationHistory[count - 1];
20                  if (allocatedHigh == last.AllocatedHigh)
21                  {
22                      if (statistics.Timestamp > last.Timestamp)
23                      {
24                          _allocationHistory[count - 1] = last with { Timestamp = statistics.Timestamp };
25                      }
26  
27                      return;
28                  }
29  
30                  // Readings can complete out of order across concurrent callers; only ever append a
31                  // strictly newer, strictly higher reading so the list stays monotone in both fields
32                  if (allocatedHigh < last.AllocatedHigh || statistics.Timestamp <= last.Timestamp)
33                  {
34                      return;
35                  }
36              }
37  
38              _allocationHistory.Add(new AllocationObservation(statistics.Timestamp, allocatedHigh));
39              if (_allocationHistory.Count > AllocationHistoryCapacity)
40              {
41                  _allocationHistory.RemoveAt(0);
42              }
43          }
44      }

