 1      private async Task persistAllocationFenceAsync(HighWaterStatistics statistics, CancellationToken token)
 2      {
 3          // Under per-tenant event partitioning tenants draw from their own sequences, so the
 4          // store-global sequence says nothing about allocation — same reason AllocatedSequenceHigh is
 5          // null there. No sound fence exists to persist.
 6          if (_graph.UseTenantPartitionedEvents)
 7          {
 8              return;
 9          }
10  
11          try
12          {
13              await using var cmd = new NpgsqlCommand($@"
14  insert into {_graph.DatabaseSchemaName}.mt_event_progression(name, last_seq_id, last_updated)
15  select '{HighWaterAllocationFence.ProgressionName}', alloc.high, transaction_timestamp()
16  from (select case when is_called then last_value else last_value - 1 end as high
17        from {_graph.DatabaseSchemaName}.mt_events_sequence) alloc
18  where alloc.high <= :mark
19  on conflict (name) do update
20     set last_seq_id = excluded.last_seq_id, last_updated = excluded.last_updated
21   where excluded.last_updated > {_graph.DatabaseSchemaName}.mt_event_progression.last_updated")
22                  .With("mark", statistics.LastMark);
23  
24              await _runner.SingleCommit(cmd, token).ConfigureAwait(false);
25          }
26          catch (Exception e) when (!token.IsCancellationRequested)
27          {
28              // The fence is an optimization on top of a conservative default: without it the detector
29              // simply holds, which is the pre-#5108 behavior. Never let recording it take down a poll.
30              _logger.LogDebug(e, "Unable to record the high water allocation fence for database {Database}",
31                  DatabaseIdentity);
32          }
33      }

