13                      .With("seq", statistics.HighestSequence)
14                      .With("fence", HighWaterAllocationFence.ProgressionName)
15                      .With("stuck", HighWaterStuckGap.ProgressionName);
16  
17              await _runner.SingleCommit(cmd, token).ConfigureAwait(false);
