 1      private async Task refreshHighWaterFreshnessAsync(CancellationToken token)
 2      {
 3          try
 4          {
 5              await using var cmd = new NpgsqlCommand(
 6                  $"update {_graph.DatabaseSchemaName}.mt_event_progression set last_updated = transaction_timestamp() where name = '{HighWaterShardIdentity.StoreGlobal}'");
 7  
 8              await _runner.SingleCommit(cmd, token).ConfigureAwait(false);
 9          }
