 1      private async Task calculateHighWaterMark(HighWaterStatistics statistics, DetectionType detectionType,
 2          CancellationToken token)
 3      {
 4          // If the last high water mark is the same as the highest number
 5          // assigned from the sequence, then the high water mark cannot
 6          // have changed
 7          if (statistics.LastMark == statistics.HighestSequence)
 8          {
 9              statistics.CurrentMark = statistics.LastMark;
10          }
11          else if (statistics.HighestSequence == 0)
12          {
13              statistics.CurrentMark = statistics.LastMark = 0;
14          }
15          else
16          {
17              statistics.CurrentMark = await findCurrentMark(statistics, detectionType, token).ConfigureAwait(false);
18          }
19  
20          await persistDetectedMarkAsync(statistics, detectionType, token).ConfigureAwait(false);
21      }

