 1      private void trackStuckGap(HighWaterStatistics statistics)
 2      {
 3          if (statistics.CurrentMark >= statistics.HighestSequence || statistics.CurrentMark > statistics.LastMark)
 4          {
 5              // caught up, or the mark advanced — whatever gap existed before is resolved
 6              _stuckGap = null;
 7              return;
 8          }
 9  
10          if (statistics.CurrentMark == 0 && statistics.HighestSequence <= 1)
11          {
12              // pristine store (Postgres sequences report last_value = 1 before first use)
13              _stuckGap = null;
14              return;
15          }
16  
17          var current = _stuckGap;
18          if (current == null || current.Mark != statistics.CurrentMark)
19          {
20              // #5109: the cap is meant to bound how long the GAP has been stuck, not how long THIS
21              // detector has watched it. A durable record of the first sighting — keyed on the pinned
22              // mark, so it only applies while the mark has not moved — is what makes daemon restarts
23              // and managed-distribution agent churn stop resetting the clock.
24              var durableSince = statistics is MartenHighWaterStatistics { PersistedStuckGap: { } stuck }
25                                 && stuck.Mark == statistics.CurrentMark
26                  ? stuck.FirstObservedAt
27                  : (DateTimeOffset?)null;
28  
29              _stuckGap = new StuckGapObservation(
30                  statistics.CurrentMark,
31                  statistics.Timestamp,
32                  (statistics as MartenHighWaterStatistics)?.CurrentXmax ?? 0,
33                  statistics.HighestSequence,
34                  findAllocationFence(statistics, statistics.CurrentMark),
35                  durableSince);
36          }
37      }

