 1      private async Task<HighWaterStatistics> detectInSafeZoneLegacy(HighWaterStatistics statistics,
 2          CancellationToken token)
 3      {
 4          // Skip gap and find next safe sequence. #4964: the SafeZone path must NOT hold before a leading
 5          // gap — its whole purpose is to skip forward past a stuck (permanent) hole and record the skip.
 6          var safeSequence = await runGapDetectorAsync(statistics.SafeStartMark + 1, false, token).ConfigureAwait(false);
 7          if (safeSequence.HasValue)
 8          {
 9              _logger.LogInformation(
10                  "Daemon projection high water detection skipping a gap in event sequence, determined that the 'safe harbor' sequence is at {SafeHarborSequence}",
11                  safeSequence);
12          }
13          else
14          {
15              _logger.LogInformation("Daemon projection high water detection was not able to determine a safe harbor sequence, will try again soon");
16          }
17  
18          if (safeSequence.HasValue)
19          {
20              statistics.SafeStartMark = safeSequence.Value;
21          }
22          else if (statistics.TryGetStaleAge(out var time))
23          {
24              // This is for GH-2681. What if there's a gap
25              // from the last good spot and the latest sequence?
26              // Instead of doing this in an infinite loop, advance
27              // the sequence
28              if (time > _settings.StaleSequenceThreshold)
29              {
30                  // This has to take into account the 32 problem. If the
31                  // HighestSequence is less than 32 higher than the LastMark or CurrentMark, do NOT advance
32                  // https://github.com/JasperFx/marten/issues/3865
33                  var safeSequenceNumber = statistics.HighestSequence - 32;
34                  if (safeSequenceNumber > statistics.LastMark)
35                  {
36                      statistics.SafeStartMark = safeSequenceNumber;
37                      statistics.CurrentMark = safeSequenceNumber;
38                  }
39              }
40          }
41  
42          await calculateHighWaterMark(statistics, DetectionType.SafeZoneSkipping, token).ConfigureAwait(false);
43  
44          return statistics;
45      }

