 1      private static bool tryBuildOrOfContainment(ISqlFragment fragment, ICollectionMember collectionMember,
 2          ISerializer serializer, [NotNullWhen(true)]out ISqlFragment? filter)
 3      {
 4          filter = default;
 5  
 6          if (fragment is not CompoundWhereFragment compound || compound.Separator.ContainsIgnoreCase("and"))
 7          {
 8              return false;
 9          }
10  
11          var branches = new List<ISqlFragment>();
12          foreach (var child in compound.Children)
13          {
14              switch (child)
15              {
16                  // ElementComparisonFilter reduces to its own single-value containment for
17                  // = / != even though it reports SupportsContainment() == false (it cannot
18                  // be merged with siblings), so CanReduceInChildCollection() is the gate here
19                  case ICollectionAware aware when aware.CanReduceInChildCollection() &&
20                                                   (aware.SupportsContainment() || aware is ElementComparisonFilter):
21                      branches.Add(aware.BuildFragment(collectionMember, serializer));
22                      break;
23  
24                  case CompoundWhereFragment inner when inner.Separator.ContainsIgnoreCase("and") &&
25                                                        inner.Children.Any() &&
26                                                        inner.Children.All(x =>
27                                                            x is ICollectionAware ia &&
28                                                            ia.CanReduceInChildCollection() && ia.SupportsContainment()):
29                      var containment = new ContainmentWhereFilter(collectionMember, serializer)
30                      {
31                          Usage = ContainmentUsage.Collection
32                      };
33                      foreach (var ia in inner.Children.OfType<ICollectionAware>())
34                      {
35                          ia.PlaceIntoContainmentFilter(containment);
36                      }
37  
38                      branches.Add(containment);
39                      break;
40  
41                  default:
42                      return false;
43              }
44          }
45  
46          filter = CompoundWhereFragment.Or(branches.ToArray());
47          return true;
48      }

