 1      public ISqlFragment CompileFragment(ICollectionMember collectionMember, ISerializer serializer)
 2      {
 3          if (_fragment is ICollectionAwareFilter awareFilter && awareFilter.CollectionMember != collectionMember)
 4          {
 5              return awareFilter.MoveUnder(collectionMember);
 6          }
 7  
 8          if (TryBuildInlineFragment(_fragment, collectionMember, serializer, out var filter))
 9          {
10              return filter;
11          }
12  
13          // The strategies below only apply to JSONB-backed collections. Duplicated
14          // array fields and dictionary members have their own storage semantics and
15          // keep the sub-query strategy
16          if (collectionMember is ChildCollectionMember or ValueCollectionMember)
17          {
18              // An OR spray of containment-eligible predicates beats a jsonpath filter
19              // because each branch stays eligible for a GIN index (BitmapOr)
20              if (tryBuildOrOfContainment(_fragment, collectionMember, serializer, out var orContainment))
21              {
22                  return orContainment;
23              }
24  
25              if (JsonPathExistsFilter.TryBuild(_fragment, collectionMember, serializer, out var jsonPath))
26              {
27                  // Mixed AND (equality + something else): the equality conjuncts also go
28                  // out as a logically redundant containment pre-filter so a GIN index can
29                  // prune before the jsonpath predicate runs. Only at the document root —
30                  // a nested filter must stay a single ICollectionAwareFilter so that an
31                  // outer Any() can flatten it via MoveUnder()
32                  if (collectionMember.Ancestors[0] is DocumentQueryableMemberCollection &&
33                      tryBuildContainmentPrefilter(_fragment, collectionMember, serializer, out var prefilter))
34                  {
35                      return CompoundWhereFragment.And(prefilter, jsonPath);
36                  }
37  
38                  return jsonPath;
39              }
40          }
41  
42          // Correlated EXISTS over the exploded elements beats the legacy explode-CTE +
43          // ctid correlation by ~8x and composes at any nesting depth
44          if (collectionMember is IExistsElementSource { ExplodedElementSource: not null } source)
45          {
46              return new ExistsCollectionFilter(collectionMember, _fragment, source.ExplodedElementSource!);
47          }
48  
49          return new SubQueryFilter(collectionMember, _fragment);
50      }

