 1      public void ConfigureCommand(ICommandBuilder builder, IStorageSession session)
 2      {
 3          var schema = _events.DatabaseSchemaName;
 4          var tenantId = session.TenantId;
 5  
 6          for (var i = 0; i < _orderedEntries.Count; i++)
 7          {
 8              // StartNewCommand (not `; <sql>`) so Npgsql sends each statement
 9              // as a separate batched command — multiple `;`-separated
10              // statements in a single prepared statement raise Postgres
11              // SQLSTATE 42601.
12              if (i > 0) builder.StartNewCommand();
13  
14              var entry = _orderedEntries[i];
15  
16              // INSERT … ON CONFLICT DO UPDATE WHERE handles the two cases the
17              // fetch path delegates to us:
18              //   - captured = 0 + row missing → INSERT(version=1) succeeds; first save wins.
19              //   - row exists → ON CONFLICT branch; the WHERE filters to captured-match
20              //     only, so any save that observed a stale version returns no row.
21              // INSERT … ON CONFLICT waits on the conflicting row's xact, so two
22              // first-time creators serialize on the unique-PK insert path the same
23              // way subsequent versioned-update saves serialize on the row lock.
24              builder.Append("insert into ");
25              builder.Append(schema);
26              builder.Append(".mt_dcb_tag_version (tag_table, tag_value, tenant_id, version) values (");
27              builder.AppendParameter(entry.TagTable);
28              builder.Append(", ");
29              builder.AppendParameter(entry.TagValue);
30              builder.Append(", ");
31              builder.AppendParameter(tenantId);
32              builder.Append(", ");
33              builder.AppendParameter(entry.CapturedVersion + 1);
34              // ON CONFLICT DO UPDATE references the existing row via the
35              // unqualified table name (`mt_dcb_tag_version.version`) — Postgres
36              // does not accept the schema prefix in this clause.
37              builder.Append(") on conflict (tag_table, tag_value, tenant_id) do update set version = mt_dcb_tag_version.version + 1 where mt_dcb_tag_version.version = ");
38              builder.AppendParameter(entry.CapturedVersion);
39              builder.Append(" returning 1");
40          }
41      }

