 1      private static DcbTagVersionEntry[] collapseDuplicateRows(DcbTagVersionEntry[] sorted)
 2      {
 3          if (sorted.Length < 2) return sorted;
 4  
 5          var kept = 1;
 6          for (var i = 1; i < sorted.Length; i++)
 7          {
 8              var previous = sorted[kept - 1];
 9              if (sorted[i].TagTable == previous.TagTable && sorted[i].TagValue == previous.TagValue) continue;
10  
11              sorted[kept++] = sorted[i];
12          }
13  
14          if (kept == sorted.Length) return sorted;
15  
16          var collapsed = new DcbTagVersionEntry[kept];
17          Array.Copy(sorted, collapsed, kept);
18          return collapsed;
19      }

