 1      public DcbTagVersionAssertion(
 2          EventGraph events,
 3          IReadOnlyList<DcbTagVersionEntry> capturedEntries)
 4      {
 5          _events = events;
 6  
 7          // Sort once, here — both ConfigureCommand and PostprocessAsync iterate
 8          // in the same order, and the deterministic order is what keeps two
 9          // concurrent appenders touching the same tag rows from deadlocking.
10          // Sorting the merged set is also what makes that guarantee hold across
11          // boundaries: two sessions holding the same pair of boundaries in
12          // opposite fetch order would otherwise take the row locks in opposite
13          // order too.
14          var sorted = new DcbTagVersionEntry[capturedEntries.Count];
15          for (var i = 0; i < capturedEntries.Count; i++) sorted[i] = capturedEntries[i];
16          Array.Sort(sorted, static (a, b) =>
17          {
18              var byTable = string.CompareOrdinal(a.TagTable, b.TagTable);
19              if (byTable != 0) return byTable;
20  
21              var byValue = string.CompareOrdinal(a.TagValue, b.TagValue);
22              if (byValue != 0) return byValue;
23  
24              // Oldest capture first, so collapsing a duplicate run below keeps the
25              // strictest check of the row: every read the session made has to still
26              // be valid, not just the most recent one.
27              return a.CapturedVersion.CompareTo(b.CapturedVersion);
28          });
29  
30          _orderedEntries = collapseDuplicateRows(sorted);
31      }

