 9          {
10              // Value types can be null via Nullable<T> (ScalarSelectClause<T>); reference types like
11              // byte[] are already naturally nullable and can't close over Nullable<T>, so they need
12              // the ScalarClassSelectClause<T> counterpart instead.
13              return typeof(T).IsValueType
14                  ? typeof(ScalarSelectClause<>).CloseAndBuildAs<ISelectClause>(string.Empty, string.Empty, typeof(T))
