17  
18          if (typeof(T).GetProperty("Id") == null && typeof(T).GetProperty("id") == null)
19          {
20              return new DataSelectClause<T>(string.Empty, string.Empty);
21          }
22          return (ILinqDocumentStorage)session.StorageFor<T>();
23      }

