 7          {
 8              if (await innerReader.ReadAsync(token).ConfigureAwait(false))
 9              {
10                  return await ((ISelector<T>)Selectors[rowIndex]).ResolveAsync(innerReader, token).ConfigureAwait(false);
11              }
12          }
13          return default;
14      }

