 1      internal static (NpgsqlDbType dbType, Func<object, object?>? transform) ResolveLeafStorage(Type memberType, StoreOptions storeOptions)
 2      {
 3          // Unwrap Nullable<T> for the type-introspection pass. The runtime setter
 4          // sees the nullable type as TValue and writes DBNull whenever the value is null;
 5          // only the non-null value hits the transform.
 6          var nonNullable = Nullable.GetUnderlyingType(memberType) ?? memberType;
 7  
 8          if (nonNullable.IsEnum)
 9          {
10              if (storeOptions.Advanced.DuplicatedFieldEnumStorage == EnumStorage.AsString)
11              {
12                  return (NpgsqlDbType.Varchar, raw => raw.ToString());
13              }
14  
15              // AsInteger: convert each enum value to its underlying int. Use
16              // Convert.ToInt32 rather than a direct cast so non-Int32-backed enums
17              // (byte, short, long) round-trip into the int column without a runtime cast error.
18              return (NpgsqlDbType.Integer, raw => Convert.ToInt32(raw));
19          }
20  
21          var valueTypeInfo = storeOptions.TryFindValueType(nonNullable);
22          if (valueTypeInfo != null)
23          {
24              var innerDbType = PostgresqlProvider.Instance.ToParameterType(valueTypeInfo.SimpleType);
25              var valueProperty = valueTypeInfo.ValueProperty;
26              return (innerDbType, raw => valueProperty.GetValue(raw));
27          }
28  
29          return (PostgresqlProvider.Instance.ToParameterType(memberType), null);
30      }

