 1      private static object BuildLeafParameterSetter(MemberInfo member, Type sourceType, StoreOptions storeOptions)
 2      {
 3          var memberType = member.GetRawMemberType()!;
 4          var (dbType, transform) = ResolveLeafStorage(memberType, storeOptions);
 5  
 6          // Default path (no special handling): preserve historical 1-arg construction
 7          // so we don't churn the existing tests / reflection layout.
 8          if (transform == null)
 9          {
10              return typeof(ParameterSetter<,>).CloseAndBuildAs<object>(member, sourceType, memberType);
11          }
12  
13          // Special path (enum / value type / nullable variants): use the explicit
14          // (member, dbType, transform) constructor so PostgresqlProvider never has
15          // to infer a parameter type from the .NET wrapper type.
16          return typeof(ParameterSetter<,>).CloseAndBuildAs<object>(
17              member, dbType, transform,
18              sourceType, memberType);
19      }

