 1      internal static IParameterSetter<IEvent> BuildSetterForMembers<T>(MemberInfo[] members, StoreOptions storeOptions)
 2      {
 3          if (members.Length == 1)
 4          {
 5              if (members[0].DeclaringType != typeof(IEvent))
 6              {
 7                  var inner = BuildLeafParameterSetter(members[0], typeof(T), storeOptions);
 8                  return new EventForwarder<T>((IParameterSetter<T>)inner);
 9              }
10          }
11  
12          // off of something on the event - MemberFinder.Determine returns the chain
13          // outer-to-leaf, e.g. [Foo, Bar, Value]. Reversing puts the leaf first so
14          // the ParameterSetter at the bottom does the actual parameter write, and
15          // each RelayParameterSetter wraps it with the next level out (handling
16          // intermediate nulls).
17          var leafFirst = members.Reverse().ToArray();
18  
19          // Leaf decides the storage db type and any value transform (enum->string,
20          // value-type unwrap, etc.). Use that db type all the way up so intermediate
21          // nulls write DBNull with the correct type.
22          var (dbType, _) = ResolveLeafStorage(leafFirst[0].GetRawMemberType()!, storeOptions);
23  
24          var setter = BuildLeafParameterSetter(leafFirst[0], leafFirst[1].GetRawMemberType()!, storeOptions);
25  
26          for (var i = 1; i < leafFirst.Length; i++)
27          {
28              setter = typeof(RelayParameterSetter<,>).CloseAndBuildAs<object>(dbType, setter,
29                  leafFirst[i], leafFirst[i].DeclaringType!, leafFirst[i].GetRawMemberType()!);
30          }
31  
32          return new EventForwarder<T>((IParameterSetter<T>)setter);
33      }

