 5      {
 6          StoreOptions(opts =>
 7          {
 8              opts.Events.EnableAdvancedAsyncTracking = useAdvancedTracking;
 9              opts.Projections.StaleSequenceThreshold = 500.Milliseconds();
10          });
11          await theStore.EnsureStorageExistsAsync(typeof(IEvent), TestContext.Current.CancellationToken);
12  
13          NumberOfStreams = 10;
14          await PublishSingleThreaded();
15  
16          var gaps = new long[] {NumberOfEvents - 100, NumberOfEvents - 95, NumberOfEvents - 88, NumberOfEvents - 33};
17          await deleteEvents(gaps);
18  
19  
20  
21          var statistics = await theDetector.Detect(CancellationToken.None);
22  
23          // This gets under the gap, using the buffer
24          statistics.CurrentMark.ShouldBe(NumberOfEvents - 101);
25          statistics.HighestSequence.ShouldBe(NumberOfEvents);
26  
27          // #4953: a stale gap is no longer skipped on first sighting — the safe zone holds until the
28          // gap has been stuck past StaleSequenceThreshold (measured from when the detector first
29          // observed it) and no live transaction could still fill it
30          var held = await theDetector.DetectInSafeZone(CancellationToken.None);
31          held.CurrentMark.ShouldBe(NumberOfEvents - 101);
32  
33          await Task.Delay(700, TestContext.Current.CancellationToken);
34  
35          var statistics2 = await theDetector.DetectInSafeZone(CancellationToken.None);
36  
37          // #5108 §2: all four dead gaps clear in ONE cycle, not one gap per cycle. Every sequence
38          // number at or below the ceiling recorded at observation was handed out before that moment,
39          // and the liveness probe just established that no transaction from before it is still alive —
40          // so every one of these gaps is provably dead, not just the first. Previously each gap cost
41          // its own detection cycle plus a fresh StaleSequenceThreshold, which is what made recovery
42          // time grow linearly with the number of gaps.
43          statistics2.CurrentMark.ShouldBe(NumberOfEvents);
