 1      private static bool TryGetClosedGenericArgs(
 2          ITypeSymbol type, string openTypeDisplayName,
 3          out System.Collections.Immutable.ImmutableArray<ITypeSymbol> args)
 4      {
 5          if (type is INamedTypeSymbol nt && nt.IsGenericType
 6              && nt.OriginalDefinition.ToDisplayString() == openTypeDisplayName)
 7          {
 8              args = nt.TypeArguments;
 9              return true;
10          }
11          foreach (var iface in type.AllInterfaces)
12          {
13              if (iface.IsGenericType
14                  && iface.OriginalDefinition.ToDisplayString() == openTypeDisplayName)
15              {
16                  args = iface.TypeArguments;
17                  return true;
18              }
19          }
20          args = System.Collections.Immutable.ImmutableArray<ITypeSymbol>.Empty;
21          return false;
22      }

