 1      private static IEnumerable<ISymbol> EnumerateMembers(INamedTypeSymbol type)
 2      {
 3          // Mirror MemberInfo.GetFields(BindingFlags.Public | BindingFlags.Instance) followed by
 4          // MemberInfo.GetProperties(...). Walk the inheritance chain to pick up inherited
 5          // public members; only public, non-static.
 6          var current = type;
 7          var seen = new HashSet<string>();
 8          while (current is not null && current.SpecialType != SpecialType.System_Object)
 9          {
10              foreach (var f in current.GetMembers().OfType<IFieldSymbol>())
11              {
12                  if (f.IsStatic || f.DeclaredAccessibility != Accessibility.Public) continue;
13                  if (f.IsImplicitlyDeclared) continue; // backing fields, etc.
14                  if (seen.Add(f.Name)) yield return f;
15              }
16              foreach (var p in current.GetMembers().OfType<IPropertySymbol>())
17              {
18                  if (p.IsStatic || p.DeclaredAccessibility != Accessibility.Public) continue;
19                  if (p.IsIndexer) continue;
20                  if (seen.Add(p.Name)) yield return p;
21              }
22              current = current.BaseType;
23          }
24      }

