 3          // Cluster A: TenantIdStyle, DefaultTenantUsageEnabled, RlsTenantSessionSetting
 4          usage.AddValue(nameof(Options.TenantIdStyle), Options.TenantIdStyle.ToString());
 5          usage.AddValue(nameof(Options.Advanced.DefaultTenantUsageEnabled), Options.Advanced.DefaultTenantUsageEnabled);
 6          usage.AddValue(
 7              "RlsTenantSessionSetting",
 8              Options.RlsTenantSessionSetting != null ? "Configured" : "Default");
 9  
10          // Cluster B: NameDataLength, ApplyChangesLockId
11          usage.AddValue(nameof(Options.NameDataLength), Options.NameDataLength);
12          usage.AddValue(nameof(Options.ApplyChangesLockId), Options.ApplyChangesLockId);
13  
14          // Cluster C: CommandTimeout, UpdateBatchSize, UseStickyConnectionLifetimes
15          usage.AddValue(nameof(Options.CommandTimeout), Options.CommandTimeout);
16          usage.AddValue(nameof(Options.UpdateBatchSize), Options.UpdateBatchSize);
17          usage.AddValue(nameof(Options.UseStickyConnectionLifetimes), Options.UseStickyConnectionLifetimes);
18  
19          // Cluster D: DuplicatedFieldEnumStorage (lifted from Advanced)
20          usage.AddValue("DuplicatedFieldEnumStorage", Options.Advanced.DuplicatedFieldEnumStorage.ToString());
21  
22          // Cluster F: OpenTelemetryTrackConnections (flattened from OpenTelemetry child),
23          // DisableNpgsqlLogging
24          usage.AddValue("OpenTelemetryTrackConnections", Options.OpenTelemetry.TrackConnections.ToString());
25          usage.AddValue(nameof(Options.DisableNpgsqlLogging), Options.DisableNpgsqlLogging);
26  
27          // Cluster H6: HiloMaxLo / HiloMaxAdvanceToNextHiAttempts (lifted from
28          // HiloSequenceDefaults). MaxLo is the canonical chunk-size knob;
29          // MaxAdvanceToNextHiAttempts bounds retry behaviour during sequence
30          // contention. SequenceName is omitted (it's a per-document override
31          // that lives on individual mappings, not the store-wide default).
32          usage.AddValue("HiloMaxLo", Options.Advanced.HiloSequenceDefaults.MaxLo);
33          usage.AddValue("HiloMaxAdvanceToNextHiAttempts", Options.Advanced.HiloSequenceDefaults.MaxAdvanceToNextHiAttempts);
34  
35          // Cluster H7: ReadSessionPreference / WriteSessionPreference
36          // (lifted from MultiHostSettings)
37          usage.AddValue(
38              "ReadSessionPreference",
39              Options.Advanced.MultiHostSettings.ReadSessionPreference.ToString());
40          usage.AddValue(
41              "WriteSessionPreference",
42              Options.Advanced.MultiHostSettings.WriteSessionPreference.ToString());
43      }

