 1      private static PartitioningDescriptor? BuildPartitioning(IPartitionStrategy? partitioning)
 2      {
 3          if (partitioning == null)
 4          {
 5              return null;
 6          }
 7  
 8          // "ListPartitioning" -> "List", "HashPartitioning" -> "Hash", etc.
 9          var strategy = partitioning.GetType().Name.Replace("Partitioning", "");
10  
11          var names = partitioning switch
12          {
13              ListPartitioning list => list.Partitions.Select(x => x.Suffix).ToArray(),
14              RangePartitioning range => range.Ranges.Select(x => x.Suffix).ToArray(),
15              HashPartitioning hash => hash.Suffixes,
16              _ => Array.Empty<string>()
17          };
18  
19          return new PartitioningDescriptor { Strategy = strategy, PartitionNames = names };
20      }

