 1      internal static bool TryBuildIndexes(DocumentMapping mapping, out List<DocumentIndexDescriptor> indexes)
 2      {
 3          try
 4          {
 5              indexes = BuildIndexes(mapping);
 6          }
 7          catch (Exception)
 8          {
 9              // Same stance as WriteSchemaCreationDdl: one mapping's model failing must not poison the snapshot,
10              // and an empty list must not then read as "no indexes".
11              indexes = new List<DocumentIndexDescriptor>();
12              return false;
13          }
14  
15          return mapping.IgnoredIndexes.Count == 0;
16      }

