 1      private static void trackForWriteBack(DocumentSessionBase session, IAggregateWriteCache cache,
 2          AggregateCacheKey key, TDoc document, TId id, long version)
 3      {
 4          var map = ((IMartenSession)session).ItemMap;
 5          if (!map.TryGetValue(typeof(PendingAggregateCacheWrites), out var raw) ||
 6              raw is not PendingAggregateCacheWrites pending)
 7          {
 8              pending = new PendingAggregateCacheWrites();
 9              map[typeof(PendingAggregateCacheWrites)] = pending;
10          }
11  
12          pending.Track(cache, key, document, id, version);
13      }

