 1      public async Task<IEventStream<TDoc>> FetchForWriting(DocumentSessionBase session, TId id, bool forUpdate,
 2          CancellationToken cancellation = default)
 3      {
 4          try
 5          {
 6              return await fetchForWriting(session, id, forUpdate, true, cancellation).ConfigureAwait(false);
 7          }
 8          catch (CachedSnapshotUnusableException)
 9          {
10              // The cached snapshot was not at the stream's current version. Unlike the Async plan there is
11              // no delta query to reconcile with -- an Inline snapshot is always exactly at the stream head,
12              // so anything else means the entry is simply wrong. TryTake has already removed it; redo the
13              // fetch on the always-correct uncached path.
14              return await fetchForWriting(session, id, forUpdate, false, cancellation).ConfigureAwait(false);
15          }
16      }

