 6              x.SchemaName = "sharded";
 7              x.PartitionSchemaName = "tenants";
 8  
 9              foreach (var (dbName, connStr) in Fixture.ConnectionStrings)
10              {
11                  x.AddDatabase(dbName, connStr);
12              }
13          });
14  
15          opts.AutoCreateSchemaObjects = AutoCreate.All;
16          opts.Events.TenancyStyle = TenancyStyle.Conjoined;
17          opts.Events.AppendMode = EventAppendMode.QuickWithServerTimestamps;
