 1          public Task<IEventStream<TDoc>> HandleAsync(DbDataReader reader, IStorageSession session, CancellationToken token)
 2          {
 3              var documentSessionBase = (DocumentSessionBase)session;
 4              // #5613: detection ON, and it surfaces as SnapshotRaceException rather than being retried. A
 5              // batch handler is handed one reader and cannot issue another statement, so there is no redo
 6              // available here -- the choice is a wrong aggregate or an exception, and for a fetch whose whole
 7              // purpose is to decide what to write, the exception is the better answer. Retry the batch.
 8              return _parent.ReadIntoStream(documentSessionBase, _id, token, reader, _loadHandler,
 9                  documentSessionBase.EventStorage(), detectSnapshotRace: true);
10          }

