 1          public void ConfigureCommand(ICommandBuilder builder, IStorageSession session)
 2          {
 3              // Asked again here rather than reusing _sharedSnapshot: the session can acquire a transaction
 4              // between enlistment and Execute(), and this is the last moment before the SQL goes out. The
 5              // enlistment-time answer only has to be good enough for the batch's own rules; this one has to
 6              // be right.
 7              var sharedSnapshot = !_forUpdate && beginSharedSnapshot(builder, (QuerySession)session);
 8  
 9              _parent._identityStrategy.BuildCommandForReadingVersionForStream(_parent.IsGlobal, builder, _id, _forUpdate);
10  
11              builder.StartNewCommand();
12  
13              _loadHandler.ConfigureCommand(builder, session);
14  
15              builder.StartNewCommand();
16  
17              _parent.writeEventFetchStatement(_id, builder);
18  
19              endSharedSnapshot(builder, sharedSnapshot);
20          }

