 1      private static bool snapshotAndDeltaDisagree(DocumentSessionBase session, TId id, long version,
 2          TDoc? document, IReadOnlyList<IEvent> events)
 3      {
 4          // A delta with events in it tells us nothing we can safely act on -- see the remarks above.
 5          if (events.Count > 0) return false;
 6  
 7          // Nothing appended yet, so there is nothing for a snapshot to be behind.
 8          if (version <= 0) return false;
 9  
10          // No snapshot row at all. Then the delta query's join matched `a.mt_version is NULL` and should
11          // have returned EVERY event of this stream, so an empty delta is flatly impossible from the state
12          // the document read saw -- the floor came from a snapshot the daemon committed in between. This is
13          // the FIRST-snapshot case, and the loudest one: the aggregate comes back null for a live stream.
14          if (document == null) return true;
15  
16          // A row was read but no revision came with it. Nothing to compare, and inventing a race from an
17          // absent measurement is how a guard like this turns into spurious retries.
18          var snapshotRevision = ((IMartenSession)session).Versions.RevisionFor<TDoc, TId>(id);
19          if (snapshotRevision == null) return false;
20  
21          // The delta is empty, so the snapshot is supposed to already be at the stream's head. If it is
22          // behind, the floor the delta query used came from a NEWER snapshot than the one we hold, and the
23          // events in between have been dropped from both.
24          return snapshotRevision.Value < version;
25      }

