 1      [MemberNotNull(nameof(_initialSql))]
 2      public async Task<IEventStream<TDoc>> FetchForWriting(DocumentSessionBase session, TId id, bool forUpdate, CancellationToken cancellation = default)
 3      {
 4          for (var attempt = 0; attempt < SnapshotRaceRedos; attempt++)
 5          {
 6              try
 7              {
 8                  return await fetchForWriting(session, id, forUpdate, true, true, cancellation).ConfigureAwait(false);
 9              }
10              catch (CacheAheadOfDatabaseException)
11              {
12                  // The cached snapshot claimed a higher version than the stream actually has, so the delta
13                  // query could not possibly reconstitute it. TryTake already removed the entry; redo the fetch
14                  // on the normal, always-correct uncached path -- but still write the result back, so the cache
15                  // heals in one round instead of two. Rare enough to not be worth optimizing further.
16                  return await fetchForWriting(session, id, forUpdate, false, true, cancellation).ConfigureAwait(false);
17              }
18              catch (SnapshotRaceException)
19              {
20                  // #5613. The daemon committed a snapshot between this batch's two reads. Nothing is wrong
21                  // with the stream; the read just straddled the write. Go round again -- but the redo has to
22                  // forget what the first attempt learned first, or a snapshot that has since gone is judged
23                  // by the revision of the one that was there.
24                  forgetSnapshot(session, id);
25              }
26          }
27  
28          // Out of redos. Run once more with detection off so this always returns a stream rather than
29          // throwing something no previous release ever threw. See SnapshotRaceRedos.
30          return await fetchForWriting(session, id, forUpdate, true, false, cancellation).ConfigureAwait(false);
31      }

