 1      private IEnumerable<Type> determineTypeDependencies(Type type)
 2      {
 3          if (type == typeof(StorageFeatures)) return Array.Empty<Type>();
 4  
 5          var mapping = FindMapping(type);
 6          var documentMapping = mapping as DocumentMapping ?? (mapping as SubClassMapping)?.Parent;
 7          if (documentMapping == null)
 8          {
 9              return Enumerable.Empty<Type>();
10          }
11  
12  
13          return documentMapping.ReferencedTypes()
14              .SelectMany(keyDefinition =>
15              {
16                  var results = new List<Type>();
17                  // If the reference type has sub-classes, also need to insert/update them first too
18                  if (FindMapping(keyDefinition) is DocumentMapping referenceMappingType &&
19                      referenceMappingType.SubClasses.Any())
20                  {
21                      results.AddRange(referenceMappingType.SubClasses.Select(s => s.DocumentType));
22                  }
23  
24                  results.Add(keyDefinition);
25                  return results;
26              });
27      }

