 1      public IFeatureSchema FindFeature(Type featureType)
 2      {
 3          if (_features.Value.TryFind(featureType, out var schema))
 4          {
 5              return schema;
 6          }
 7  
 8          if (_options.EventGraph.AllEvents().Any(x => x.DocumentType == featureType))
 9          {
10              return _options.EventGraph;
11          }
12  
13          if (featureType == typeof(StorageFeatures))
14          {
15              return this;
16          }
17  
18          // 9.0: With lazy mapping materialization (#4303) a subclass-only
19          // feature lookup (e.g. EnsureStorageExistsAsync(typeof(SuperUser))
20          // when User is the registered parent) can't be served from
21          // _features yet. Route through FindMapping so its type-chain walk
22          // materializes the parent, populates _features for the subclass,
23          // and we can complete the lookup correctly. If that still doesn't
24          // produce a feature entry the type is genuinely a top-level
25          // mapping and MappingFor.Schema is the right answer.
26          FindMapping(featureType);
27          if (_features.Value.TryFind(featureType, out schema))
28          {
29              return schema;
30          }
31  
32          return MappingFor(featureType).Schema;
33      }

