 1      private void assertNoDuplicateDocumentAliases()
 2      {
 3          var duplicates =
 4              AllDocumentMappings.Where(x => !x.StructuralTyped)
 5                  .GroupBy(x => $"{x.DatabaseSchemaName}.{x.Alias}")
 6                  .Where(x => x.Count() > 1)
 7                  .ToArray();
 8  
 9          if (duplicates.Length != 0)
10          {
11              var message = duplicates
12                      // We are making it legal to use the same document alias across different schemas
13                  .Select(group =>
14              {
15                  return
16                      $"Document types {group.Select(x => x.DocumentType.FullName!).Join(", ")} all have the same document alias '{group.Key}'. You must explicitly make document type aliases to disambiguate the database schema objects";
17              }).Join("\n");
18  
19              throw new AmbiguousDocumentTypeAliasesException(message);
20          }
21      }

