 1      internal IDocumentMapping FindMapping(Type documentType)
 2      {
 3          ArgumentNullException.ThrowIfNull(documentType);
 4  
 5          if (!_mappings.Value.TryFind(documentType, out var value))
 6          {
 7              // 9.0: BuildAllMappings is no longer eager (#4303), so a subclass
 8              // looked up on its own (without the parent ever being touched)
 9              // wouldn't show up in AllDocumentMappings. Walk the type chain
10              // and the implemented-interfaces set, force-materializing any
11              // registered ancestor so its SubClasses declarations populate.
12              // This is targeted: we only materialize candidates that the
13              // queried type actually inherits from, not every builder.
14              for (var ancestor = documentType.BaseType;
15                   ancestor != null && ancestor != typeof(object);
16                   ancestor = ancestor.BaseType)
17              {
18                  if (_builders.Value.TryFind(ancestor, out _))
19                  {
20                      MappingFor(ancestor);
21                  }
22              }
