 1      internal void BuildAllMappings()
 2      {
 3          foreach (var pair in _builders.Value.ToArray())
 4          {
 5              // 9.0: DeadLetterEvent is registered unconditionally in
 6              // ApplyConfiguration but is only meant to participate in schema
 7              // generation when the event store is active (#4303). The eager
 8              // pre-#4303 path skipped this implicitly because materialization
 9              // was driven by AllActiveFeatures' conditional MappingFor call;
10              // now that we're forcing materialization explicitly, replicate
11              // that gate here so we don't conjure a dlq table for stores that
12              // never use the event store.
13              if (pair.Key == typeof(DeadLetterEvent)
14                  && !_options.Events.As<EventGraph>().IsActive(_options))
15              {
16                  continue;
17              }
18  
19              // Just forcing them all to be built
20              FindMapping(pair.Key);
21          }
22  
23          // This needs to be done second so that it can pick up any subclass
24          // relationships. #5351: a published type backed by custom projection storage still
25          // materializes here -- PublishedTypes() is deliberately untouched -- but MappingFor
26          // marks its mapping SkipSchemaGeneration so no mt_doc_ table is emitted for it.
27          foreach (var documentType in _options.Projections.AllPublishedTypes()) FindMapping(documentType);
28      }

