 1          public MartenConfigurationExpression AddAsyncDaemon(DaemonMode mode)
 2          {
 3              Services.ConfigureMarten(opts => opts.Projections.AsyncMode = mode);
 4  
 5              // Only Solo/HotCold mean "this process hosts the daemon". Disabled hosts nothing, and
 6              // ExternallyManaged (jasperfx#490) means an external system (e.g. Wolverine's managed
 7              // event-subscription distribution) executes the async projections — Marten must not
 8              // register its own coordination for either.
 9              // marten#5056: guard against a repeated AddAsyncDaemon() call registering a second
10              // IHostedService forwarding to the same coordinator singleton. The host would call
11              // StopAsync twice on it at shutdown, and the second pass used to fan StopAllAsync out
12              // over daemons the first pass had already disposed (the marten#5055 error-log storm).
13              if (mode is DaemonMode.Solo or DaemonMode.HotCold && !Services.Any(x =>
14                      x.ServiceType == typeof(Marten.Events.Daemon.Coordination.IProjectionCoordinator) &&
15                      x.ImplementationType == typeof(ProjectionCoordinator)))
16              {
17                  Services.AddSingleton<Marten.Events.Daemon.Coordination.IProjectionCoordinator, ProjectionCoordinator>();
18                  Services.AddSingleton<IHostedService>(s => s.GetRequiredService<Marten.Events.Daemon.Coordination.IProjectionCoordinator>());
19                  // jasperfx#430 — also resolve the JasperFx.Events base interface, so a stock host can
20                  // GetService<JasperFx.Events.Daemon.IProjectionCoordinator>() directly instead of walking
21                  // the registered IHostedServices for one.
22                  Services.AddSingleton<JasperFx.Events.Daemon.IProjectionCoordinator>(s => s.GetRequiredService<Marten.Events.Daemon.Coordination.IProjectionCoordinator>());
23              }
24  
25              return this;
26          }

