 5          services.AddSingleton<IDocumentStoreSource, DocumentStoreSource<T>>();
 6  
 7          services.AddSingleton<ISystemPart, MartenSystemPart<T>>();
 8  
 9          services.AddSingleton<IEventStore>(s => (IEventStore)s.GetRequiredService<T>());
10          services.AddSingleton<IDocumentStoreUsageSource>(s => (IDocumentStoreUsageSource)s.GetRequiredService<T>());
11          services.AddSingleton<IDocumentStoreDiagnostics>(s => (IDocumentStoreDiagnostics)s.GetRequiredService<T>());
12          // #5543: an ancillary store carries its own Subject, so a console holding several
13          // IDocumentStoreDiagnosticsWriter instances can still tell which store each one writes to.
14          services.AddSingleton<IDocumentStoreDiagnosticsWriter>(s => (IDocumentStoreDiagnosticsWriter)s.GetRequiredService<T>());
15  
16          // #5394 (jasperfx#825): an ancillary store derives its own View slices, resolved through its
17          // marker type. Registered per store rather than once over every IEventStore in the container
18          // for the same reason AddMarten's is: the marker is what says WHICH store, and only this
19          // method knows it. Two sources emitting a slice for the same document type is harmless --
20          // slices merge by name, which is what naming them after the document is for.
21          services.AddEventModelSource(new MartenProjectionEventModelSource(s => s.GetRequiredService<T>()));
22  
23          var instrument = new SetEventStoreInstrumentation<T>();
24          services.AddSingleton<IConfigureMarten<T>>(instrument);
25          services.AddSingleton<IEventStoreInstrumentation>(instrument);
26  
27          var stores = services
28              .Where(x => !x.IsKeyedService)
29              .Select(x => x.ImplementationInstance)
30              .OfType<SecondaryDocumentStores>().FirstOrDefault();
31  
32          if (stores == null)
33          {
34              stores = new SecondaryDocumentStores();
35              services.AddSingleton(stores);
36          }
37  
38          services.AddSingleton<IDatabaseSource>(s => s.GetRequiredService<T>().As<DocumentStore>().Tenancy);
39  
40          var config = new SecondaryStoreConfig<T>(configure);
41          stores.Add(config);
42  
43          services.AddSingleton<T>(s => config.Build(s));
44          services.AddSingleton<Lazy<T>>(s => new Lazy<T>(() => s.GetRequiredService<T>()));
45          services.AddSingleton<Func<T, IStorageOperations>>(_ => store => (IStorageOperations)store.LightweightSession());
46  
47          // Default keyed session factory for the ancillary store
48          services.AddKeyedSingleton<ISessionFactory>(typeof(T), (sp, _) =>
49          {
50              var store = (IDocumentStore)sp.GetRequiredService<T>();
51              return new LightweightSessionFactory(store);
52          });
53  
54          services.AddSingleton<IMasterTableMultiTenancy>(s => (IMasterTableMultiTenancy)s.GetRequiredService<T>());
55  
56          return new MartenStoreExpression<T>(services);
57      }

