 1      static string ParseFilePath(Uri address)
 2      {
 3          if (address.Scheme != "urn")
 4              throw new ArgumentException("The address must be a urn");
 5  
 6          var parts = address.Segments[0].Split(':');
 7          if (parts[0] != "file")
 8              throw new ArgumentException("The address must be a urn:file");
 9  
10          var length = parts.Length - 1;
11          var elements = new string[length];
12          Array.Copy(parts, 1, elements, 0, length);
13  
14          return Path.Combine(elements);
15      }

