 1          public string FormatSubscriptionName(string subscriptionName)
 2          {
 3              string name;
 4              if (subscriptionName.Length > 50)
 5              {
 6                  string hashed;
 7                  using (var hasher = SHA1.Create())
 8                  {
 9                      var buffer = Encoding.UTF8.GetBytes(subscriptionName);
10                      var hash = hasher.ComputeHash(buffer);
11                      hashed = FormatUtil.Formatter.Format(hash).Substring(0, 6);
12                  }
13  
14                  name = $"{subscriptionName.Substring(0, 43)}-{hashed}";
15              }
16              else
17                  name = subscriptionName;
18  
19              return name;
20          }

