 2          {
 3              using var pop = _scopeContext.PushConsumeContext(context);
 4  
 5              var timer = Stopwatch.StartNew();
 6  
 7              if (!context.IsMessageConsumed)
 8              {
 9                  await _next.Send(context).ConfigureAwait(false);
10  
11                  await context.ConsumeCompleted.ConfigureAwait(false);
12  
13                  try
14                  {
15                      await context.SetConsumed().ConfigureAwait(false);
16                  }
17                  catch (Exception exception)
