19                      if (!context.ReceiveContext.IsFaulted)
20                          await context.NotifyFaulted(timer.Elapsed, TypeCache<TMessage>.ShortName, exception).ConfigureAwait(false);
21  
22                      throw;
23                  }
24  
25                  return;
26              }
27  
28              if (!context.IsOutboxDelivered)
29              {
30                  await DeliverOutboxMessages(context).ConfigureAwait(false);
31  
32                  await context.ConsumeCompleted.ConfigureAwait(false);
33  
34                  return;
35              }
36  
37              await context.RemoveOutboxMessages().ConfigureAwait(false);
38  
39              LogContext.Debug?.Log("Outbox Completed: {MessageId} ({ReceiveCount})", context.MessageId, context.ReceiveCount);
40  
41              if (context.ReceiveContext is { IsDelivered: false, IsFaulted: false })
42                  await context.NotifyConsumed(context, timer.Elapsed, _options.ConsumerType).ConfigureAwait(false);
43  
44              context.ContinueProcessing = false;
45          }

