 1          internal StackTraceUsage PrecalculateStackTraceUsage()
 2          {
 3              var stackTraceUsage = StackTraceUsage.None;
 4  
 5              // find all objects which may need stack trace
 6              // and determine maximum
 7              if (Target != null)
 8              {
 9                  stackTraceUsage = Target.StackTraceUsage;
10              }
11  
12              //recurse into chain if not max
13              if (NextInChain != null && (stackTraceUsage & StackTraceUsage.Max) != StackTraceUsage.Max)
14              {
15                  var stackTraceUsageForChain = NextInChain.PrecalculateStackTraceUsage();
16                  stackTraceUsage |= stackTraceUsageForChain;
17              }
18  
19              StackTraceUsage = stackTraceUsage;
20              return stackTraceUsage;
21          }

