 1          private AsyncLogEventInfo WrapWithRetry(AsyncLogEventInfo logEvent, Func<int, bool> sleepBeforeRetry)
 2          {
 3              AsyncContinuation? continuation = null;
 4              int counter = 0;
 5  
 6              continuation = ex =>
 7              {
 8                  if (ex is null)
 9                  {
10                      logEvent.Continuation(null);
11                      return;
12                  }
13  
14                  int retryNumber = Interlocked.Increment(ref counter);
15                  var retryCount = RetryCount.RenderValue(logEvent.LogEvent);
16                  var retryDelayMilliseconds = RetryDelayMilliseconds.RenderValue(logEvent.LogEvent);
17                  InternalLogger.Warn(ex, "{0}: Error while writing to '{1}'. Try {2}/{3}", this, WrappedTarget, retryNumber, retryCount);
18  
19                  // exceeded retry count
20                  if (retryNumber >= retryCount)
21                  {
22                      InternalLogger.Warn("{0}: Too many retries. Aborting.", this);
23                      logEvent.Continuation(ex);
24                      return;
25                  }
26  
27                  // sleep and try again (Check every 100 ms if target have been closed)
28                  if (sleepBeforeRetry(retryNumber))
29                  {
30                      for (int i = 0; i < retryDelayMilliseconds;)
31                      {
32                          int retryDelay = Math.Min(100, retryDelayMilliseconds - i);
33                          AsyncHelpers.WaitForDelay(TimeSpan.FromMilliseconds(retryDelay));
34                          i += retryDelay;
35                          if (!IsInitialized)
36                          {
37                              InternalLogger.Warn("{0}): Target closed. Aborting.", this);
38                              logEvent.Continuation(ex);
39                              return;
40                          }
41                      }
42                  }
43  
44                  WrappedTarget?.WriteAsyncLogEvent(continuation is null ? logEvent : logEvent.LogEvent.WithContinuation(continuation));
45              };
46  
47              return logEvent.LogEvent.WithContinuation(continuation);
48          }

