 2          {
 3              // We only want to wait for the operations currently in progress (not the future operations)
 4              int remainingCompletionCounter = System.Threading.Interlocked.Increment(ref _pendingOperationCounter);
 5              if (remainingCompletionCounter <= 1)
 6              {
 7                  // No active operations
 8                  if (NotifyCompletion(null) < 0)
 9                  {
10                      System.Threading.Interlocked.Exchange(ref _pendingOperationCounter, 0);
11                  }
12                  return asyncContinuation;
13              }
14              else
15              {
16                  lock (_pendingCompletionList)
17                  {
18                      if (NotifyCompletion(null) <= 0)
19                      {
20                          return asyncContinuation;   // No active operations
21                      }
22  
23                      var pendingCompletion = new LinkedListNode<AsyncContinuation?>(null);
24                      _pendingCompletionList.AddLast(pendingCompletion);
25                      remainingCompletionCounter = System.Threading.Interlocked.Increment(ref _pendingOperationCounter);
26                      if (remainingCompletionCounter <= 0)
27                      {
28                          remainingCompletionCounter = 1;
29                      }
30  
31                      pendingCompletion.Value = (ex) =>
32                      {
33                          if (System.Threading.Interlocked.Decrement(ref remainingCompletionCounter) == 0)
34                          {
35                              lock (_pendingCompletionList)
36                              {
37                                  _pendingCompletionList.Remove(pendingCompletion);
38                                  NotifyCompletion(ex);
39                              }
40  
41                              asyncContinuation(ex);
42                          }
43                      };
44  
45                      return pendingCompletion.Value;
46                  }
47              }
48          }

