 1          private int NotifyCompletion(Exception? exception)
 2          {
 3              int pendingOperations = System.Threading.Interlocked.Decrement(ref _pendingOperationCounter);
 4  
 5              if (_pendingCompletionList.Count > 0)
 6              {
 7                  lock (_pendingCompletionList)
 8                  {
 9                      var nodeNext = _pendingCompletionList.First;
10                      while (nodeNext != null)
11                      {
12                          var nodeValue = nodeNext.Value;
