 1          private static AsyncContinuation CreateCountedContinuation(AsyncContinuation originalContinuation, int targetCounter)
 2          {
 3              IList<Exception>? exceptions = null;
 4  
 5              AsyncContinuation wrapper =
 6                  ex =>
 7                  {
 8                      if (ex != null)
 9                      {
10                          if (exceptions is null)
11                          {
12                              Interlocked.CompareExchange(ref exceptions, new List<Exception>(), null);
13                          }
14                          lock (exceptions)
15                          {
16                              exceptions.Add(ex);
17                          }
18                      }
19  
20                      int pendingTargets = Interlocked.Decrement(ref targetCounter);
21                      if (pendingTargets == 0)
22                      {
23                          var combinedException = AsyncHelpers.GetCombinedException(exceptions ?? Internal.ArrayHelper.Empty<Exception>());
24                          InternalLogger.Trace("SplitGroup: Combined exception: {0}", combinedException);
25                          originalContinuation(combinedException);
26                      }
27                      else
28                      {
29                          InternalLogger.Trace("SplitGroup: {0} remaining.", pendingTargets);
30                      }
31                  };
32  
33              return wrapper;
34          }

