 1          protected override void Write(IList<AsyncLogEventInfo> logEvents)
 2          {
 3              InternalLogger.Trace("{0}: Writing {1} events", this, logEvents.Count);
 4  
 5              if (logEvents.Count == 1)
 6              {
 7                  Write(logEvents[0]);    // Skip array allocation for each destination target
 8              }
 9              else if (Targets.Count == 0 || logEvents.Count == 0)
10              {
11                  for (int i = 0; i < logEvents.Count; ++i)
12                  {
13                      logEvents[i].Continuation(null);
14                  }
15              }
16              else
17              {
18                  if (Targets.Count > 1)
19                  {
20                      for (int i = 0; i < logEvents.Count; ++i)
21                      {
22                          AsyncLogEventInfo ev = logEvents[i];
23                          logEvents[i] = ev.LogEvent.WithContinuation(CreateCountedContinuation(ev.Continuation, Targets.Count));
24                      }
25                  }
26  
27                  for (int i = 0; i < Targets.Count; ++i)
28                  {
29                      InternalLogger.Trace("{0}: Sending {1} events to {2}", this, logEvents.Count, Targets[i]);
30  
31                      var targetLogEvents = logEvents;
32                      if (i < Targets.Count - 1)
33                      {
34                          // WriteAsyncLogEvents will modify the input-array (so we make clones here)
35                          AsyncLogEventInfo[] cloneLogEvents = new AsyncLogEventInfo[logEvents.Count];
36                          logEvents.CopyTo(cloneLogEvents, 0);
37                          targetLogEvents = cloneLogEvents;
38                      }
39  
40                      Targets[i].WriteAsyncLogEvents(targetLogEvents);
41                  }
42              }
43          }

