 2          {
 3              try
 4              {
 5                  //stop timer on domain unload, otherwise:
 6                  //Exception: System.AppDomainUnloadedException
 7                  //Message: Attempted to access an unloaded AppDomain.
 8                  InternalLogger.Info("AppDomain Shutting down. LogFactory closing...");
 9                  bool closeConfig = true;
10                  if (PlatformDetector.IsWin32)
11                  {
12                      // Domain-Unload has to complete in about 2 secs on Windows-platform, before being terminated.
13                      // Other platforms like Linux will fail when trying to spin up new threads at domain unload.
14                      closeConfig = FlushInternal(TimeSpan.FromMilliseconds(1500), null);
