16  
17                  DisposeInternal(closeConfig);
18              }
19              catch (Exception ex)
20              {
21                  if (ex.MustBeRethrownImmediately())
22                      throw;
23  
24                  InternalLogger.Error(ex, "LogFactory failed to close down.");
25              }
26          }

