 1          private bool FlushInternal(TimeSpan flushTimeout, AsyncContinuation? asyncContinuation)
 2          {
 3              InternalLogger.Debug("LogFactory Starting Flush with timeout={0} secs", flushTimeout.TotalSeconds);
 4  
 5              try
 6              {
 7                  LoggingConfiguration? config;
 8                  lock (_syncRoot)
 9                  {
10                      config = _config;   // Flush should not attempt to auto-load Configuration
11                      if (!_configLoaded)
12                          config = null;
13                  }
14  
15                  if (config is null)
16                  {
17                      asyncContinuation?.Invoke(null);
18                      return true;
19                  }
20  
21                  asyncContinuation = asyncContinuation is null ? null : NLog.Common.AsyncHelpers.PreventMultipleCalls(asyncContinuation);
22  
23                  using (var waitForFlush = new ManualResetEvent(false))
24                  {
25                      var ev = waitForFlush;
26                      var flushTimeoutHandler = config.FlushAllTargets((ex) => { asyncContinuation?.Invoke(ex); ev?.Set(); });
27                      if (flushTimeoutHandler is null)
28                      {
29                          asyncContinuation?.Invoke(null);
30                          return true;
31                      }
32                      else
33                      {
34                          bool flushCompleted = waitForFlush.WaitOne(flushTimeout);
35                          ev = null;  // Avoid object-disposed on late flush completion
36                          flushTimeoutHandler.Invoke(null);
37                          asyncContinuation?.Invoke(flushCompleted ? null : new NLogRuntimeException("LogFactory Flush Timeout"));
38                          return flushCompleted;
39                      }
40                  }
41              }
42              catch (Exception ex)
43              {
44                  InternalLogger.Error(ex, "LogFactory failed to flush targets.");
45                  asyncContinuation?.Invoke(ex);
46                  return false;
47              }
48          }

