10              else if (inputParameters.Count == 1)
11              {
12                  Func<LogEventInfo, object?, object?>? method = _configurationItemFactory.ConditionMethodFactory.TryCreateInstanceWithOneParameter(functionName);
13                  if (method != null)
14                      return ConditionMethodExpression.CreateMethodOneParameter(functionName, method, inputParameters);
15              }
16              else if (inputParameters.Count == 2)
17              {
18                  Func<LogEventInfo, object?, object?, object?>? method = _configurationItemFactory.ConditionMethodFactory.TryCreateInstanceWithTwoParameters(functionName);
19                  if (method != null)
20                      return ConditionMethodExpression.CreateMethodTwoParameters(functionName, method, inputParameters);
