22              else if (inputParameters.Count == 3)
23              {
24                  Func<LogEventInfo, object?, object?, object?, object?>? method = _configurationItemFactory.ConditionMethodFactory.TryCreateInstanceWithThreeParameters(functionName);
25                  if (method != null)
26                      return ConditionMethodExpression.CreateMethodThreeParameters(functionName, method, inputParameters);
27              }
28  
29              Func<object?[], object?>? manyParameterMethod = _configurationItemFactory.ConditionMethodFactory.TryCreateInstanceWithManyParameters(functionName, out var manyParameterMinCount, out var manyParameterMaxCount, out var manyParameterWithLogEvent);
