 1          public static string NormalizeName(string itemName)
 2          {
 3              if (itemName is null)
 4              {
 5                  return string.Empty;
 6              }
 7  
 8              var delimitIndex = itemName.IndexOf('-');
 9              if (delimitIndex < 0)
10              {
11                  return itemName;
12              }
13  
14              // Only for the first comma
15              var commaIndex = itemName.IndexOf(',');
16              if (commaIndex >= 0)
17              {
18                  var left = itemName.Substring(0, commaIndex).Replace("-", string.Empty);
19                  var right = itemName.Substring(commaIndex);
20                  return left + right;
21              }
22  
23              return itemName.Replace("-", string.Empty);
24          }

