 1      private async Task ServeAsync(Socket socket)
 2      {
 3          try
 4          {
 5              socket.NoDelay = true;
 6              using var stream = new NetworkStream(socket, ownsSocket: true);
 7  
 8              // one pipe each way, which is what RunClientAsync expects
 9              var input = PipeReader.Create(stream);
10              var output = PipeWriter.Create(stream);
11              await Server.RunClientAsync(new DuplexPipe(input, output));
12          }
13          catch (Exception ex) when (ex is System.IO.IOException or ObjectDisposedException or SocketException)
14          {
15              // an ordinary disconnect; the soak causes plenty of them on purpose
16          }
17          catch (Exception ex)
18          {
19              Console.WriteLine($"client faulted: {ex.GetType().Name}: {ex.Message}");
20          }
21      }

