 1          static bool ProcessHighIntegrityResponseToken(Message message, ReadOnlySpan<byte> frame, PhysicalConnection? connection)
 2          {
 3              bool isValid = false;
 4              var reader = new RespReader(frame); // no services needed: never leases
 5              if ((reader.SafeTryMoveNext() & reader.IsScalar)
 6                  && reader.ScalarLength() is 4)
 7              {
 8                  uint interpreted;
 9                  if (reader.TryGetSpan(out var span))
10                  {
11                      interpreted = BinaryPrimitives.ReadUInt32LittleEndian(span);
12                  }
13                  else
14                  {
15                      Span<byte> tmp = stackalloc byte[4];
16                      reader.CopyTo(tmp);
17                      interpreted = BinaryPrimitives.ReadUInt32LittleEndian(tmp);
18                  }
19                  isValid = interpreted == message.HighIntegrityToken;
20              }
21              if (isValid)
22              {
23                  message.Complete(connection);
24                  return true;
25              }
26              else
27              {
28                  message.SetExceptionAndComplete(new InvalidOperationException("High-integrity mode detected possible protocol de-sync"), connection);
29                  return false;
30              }
31          }

