 1      private void OnResponseFrame(RespPrefix prefix, ReadOnlySpan<byte> frame, ref IMemoryOwner<byte>? memoryOwner)
 2      {
 3          DebugValidateSingleFrame(frame);
 4          _readStatus = ReadStatus.MatchResult;
 5  
 6          switch (prefix)
 7          {
 8              case RespPrefix.Push: // explicit RESP3 push message
 9              case RespPrefix.Array when ((_protocol is RedisProtocol.Resp2) & (connectionType is ConnectionType.Subscription))
10                                         && !IsArrayPong(frame): // could be a RESP2 pub/sub payload
11                  // out-of-band; pub/sub etc
12                  switch (OnOutOfBand(frame, ref memoryOwner))
13                  {
14                      case OutOfBandResult.Handled:
15                          OnDetailLog($"out-of-band message, not dequeuing: {prefix}");
16                          return;
17                      case OutOfBandResult.NotRecognized when prefix is RespPrefix.Push:
18                          // a RESP3 push frame is out-of-band *by definition*; if we don't recognize it
19                          // (newer server, or a feature we don't implement) we drop it - matching it to a
20                          // pending command would desynchronize the entire response stream
21                          OnDetailLog($"unrecognized out-of-band message, dropped: {prefix}");
22                          return;
23                  }
24                  break;
25          }
26  
27          // request/response; match to inbound
28          MatchNextResult(frame);
29  
30          static bool IsArrayPong(ReadOnlySpan<byte> payload)
31          {
32              if (payload.Length >= sizeof(ulong))
33              {
34                  var hash = AsciiHash.HashCS(payload);
35                  switch (hash)
36                  {
37                      case ArrayPong_LC_Bulk.HashCS when payload.StartsWith(ArrayPong_LC_Bulk.U8):
38                      case ArrayPong_UC_Bulk.HashCS when payload.StartsWith(ArrayPong_UC_Bulk.U8):
39                      case ArrayPong_LC_Simple.HashCS when payload.StartsWith(ArrayPong_LC_Simple.U8):
40                      case ArrayPong_UC_Simple.HashCS when payload.StartsWith(ArrayPong_UC_Simple.U8):
41                          var reader = new RespReader(payload); // no services needed: never leases
42                          return reader.SafeTryMoveNext() // have root
43                                 && reader.Prefix == RespPrefix.Array // root is array
44                                 && reader.SafeTryMoveNext() // have first child
45                                 && (reader.IsInlneCpuUInt32(pong) || reader.IsInlneCpuUInt32(PONG)); // pong
46                  }
47              }
48  
49              return false;
50          }
51      }

