30              // another formatter glitch
31              while (CommitAndParseFrames(read) && !ForceReconnect);
32  
33              _readStatus = ReadStatus.ProcessBufferComplete;
34  
35              // Volatile.Write(ref _readStatus, ReaderCompleted);
36              _readBuffer.Release(); // clean exit, we can recycle
37              _readStatus = ReadStatus.RanToCompletion;
38              RecordConnectionFailed(ConnectionFailureType.SocketClosed);
39          }
