 1              public override async ValueTask<Stream?> BeforeAuthenticateAsync(EndPoint endpoint, ConnectionType connectionType, Socket? socket, CancellationToken cancellationToken)
 2              {
 3                  if (socket is not null)
 4                  {
 5                      var encoding = Encoding.ASCII;
 6                      var ep = Format.ToString(endpoint);
 7                      const string Prefix = "CONNECT ", Suffix = " HTTP/1.1\r\n\r\n", ExpectedResponse1 = "HTTP/1.1 200 OK\r\n\r\n", ExpectedResponse2 = "HTTP/1.1 200 Connection established\r\n\r\n";
 8                      byte[] chunk = ArrayPool<byte>.Shared.Rent(Math.Max(
 9                          encoding.GetByteCount(Prefix) + encoding.GetByteCount(ep) + encoding.GetByteCount(Suffix),
10                          Math.Max(encoding.GetByteCount(ExpectedResponse1), encoding.GetByteCount(ExpectedResponse2))));
11                      var offset = 0;
12                      offset += encoding.GetBytes(Prefix, 0, Prefix.Length, chunk, offset);
13                      offset += encoding.GetBytes(ep, 0, ep.Length, chunk, offset);
14                      offset += encoding.GetBytes(Suffix, 0, Suffix.Length, chunk, offset);
15  
16                      await socket.SendAsync(chunk.AsMemory(0, offset), SocketFlags.None, cancellationToken).ForAwait();
17  
18                      // we expect to see: "HTTP/1.1 200 OK\n"; note our buffer is definitely big enough already
19                      int toRead = Math.Max(encoding.GetByteCount(ExpectedResponse1), encoding.GetByteCount(ExpectedResponse2)), read;
20                      offset = 0;
21  
22                      var actualResponse = "";
23                      while (toRead > 0 && !actualResponse.EndsWith("\r\n\r\n"))
24                      {
25                          read = await socket.ReceiveAsync(chunk.AsMemory(offset, toRead), SocketFlags.None, cancellationToken).ForAwait();
26                          if (read <= 0) break; // EOF (since we're never doing zero-length reads)
27                          toRead -= read;
28                          offset += read;
29  
30                          actualResponse = encoding.GetString(chunk, 0, offset);
31                      }
32                      if (toRead != 0 && !actualResponse.EndsWith("\r\n\r\n")) throw new EndOfStreamException("EOF negotiating HTTP tunnel");
33                      // lazy
34                      if (ExpectedResponse1 != actualResponse && ExpectedResponse2 != actualResponse)
35                      {
36                          throw new InvalidOperationException("Unexpected response negotiating HTTP tunnel");
37                      }
38                      ArrayPool<byte>.Shared.Return(chunk);
39                  }
40                  return default; // no need for custom stream wrapper here
41              }

