 1          internal static string GetUtf8String(in ReadOnlySequence<byte> buffer)
 2          {
 3              if (buffer.IsEmpty) return "(empty)";
 4              char[] lease = null;
 5              var maxLen = Encoding.UTF8.GetMaxCharCount(checked((int)buffer.Length));
 6              Span<char> target = maxLen <= 128 ? stackalloc char[128] : (lease = ArrayPool<char>.Shared.Rent(maxLen));
 7              int charCount = 0;
 8              if (buffer.IsSingleSegment)
 9              {
10                  charCount = Encoding.UTF8.GetChars(buffer.First.Span, target);
11              }
12              else
13              {
14                  foreach (var segment in buffer)
15                  {
16                      charCount += Encoding.UTF8.GetChars(segment.Span, target.Slice(charCount));
17                  }
18              }
19  
20              const string CR = "\u240D", LF = "\u240A", CRLF = CR + LF;
21              string s = target.Slice(0, charCount).ToString()
22                  .Replace("\r\n", CRLF).Replace("\r", CR).Replace("\n", LF);
23              if (lease is not null) ArrayPool<char>.Shared.Return(lease);
24              return s;
25          }

