 1          private static Dictionary<AsciiHash, RespCommand> BuildCommands(RespServer server)
 2          {
 3              static RedisCommandAttribute CheckSignatureAndGetAttribute(MethodInfo method)
 4              {
 5                  if (method.ReturnType != typeof(TypedRedisValue)) return null;
 6                  var p = method.GetParameters();
 7                  if (p.Length != 2 || p[0].ParameterType != typeof(RedisClient) || p[1].ParameterType != typeof(RedisRequest).MakeByRefType())
 8                      return null;
 9                  return (RedisCommandAttribute)Attribute.GetCustomAttribute(method, typeof(RedisCommandAttribute));
10              }
11  
12              var grouped = (
13                      from method in server.GetType()
14                          .GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
15                      let attrib = CheckSignatureAndGetAttribute(method)
16                      where attrib != null
17                      select new RespCommand(attrib, method, server))
18                  .GroupBy(x => new AsciiHash(x.Command.ToUpperInvariant()), AsciiHash.CaseSensitiveEqualityComparer);
19  
20              var result = new Dictionary<AsciiHash, RespCommand>(AsciiHash.CaseSensitiveEqualityComparer);
21              foreach (var grp in grouped)
22              {
23                  RespCommand parent;
24                  if (grp.Any(x => x.IsSubCommand))
25                  {
26                      var subs = grp.Where(x => x.IsSubCommand).ToArray();
27                      parent = grp.SingleOrDefault(x => !x.IsSubCommand).WithSubCommands(subs);
28                  }
29                  else
30                  {
31                      parent = grp.Single();
32                  }
33  
34                  Debug.WriteLine($"Registering: {grp.Key}");
35                  result.Add(grp.Key, parent);
36              }
37              return result;
38          }

