 1      internal void UnsubscribeAll(RedisCommand cmd)
 2      {
 3          var subs = Subscriptions;
 4          if (subs is null) return;
 5          RedisChannel[] remove;
 6          int count = 0;
 7          string msg;
 8          lock (subs)
 9          {
10              remove = ArrayPool<RedisChannel>.Shared.Rent(count);
11              foreach (var pair in subs)
12              {
13                  var key = pair.Key;
14                  if (cmd switch
15                      {
16                          RedisCommand.UNSUBSCRIBE when !(pair.Key.IsPattern | pair.Key.IsSharded) => true,
17                          RedisCommand.PUNSUBSCRIBE when pair.Key.IsPattern => true,
18                          RedisCommand.SUNSUBSCRIBE when pair.Key.IsSharded => true,
19                          _ => false,
20                      })
21                  {
22                      remove[count++] = key;
23                  }
24              }
25  
26              foreach (var key in remove.AsSpan(0, count))
27              {
28                  _subscriptions.Remove(key);
29              }
30  
31              switch (cmd)
32              {
33                  case RedisCommand.SUNSUBSCRIBE:
34                      msg = "sunsubscribe";
35                      shardedCount = 0;
36                      break;
37                  case RedisCommand.PUNSUBSCRIBE:
38                      msg = "punsubscribe";
39                      patternCount = 0;
40                      break;
41                  case RedisCommand.UNSUBSCRIBE:
42                      msg = "unsubscribe";
43                      simpleCount = 0;
44                      break;
45                  default:
46                      msg = "";
47                      break;
48              }
49          }
50          foreach (var key in remove.AsSpan(0, count))
51          {
52              SendSubUnsubMessage(msg, key, 0);
53          }
54          ArrayPool<RedisChannel>.Shared.Return(remove);
55      }

