 1      internal int UnsubscribeMigratedSlot(int hashSlot)
 2      {
 3          var subs = SubscriptionsIfAny;
 4          if (subs is null) return 0;
 5  
 6          List<RedisChannel> affected = null;
 7          lock (subs)
 8          {
 9              foreach (var pair in subs)
10              {
11                  var channel = pair.Key;
12                  if (channel.IsSharded && ServerSelectionStrategy.GetClusterSlot((byte[])channel) == hashSlot)
13                  {
14                      (affected ??= new()).Add(channel);
15                  }
16              }
17          }
18  
19          if (affected is null) return 0;
20          foreach (var channel in affected)
21          {
22              Unsubscribe(channel); // removes it *and* sends the push, exactly as a client-issued one would
23          }
24  
25          return affected.Count;
26      }

