 1      private TypedRedisValue SubscribeImpl(RedisClient client, in RedisRequest request, RedisCommand cmd)
 2      {
 3          bool add = cmd is RedisCommand.SUBSCRIBE or RedisCommand.PSUBSCRIBE or RedisCommand.SSUBSCRIBE;
 4          var options = cmd switch
 5          {
 6              RedisCommand.SUBSCRIBE or RedisCommand.UNSUBSCRIBE => RedisChannel.RedisChannelOptions.None,
 7              RedisCommand.PSUBSCRIBE or RedisCommand.PUNSUBSCRIBE => RedisChannel.RedisChannelOptions.Pattern,
 8              RedisCommand.SSUBSCRIBE or RedisCommand.SUNSUBSCRIBE => RedisChannel.RedisChannelOptions.Sharded,
 9              _ => throw new ArgumentOutOfRangeException(nameof(cmd)),
10          };
11  
12          // buffer the slots while checking validity
13          var subCount = request.Count - 1;
14          if (subCount == 0 & !add)
15          {
16              client.UnsubscribeAll(cmd);
17          }
18          else
19          {
20              var lease = ArrayPool<RedisChannel>.Shared.Rent(subCount);
21              try
22              {
23                  var channel = lease[0] = request.GetChannel(1, options);
24                  int slot = channel.IsSharded
25                      ? ServerSelectionStrategy.GetClusterSlot(channel)
26                      : ServerSelectionStrategy.NoSlot;
27                  if (!client.Node.HasSlot(slot)) KeyMovedException.Throw(slot);
28                  for (int i = 2; i <= subCount; i++)
29                  {
30                      channel = lease[i - 1] = request.GetChannel(i, options);
31                      if (slot != ServerSelectionStrategy.NoSlot &&
32                          slot != ServerSelectionStrategy.GetClusterSlot(channel))
33                      {
34                          CrossSlotException.Throw();
35                      }
36                  }
37  
38                  for (int i = 0; i < subCount; i++)
39                  {
40                      if (add) client.Subscribe(lease[i]);
41                      else client.Unsubscribe(lease[i]);
42                  }
43              }
44              finally
45              {
46                  ArrayPool<RedisChannel>.Shared.Return(lease);
47              }
48          }
49  
50          return TypedRedisValue.Nil;
51      }

