 1      [RedisCommand(3)]
 2      protected virtual TypedRedisValue SPublish(RedisClient client, in RedisRequest request)
 3      {
 4          var channel = request.GetChannel(1, RedisChannel.RedisChannelOptions.Sharded);
 5          var node = client.Node; // filter to clients on the same node
 6          var slot = ServerSelectionStrategy.GetClusterSlot((byte[])channel);
 7          if (!node.HasSlot(slot)) KeyMovedException.Throw(slot);
 8  
 9          // note the node: without it pair.Node is null, ReferenceEquals never matches, and sharded publish
10          // silently delivers to nobody - which is how it behaved until 2026-08-26
11          PublishPair pair = new(channel, request.GetValue(2), node);
12          int count = ForAllClients(pair, static (client, pair) =>
13              ReferenceEquals(client.Node, pair.Node) ? client.Publish(pair.Channel, pair.Value) : 0);
14          return TypedRedisValue.Integer(count);
15      }

