15                  foreach (var member in commandFlags.GetMembers("FireAndForget"))
16                  {
17                      if (member is IFieldSymbol { HasConstantValue: true, ConstantValue: int value })
18                      {
19                          fireAndForget = value;
20                          break;
21                      }
22                  }
23              }
