32                  }
33              }
34  
35              return new KnownSymbols(
36                  blockingHelpers,
37                  redisAsync,
38                  batch,
39                  transactionAsync,
40                  compilation.GetTypeByMetadataName("StackExchange.Redis.ITransaction"),
41                  commandFlags,
42                  compilation.GetTypeByMetadataName("System.Threading.Tasks.Task"),
43                  fireAndForget);
44          }

