10              // ConstantValue reports that for us rather than it being assumed here. Enums arrive as their
11              // underlying value, and CommandFlags is int-backed; "A | B" over two constants is itself a
12              // constant, so the fully-spelled-out combined forms land here too.
13              var value = Unwrap(argument.Value);
