 5          // small payloads: linearize onto the stack and decode contiguously - no Decoder allocation
 6          long length = seq.Length;
 7          if (length <= MaxStackLinearizeBytes)
 8          {
 9              Span<byte> linear = stackalloc byte[(int)length];
10              seq.CopyTo(linear);
11              return encoding.GetChars(linear, chars);
12          }
13  
14          var decoder = encoding.GetDecoder();
15          int total = 0;
16          var position = seq.Start;
17          bool have = seq.TryGet(ref position, out var current);
