19          {
20              var nextPosition = position;
21              bool haveNext = seq.TryGet(ref nextPosition, out var next);
22              int written = decoder.GetChars(current.Span, chars, flush: !haveNext);
23              chars = chars.Slice(written); // advance by chars *written*, not by bytes consumed
24              total += written;
25              current = next;
26              position = nextPosition;
27              have = haveNext;
28          }
