 1      public static int GetCharCount(this Encoding encoding, in ReadOnlySequence<byte> seq)
 2      {
 3          // common case: a single segment can be measured directly, with no decoder state to track
 4          if (seq.IsSingleSegment) return encoding.GetCharCount(seq.FirstSpan);
 5  
 6          // small payloads: linearize onto the stack and measure contiguously - no Decoder allocation, and no
 7          // glyph-straddles-a-boundary problem once the bytes are contiguous
 8          long length = seq.Length;
 9          if (length <= MaxStackLinearizeBytes)
10          {
11              Span<byte> linear = stackalloc byte[(int)length];
12              seq.CopyTo(linear);
13              return encoding.GetCharCount(linear);
14          }
15  
16          // larger multi-segment: a multi-byte glyph can straddle a segment boundary, so we *must* decode with
17          // a stateful decoder rather than summing per-segment counts (which would over-count split glyphs).
18          // Note we cannot use Decoder.GetCharCount: unlike GetChars/Convert it does not carry partial-glyph
19          // state between calls, so it too over-counts. Decoder.Convert reports the chars produced without us
20          // having to keep them, so we decode into a small scratch buffer and discard the output, flushing on
21          // the final segment.
22          var decoder = encoding.GetDecoder();
23          Span<char> scratch = stackalloc char[128];
24          int count = 0;
25          var position = seq.Start;
26          bool have = seq.TryGet(ref position, out var current);
27          while (have)
28          {
29              var nextPosition = position;
30              bool haveNext = seq.TryGet(ref nextPosition, out var next);
31              var bytes = current.Span;
32              bool flush = !haveNext;
33              bool completed;
34              do
35              {
36                  decoder.Convert(bytes, scratch, flush, out int bytesUsed, out int charsUsed, out completed);
37                  count += charsUsed;
38                  bytes = bytes.Slice(bytesUsed);
39              }
40              while (!bytes.IsEmpty || (flush && !completed));
41              current = next;
42              position = nextPosition;
43              have = haveNext;
44          }
45          return count;
46      }

