 1          internal virtual RedisFeatures GetFeatures(in RedisKey key, CommandFlags flags, RedisCommand command, out ServerEndPoint? server)
 2          {
 3              // the server picked here is the one the message is sent to, so a primary-only command has to pick the primary
 4              // here as well, the same way Message.SetPrimaryOnly does when the message is created; otherwise PreferReplica
 5              // picks a replica that then rejects it (DemandReplica is left alone so that it still fails the same way)
