 5  
 6          // invariant throughout: this is a version from a config file, not something a human typed in a locale
 7          var parts = text!.Trim().Split('.');
 8          if (!int.TryParse(parts[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out var major) || major <= 0) return false;
 9  
