 1      public bool KeyStartsWith(ReadOnlySpan<byte> prefix) // intentionally leading people to the BLOB API
 2      {
 3          switch (_kind)
 4          {
 5              case KeyNotificationKind.KeySpace:
 6              case KeyNotificationKind.SubKeySpace:
 7                  // Key is in the channel suffix
 8                  return ChannelSuffix.Slice(_keyOffset).StartsWith(prefix);
 9  
10              case KeyNotificationKind.KeyEvent:
11                  // Key is in the value/payload (plain key, not length-prefixed)
12                  if (_keyOffset == 0) return _value.StartsWith(prefix);
13  
14                  var span = GetKeySpan(out var lease, stackalloc byte[128]);
15                  bool result = span.StartsWith(prefix);
16                  Return(lease);
17                  return result;
18  
19              case KeyNotificationKind.SubKeyEvent:
20                  // Key is length-prefixed in payload: <key_len>:<key>|<len>:<subkey>
21                  var keyValue = ExtractLengthPrefixedValue(_value, 0);
22                  if (keyValue.IsNull) return false;
23                  if (_keyOffset == 0) return keyValue.StartsWith(prefix);
24  
25                  // Need to check the sliced portion
26                  byte[]? keyBytes = keyValue;
27                  if (keyBytes is not null && _keyOffset < keyBytes.Length)
28                  {
29                      return keyBytes.AsSpan(_keyOffset).StartsWith(prefix);
30                  }
31                  return false;
32  
33              case KeyNotificationKind.SubKeySpaceItem:
34                  // Key is in channel: __subkeyspaceitem@<db>__:<key>\n<subkey>
35                  var suffixItem = ChannelSuffix;
36                  var newlineIndex = suffixItem.IndexOf((byte)'\n');
37                  if (newlineIndex > 0)
38                  {
39                      var keySpan = suffixItem.Slice(_keyOffset, newlineIndex - _keyOffset);
40                      return keySpan.StartsWith(prefix);
41                  }
42                  return false;
43  
44              case KeyNotificationKind.SubKeySpaceEvent:
45                  // Key is in channel: __subkeyspaceevent@<db>__:<event>|<key>
46                  var suffixEvent = ChannelSuffix;
47                  var pipeIndex = suffixEvent.IndexOf((byte)'|');
48                  if (pipeIndex >= 0 && pipeIndex + 1 < suffixEvent.Length)
49                  {
50                      var keySpan = suffixEvent.Slice(pipeIndex + 1 + _keyOffset);
51                      return keySpan.StartsWith(prefix);
52                  }
53                  return false;
54  
55              default:
56                  return false;
57          }
58      }

