 1      private static async Task LiveServerEvents(string alive)
 2      {
 3          const string ClientName = "aot-rig";
 4          var options = ConfigurationOptions.Parse(alive);
 5          options.AllowAdmin = true;
 6          options.AbortOnConnectFail = false;
 7          options.ClientName = ClientName;
 8          await using var muxer = await ConnectionMultiplexer.ConnectAsync(options).ConfigureAwait(false);
 9  
10          int restored = 0, failed = 0;
11          var signal = new SemaphoreSlim(0);
12          muxer.ConnectionRestored += (_, _) => Interlocked.Increment(ref restored);
13          muxer.ConnectionRestored += (_, _) => signal.Release();
14          muxer.ConnectionFailed += (_, _) => Interlocked.Increment(ref failed);
15          muxer.ErrorMessage += (_, _) => { };
16  
17          var db = muxer.GetDatabase();
18          await db.PingAsync().ConfigureAwait(false);
19  
20          // kill our own connections server-side; the multiplexer should notice and re-establish,
21          // raising ConnectionFailed/ConnectionRestored through the machinery we care about
22          var server = muxer.GetServer(muxer.GetEndPoints()[0]);
23          foreach (var client in await server.ClientListAsync().ConfigureAwait(false))
24          {
25              if (client.Name == ClientName)
26              {
27                  try
28                  {
29                      await server.ClientKillAsync(id: client.Id, skipMe: false).ConfigureAwait(false);
30                  }
31                  catch (RedisConnectionException)
32                  {
33                      // expected when we kill the connection issuing the command
34                  }
35              }
36          }
37  
38          if (!await signal.WaitAsync(20_000).ConfigureAwait(false))
39          {
40              throw new TimeoutException($"no ConnectionRestored within timeout (failed: {Volatile.Read(ref failed)})");
41          }
42  
43          await db.PingAsync().ConfigureAwait(false);
44          Console.Write($"[failed:{Volatile.Read(ref failed)} restored:{Volatile.Read(ref restored)}] ");
45      }

