17  
18          RedisKey hash = "aot-rig:hash";
19          await db.KeyDeleteAsync(hash).ConfigureAwait(false);
20          await db.HashSetAsync(hash, [new HashEntry("a", 1), new HashEntry("b", 2)]).ConfigureAwait(false);
21          if ((await db.HashGetAllAsync(hash).ConfigureAwait(false)).Length != 2) throw new InvalidOperationException("HGETALL");
22  
