 1      private static async Task ConnectionFailedEvents(string dead)
 2      {
 3          var options = new ConfigurationOptions
 4          {
 5              AbortOnConnectFail = false,
 6              ConnectTimeout = 1000,
 7              ConnectRetry = 1,
 8              AllowAdmin = true,
 9          };
10          options.EndPoints.Add(dead);
11  
12          int failed = 0, internalError = 0;
13          var signal = new SemaphoreSlim(0);
14          await using var muxer = await ConnectionMultiplexer.ConnectAsync(options).ConfigureAwait(false);
15          muxer.ConnectionFailed += (_, _) => Interlocked.Increment(ref failed);
16          muxer.ConnectionFailed += (_, _) =>
17          {
18              // deliberately a second handler, so the multicast path is used too
19              signal.Release();
20          };
21          muxer.InternalError += (_, _) => Interlocked.Increment(ref internalError);
22  
23          // the initial (failed) connect happens before we can attach handlers, so keep poking it:
24          // each attempt is another connect failure, and therefore another event
25          var db = muxer.GetDatabase();
26          var deadline = Environment.TickCount64 + 30_000;
27          while (!await signal.WaitAsync(250).ConfigureAwait(false))
28          {
29              if (Environment.TickCount64 > deadline)
30              {
31                  throw new TimeoutException($"no ConnectionFailed event within timeout (single-handler count: {Volatile.Read(ref failed)}, internal errors: {Volatile.Read(ref internalError)})");
32              }
33  
34              try
35              {
36                  await db.PingAsync().ConfigureAwait(false);
37              }
38              catch (RedisConnectionException)
39              {
40                  // expected
41              }
42          }
43  
44          Console.Write($"[failed:{Volatile.Read(ref failed)} internal:{Volatile.Read(ref internalError)}] ");
45      }

