 1          public bool MoveNext()
 2          {
 3              while (true) // for each streaming element
 4              {
 5                  _offset += CurrentLength;
 6                  while (_remaining > 0) // for each span in the current element
 7                  {
 8                      // look in the active span
 9                      var take = Math.Min(_remaining, _current.Length - _offset);
10                      if (take > 0) // more in the current chunk
11                      {
12                          _remaining -= take;
13                          CurrentLength = take;
14                          return true;
15                      }
16  
17                      // otherwise, we expect more tail data
18                      if (_tail is null) ThrowEof();
19  
20                      _current = _tail.Memory.Span;
21                      _offset = 0;
22                      _tail = _tail.Next;
23                  }
24  
25                  if (!_reader.MoveNextStreamingScalar()) break;
26                  InitSegment();
27              }
28  
29              CurrentLength = 0;
30              return false;
31          }

