 1          private static ServerEndPoint? FindReplica(ServerEndPoint endpoint, RedisCommand command, bool allowDisconnected = false)
 2          {
 3              if (endpoint.IsReplica && endpoint.IsSelectable(command, allowDisconnected)) return endpoint;
 4  
 5              var replicas = endpoint.Replicas;
 6              var len = replicas.Length;
 7              uint startOffset = len <= 1 ? 0 : endpoint.NextReplicaOffset();
 8              for (int i = 0; i < len; i++)
 9              {
10                  endpoint = replicas[(int)(((uint)i + startOffset) % len)];
11                  if (endpoint.IsReplica && endpoint.IsSelectable(command, allowDisconnected)) return endpoint;
12              }
13              return null;
14          }

