 1          public int HashSlot(in RedisChannel channel)
 2          {
 3              if (ServerType == ServerType.Standalone || channel.IsNull) return NoSlot;
 4  
 5              ReadOnlySpan<byte> routingSpan = channel.RoutingSpan;
 6              byte[] prefix;
 7              return channel.IgnoreChannelPrefix || (prefix = ChannelPrefix).Length == 0
 8                  ? GetClusterSlot(routingSpan)
 9                  : GetClusterSlotWithPrefix(prefix, routingSpan);
10  
11              static int GetClusterSlotWithPrefix(byte[] prefixRaw, ReadOnlySpan<byte> routingSpan)
12              {
13                  ReadOnlySpan<byte> prefixSpan = prefixRaw;
14                  const int MAX_STACK = 128;
15                  byte[]? lease = null;
16                  var totalLength = prefixSpan.Length + routingSpan.Length;
17                  var span = totalLength <= MAX_STACK
18                      ? stackalloc byte[MAX_STACK]
19                      : (lease = ArrayPool<byte>.Shared.Rent(totalLength));
20  
21                  prefixSpan.CopyTo(span);
22                  routingSpan.CopyTo(span.Slice(prefixSpan.Length));
23                  var result = GetClusterSlot(span.Slice(0, totalLength));
24                  if (lease is not null) ArrayPool<byte>.Shared.Return(lease);
25                  return result;
26              }
27          }

