 1          internal static int GetHashSlot(in RedisKey key)
 2          {
 3              if (key.IsNull) return NoSlot;
 4              if (key.TryGetSimpleBuffer(out var arr)) // key was constructed from a byte[]
 5              {
 6                  return GetClusterSlot(arr);
 7              }
 8              var length = key.TotalLength();
 9              if (length <= 256)
10              {
11                  Span<byte> span = stackalloc byte[length];
12                  var written = key.CopyTo(span);
13                  Debug.Assert(written == length, "key length/write error");
14                  return GetClusterSlot(span);
15              }
16              else
17              {
18                  arr = ArrayPool<byte>.Shared.Rent(length);
19                  var span = new Span<byte>(arr, 0, length);
20                  var written = key.CopyTo(span);
21                  Debug.Assert(written == length, "key length/write error");
22                  var result = GetClusterSlot(span);
23                  ArrayPool<byte>.Shared.Return(arr);
24                  return result;
25              }
26          }

