 1              public bool Remove(ConnectionGroupMember member)
 2              {
 3                  while (true)
 4                  {
 5                      var arr = _members;
 6                      int index = -1;
 7                      for (int i = 0; i < arr.Length; i++)
 8                      {
 9                          if (ReferenceEquals(arr[i], member))
10                          {
11                              index = i;
12                              break;
13                          }
14                      }
15  
16                      if (index == -1) return false;
17                      var newArr = new ConnectionGroupMember[arr.Length - 1];
18                      if (index > 0) Array.Copy(arr, 0, newArr, 0, index);
19                      if (index < newArr.Length) Array.Copy(arr, index + 1, newArr, index, newArr.Length - index);
20                      if (Interlocked.CompareExchange(ref _members, newArr, arr) == arr) break;
