 1              public bool TryFailoverTo(ConnectionGroupMember? member)
 2              {
 3                  if (member is null)
 4                  {
 5                      // remove any explicit overrides, returning whether that was an actual change
 6                      bool result = false;
 7                      foreach (var m in _members)
 8                      {
 9                          if (m.ExplicitOverride)
10                          {
11                              result = true; // someone was explicitly enabled
12                              m.ExplicitOverride = false;
13                          }
14                      }
15  
16                      SelectPreferredGroup();
17                      return result;
18                  }
19  
20                  var members = _members;
21                  if (!members.Contains(member))
22                  {
23                      // not one of ours?
24                      return false;
25                  }
26  
27                  member.ResetIsUnhealthy(); // the user explicitly asked us to consider this node
28                  if (!member.IsConnected)
29                  {
30                      // not allowed
31                      return false;
32                  }
33  
34                  if (member.ExplicitOverride)
35                  {
36                      // already preferred; no change, but report as success
37                      return true;
38                  }
39  
40                  // otherwise, deselect everyone else, and select this one
41                  foreach (var m in members)
42                  {
43                      m.ExplicitOverride = ReferenceEquals(m, member);
44                  }
45  
46                  SelectPreferredGroup();
47                  return true;
48              }

