 1              public async Task AddAsync(ConnectionGroupMember member, TextWriter? log = null)
 2              {
 3                  // connect
 4                  member.Init(_members.Length);
 5                  member.Configuration.AbortOnConnectFail = false; // members are gated by health-checks, not connect-fail
 6                  member.Configuration.HeartbeatConsistencyChecks = true;
 7                  var muxer = await ConnectionMultiplexer.ConnectGroupMemberAsync(
 8                      member.Configuration, log, member.ResolveCircuitBreaker(_options)).ConfigureAwait(false);
 9                  member.SetMultiplexer(muxer);
10  
11                  // unless told otherwise, run an initial health-check so a healthy member can be selected immediately;
12                  // when skipped, the member is added as not-yet-connected and the poll loop brings it online once it
13                  // passes - this is the only way to add a member that is not yet healthy
14                  if (!member.SkipInitialHealthCheck)
15                  {
16                      var health = await member.ResolveHealthCheck(_options).CheckHealthAsync(muxer).ConfigureAwait(false);
17                      member.UpdateState(health, GetFailbackFailureCutoff(member));
18  
19                      // a newly added member is never the active one, so its failback check applies at once
20                      if (member.ResolveFailbackHealthCheck(_options) is { } failback && member.ConsiderActive)
21                      {
22                          member.FailbackVerified = await failback.CheckHealthAsync(muxer).ConfigureAwait(false) is HealthCheckResult.Healthy;
23                      }
24                  }
25  
26                  // apply any shared hooks
27                  AddEventHandlers(muxer); // includes circuit-breaker
28                  if (_profilingSessionProvider is not null) muxer.RegisterProfiler(_profilingSessionProvider);
29                  lock (_suffixes)
30                  {
31                      foreach (var suffix in _suffixes)
32                      {
33                          muxer.AddLibraryNameSuffix(suffix);
34                      }
35                  }
36  
37                  // update the members array
38                  while (true)
39                  {
40                      var arr = _members;
41                      var newArr = new ConnectionGroupMember[arr.Length + 1];
42                      Array.Copy(arr, 0, newArr, 0, arr.Length);
43                      newArr[arr.Length] = member;
44                      if (Interlocked.CompareExchange(ref _members, newArr, arr) == arr) break;
45                  }
46  
47                  OnConnectionChanged(GroupConnectionChangedEventArgs.ChangeType.Added, member);
48                  SelectPreferredGroup();
49  
50                  // pub/sub
51                  await AddPubSubHandlersAsync(member).ConfigureAwait(false);
52              }

