 1              private void OnMemberConnectionFailed(object? sender, ConnectionFailedEventArgs e)
 2              {
 3                  // deliberately scoped to these failure types; re-probe and re-select promptly rather than
 4                  // waiting for the next poll tick, so traffic routes away from the dropped member. A breaker
 5                  // trip is the member's own traffic telling us it is unstable; LOADING is the server telling
 6                  // us outright that it cannot serve yet (and its handshake will keep failing the same way
 7                  // until it can, so nothing routed there in the meantime gets a reply - the breaker only ever
 8                  // sees replies, so it cannot be what moves us). Ordinary socket drops are left to reconnect
 9                  if (e.FailureType is ConnectionFailureType.CircuitBreaker or ConnectionFailureType.Loading
10                      && Interlocked.CompareExchange(ref _rerouteDebounce, 1, 0) is 0)
11                  {
12                      GetMember(sender as ConnectionMultiplexer)?.SetUnhealthy();
13                      _ = Task.Run(async () =>
14                      {
15                          try
16                          {
17                              await TryHealthCheckAndSelectPreferredGroupAsync(this);
18                          }
19                          catch (Exception ex)
20                          {
21                              Debug.WriteLine(ex.Message);
22                          }
23                          finally
24                          {
25                              Volatile.Write(ref _rerouteDebounce, 0);
26                          }
27                      });
28                  }
29  
30                  // invoke any custom logic from consumers subscribing to the public events
31                  _connectionFailedExternal?.Invoke(sender, e);
32              }

