 1              private static bool RemoveHandler<T>(ref T? field, T? value) where T : Delegate
 2              {
 3                  if (value is null) return false;
 4                  while (true) // loop until we win (competition)
 5                  {
 6                      var oldValue = field;
 7                      var newValue = oldValue is null ? null : (T?)Delegate.Remove(oldValue, value);
 8  
 9                      if (ReferenceEquals(Interlocked.CompareExchange(ref field, newValue, oldValue), oldValue))
10                      {
11                          return newValue is null;
12                      }
13                  }
14              }

