 1              internal void SelectPreferredGroup()
 2              {
 3                  if (_disposed) return;
 4                  var existingActive = _activeStub.Active;
 5                  ConnectionGroupMember? preferredMember = null, fallbackMember = null, previousMember = null;
 6                  var members = _members;
 7                  foreach (var member in members)
 8                  {
 9                      if (previousMember is null && ReferenceEquals(member.Multiplexer, existingActive))
10                      {
11                          previousMember = member;
12                      }
13  
14                      if (member.ConsiderActive)
15                      {
16                          member.UpdateLatency(); // this can change passively
17  
18                          // (note that when in doubt, we prefer the active muxer, to prevent flapping)
19                          fallbackMember = ConnectionGroupMember.Select(fallbackMember, member, existingActive);
20                          if (IsFailbackEligible(member, existingActive))
21                          {
22                              preferredMember = ConnectionGroupMember.Select(preferredMember, member, existingActive);
23                          }
24                      }
25                  }
26  
27                  // The active member is eligible unless provisional, so this only applies when it is gone, there is
28                  // none, or it is itself provisional: if no live member has passed its failback check - every one
29                  // lagging, say, which is the normal state of a partition between regions - serve from the best live
30                  // member rather than from none, marking it provisional.
31                  if (preferredMember is null)
32                  {
33                      preferredMember = fallbackMember;
34                      Volatile.Write(ref _provisional, fallbackMember?.Multiplexer);
35                  }
36                  else
37                  {
38                      Volatile.Write(ref _provisional, null);
39                  }
40  
41                  SetActive(preferredMember?.Multiplexer);
42  
43                  if (preferredMember is not null && !ReferenceEquals(preferredMember, previousMember))
44                  {
45                      OnConnectionChanged(
46                          GroupConnectionChangedEventArgs.ChangeType.ActiveChanged,
47                          preferredMember,
48                          previousMember);
49                  }
50              }

