 1              private long GetFailbackFailureCutoff(ConnectionGroupMember member)
 2              {
 3                  // the minimum last-observed unhealthy time (as UTC ticks) that we'll allow for reconnect;
 4                  // for example, if the FailbackDelay is 2 minutes, and the time is 14:32:55, then the last
 5                  // failure must have happened at 14:30:55 or earlier. Pure long tick math on the wall clock:
 6                  // DateTime.Ticks and TimeSpan.Ticks are the same 100ns unit, so the subtraction is valid
 7                  var delay = member.ResolveFailbackDelay(_options);
 8                  if (delay == TimeSpan.MaxValue) return long.MinValue; // manual mode: never auto-reset
 9  
10                  return DateTime.UtcNow.Ticks - delay.Ticks;
11              }

