 1              private async Task RunFailbackChecksAsync(ConnectionGroupMember[] members)
 2              {
 3                  // a provisional active member (chosen by the liveness fallback) is still checked, so that it can
 4                  // stop being provisional once it has caught up; a normal active member is not
 5                  var active = _activeStub.Active;
 6                  var provisional = Volatile.Read(ref _provisional);
 7                  List<PendingFailbackCheck>? checks = null;
 8                  int totalTimeoutMillis = 0;
 9                  foreach (var member in members)
10                  {
11                      var check = member.ResolveFailbackHealthCheck(_options);
12                      if (check is null) continue;
13  
14                      if (!member.ConsiderActive || (ReferenceEquals(member.Multiplexer, active) && !ReferenceEquals(active, provisional)))
15                      {
16                          member.FailbackVerified = false;
17                          continue;
18                      }
19  
20                      totalTimeoutMillis = Math.Max(totalTimeoutMillis, check.TotalTimeoutMillis());
21                      (checks ??= []).Add(new(member, check.CheckHealthAsync(member.Multiplexer)));
22                  }
23  
24                  if (checks is null) return;
25  
26                  var all = new Task[checks.Count];
27                  for (int i = 0; i < all.Length; i++) all[i] = checks[i].Pending;
28                  await Task.WhenAll(all).TimeoutAfter(totalTimeoutMillis).ForAwait();
29  
30                  foreach (var item in checks)
31                  {
32                      var member = item.Member;
33                      var pending = item.Pending;
34                      if (pending.IsCompletedSuccessfully)
35                      {
36                          member.FailbackVerified = await pending.ForAwait() is HealthCheckResult.Healthy;
37                      }
38                      else
39                      {
40                          _ = pending.ObserveErrors();
41                          member.FailbackVerified = false;
42                      }
43                  }
44              }

