 1              internal async Task RunHealthCheckAsync()
 2              {
 3                  if (_disposed) return;
 4                  var members = _members;
 5                  if (members.Length == 0) return; // nothing to check (and no budget to compute)
 6  
 7                  var pending = HealthCheck.GetReusablePending(ref _reusableHealthCheckBuffer, members.Length);
 8  
 9                  // members can use different health-checks (see ConnectionGroupMember.HealthCheck), so the
10                  // budget for the whole pass is the largest individual budget
11                  int totalTimeoutMillis = 0;
12                  for (int i = 0; i < members.Length; i++)
13                  {
14                      var muxer = members[i].Multiplexer;
15                      var healthCheck = members[i].ResolveHealthCheck(_options);
16                      totalTimeoutMillis = Math.Max(totalTimeoutMillis, healthCheck.TotalTimeoutMillis());
17                      pending[i] = healthCheck.CheckHealthAsync(muxer);
18                  }
19  
20                  await Task.WhenAll(pending).TimeoutAfter(totalTimeoutMillis).ForAwait();
21                  for (int i = 0; i < pending.Length; i++)
22                  {
23                      HealthCheckResult result;
24                      if (pending[i].IsCompletedSuccessfully)
25                      {
26                          result = await pending[i].ForAwait();
27                      }
28                      else
29                      {
30                          _ = pending[i].ObserveErrors();
31                          result = HealthCheckResult.Unhealthy;
32                      }
33  
34                      var delta = members[i].UpdateState(result, GetFailbackFailureCutoff(members[i]));
35                      if (delta != GroupConnectionChangedEventArgs.ChangeType.Unknown)
36                      {
37                          OnConnectionChanged(delta, members[i]);
38                      }
39                  }
40  
41                  HealthCheck.PutReusablePending(ref _reusableHealthCheckBuffer, ref pending);
42                  await RunFailbackChecksAsync(members).ForAwait();
43              }

