 6                  _ = Task.Run(() => PollAsync(new(this), cancellationToken));
 7  
 8                  static async Task PollAsync(WeakReference weakRef, CancellationToken cancellationToken)
 9                  {
10                      while (TryGetHealthCheck(weakRef.Target, out var interval))
11                      {
12                          try
13                          {
14                              await Task.Delay(interval, cancellationToken).ForAwait();
15                          }
16                          catch (OperationCanceledException)
17                          {
18                              break; // disposed; stop polling without waiting out the interval
19                          }
20  
21                          if (!await TryHealthCheckAndSelectPreferredGroupAsync(weakRef.Target).ForAwait()) break;
22                      }
23                  }
24  
25                  static bool TryGetHealthCheck(object? target, out TimeSpan interval)
26                  {
27                      if (target is MultiGroupMultiplexer typed)
