29                          // note the interval is a group-level concern (how often we re-evaluate the active
30                          // member), not a property of any individual health-check
31                          interval = typed._options.HealthCheckInterval;
32                          return (interval > TimeSpan.Zero) & (interval != TimeSpan.MaxValue);
33                      }
34  
35                      interval = TimeSpan.Zero;
36                      return false;
37                  }
38              }

