 4                  {
 5                      if (typed.IsDisposed) return false;
 6  
 7                      // serialize health-check + select: the poll loop and the circuit-breaker fast-path
 8                      // can both land here, and we must not run two overlapping check/select passes (they
 9                      // would race _active and emit duplicate change events). If a pass is already running,
10                      // skip - it will select on our behalf, and we converge on the next tick regardless.
11                      if (Interlocked.CompareExchange(ref typed._healthCheckGate, 1, 0) is not 0)
12                      {
13                          return true; // still a live target; keep polling
14                      }
15  
16                      try
17                      {
18                          await typed.RunHealthCheckAsync().ForAwait();
19                          typed.SelectPreferredGroup();
20                      }
21                      catch (Exception ex)
22                      {
23                          typed.OnInternalError(ex, origin: "update group");
24                      }
25                      finally
26                      {
27                          Volatile.Write(ref typed._healthCheckGate, 0);
28                      }
29  
30                      return true; // even if we fault: try again
31                  }
32  
33                  return false;
34              }

