 1              internal static ConnectionGroupMember? Select(ConnectionGroupMember? x, ConnectionGroupMember? y, ConnectionMultiplexer? active)
 2              {
 3                  if (x is null) return y;
 4                  if (y is null) return x;
 5  
 6                  // always prefer a connected endpoint
 7                  bool xc = x.IsConnected, yc = y.IsConnected;
 8                  if (xc != yc) return xc ? x : y;
 9  
10                  // prefer manual override if only one is overridden
11                  xc = x.ExplicitOverride;
12                  yc = y.ExplicitOverride;
13                  if (xc != yc) return xc ? x : y;
14  
15                  // prefer higher weight
16                  double xw = x.Weight, yw = y.Weight;
17                  // ReSharper disable once CompareOfFloatsByEqualityOperator
18                  if (xw != yw) return xw > yw ? x : y;
19  
20                  // then by latency
21                  uint xl = x._latencyTicks, yl = y._latencyTicks;
22                  if (xl != yl) return xl < yl ? x : y;
23  
24                  // getting hard to choose; is either of them the existing active node? choose that to prevent flapping
25                  if (ReferenceEquals(x._muxer, active)) return x;
26                  if (ReferenceEquals(y._muxer, active)) return y;
27  
28                  // I've got nothing; choose x arbitrarily
29                  return x;
30              }

