 1  export function asyncThrottle<TArgs extends ReadonlyArray<unknown>>(
 2    func: (...args: TArgs) => Promise<void>,
 3    { interval = 1000, onError = noop }: AsyncThrottleOptions = {},
 4  ) {
 5    if (typeof func !== 'function') throw new Error('argument is not function.')
 6  
 7    let nextExecutionTime = 0
 8    let lastArgs = null
 9    let isExecuting = false
10    let isScheduled = false
11  
12    return async (...args: TArgs) => {
13      lastArgs = args
14      if (isScheduled) return
15      isScheduled = true
16      while (isExecuting) {
17        await new Promise((done) => timeoutManager.setTimeout(done, interval))
18      }
19      while (Date.now() < nextExecutionTime) {
20        await new Promise((done) =>
21          timeoutManager.setTimeout(done, nextExecutionTime - Date.now()),
22        )
23      }
24      isScheduled = false
25      isExecuting = true
26      try {
27        await func(...lastArgs)
28      } catch (error) {
29        try {
30          onError(error)
31        } catch {}
32      }
33      nextExecutionTime = Date.now() + interval
34      isExecuting = false
35    }
36  }

