 1  export function createSearchText(rootValue: unknown): string {
 2    const rootText = primitiveText(rootValue)
 3    if (rootText !== undefined) return rootText.toLowerCase()
 4    const parts: Array<string> = []
 5    const seen = new Set<unknown>([rootValue])
 6    const queue: Array<{ value: unknown; depth: number }> = [
 7      { value: rootValue, depth: 0 },
 8    ]
 9    // Also visits the entries pushed while iterating
10    for (const { value, depth } of queue) {
11      for (const entry of searchEntries(value) ?? []) {
12        parts.push(entry.label.toLowerCase())
13        if (entry.accessor) continue
14        const text = primitiveText(entry.value)
15        if (text !== undefined) {
16          parts.push(text.toLowerCase())
17        } else if (
18          depth < 500 &&
19          typeof entry.value === 'object' &&
20          !seen.has(entry.value)
21        ) {
22          seen.add(entry.value)
23          queue.push({ value: entry.value, depth: depth + 1 })
24        }
25      }
26    }
27    return parts.join(SEARCH_TEXT_SEPARATOR)
28  }

