13        return Array.from(Map.prototype.entries.call(value), ([key, entry]) => ({
14          key,
15          label: primitiveText(key) ?? '[Object key]',
16          value: entry,
17        }))
18      }
19      if (type === 'Set') {
20        return Array.from(Set.prototype.values.call(value), (entry, index) => ({
21          key: String(index),
22          label: String(index),
23          value: entry,
24        }))
25      }
26      const entries = Object.entries(Object.getOwnPropertyDescriptors(value))
27        .filter(([, descriptor]) => descriptor.enumerable)
28        .map(([key, descriptor]) => ({
29          key,
30          label: key,
31          value: descriptor.value,
32          accessor: !('value' in descriptor),
33        }))
34      if (
35        !Array.isArray(value) &&
36        Object.getPrototypeOf(value) !== Object.prototype &&
37        Object.getPrototypeOf(value) !== null &&
38        !entries.some(
39          (entry) => !entry.accessor && typeof entry.value !== 'function',
40        )
41      ) {
42        return undefined
43      }
44      return entries
45    } catch {
46      return undefined
47    }
48  }

