 1  function typeAliasBody(source: string | undefined) {
 2    const declaration = source?.match(/```ts\ntype \w+/)
 3    if (!source || !declaration) {
 4      return undefined
 5    }
 6    let index = declaration.index! + declaration[0].length
 7    if (source[index] === '<') {
 8      let depth = 0
 9      for (; index < source.length; index++) {
10        if (source[index] === '<') {
11          depth++
12        } else if (
13          source[index] === '>' &&
14          source[index - 1] !== '=' &&
15          --depth === 0
16        ) {
17          index++
18          break
19        }
20      }
21    }
22    return source.slice(index).match(/^ = ([\s\S]*?);\n```/)?.[1]
23  }

