 9      const members = await Promise.all(
10        node.types.map((member) => declaredTypeLabel(outputDir, member)),
11      )
12      return members.every(Boolean)
13        ? members.join(ts.isIntersectionTypeNode(node) ? ' & ' : ' | ')
14        : undefined
15    }
16    if (ts.isFunctionTypeNode(node) && node.parameters.length === 0) {
17      const result = await declaredTypeLabel(outputDir, node.type)
18      return result && `() => ${result}`
19    }
20    if (ts.isTypeLiteralNode(node)) {
21      const keys = node.members
22        .map((member) => member.name?.getText())
23        .filter(Boolean)
24      return keys.length > 0 ? `{ ${keys.join(', ')} }` : undefined
25    }
26    if (
27      ts.isTypeReferenceNode(node) &&
28      typeTransforms.has(node.typeName.getText()) &&
29      node.typeArguments?.[0]
30    ) {
31      const target = await declaredTypeLabel(outputDir, node.typeArguments[0])
32      return target && `${node.typeName.getText()}<${target}>`
33    }
34    return typeNameInCode(outputDir, node.getText())
35  }

