 1  async function declaredSignatureTypes(signature: string) {
 2    const location = signature.match(/^Defined in: \[([^\]]+):(\d+)\]/m)
 3    if (!location) {
 4      return undefined
 5    }
 6    const [, file, line] = location
 7    let source = sourceFiles.get(file!)
 8    if (!source) {
 9      const text = await readFile(resolve(__dirname, '..', file!), 'utf8').catch(
10        () => undefined,
11      )
12      if (text === undefined) {
13        return undefined
14      }
15      source = ts.createSourceFile(file!, text, ts.ScriptTarget.Latest, true)
16      sourceFiles.set(file!, source)
17    }
