19    const visit = (node: ts.Node) => {
20      if (found) {
21        return
22      }
23      if (
24        ts.isFunctionLike(node) &&
25        'parameters' in node &&
26        source.getLineAndCharacterOfPosition(node.getStart()).line ===
27          Number(line) - 1
28      ) {
29        found = node
30        return
31      }
32      ts.forEachChild(node, visit)
33    }
34    visit(source)
35    return found && { parameter: found.parameters[0]?.type, returns: found.type }
36  }

