 1      private static string ConvertDictionaryToQueryString(Dictionary<string, StringValues> queryDictionary)
 2      {
 3          var builder = new StringBuilder();
 4  
 5          builder.Append('?');
 6  
 7          var outerCount = 0;
 8  
 9          foreach (var query in queryDictionary)
10          {
11              for (var innerCount = 0; innerCount < query.Value.Count; innerCount++)
12              {
13                  builder.Append($"{query.Key}={query.Value[innerCount]}");
14  
15                  if (innerCount < (query.Value.Count - 1))
16                  {
17                      builder.Append('&');
18                  }
19              }
20  
21              if (outerCount < (queryDictionary.Count - 1))
22              {
23                  builder.Append('&');
24              }
25  
26              outerCount++;
27          }
28  
29          return builder.ToString();
30      }

