 1      protected HttpMessageInvoker CreateMessageInvoker(DownstreamRoute route)
 2      {
 3          HttpMessageHandler baseHandler = CreateHandler(route);
 4          List<DelegatingHandler> handlers = _handlerFactory.Get(route);
 5          handlers.Reverse();
 6          foreach (DelegatingHandler handler in handlers)
 7          {
 8              handler.InnerHandler = baseHandler;
 9              baseHandler = handler;
10          }
11  
12          int milliseconds = EnsureRouteTimeoutIsGreaterThanQosOne(route);
13          TimeSpan timeout = TimeSpan.FromMilliseconds(milliseconds);
14  
15          // Adding timeout handler to the top of the chain.
16          // It's standard behavior to throw TimeoutException after the defined timeout (90 seconds by default)
17          HttpMessageHandler timeoutHandler = new TimeoutDelegatingHandler(timeout)
18          {
19              InnerHandler = baseHandler,
20          };
21          return new(timeoutHandler, true);
22      }

