 4          var roles = await _userManager.GetRolesAsync(user);
 5          var roleClaims = roles
 6              .Select(role => new Claim(ClaimTypes.Role, role));
 7          var claims = new List<Claim>
 8          {
 9              new(JwtRegisteredClaimNames.Sub, user.Id),
10              new(JwtRegisteredClaimNames.Email, user.Email ?? string.Empty),
11              new(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
12          }
13          .Union(userClaims)
14          .Union(roleClaims);
