20              issuer: issuer, //_config["Jwt:Issuer"],
21              audience: audience, // _config["Jwt:Audience"],
22              claims: claims,
23              expires: expiry,
24              signingCredentials: creds
25          );
26          var jwt = new JwtSecurityTokenHandler().WriteToken(token);
27          BearerToken bt = new()
28          {
29              AccessToken = jwt,
30              ExpiresIn = (int)(expiry - DateTime.UtcNow).TotalSeconds,
31              TokenType = JwtBearerDefaults.AuthenticationScheme,
32          };
33          return bt;
