 1      public static string GetMergedOcelotJson(this IConfigurationBuilder builder, string folder, IWebHostEnvironment env,
 2          FileConfiguration fileConfiguration = null, string primaryFile = null, string globalFile = null, string environmentFile = null)
 3      {
 4          // All versions of overloaded AddOcelot methods call this GetMergedOcelotJson one, so we improve Regex performance by cache increasing.
 5          // Developers can adjust the RegexGlobal value BEFORE calling AddOcelot
 6          // Developers can adjust the Regex.CacheSize value AFTER calling AddOcelot
 7          Regex.CacheSize = RegexGlobal.RegexCacheSize;
 8  
 9          var envName = string.IsNullOrEmpty(env?.EnvironmentName) ? "Development" : env.EnvironmentName;
10          environmentFile ??= Path.Join(folder, string.Format(EnvironmentConfigFile, envName));
11          var reg = SubConfigRegex();
12          var environmentFileInfo = new FileInfo(environmentFile);
13          var files = new DirectoryInfo(folder)
14              .EnumerateFiles()
15              .Where(fi => reg.IsMatch(fi.Name) &&
16                  !fi.Name.Equals(environmentFileInfo.Name, StringComparison.OrdinalIgnoreCase) &&
17                  !fi.FullName.Equals(environmentFileInfo.FullName, StringComparison.OrdinalIgnoreCase))
18              .ToArray();
19  
20          fileConfiguration ??= new FileConfiguration();
21          GuardSchema(fileConfiguration);
22          dynamic fcMerged = JObject.FromObject(fileConfiguration);
23  
24          primaryFile ??= Path.Join(folder, PrimaryConfigFile);
25          globalFile ??= Path.Join(folder, GlobalConfigFile);
26          var primaryFileInfo = new FileInfo(primaryFile);
27          var globalFileInfo = new FileInfo(globalFile);
28          foreach (var file in files)
29          {
30              if (files.Length > 1 &&
31                  file.Name.Equals(primaryFileInfo.Name, StringComparison.OrdinalIgnoreCase) &&
32                  file.FullName.Equals(primaryFileInfo.FullName, StringComparison.OrdinalIgnoreCase))
33              {
34                  continue;
35              }
36  
37              var lines = File.ReadAllText(file.FullName);
38              dynamic fromConfig = JToken.Parse(lines);
39              bool isGlobal = file.Name.Equals(globalFileInfo.Name, StringComparison.OrdinalIgnoreCase) &&
40                  file.FullName.Equals(globalFileInfo.FullName, StringComparison.OrdinalIgnoreCase);
41              OcelotMergeConfiguration(fcMerged, fromConfig, isGlobal);
42          }
43  
44          JObject jobj = (JObject)fcMerged;
45          builder.Properties[MergedConfigJObjectKey] = MergedConfigJObject = jobj;
46          var json = jobj.ToString();
47          builder.Properties[MergedConfigJsonKey] = MergedConfigJson = json;
48          return json; // returning for attachment to an IConfigurationProvider (IConfiguration), as either in-memory or file source
49      }

