 1      private static string CreateMessage(HttpContext context, Exception e, bool includeException = false)
 2      {
 3          var original = e;
 4          var builder = new StringBuilder()
 5              .AppendLine($"{e.GetType().Name} caught in global error handler!");
 6          int total = 0;
 7          while (e.InnerException != null)
 8          {
 9              builder.AppendLine(e.InnerException.ToString());
10              e = e.InnerException;
11              total++;
12          }
13  
14          builder.Append($"DONE reporting of a total {total} inner exception{total.Plural()} for request {context.TraceIdentifier} of the original {original.GetType().Name} below ->");
15          if (includeException)
16          {
17              builder.Append(Environment.NewLine + original.ToString());
18          }
19  
20          return builder.ToString();
21      }

