 2      {
 3          if (targetType == typeof(string))
 4          {
 5              return value;
 6          }
 7  
 8          if (targetType == typeof(bool))
 9          {
10              return TruthyValues.Contains(value.Trim());
11          }
12  
13          if (targetType == typeof(bool?))
14          {
15              return TruthyValues.Contains(value.Trim())
16                  ? true
17                  : FalsyValues.Contains(value.Trim()) ? false : null;
18          }
19  
20          if (targetType == typeof(string[]))
21          {
22              return (value == null)
23                  ? Array.Empty<string>()
24                  : value.Split(options.Separators, options.StringSplitOption)
25                      .Select(s => s.Trim(options.TrimChars))
26                      .Where(s => !string.IsNullOrEmpty(s))
27                      .ToArray();
28          }
29  
30          return NumericTypes.Contains(targetType)
31              ? ConvertToNumericType(value, targetType, options.CurrentCulture, options.NumberStyle)
32              : JsonSerializer.Deserialize(value, targetType, jsonOptions);
33      }

