 1      protected virtual async Task PumpAsync(WebSocket source, WebSocket destination, CancellationToken cancellation)
 2      {
 3          ArgumentOutOfRangeException.ThrowIfNegativeOrZero(BufferSize); // TODO Better to add validation or log warning early, a constraint is required.
 4          var buffer = new byte[BufferSize];
 5          while (true)
 6          {
 7              WebSocketReceiveResult result = default;
 8              try
 9              {
10                  result = await source.ReceiveAsync(new ArraySegment<byte>(buffer), cancellation);
11              }
12              catch (OperationCanceledException)
13              {
14                  await TryCloseOutputAsync(destination, WebSocketCloseStatus.EndpointUnavailable, nameof(OperationCanceledException), cancellation);
15                  return; // we don't rethrow timeout/cancellation errors
16              }
17              catch (WebSocketException e)
18              {
19                  if (e.WebSocketErrorCode == WebSocketError.ConnectionClosedPrematurely)
20                  {
21                      await TryCloseOutputAsync(destination, WebSocketCloseStatus.EndpointUnavailable, $"{nameof(WebSocketException)} when {nameof(e.WebSocketErrorCode)} is {nameof(WebSocketError.ConnectionClosedPrematurely)}", cancellation);
22                  }
23  
24                  // DON'T THROW, NEVER! Just log the warning...
25                  // The logging level has been decreased from level 4 (Error) to level 3 (Warning) due to the high number of disconnecting events for sensitive WebSocket connections in unstable networks.
26                  Logger.LogWarning(() => $"{nameof(WebSocketException)} when {nameof(e.WebSocketErrorCode)} is {e.WebSocketErrorCode}");
27                  return; // swallow the error
28              }
29  
30              if (result.MessageType == WebSocketMessageType.Close)
31              {
32                  await TryCloseOutputAsync(destination, source.CloseStatus.Value, source.CloseStatusDescription, cancellation);
33                  return;
34              }
35  
36              if (destination.State == WebSocketState.Open)
37              {
38                  await destination.SendAsync(new ArraySegment<byte>(buffer, 0, result.Count), result.MessageType, result.EndOfMessage, cancellation);
39              }
40          }
41      }

