 5          bool isGlobal = globalOptions?.RouteKeys is null // undefined section or array option -> is global
 6              || globalOptions.RouteKeys.Count == 0 // empty collection -> is global
 7              || globalOptions.RouteKeys.Contains(grouping.Key); // this route is in the group
 8  
 9          if (options == null && globalOptions != null && isGlobal)
