 1      public async Task StopAsync(CancellationToken cancellationToken)
 2      {
 3          var timer = Interlocked.Exchange(ref _timer, null);
 4          if (timer is null)
 5              return;
 6  
 7          _logger.LogInformation(() => $"{nameof(FileConfigurationPoller)} is stopping.");
 8          timer.Change(Timeout.Infinite, Timeout.Infinite); // Stop the timer to prevent new callbacks
 9  
10          // timer.Dispose(WaitHandle) signals the WaitHandle once all pending callbacks complete.
11          // Do NOT use 'using': if WaitOne times out while a callback is still in-flight, the timer will attempt to signal the handle when the callback eventually finishes.
12          // Disposing the handle early causes an ObjectDisposedException on the ThreadPool thread.
13          var timerStopped = new ManualResetEvent(false);
14          timer.Dispose(timerStopped);
15  
16          // Await asynchronously so callers are not blocked while waiting for in-flight callbacks.
17          var completed = await Task.Run(
18              () => timerStopped.WaitOne(TimeSpan.FromSeconds(5)),
19              CancellationToken.None) // do not cancel the wait; we must always let cleanup run
20              .ConfigureAwait(false);
21  
22          if (!completed)
23          {
24              _logger.LogWarning(() => $"{nameof(FileConfigurationPoller)}: Timer disposal did not complete within timeout.");
25  
26              // Keep timerStopped alive until the timer signals it (when the callback finishes), to prevent ObjectDisposedException on the ThreadPool thread.
27              _ = Task.Run(() => SafeDisposeManualResetEvent(timerStopped));
28          }
29          else
30          {
31              timerStopped.Dispose();
32          }
33      }

