 1      protected static string RemoveQueryStringParametersThatHaveBeenUsedInTemplate(DownstreamRequest request, List<PlaceholderNameAndValue> templatePlaceholders)
 2      {
 3          if (templatePlaceholders.Count == 0 || request.Query.IsEmpty())
 4          {
 5              return request.Query;
 6          }
 7  
 8          var query = QueryHelpers.ParseQuery(request.Query);
 9          foreach (var placeholder in templatePlaceholders.Where(p => query.ContainsKey(p.Key)))
10          {
11              query.Remove(placeholder.Key);
12          }
13  
14          return QueryHelpers.AddQueryString(string.Empty, query);
15      }

