 1      protected static string MergeQueryStringsWithoutDuplicateValues(string queryString, string newQueryString, List<PlaceholderNameAndValue> placeholders)
 2      {
 3          newQueryString = newQueryString.Replace(QuestionMark, Ampersand);
 4          var queries = HttpUtility.ParseQueryString(queryString);
 5          var newQueries = HttpUtility.ParseQueryString(newQueryString);
 6  
 7          // Remove old replaced query parameters
 8          var placeholderKeys = new HashSet<string>(placeholders.Select(p => p.Key));
 9          foreach (var queryKey in queries.AllKeys.Where(placeholderKeys.Contains))
10          {
11              queries.Remove(queryKey);
12          }
13  
14          var parameters = newQueries.AllKeys
15              .Where(key => key.IsNotEmpty())
16              .ToDictionary(key => key, key => newQueries[key]);
17  
18          _ = queries.AllKeys
19              .Where(key => key.IsNotEmpty() && !parameters.ContainsKey(key))
20              .All(key => parameters.TryAdd(key, queries[key]));
21  
22          return QueryHelpers.AddQueryString(string.Empty, parameters);
23      }

