 1      public async Task Invoke(HttpContext context)
 2      {
 3          var downstreamRoute = context.Items.DownstreamRoute();
 4          var placeholders = context.Items.TemplatePlaceholderNameAndValues();
 5          var downstreamPathTemplate = context.Items.Route()?.IsDynamic == true
 6              ? DiscoveryDownstreamRouteFinder.GetDownstreamPath(context.Request.Path.ToString()) // TODO Consider extending the IDownstreamRouteProvider interface and injecting it
 7              : downstreamRoute.DownstreamPathTemplate.Value; // TODO Consider overriding the constructor with a second version that has a Func<T> callback. For a dynamic route, DownstreamPathTemplate should be empty, but with an initialized callback.
 8          var downstreamPath = _replacer.Replace(downstreamPathTemplate, placeholders);
 9          if (downstreamPath.Value.IsEmpty())
10          {
11              throw new NotSupportedException($"{_replacer.GetType().Name} returned an empty {nameof(DownstreamPath)} for the route {downstreamRoute.Name()}.");
12          }
13  
14          var dsPath = downstreamPath.Value;
15          var downstreamRequest = context.Items.DownstreamRequest();
16          var upstreamPath = downstreamRequest.AbsolutePath;
17          if (dsPath.EndsWith(Slash) && !upstreamPath.EndsWith(Slash))
18          {
19              dsPath = dsPath.TrimEnd(Slash);
20              downstreamPath = new DownstreamPath(dsPath);
21          }
22  
23          if (!string.IsNullOrEmpty(downstreamRoute.DownstreamScheme))
24          {
25              // TODO Make sure this works, hopefully there is a test ;E
26              context.Items.DownstreamRequest().Scheme = downstreamRoute.DownstreamScheme;
27          }
28  
29          var internalConfiguration = context.Items.IInternalConfiguration();
30  
31          if (ServiceFabricRequest(internalConfiguration, downstreamRoute))
32          {
33              var (path, query) = CreateServiceFabricUri(downstreamRequest, downstreamRoute, placeholders, downstreamPath);
34  
35              // TODO Check this works again hope there is a test..
36              downstreamRequest.AbsolutePath = path;
37              downstreamRequest.Query = query;
38          }
39          else
40          {
41              if (dsPath.Contains(QuestionMark))
42              {
43                  downstreamRequest.AbsolutePath = GetPath(dsPath).ToString();
44                  var newQuery = GetQueryString(dsPath).ToString();
45                  downstreamRequest.Query = string.IsNullOrEmpty(downstreamRequest.Query)
46                      ? newQuery
47                      : MergeQueryStringsWithoutDuplicateValues(downstreamRequest.Query, newQuery, placeholders);
48              }
49              else
50              {
51                  downstreamRequest.AbsolutePath = dsPath;
52                  downstreamRequest.Query = RemoveQueryStringParametersThatHaveBeenUsedInTemplate(downstreamRequest, placeholders);
53              }
54          }
55  
56          Logger.LogDebug(() => $"Downstream URL: {downstreamRequest}");
57  
58          await _next.Invoke(context);
59      }

