 1      public List<DelegatingHandler> Get(DownstreamRoute route)
 2      {
 3          var globalDelegatingHandlers = _serviceProvider.GetServices<GlobalDelegatingHandler>()
 4              .ToArray();
 5          var routeSpecificHandlers = _serviceProvider.GetServices<DelegatingHandler>()
 6              .ToList();
 7          var handlers = new List<DelegatingHandler>();
 8  
 9          foreach (var handler in globalDelegatingHandlers)
10          {
11              if (GlobalIsInHandlersConfig(route, handler))
12              {
13                  routeSpecificHandlers.Add(handler.DelegatingHandler);
14              }
15              else
16              {
17                  handlers.Add(handler.DelegatingHandler);
18              }
19          }
20  
21          if (route.DelegatingHandlers.Count != 0)
22          {
23              var sorted = SortByConfigOrder(route, routeSpecificHandlers);
24              handlers.AddRange(sorted);
25          }
26  
27          if (route.HttpHandlerOptions.UseTracing)
28          {
29              var tracing = (DelegatingHandler)_tracingFactory.Get();
30              handlers.Add(tracing);
31          }
32  
33          if (route.QosOptions.UseQos)
34          {
35              var qos = _qosFactory.Get(route);
36              handlers.Add(qos);
37          }
38  
39          return handlers;
40      }

