 1      private Route SetUpDynamicRoute(FileDynamicRoute dynamicRoute, FileGlobalConfiguration globalConfiguration)
 2      {
 3          // The old RateLimitRule property takes precedence over the new RateLimitOptions property for backward compatibility, thus, override forcibly
 4          if (dynamicRoute.RateLimitRule != null)
 5          {
 6              dynamicRoute.RateLimitOptions = dynamicRoute.RateLimitRule;
 7          }
 8  
 9          // Load balancing dependants
10          var lbOptions = _loadBalancerOptionsCreator.Create(dynamicRoute, globalConfiguration);
11          var lbKey = _loadBalancerKeyCreator.Create(dynamicRoute, lbOptions);
12          var cacheOptions = _cacheOptionsCreator.Create(dynamicRoute, globalConfiguration, lbKey);
13  
14          var authOptions = _authOptionsCreator.Create(dynamicRoute, globalConfiguration);
15          var version = _versionCreator.Create(dynamicRoute.DownstreamHttpVersion.IfEmpty(globalConfiguration.DownstreamHttpVersion));
16          var versionPolicy = _versionPolicyCreator.Create(dynamicRoute.DownstreamHttpVersionPolicy.IfEmpty(globalConfiguration.DownstreamHttpVersionPolicy));
17          var scheme = dynamicRoute.DownstreamScheme.IfEmpty(globalConfiguration.DownstreamScheme);
18          var handlerOptions = _httpHandlerOptionsCreator.Create(dynamicRoute, globalConfiguration);
19          var metadata = _metadataCreator.Create(dynamicRoute.Metadata, globalConfiguration);
20          var qosOptions = _qosOptionsCreator.Create(dynamicRoute, globalConfiguration);
21          var rlOptions = _rateLimitOptionsCreator.Create(dynamicRoute, globalConfiguration);
22          var timeout = CreateTimeout(dynamicRoute, globalConfiguration);
23          var downstreamRoute = new DownstreamRouteBuilder()
24              .WithAuthenticationOptions(authOptions)
25              .WithCacheOptions(cacheOptions)
26              .WithDownstreamHttpVersion(version)
27              .WithDownstreamHttpVersionPolicy(versionPolicy)
28              .WithDownstreamScheme(scheme)
29              .WithHttpHandlerOptions(handlerOptions)
30              .WithLoadBalancerKey(lbKey)
31              .WithLoadBalancerOptions(lbOptions)
32              .WithMetadata(metadata)
33              .WithQosOptions(qosOptions)
34              .WithRateLimitOptions(rlOptions)
35              .WithServiceName(dynamicRoute.ServiceName)
36              .WithServiceNamespace(dynamicRoute.ServiceNamespace)
37              .WithTimeout(timeout)
38              .Build();
39          return new Route(true, downstreamRoute); // IsDynamic -> true
40      }

