 1      private void CreateLogBasedOnResponse(Response<HttpResponseMessage> response)
 2      {
 3          var status = response.Data?.StatusCode ?? HttpStatusCode.Processing;
 4          var reason = response.Data?.ReasonPhrase ?? "unknown";
 5          var uri = response.Data?.RequestMessage?.RequestUri?.ToString() ?? string.Empty;
 6  
 7          string message() => $"{(int)status} {reason} status code of request URI: {uri}";
 8  
 9          if (status < HttpStatusCode.BadRequest)
10          {
11              Logger.LogInformation(message);
12          }
13          else
14          {
15              Logger.LogWarning(message);
16          }
17      }

