 1      protected virtual IDictionary<string, UpstreamHeaderTemplate> Create(IDictionary<string, string> upstreamHeaderTemplates, bool routeIsCaseSensitive)
 2      {
 3          var result = new Dictionary<string, UpstreamHeaderTemplate>();
 4          foreach (var headerTemplate in upstreamHeaderTemplates)
 5          {
 6              var headerTemplateValue = headerTemplate.Value;
 7              var matches = RegexPlaceholders().Matches(headerTemplateValue);
 8  
 9              if (matches.Count > 0)
10              {
11                  var placeholders = matches.Select(m => m.Groups[1].Value).ToArray();
12                  for (int i = 0; i < placeholders.Length; i++)
13                  {
14                      var placeholder = placeholders[i];
15                      var placeholderName = placeholder[8..^1]; // remove "{header:" and "}"
16                      headerTemplateValue = headerTemplateValue.Replace(placeholder, $"(?<{placeholderName}>.+)");
17                  }
18              }
19  
20              var template = routeIsCaseSensitive
21                  ? $"^{headerTemplateValue}$"
22                  : $"^(?i){headerTemplateValue}$"; // ignore case
23  
24              result.Add(headerTemplate.Key, new(template, headerTemplate.Value));
25          }
26  
27          return result;
28      }

