 1      public async Task Invoke(HttpContext httpContext)
 2      {
 3          var downstreamRoute = httpContext.Items.DownstreamRoute();
 4          var options = downstreamRoute.CacheOptions;
 5          if (!options.UseCache)
 6          {
 7              await _next.Invoke(httpContext);
 8              return;
 9          }
10  
11          var downstreamRequest = httpContext.Items.DownstreamRequest();
12          var downstreamUrlKey = $"{downstreamRequest.Method}-{downstreamRequest.OriginalString}";
13          var downStreamRequestCacheKey = await _cacheGenerator.GenerateRequestCacheKey(downstreamRequest, downstreamRoute);
14  
15          Logger.LogDebug(() => $"Started checking cache for the '{downstreamUrlKey}' key.");
16          var cached = _outputCache.Get(downStreamRequestCacheKey, options.Region);
17          if (cached != null)
18          {
19              Logger.LogDebug(() => $"Cache entry exists for the '{downstreamUrlKey}' key.");
20              var response = CreateHttpResponseMessage(cached);
21              SetHttpResponseMessageThisRequest(httpContext, response);
22              Logger.LogDebug(() => $"Finished returning of cached response for the '{downstreamUrlKey}' key.");
23              return;
24          }
25  
26          Logger.LogDebug(() => $"No response cached for the '{downstreamUrlKey}' key.");
27  
28          await _next.Invoke(httpContext);
29  
30          if (httpContext.Items.Errors().Count > 0)
31          {
32              Logger.LogDebug(() => $"There was a pipeline error for the '{downstreamUrlKey}' key.");
33              return;
34          }
35  
36          var downstreamResponse = httpContext.Items.DownstreamResponse();
37          cached = await CreateCachedResponse(downstreamResponse);
38  
39          var ttl = TimeSpan.FromSeconds(options.TtlSeconds);
40          _outputCache.Add(downStreamRequestCacheKey, cached, options.Region, ttl);
41          Logger.LogDebug(() => $"Finished response added to cache for the '{downstreamUrlKey}' key.");
42      }

