 2      {
 3          var type = exception.GetType();
 4  
 5          // If there is a custom mapper for this exception type, use it
 6          // The idea is the following: When implementing features or providers,
 7          // you can provide a custom mapper
 8          if (_mappers != null && _mappers.TryGetValue(type, out var mapper))
 9          {
10              return mapper(exception);
11          }
12  
13          // The exception thrown by Ocelot.Requester.TimeoutDelegatingHandler
14          if (type == typeof(TimeoutException) && exception.InnerException is null)
15          {
16              return new RequestTimedOutError(exception); // -> 504 Gateway Timeout
17          }
18  
19          if (type == typeof(OperationCanceledException) || type.IsSubclassOf(typeof(OperationCanceledException)))
20          {
21              return new RequestCanceledError(exception.Message);
22          }
23  
24          // Bug #2376 -> https://github.com/ThreeMammals/Ocelot/issues/2376
25          // Late Catch: Map the HttpRequestException to a 400 Bad Request.
26          // If the header format is invalid, HttpClient throws this exception locally.
27          // By catching it here, we ensure Ocelot returns a clean 4xx client error instead of a generic 502 Bad Gateway.
28          if (exception is HttpRequestException && exception.Message.Contains("Request headers must contain only ASCII characters."))
29          {
30              return new BadRequestError(exception); // -> 400 Bad Request
31          }
32  
33          // Map to a 413 Content Too Large (prior Request Entity Too Large) or 502 Bad Gateway
34          if (type == typeof(HttpRequestException) || type == typeof(TimeoutException))
35          {
36              // Inner exception is a BadHttpRequestException, and only this exception exposes the StatusCode property.
37              // We check if the inner exception is a BadHttpRequestException and if the StatusCode is 413, we return a PayloadTooLargeError
38              if (exception.InnerException is BadHttpRequestException { StatusCode: StatusCodes.Status413RequestEntityTooLarge })
39              {
40                  return new PayloadTooLargeError(exception); // -> 413 Content Too Large
41              }
42  
43              return new ConnectionToDownstreamServiceError(exception); // -> 502 Bad Gateway
44          }
45  
46          return new UnableToCompleteRequestError(exception); // -> 500 Internal Server Error
47      }

