 1          internal override string ToString(RecursionLevel level)
 2          {
 3              if (!level.TryIncrement())
 4              {
 5                  return MaximumRecursionLevelReachedToStringValue;
 6              }
 7  
 8              using var textBuilder = StringBuilderPool.Rent();
 9              var text = textBuilder.Builder;
10              text.Append("[ ");
11  
12              foreach (var child in children)
13              {
14                  if (text.Length > 2)
15                  {
16                      text.Append(", ");
17                  }
18                  text.Append(child.ToString(level));
19              }
20  
21              text.Append(" ]");
22  
23              level.Decrement();
24  
25              return text.ToString();
26          }

