 1          private void FillBuffer()
 2          {
 3              if (endOfInput)
 4              {
 5                  return;
 6              }
 7  
 8              var remainingSize = blockSize;
 9              do
10              {
11                  var readCount = input.Read(buffer, writeOffset, remainingSize);
12                  if (readCount == 0)
13                  {
14                      endOfInput = true;
15                      return;
16                  }
17  
18                  remainingSize -= readCount;
19                  writeOffset += readCount;
20                  count += readCount;
