 1          public static string UnIndent(string text)
 2          {
 3              var lines = text
 4                  .Split('\n')
 5                  .Select(l => l.TrimEnd('\r', '\n'))
 6                  .SkipWhile(l => l.Trim(' ', '\t').Length == 0)
 7                  .ToList();
 8  
 9              while (lines.Count > 0 && lines[lines.Count - 1].Trim(' ', '\t').Length == 0)
10              {
11                  lines.RemoveAt(lines.Count - 1);
12              }
13  
14              if (lines.Count > 0)
15              {
16                  var indent = Regex.Match(lines[0], @"^(\s*)");
17                  if (!indent.Success)
18                  {
19                      throw new ArgumentException("Invalid indentation");
20                  }
21  
22                  lines = lines
23                      .Select(l => l.Substring(indent.Groups[1].Length))
24                      .ToList();
25              }
26  
27              return string.Join("\n", lines.ToArray());
28          }

