 1          private static IEnumerable<string> WrapText(string text, int length)
 2          {
 3              foreach (var textLine in text.Split('\n'))
 4              {
 5                  var line = new StringBuilder();
 6                  foreach (var word in textLine.Split(' '))
 7                  {
 8                      if (line.Length == 0)
 9                      {
10                          line.Append(word);
11                      }
12                      else if (line.Length + word.Length + 1 < length)
13                      {
14                          line.Append(' ').Append(word);
15                      }
16                      else
17                      {
18                          yield return line.ToString();
19                          line.Clear().Append(word);
20                      }
21                  }
22  
23                  if (line.Length > 0 || textLine.Length == 0)
24                  {
25                      yield return line.ToString();
26                  }
27              }
28          }

