 1          public override bool EnterMapping(IPropertyDescriptor key, IObjectDescriptor value, IEmitter context, ObjectSerializer serializer)
 2          {
 3              var configuration = handling;
 4              var yamlMember = key.GetCustomAttribute<YamlMemberAttribute>();
 5              if (yamlMember != null && yamlMember.IsDefaultValuesHandlingSpecified)
 6              {
 7                  configuration = yamlMember.DefaultValuesHandling;
 8              }
 9  
10              if ((configuration & DefaultValuesHandling.OmitNull) != 0)
11              {
12                  if (value.Value is null)
13                  {
14                      return false;
15                  }
16              }
17  
18              if ((configuration & DefaultValuesHandling.OmitEmptyCollections) != 0)
19              {
20                  if (value.Value is IEnumerable enumerable)
21                  {
22                      var enumerator = enumerable.GetEnumerator();
23                      var canMoveNext = enumerator.MoveNext();
24                      if (enumerator is IDisposable disposable)
25                      {
26                          disposable.Dispose();
27                      }
28  
29                      if (!canMoveNext)
30                      {
31                          return false;
32                      }
33                  }
34              }
35  
36              if ((configuration & DefaultValuesHandling.OmitDefaults) != 0)
37              {
38                  var defaultValue = key.GetCustomAttribute<DefaultValueAttribute>()?.Value ?? GetDefault(key.Type);
39                  if (Equals(value.Value, defaultValue))
40                  {
41                      return false;
42                  }
43              }
44  
45              return base.EnterMapping(key, value, context, serializer);
46          }

