 4              {
 5                  while (parser.Current != null)
 6                  {
 7                      // so we only want to check keys in this mapping, don't descend
 8                      switch (parser.Current)
 9                      {
10                          case Scalar scalar:
11                              // we've found a scalar, check if it's value matches our predicate
12                              var keyMatched = selector(scalar);
