14                              // move head so we can read or skip value
15                              parser.MoveNext();
16  
17                              // read the value of the mapping key
18                              if (keyMatched)
19                              {
20                                  // success
21                                  value = parser.Current;
22                                  key = scalar;
23                                  return true;
24                              }
25  
26                              // skip the value
27                              parser.SkipThisAndNestedEvents();
28  
29                              break;
30                          case MappingStart _:
31                          case SequenceStart _:
32                              parser.SkipThisAndNestedEvents();
33                              break;
34                          default:
35                              // do nothing, skip to next node
36                              parser.MoveNext();
37                              break;
38                      }
39                  }
40              }
41  
42              key = null;
43              value = null;
44              return false;
45          }

