 9  
10          if (Myself == _config.Controller)
11          {
12              await EnterBarrierAsync("before-shutdown" + n);
13              await TestConductor.ExitAsync(leader, 0);
14              await EnterBarrierAsync("after-shutdown" + n, "after-unavailable" + n, "after-down" + n, "completed" + n);
15          }
16          else if (Myself == leader)
17          {
18              await EnterBarrierAsync("before-shutdown" + n, "after-shutdown" + n);
19              // this node will be shutdown by the controller and doesn't participate in more barriers
20          }
21          else if (Myself == aUser)
22          {
23              var leaderAddress = GetAddress(leader);
24              await EnterBarrierAsync("before-shutdown" + n, "after-shutdown" + n);
25  
26              // detect failure
27              MarkNodeAsUnavailable(leaderAddress);
28              await AwaitAssertAsync(() => ClusterView.UnreachableMembers.Select(x => x.Address).Contains(leaderAddress).ShouldBeTrue());
29              await EnterBarrierAsync("after-unavailable" + n);
30  
31              // user marks the shutdown leader as DOWN
32              Cluster.Down(leaderAddress);
33  
34              // removed
35              await AwaitAssertAsync((() => ClusterView.UnreachableMembers.Select(x => x.Address).Contains(leaderAddress).ShouldBeFalse()));
36              await EnterBarrierAsync("after-down" + n, "completed" + n);
37          }
38          else if (remainingRoles.Contains(Myself))
39          {
40              // remaining cluster nodes, not shutdown
41              var leaderAddress = GetAddress(leader);
42              await EnterBarrierAsync("before-shutdown" + n, "after-shutdown" + n);
43  
44              await AwaitAssertAsync(() => ClusterView.UnreachableMembers.Select(x => x.Address).Contains(leaderAddress).ShouldBeTrue());
45              await EnterBarrierAsync("after-unavailable" + n);
46  
47              await EnterBarrierAsync("after-down" + n);
48              await AwaitMembersUpAsync(currentRoles.Count - 1);
49              var nextExpectedLeader = remainingRoles.First();
50              ClusterView.IsLeader.ShouldBe(Myself == nextExpectedLeader);
51              AssertLeaderIn(remainingRoles);
52  
53              await EnterBarrierAsync("completed" + n);
54          }
55      }

