 2          public async Task QueueSource_should_not_trigger_UnobservedTaskException_when_completion_is_not_watched_and_materializer_is_shut_down()
 3          {
 4              var unobserved = new TaskCompletionSource<AggregateException>(TaskCreationOptions.RunContinuationsAsynchronously);
 5  
 6              EventHandler<UnobservedTaskExceptionEventArgs> handler = (_, args) =>
 7              {
 8                  try
 9                  {
10                      if (args.Exception.Flatten().InnerExceptions.OfType<StreamDetachedException>().Any())
11                          unobserved.TrySetResult(args.Exception);
12                  }
13                  finally
14                  {
15                      args.SetObserved();
16                  }
17              };
18  
19              TaskScheduler.UnobservedTaskException += handler;
20              try
21              {
22                  var refs = await this.AssertAllStagesStoppedAsync(() => CreateIssue8210FaultedCompletionTaskRefsAsync(10), _materializer);
23  
24                  for (var i = 0; i < 30 && !unobserved.Task.IsCompleted && refs.Any(r => r.Queue.IsAlive || r.CompletionTask.IsAlive); i++)
25                  {
26                      GC.Collect();
27                      GC.WaitForPendingFinalizers();
28                      GC.Collect();
29                      await Task.Delay(100);
30                  }
31  
32                  refs.Count(r => !r.Queue.IsAlive).Should().BeGreaterThan(0,
33                      "the discarded Source.Queue materialized values should become collectible during the repro");
