38                  unobserved.Task.IsCompleted.Should().BeFalse(
39                      "discarding Source.Queue completion should not leave an internal faulted task unobserved during abrupt shutdown");
40              }
41              finally
42              {
43                  TaskScheduler.UnobservedTaskException -= handler;
44              }
45          }

