 1          public override object FromBinary(byte[] bytes, Type type)
 2          {
 3              var selectionEnvelope = Proto.Msg.SelectionEnvelope.Parser.ParseFrom(bytes);
 4  
 5              var elements = new SelectionPathElement[selectionEnvelope.Pattern.Count];
 6              for (var i = 0; i < selectionEnvelope.Pattern.Count; i++)
 7              {
 8                  var p = selectionEnvelope.Pattern[i];
 9                  if (p.Type == Proto.Msg.Selection.Types.PatternType.ChildName)
10                      elements[i] = new SelectChildName(p.Matcher);
11                  if (p.Type == Proto.Msg.Selection.Types.PatternType.ChildPattern)
12                      elements[i] = new SelectChildPattern(p.Matcher);
13                  if (p.Type == Proto.Msg.Selection.Types.PatternType.Parent)
14                      elements[i] = new SelectParent();
15              }
16  
17              object message;
18              try
19              {
20                  message = _payloadSupport.PayloadFrom(selectionEnvelope.Payload);
21              }
22              catch (Exception ex)
23              {
24                  var payload = selectionEnvelope.Payload;
25  
26                  var manifest = !payload.MessageManifest.IsEmpty
27                      ? payload.MessageManifest.ToStringUtf8()
28                      : string.Empty;
29  
30                  throw new SerializationException(
31                      $"Failed to deserialize payload object when deserializing {nameof(ActorSelectionMessage)} with " +
32                      $"payload [SerializerId={payload.SerializerId}, Manifest={manifest}] addressed to [" +
33                      $"{string.Join(",", elements.Select(e => e.ToString()))}]. {GetErrorForSerializerId(payload.SerializerId)}", ex);
34              }
35  
36              return new ActorSelectionMessage(message, elements);
37          }

