 1          public override void Stop()
 2          {
 3              while (true)
 4              {
 5                  var state = State;
 6                  // if path was never queried nobody can possibly be watching us, so we don't have to publish termination either
 7                  if (state == null)
 8                  {
 9                      if (UpdateState(null, Stopped.Instance)) StopEnsureCompleted();
10                      else continue;
11                  }
12                  else if (state is ActorPath p)
13                  {
14                      if (UpdateState(p, new StoppedWithPath(p)))
15                      {
16                          try
17                          {
18                              StopEnsureCompleted();
19                          }
20                          finally
21                          {
22                              Provider.UnregisterTempActor(p);
23                          }
24                      }
25                      else
26                      {
27                          continue;
28                      }
29                  }
30                  else if (state is Stopped or StoppedWithPath)
31                  {
32                      //already stopped
33                  }
34                  else if (state is Registering)
35                  {
36                      //spin until registration is completed before stopping
37                      continue;
38                  }
39                  break;
40              }
41          }

