 1          public override void SendSystemMessage(ISystemMessage message)
 2          {
 3              switch (message)
 4              {
 5                  case Terminate _:
 6                      Stop();
 7                      break;
 8                  case DeathWatchNotification dw:
 9                      Tell(new Terminated(dw.Actor, dw.ExistenceConfirmed, dw.AddressTerminated), this);
10                      break;
11                  case Watch watch:
12                  {
13                      if (Equals(watch.Watchee, this))
14                      {
15                          if (!AddWatcher(watch.Watcher))
16                          {
17                              // ➡➡➡ NEVER SEND THE SAME SYSTEM MESSAGE OBJECT TO TWO ACTORS ⬅⬅⬅
18                              watch.Watcher.SendSystemMessage(new DeathWatchNotification(watch.Watchee, existenceConfirmed: true,
19                                  addressTerminated: false));
20                          }
21                          else
22                          {
23                              //TODO: find a way to get access to logger?
24                              Console.WriteLine("BUG: illegal Watch({0},{1}) for {2}", watch.Watchee, watch.Watcher, this);
25                          }
26                      }
27  
28                      break;
29                  }
30                  case Unwatch unwatch when Equals(unwatch.Watchee, this) && !Equals(unwatch.Watcher, this):
31                      RemoveWatcher(unwatch.Watcher);
32                      break;
33                  case Unwatch unwatch:
34                      Console.WriteLine("BUG: illegal Unwatch({0},{1}) for {2}", unwatch.Watchee, unwatch.Watcher, this);
35                      break;
36              }
37          }

