 1          private ActorPath GetPath()
 2          {
 3              while (true)
 4              {
 5                  // snapshot the state once per iteration - another thread can flip it at any time
 6                  // (i.e. a concurrent Stop() moving us from ActorPath to StoppedWithPath), so
 7                  // matching on the field and then re-reading it can observe two different values.
 8                  var state = State;
 9                  switch (state)
10                  {
11                      case null when UpdateState(null, Registering.Instance):
12                      {
13                          ActorPath p = null;
14                          try
15                          {
16                              p = Provider.TempPath();
17                              Provider.RegisterTempActor(this, p);
18                              return p;
19                          }
20                          finally
21                          {
22                              State = p;
23                          }
24                      }
25                      case null:
26                          continue;
27                      case ActorPath path:
28                          return path;
29                      case StoppedWithPath stoppedWithPath:
30                          return stoppedWithPath.Path;
31                      case Stopped _:
32                          //even if we are already stopped we still need to produce a proper path
33                          UpdateState(Stopped.Instance, new StoppedWithPath(Provider.TempPath()));
34                          continue;
35                      case Registering _:
36                          continue;
37                  }
38              }
39          }

