 1          public static Task<T> Ask<T>(this ICanTell self, Func<IActorRef, object> messageFactory, TimeSpan? timeout, CancellationToken cancellationToken)
 2          {
 3              IActorRefProvider provider = ResolveProvider(self);
 4              if (provider == null)
 5                  throw new ArgumentException("Unable to resolve the target Provider", nameof(self));
 6  
 7              var result = TaskEx.NonBlockingTaskCompletionSource<T>();
 8  
 9              CancellationTokenSource timeoutCancellation = null;
10              timeout ??= provider.Settings.AskTimeout;
11  
12              CancellationTokenRegistration? ctr1 = null;
13              CancellationTokenRegistration? ctr2 = null;
14  
15              if (timeout != Timeout.InfiniteTimeSpan && timeout.Value > default(TimeSpan))
16              {
17                  timeoutCancellation = new CancellationTokenSource();
18  
19                  ctr1 = timeoutCancellation.Token.Register(() =>
20                  {
21                      result.TrySetException(new AskTimeoutException($"Timeout after {timeout.Value.TotalSeconds:F2} seconds"));
22                  });
23  
24                  timeoutCancellation.CancelAfter(timeout.Value);
25              }
26  
27              if (cancellationToken.CanBeCanceled)
28              {
29                  ctr2 = cancellationToken.Register(() => result.TrySetCanceled());
30              }
31  
32              var future = provider.CreateFutureRef(result);
33              var path = future.Path;
34  
35              //The future actor needs to be unregistered in the temp container
36              _ = result.Task.ContinueWith(_ =>
37              {
38                  provider.UnregisterTempActor(path);
39  
40                  ctr1?.Dispose();
41                  ctr2?.Dispose();
42                  timeoutCancellation?.Dispose();
43              }, TaskContinuationOptions.ExecuteSynchronously);
44  
45              //The future actor needs to be registered in the temp container
46              provider.RegisterTempActor(future, path);
47              var message = messageFactory(future);
48              future.DeliverAsk(message, self);
49  
50              return result.Task;
51          }

