 1          public static void RunTask(Func<Task> asyncAction)
 2          {
 3              var context = ActorCell.Current;
 4  
 5              if (context == null)
 6                  throw new InvalidOperationException("RunTask must be called from an actor context.");
 7  
 8              var dispatcher = context.Dispatcher;
 9  
10              //suspend the mailbox
11              dispatcher.Suspend(context);
12  
13              var actorScheduler = context.TaskScheduler;
14              actorScheduler.CurrentMessage = context.CurrentMessage;
15  
16              actorScheduler.OnBeforeTaskStarted();
17  
18              Task<Task>.Factory.StartNew(asyncAction, CancellationToken.None, TaskCreationOptions.None, actorScheduler)
19                                .Unwrap()
20                                .ContinueWith(parent =>
21                                {
22                                    var exception = GetTaskException(parent);
23                                    if (exception == null)
24                                    {
25                                        dispatcher.Resume(context);
26                                        context.CheckReceiveTimeout(context.CurrentMessage is not INotInfluenceReceiveTimeout);
27                                    }
28                                    else
29                                    {
30                                        context.Self.AsInstanceOf<IInternalActorRef>().SendSystemMessage(new ActorTaskSchedulerMessage(exception, actorScheduler.CurrentMessage));
31                                    }
32  
33                                    // Used by TestActorRef to intercept async execution result
34                                    if(actorScheduler is IAsyncResultInterceptor interceptor)
35                                        interceptor.OnTaskCompleted(actorScheduler.CurrentMessage, exception);
36  
37                                    //clear the current message field of the scheduler
38                                    actorScheduler.CurrentMessage = null;
39                                    actorScheduler.OnAfterTaskCompleted();
40                                }, actorScheduler);
41          }

