 1          protected override void QueueTask(Task task)
 2          {
 3              if ((task.CreationOptions & TaskCreationOptions.LongRunning) == TaskCreationOptions.LongRunning)
 4              {
 5                  // Executing a LongRunning task in an ActorTaskScheduler is bad practice, it will potentially
 6                  // hang the actor and starve the ThreadPool
 7  
 8                  // The best thing we can do here is force a rescheduling to at least not execute the task inline.
 9                  ScheduleTask(task);
10                  return;
11              }
12  
13              // Schedule the task execution, run inline if we are already in the actor context.
14              if (ActorCell.Current == _actorCell)
15              {
16                  TryExecuteTask(task);
17              }
18              else
19              {
20                  ScheduleTask(task);
21              }
22          }

