 1          private async Task RandomDemandAsync(Dictionary<int, SubFlowState> map, RandomDemandProperties props)
 2          {
 3              while (true)
 4              {
 5                  var nextIndex = ThreadLocalRandom.Current.Next(0, map.Count);
 6                  var key = map.Keys.ToArray()[nextIndex];
 7                  if (!map[key].HasDemand)
 8                  {
 9                      var state = map[key];
10                      map[key] = new SubFlowState(state.Probe, true, state.FirstElement);
11  
12                      await state.Probe.RequestAsync(1);
13  
14                      // need to verify elements that are first element in subFlow or is in nextElement buffer before
15                      // pushing next element from upstream
16                      if (state.FirstElement != null)
17                      {
18                          (await state.Probe.ExpectNextAsync()).Span.SequenceEqual(state.FirstElement.Value.Span).Should().BeTrue();
19                          map[key] = new SubFlowState(state.Probe, false, null);
20                      }
21                      else if (props.BlockingNextElement != null && Math.Abs(props.BlockingNextElement.Value.Span[0] % 100) == key)
22                      {
23                          (await state.Probe.ExpectNextAsync()).Span.SequenceEqual(props.BlockingNextElement.Value.Span).Should().BeTrue();
24                          props.BlockingNextElement = null;
25                          map[key] = new SubFlowState(state.Probe, false, null);
26                      }
27                      else if (props.BlockingNextElement == null)
28                          break;
29                  }
30              }
31  
32          }

