 1          private async Task<Option<(OffsetState, IReadOnlyList<EventEnvelope>)>> ByOrderingStep(string? tag, bool live, OffsetState state)
 2          {
 3              if (state.Done)
 4                  return Option<(OffsetState, IReadOnlyList<EventEnvelope>)>.None;
 5  
 6              var next = state.Started ? state.Next : await ResolveStartAsync(tag, state.Initial).ConfigureAwait(false);
 7              if (live && state.Wait)
 8                  await Delay().ConfigureAwait(false);
 9  
10              var take = _settings.MaxBufferSize;
11              long max;
12              List<RawJournalRow> rows;
13              var from = next;
14              if (!live && state.Started)
15              {
16                  // a current query stops at the max it saw when it started
17                  max = state.Max;
18                  rows = await RunAsync(connection => _sql.ReadOrdered(connection, null, tag, from, state.Max, take)).ConfigureAwait(false);
19              }
20              else
21              {
22                  // MAX(ordering) and the batch come from one read transaction: no committed row can hide below it
23                  var batch = await RunAsync(connection => _sql.ReadMaxAndBatch(connection, tag, from, take)).ConfigureAwait(false);
24                  max = batch.MaxOrdering;
25                  rows = batch.Rows;
26              }
27  
28              if (!live)
29              {
30                  if (rows.Count == 0)
31                      return Option<(OffsetState, IReadOnlyList<EventEnvelope>)>.None;
32  
33                  var lastOrdering = rows[^1].Ordering;
34                  var done = rows.Count < take || lastOrdering >= max;
35                  return Next(state with { Started = true, Next = lastOrdering, Max = max, Done = done }, ToEnvelopes(rows));
36              }
37  
38              if (rows.Count == 0)
39                  return Next(state with { Started = true, Next = Math.Max(next, max), Max = max, Wait = true }, Array.Empty<EventEnvelope>());
40  
41              return Next(
42                  state with { Started = true, Next = rows[^1].Ordering, Max = max, Wait = rows.Count < take },
43                  ToEnvelopes(rows));
44          }

