 1          private async Task<long> ResolveStartAsync(string? tag, Offset? offset)
 2          {
 3              switch (offset)
 4              {
 5                  case Sequence sequence:
 6                      return sequence.Value;
 7                  case FromEnd fromEnd:
 8                      {
 9                          var count = fromEnd.Count;
10                          var found = await RunAsync(connection => _sql.ReadFromEndOrdering(connection, tag, count)).ConfigureAwait(false);
11                          return found is null ? 0L : found.Value - 1;
12                      }
13                  default:
14                      // NoOffset, null and every other offset type start at the beginning
15                      return 0L;
16              }
17          }

