 1          private async Task<Option<(PidState, IReadOnlyList<EventEnvelope>)>> ByPersistenceIdStep(string persistenceId, long to, bool live, PidState state)
 2          {
 3              if (state.Done || state.Next > to)
 4                  return Option<(PidState, IReadOnlyList<EventEnvelope>)>.None;
 5  
 6              if (live && state.Wait)
 7                  await Delay().ConfigureAwait(false);
 8  
 9              var take = _settings.MaxBufferSize;
10              var next = state.Next;
11              var rows = await RunAsync(connection => _sql.ReadByPersistenceId(connection, persistenceId, next, to, take)).ConfigureAwait(false);
12  
13              if (rows.Count == 0)
14              {
15                  return live
16                      ? Next(state with { Wait = true }, Array.Empty<EventEnvelope>())
17                      : Option<(PidState, IReadOnlyList<EventEnvelope>)>.None;
18              }
19  
20              var envelopes = ToEnvelopes(rows);
21              var last = rows[^1].SequenceNr;
22              var reachedEnd = last >= to;
23              var done = live ? reachedEnd : reachedEnd || rows.Count < take;
24              return Next(new PidState(last + 1, live && rows.Count < take, done), envelopes);
25          }

