 3              _log.Debug("allocateShard [{0}] [{1}] [{2}]", shardId, requester, string.Join(", ", currentShardAllocations.Select(i => $"{i.Key}: {string.Join(", ", i.Value)}")));
 4  
 5              // current shard allocations include all current shard regions
 6              try
 7              {
 8                  var slr = await _shardState.Ask<GetShardLocationResponse>(new GetShardLocation(shardId), Timeout);
 9  
10                  if (slr.Address != null)
11                  {
12                      _log.Debug("No specific location for shard [{0}]. Allocating to requester [{1}]", shardId, requester);
13                      return requester;
14                  }
15                  else
16                  {
17                      // if it is the local address, convert it so it is found in the shards
18                      if (slr.Address.Equals(_cluster.SelfAddress))
19                      {
20                          var localShardRegion = currentShardAllocations.Keys.FirstOrDefault(i => i.Path.Address.HasLocalScope);
21                          if (localShardRegion == null)
22                          {
23                              _log.Debug("unable to find local shard in currentShardAllocation. Using requester");
24                              return requester;
25                          }
26                          else
27                          {
28                              _log.Debug("allocating to local shard");
29                              return localShardRegion;
30                          }
31                      }
32                      else
33                      {
34                          var location = currentShardAllocations.Keys.FirstOrDefault(i => i.Path.Address.Equals(slr.Address));
35                          if (location == null)
36                          {
37                              _log.Debug("External shard location [{0}] for shard [{1}] not found in members [{2}]",
38                                  slr.Address,
39                                  shardId,
40                                  string.Join(", ", currentShardAllocations.Keys));
41                              return requester;
42                          }
43                          else
44                          {
45                              _log.Debug("Allocating shard to location [{0}]", location);
46                              return location;
47                          }
48                      }
49                  }
50              }
51              catch (AskTimeoutException)
52              {
53                  _log.Warning("allocate timed out waiting for shard allocation state [{0}]. Allocating to requester [{1}]",
54                      shardId,
55                      requester);
56                  return requester;
57              }
58          }

