 1          private static MultiNodeTestRunnerOptions Load(Stream configStream)
 2          {
 3              var result = new MultiNodeTestRunnerOptions();
 4              try
 5              {
 6                  using (var reader = new StreamReader(configStream))
 7                  {
 8                      var config = (JsonObject) JsonDeserializer.Deserialize(reader);
 9                      foreach (var propertyName in config.Keys)
10                      {
11                          var propertyValue = config.Value(propertyName);
12  
13                          switch (propertyValue)
14                          {
15                              case JsonBoolean booleanValue:
16                                  if (string.Equals(propertyName, Configuration.AppendLogOutput, StringComparison.OrdinalIgnoreCase))
17                                      result.AppendLogOutput = booleanValue.Value;
18                                  if (string.Equals(propertyName, Configuration.UseBuiltInTrxReporter, StringComparison.OrdinalIgnoreCase))
19                                      result.UseBuiltInTrxReporter = booleanValue.Value;
20                                  break;
21  
22                              case JsonString stringValue:
23                                  if (string.Equals(propertyName, Configuration.OutputDirectory, StringComparison.OrdinalIgnoreCase))
24                                      result.OutputDirectory = stringValue.Value;
25                                  if (string.Equals(propertyName, Configuration.FailedSpecsDirectory, StringComparison.OrdinalIgnoreCase))
26                                      result.FailedSpecsDirectory = stringValue.Value;
27                                  if(string.Equals(propertyName, Configuration.ListenAddress, StringComparison.OrdinalIgnoreCase))
28                                      result.ListenAddress = stringValue.Value;
29                                  break;
30  
31                              case JsonNumber numberValue when string.Equals(propertyName, Configuration.ListenPort, StringComparison.OrdinalIgnoreCase):
32                                  int.TryParse(numberValue.Raw, out var port);
33                                  if(port != 0)
34                                      result.ListenPort = port;
35                                  break;
36                          }
37                      }
38                  }
39              }
40              catch { }
41  
42              return result;
43          }

