34              });
35  
36              // Shard should still be functioning without any disruption
37              setup.Sharding.Tell(new EntityEnvelope(1, "hello2"), probe.Ref);
38              await probe.ExpectMsgAsync("ack hello2", TimeSpan.FromSeconds(3));
39          }

