 1      internal static ScanResult Scan(IEnumerable<string> logLines, string repoRoot, IReadOnlyList<string> scopePrefixes)
 2      {
 3          var found = new List<Warning>();
 4          var seen = new HashSet<string>(StringComparer.Ordinal);
 5          var otherFile = 0;
 6          var noLocation = 0;
 7  
 8          foreach (var line in logLines)
 9          {
10              var match = Diagnostic.Match(line);
11              if (!match.Success)
12              {
13                  if (NoLocation.IsMatch(line))
14                      noLocation++;
15                  continue;
16              }
17  
18              var file = ToRepoRelative(match.Groups["file"].Value, repoRoot);
19              if (!scopePrefixes.Any(prefix => file.StartsWith(prefix, StringComparison.Ordinal)))
20              {
21                  otherFile++;
22                  continue;
23              }
24  
25              var body = ProjectSuffix.Replace(match.Groups["message"].Value, string.Empty).Trim();
26  
27              // Split the member prefix off the prose, so the two get their own key components. The
28              // Roslyn analyzer form has no prefix, leaving the member empty.
29              var prefix = MemberPrefix.Match(body);
30              var member = prefix.Success ? prefix.Groups["member"].Value : string.Empty;
31              var prose = prefix.Success ? body[prefix.Length..] : body;
32  
33              var warning = new Warning(
34                  match.Groups["code"].Value,
35                  file,
36                  member,
37                  WhitespaceAndDigits.Replace(prose, string.Empty),
38                  // First sighting's text, so the failure report quotes a real line number even though
39                  // the key does not use one.
40                  $"{file}({match.Groups["line"].Value}): {match.Groups["severity"].Value} {match.Groups["code"].Value}: {body}");
41  
42              if (seen.Add(warning.Key))
43                  found.Add(warning);
44          }
45  
46          // Fold the Roslyn-analyzer form (no member prefix) into the ILC/ILLink form of the same
47          // warning, so a publish log that happens to contain both does not baseline it twice.
48          var withMember = found.Where(w => w.Member.Length > 0).Select(w => w.FormKey)
49                                .ToHashSet(StringComparer.Ordinal);
50          var kept = found.Where(w => w.Member.Length > 0 || !withMember.Contains(w.FormKey));
51  
52          var inScope = new Dictionary<string, string>(StringComparer.Ordinal);
53          foreach (var warning in kept)
54              inScope[warning.Key] = warning.Display;
55  
56          return new ScanResult(inScope, otherFile, noLocation);
57      }

