 1          [InternalApi]
 2          protected IActorRef ActorOf(Props props, string name, string dispatcher)
 3          {
 4              switch (Supervisor)
 5              {
 6                  case LocalActorRef localActorRef:
 7                      return ((ActorCell) localActorRef.Underlying).AttachChild(props.WithDispatcher(dispatcher),
 8                          isSystemService: false, name: name);
 9                  case RepointableActorRef { IsStarted: true } repointableActorRef:
10                      return ((ActorCell)repointableActorRef.Underlying).AttachChild(props.WithDispatcher(dispatcher), isSystemService: false, name: name);
11                  case RepointableActorRef repointableActorRef:
12                  {
13                      var timeout = repointableActorRef.Underlying.System.Settings.CreationTimeout;
14                      var f = repointableActorRef.Ask<IActorRef>(new StreamSupervisor.Materialize(props.WithDispatcher(dispatcher), name), timeout);
15                      return f.Result;
16                  }
17                  default:
18                      throw new IllegalStateException($"Stream supervisor must be a local actor, was [{Supervisor.GetType()}]");
19              }
20          }

