 1          [Fact(DisplayName = "A stale UID quarantine and delayed old-incarnation Clear preserve the replacement peer's reliable state")]
 2          public async Task Should_Preserve_New_Incarnation_State_When_Old_UID_Is_Quarantined()
 3          {
 4              var cancellation = TestContext.Current.CancellationToken;
 5              var (registry, association, oldPeer, context) = SeedUnacknowledgedWatch();
 6              var oldIncarnation = association.CurrentState.Incarnation;
 7              registry.CompleteHandshake(Remote, new UniqueAddress(Remote, oldPeer.Uid + 1));
 8              // This seeded state now belongs to the replacement incarnation; no stage owns it yet.
 9              association.SystemMessageDeliveryState.CurrentIncarnation = association.CurrentState.Incarnation;
10              association.Quarantine(oldPeer.Uid).Should().BeFalse();
11              association.TryEnqueueControl(new OutboundEnvelope(new ClearSystemMessageDelivery(oldIncarnation), null, null)).Should().BeTrue();
12              var barrier = new OutboundEnvelope("new-incarnation", null, null);
13              association.TryEnqueueControl(barrier).Should().BeTrue();
14              association.PrepareControlRestart();
15              association.CompleteControlOutbound();
16              var sink = ChannelSource.FromReader(association.ControlReader)
17                  .Via(Flow.FromGraph(Stage(context, association.SystemMessageDeliveryState)))
18                  .RunWith(this.SinkProbe<IOutboundEnvelope>(), ActorMaterializer.Create(Sys));
19              await sink.RequestAsync(3);
20              (await sink.ExpectNextAsync(TimeSpan.FromSeconds(3), cancellation)).Message.Should().BeOfType<SystemMessageEnvelope>();
21              (await sink.ExpectNextAsync(TimeSpan.FromSeconds(3), cancellation)).Should().BeSameAs(barrier);
22              await sink.ExpectCompleteAsync(cancellationToken: cancellation);
23              association.SystemMessageDeliveryState.Buffer.Should().HaveCount(1);
24              association.SystemMessageDeliveryState.NextSeq.Should().Be(2L);
25          }

