 1          [Fact(DisplayName = "Reliable replay already held by handshake cannot reach encoding after quarantine")]
 2          public async Task Should_Filter_Reliable_Replay_Already_Held_Downstream_Of_Delivery_Stage()
 3          {
 4              var cancellation = TestContext.Current.CancellationToken;
 5              var (registry, association, peer, context) = SeedUnacknowledgedWatch();
 6              var passedDelivery = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
 7              // Separate contexts share association state, but only the delivery context
 8              // observes callbacks. Handshake reads cannot satisfy the ordering barrier.
 9              var handshakeContext = new AssociationRegistryOutboundContext(registry, Local, Remote, _ => { });
10              var handshake = new OutboundHandshakeStage(handshakeContext,
11                  TimeSpan.FromSeconds(30), TimeSpan.FromMinutes(1), TimeSpan.FromMinutes(1), forceReqOnStart: true);
12              var (pub, sub) = this.SourceProbe<IOutboundEnvelope>()
13                  .Via(Flow.FromGraph(Stage(context, association.SystemMessageDeliveryState)))
14                  .Select(envelope =>
15                  {
16                      if (envelope.Message is SystemMessageEnvelope) passedDelivery.TrySetResult(true);
17                      return envelope;
18                  })
19                  .Via(Flow.FromGraph(handshake))
20                  .Where(association.ShouldSendControl) // The production guard immediately before encode.
21                  .ToMaterialized(this.SinkProbe<IOutboundEnvelope>(), Keep.Both)
22                  .Run(ActorMaterializer.Create(Sys));
23              await sub.RequestAsync(2);
24              (await sub.ExpectNextAsync(TimeSpan.FromSeconds(3), cancellation)).Message.Should().BeOfType<HandshakeReq>();
25              await passedDelivery.Task.WaitAsync(TimeSpan.FromSeconds(3), cancellation);
26              var subscriber = await context.Subscriber.Task.WaitAsync(TimeSpan.FromSeconds(3), cancellation);
27              var held = context.ObserveNextRead();
28              subscriber.ControlMessageReceived(peer.Uid, new SysAck(0L, peer));
29              await held.WaitAsync(TimeSpan.FromSeconds(3), cancellation);
30  
31              // The callback runs after the fused handshake OnPush has parked the Watch.
32              // Clearing delivery's own queue now cannot retract that downstream envelope.
33              association.Quarantine(peer.Uid).Should().BeTrue();
34              registry.CompleteOutboundHandshake(Remote, peer);
35              var barrier = new OutboundEnvelope("after-handshake", null, null);
36              await pub.SendNextAsync(barrier);
37              (await sub.ExpectNextAsync(TimeSpan.FromSeconds(3), cancellation)).Should().BeSameAs(barrier);
38              await pub.SendCompleteAsync();
39              await sub.ExpectCompleteAsync(cancellationToken: cancellation);
40              association.SystemMessageDeliveryState.Buffer.Should().BeEmpty();
41          }

