 1          [Theory(DisplayName = "Restarting after quarantine never replays an unacknowledged Watch ahead of retained control traffic or a delayed Clear")]
 2          [InlineData(false)]
 3          [InlineData(true)]
 4          public async Task Should_Clear_Quarantined_Reliable_State_Before_Restart_Replay(bool earlierControl)
 5          {
 6              var cancellation = TestContext.Current.CancellationToken;
 7              var (registry, association, peer, context) = SeedUnacknowledgedWatch();
 8              var materializer = ActorMaterializer.Create(Sys);
 9              var (oldPub, oldSub) = this.SourceProbe<IOutboundEnvelope>()
10                  .Via(Flow.FromGraph(Stage(context, association.SystemMessageDeliveryState)))
11                  .ToMaterialized(this.SinkProbe<IOutboundEnvelope>(), Keep.Both)
12                  .Run(materializer);
13              await oldSub.RequestAsync(1);
14              (await oldSub.ExpectNextAsync(TimeSpan.FromSeconds(3), cancellation)).Message.Should().BeOfType<SystemMessageEnvelope>();
15              var retained = new OutboundEnvelope(new DaemonMsgCreate(Props.Empty, Deploy.None, "/remote/target", TestActor), null, null);
16              var notice = new OutboundEnvelope(new ArteryQuarantined(Local, peer.Uid), null, null);
17              if (earlierControl) association.TryEnqueueControl(retained).Should().BeTrue();
18              association.TryEnqueueControl(notice).Should().BeTrue();
19              association.TryEnqueueControl(new OutboundEnvelope(
20                  new ClearSystemMessageDelivery(association.CurrentState.Incarnation), null, null)).Should().BeTrue();
21              association.Quarantine(peer.Uid).Should().BeTrue();
22  
23              // Fail the actual old stream after its Watch was emitted but never acked.
24              // Await PostStop before touching shared delivery state from restart cleanup.
25              var failure = new IOException("Injected control-stream failure.");
26              await oldPub.SendErrorAsync(failure, cancellation);
27              (await oldSub.ExpectErrorAsync(cancellation)).Should().BeSameAs(failure);
28              await context.Stopped.Task.WaitAsync(TimeSpan.FromSeconds(3), cancellation);
29              association.SystemMessageDeliveryState.Buffer.Should().HaveCount(1);
30              association.PrepareControlRestart();
31              association.CompleteControlOutbound();
32              context = new ObservingContext(new AssociationRegistryOutboundContext(registry, Local, Remote, _ => { }));
33              var sink = ChannelSource.FromReader(association.ControlReader)
34                  .Via(Flow.FromGraph(Stage(context, association.SystemMessageDeliveryState)))
35                  .RunWith(this.SinkProbe<IOutboundEnvelope>(), materializer);
36              await sink.RequestAsync(4);
37              if (earlierControl)
38                  (await sink.ExpectNextAsync(TimeSpan.FromSeconds(3), cancellation)).Should().BeSameAs(retained);
39              (await sink.ExpectNextAsync(TimeSpan.FromSeconds(3), cancellation)).Should().BeSameAs(notice);
40              await sink.ExpectCompleteAsync(cancellationToken: cancellation);
41              association.SystemMessageDeliveryState.Buffer.Should().BeEmpty();
42              association.SystemMessageDeliveryState.NextSeq.Should().Be(1L);
43          }

