 1      private static void PrintFailure(Exception? ex)
 2      {
 3          if (ex is null)
 4          {
 5              Console.WriteLine("[canary-sqlite] FAILED: unhandled non-exception throw");
 6              return;
 7          }
 8  
 9          Console.WriteLine($"[canary-sqlite] FAILED: {ex.GetType().FullName}: {ex.Message}");
10          Console.WriteLine(ex.StackTrace);
11  
12          var inner = ex.InnerException;
13          var depth = 0;
14          while (inner is not null && depth++ < 10)
15          {
16              Console.WriteLine($"[canary-sqlite]  --> inner: {inner.GetType().FullName}: {inner.Message}");
17              Console.WriteLine(inner.StackTrace);
18              inner = inner.InnerException;
19          }
20      }

