 1      private static async Task RunCustomTablesAsync(string path)
 2      {
 3          const string label = "custom-tables";
 4          var watchdog = new LogWatchdogFilter();
 5          await using var hosted = await StartHostedAsync(label, path, customTableNames: true, watchdog);
 6          var system = hosted.System;
 7          {
 8              var actor = system.ActorOf(Props.Create(() => new CanaryPersistentActor("custom-1", true)), "custom-1");
 9              Require(label, await actor.Ask<int>(new PersistCmd("plain", false), AskTimeout) == 1, "persist plain");
10              Require(label, await actor.Ask<int>(new PersistCmd("tagged", true), AskTimeout) == 2, "persist tagged");
11              Require(label, await actor.Ask<int>(new PersistCmd("last", true), AskTimeout) == 3, "persist last");
12              Require(label, await actor.Ask<long>(new SaveNow(), AskTimeout) == 3, "snapshot at 3");
13              Require(label, await actor.Ask<long>(new DeleteTo(2), AskTimeout) == 2, "delete up to 2");
14  
15              var readJournal = system.ReadJournalFor<SqliteReadJournal>(SqliteReadJournal.Identifier);
16              var found = await readJournal.CurrentEventsByTag("red", Offset.NoOffset())
17                  .RunWith(Sink.Seq<EventEnvelope>(), system.Materializer()).WaitAsync(AskTimeout);
18              Require(label, found.Count == 1 && found[0].SequenceNr == 3 && found[0].Tags.SequenceEqual(["red"]),
19                  $"CurrentEventsByTag(red) returned {found.Count} envelopes after the delete");
20  
21              await using var connection = new SqliteConnection($"Data Source={path};Pooling=False");
22              await connection.OpenAsync();
23              await using var command = connection.CreateCommand();
24              command.CommandText = "SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('canary_events', 'canary_tags', 'canary_snapshots', 'journal', 'tags', 'snapshot')";
25              var names = new List<string>();
26              await using (var reader = await command.ExecuteReaderAsync())
27              {
28                  while (await reader.ReadAsync())
29                      names.Add(reader.GetString(0));
30              }
31  
32              Require(label, names.Order().SequenceEqual(["canary_events", "canary_snapshots", "canary_tags"]),
33                  $"the tables were [{string.Join(',', names)}]");
34              Console.WriteLine($"[canary-sqlite] {label}: events, tags and snapshots went to the custom tables, and the tag query skipped the tombstone");
35  
36              watchdog.ThrowIfAnyProblems(label, "run");
37          }
38          Console.WriteLine($"[canary-sqlite] {label}: terminated");
39      }

