 1      private static async Task AssertCurrentQueriesAsync(string label, ActorSystem system)
 2      {
 3          var readJournal = system.ReadJournalFor<SqliteReadJournal>(SqliteReadJournal.Identifier);
 4          var materializer = system.Materializer();
 5  
 6          var ids = await readJournal.CurrentPersistenceIds().RunWith(Sink.Seq<string>(), materializer).WaitAsync(AskTimeout);
 7          Require(label, ids.SequenceEqual(["p1"]), $"CurrentPersistenceIds returned [{string.Join(',', ids)}]");
 8  
 9          var byId = await readJournal.CurrentEventsByPersistenceId("p1", 0, long.MaxValue)
10              .RunWith(Sink.Seq<EventEnvelope>(), materializer).WaitAsync(AskTimeout);
11          Require(label, byId.Select(e => e.SequenceNr).SequenceEqual([3L, 4L, 5L]), "CurrentEventsByPersistenceId did not return events 3-5");
12          Require(label, byId.All(e => e.Offset is Sequence), "an envelope did not carry a Sequence offset");
13  
14          var byTag = await readJournal.CurrentEventsByTag("red", Offset.NoOffset())
15              .RunWith(Sink.Seq<EventEnvelope>(), materializer).WaitAsync(AskTimeout);
16          Require(label, byTag.Count == 1 && byTag[0].SequenceNr == 4 && byTag[0].Tags.SequenceEqual(["red"]),
17              $"CurrentEventsByTag(red) returned {byTag.Count} envelopes");
18  
19          var all = await readJournal.CurrentAllEvents(Offset.NoOffset())
20              .RunWith(Sink.Seq<EventEnvelope>(), materializer).WaitAsync(AskTimeout);
21          Require(label, all.Count == 3, $"CurrentAllEvents returned {all.Count} envelopes, not 3");
22  
23          var fromEnd = await readJournal.CurrentAllEvents(new FromEnd(1))
24              .RunWith(Sink.Seq<EventEnvelope>(), materializer).WaitAsync(AskTimeout);
25          Require(label, fromEnd.Count == 1 && fromEnd[0].SequenceNr == 5 && fromEnd[0].Offset is Sequence,
26              $"CurrentAllEvents(FromEnd(1)) returned {fromEnd.Count} envelopes");
27  
28          Console.WriteLine($"[canary-sqlite] {label}: every current query returned what it should");
29      }

