 1          protected override async Task<AssociationHandle> AssociateInternal(Address remoteAddress)
 2          {
 3              try
 4              {
 5                  var clientBootstrap = ClientFactory(remoteAddress);
 6                  var socketAddress = AddressToSocketAddress(remoteAddress);
 7                  socketAddress = await MapEndpointAsync(socketAddress).ConfigureAwait(false);
 8                  var associate = await clientBootstrap.ConnectAsync(socketAddress).ConfigureAwait(false);
 9                  var handler = (TcpClientHandler)associate.Pipeline.Last();
10                  // Wait for channel activation (socket connect)
11                  var handle = await handler.StatusFuture.ConfigureAwait(false);
12  
13                  if (!Settings.EnableSsl)
14                      return handle;
15  
16                  // If SSL is enabled, ensure the TLS handshake has completed successfully
17                  try
18                  {
19                      await handler.TlsHandshakeTask.ConfigureAwait(false);
20                  }
21                  catch (Exception ex)
22                  {
23                      throw new InvalidAssociationException($"TLS handshake failed for {remoteAddress}: {ex.Message}", ex);
24                  }
25  
26                  return handle;
27              }
28              catch (ConnectException c)
29              {
30                  throw HandleConnectException(remoteAddress, c, null);
31              }
32              catch (AggregateException e) when (e.InnerException is ConnectException cause)
33              {
34                  throw HandleConnectException(remoteAddress, cause, e);
35              }
36              catch (ConnectTimeoutException t)
37              {
38                  throw new InvalidAssociationException(t.Message);
39              }
40              catch (AggregateException e) when (e.InnerException is ConnectTimeoutException cause)
41              {
42                  throw new InvalidAssociationException(cause.Message);
43              }
44          }

