 1          public override void ExceptionCaught(IChannelHandlerContext context, Exception exception)
 2          {
 3              var se = exception as SocketException;
 4  
 5              if (se?.SocketErrorCode is SocketError.OperationAborted or SocketError.ConnectionAborted)
 6              {
 7                  Log.Info("Socket read operation aborted. Connection is about to be closed. Channel [{0}->{1}](Id={2})",
 8                      context.Channel.LocalAddress, context.Channel.RemoteAddress, context.Channel.Id);
 9  
10                  NotifyListener(new Disassociated(DisassociateInfo.Shutdown));
11              }
12              else if (se?.SocketErrorCode == SocketError.ConnectionReset)
13              {
14                  Log.Info("Connection was reset by the remote peer. Channel [{0}->{1}](Id={2})",
15                      context.Channel.LocalAddress, context.Channel.RemoteAddress, context.Channel.Id);
16  
17                  NotifyListener(new Disassociated(DisassociateInfo.Shutdown));
18              }
19              // Enhanced TLS exception handling
20              else if (exception is System.Security.Authentication.AuthenticationException
21                       or System.Security.Cryptography.CryptographicException)
22              {
23                  // Determine if this is client or server side based on handler type
24                  var isClient = this is TcpClientHandler;
25                  var detailedError = TlsErrorMessageBuilder.BuildTlsHandshakeErrorMessage(exception, isClient);
26  
27                  Log.Error(exception, "TLS exception on channel [{0}->{1}](Id={2})\n{3}",
28                      context.Channel.LocalAddress, context.Channel.RemoteAddress, context.Channel.Id, detailedError);
29  
30                  NotifyListener(new Disassociated(DisassociateInfo.Unknown));
31              }
32              else
33              {
34                  base.ExceptionCaught(context, exception);
35                  NotifyListener(new Disassociated(DisassociateInfo.Unknown));
36              }
37  
38              context.CloseAsync(); // close the channel
39          }

