 1          public override void UserEventTriggered(IChannelHandlerContext context, object evt)
 2          {
 3              if (evt is DrainInbound)
 4              {
 5                  _draining = true;
 6                  return;
 7              }
 8  
 9              if (evt is TlsHandshakeCompletionEvent { IsSuccessful: false } tlsEvent)
10              {
11                  var ex = tlsEvent.Exception ?? new Exception("TLS handshake failed.");
12  
13                  // Determine if this is client or server side based on handler type
14                  var isClient = this is TcpClientHandler;
15                  var detailedError = TlsErrorMessageBuilder.BuildTlsHandshakeErrorMessage(ex, isClient);
16  
17                  Log.Error(ex, "TLS handshake failed on channel [{0}->{1}](Id={2})\n{3}",
18                      context.Channel.LocalAddress, context.Channel.RemoteAddress,
19                      context.Channel.Id, detailedError);
20  
21                  // Only shutdown the ActorSystem if this is a client-side failure
22                  // Server-side failures (incoming connections) should just reject the connection
23                  if (isClient)
24                  {
25                      // Client-side: We initiated the connection and TLS failed - this is critical
26                      var cs = CoordinatedShutdown.Get(Transport.System);
27                      cs.Run(new TlsHandshakeFailureReason($"TLS handshake failed on outbound connection to [{context.Channel.RemoteAddress}]"));
28                  }
29                  else
30                  {
31                      // Server-side: Someone connected to us with invalid TLS - just reject them
32                      Log.Warning("Rejected incoming connection from [{0}] due to TLS handshake failure. This is likely invalid or malicious traffic.",
33                          context.Channel.RemoteAddress);
34                  }
35  
36                  context.CloseAsync();
37                  return; // don't pass to next handlers
38              }
39  
40              base.UserEventTriggered(context, evt);
41          }

