 1          public override void ChannelRead(IChannelHandlerContext context, object message)
 2          {
 3              var buf = ((IByteBuffer)message);
 4              if (!_draining && buf.ReadableBytes > 0)
 5              {
 6                  // no need to copy the byte buffer contents; ByteString does that automatically
 7                  var bytes = ByteString.CopyFrom(buf.Array, buf.ArrayOffset + buf.ReaderIndex, buf.ReadableBytes);
 8                  NotifyListener(new InboundPayload(bytes));
 9              }
10  
11              // decrease the reference count to 0 (releases buffer)
12              ReferenceCountUtil.SafeRelease(message);
13          }

