 1          private Deploy DeployFromProto(Proto.Msg.DeployData protoDeploy)
 2          {
 3              Config config;
 4              if (protoDeploy.ConfigSerializerId >
 5                  0) // TODO: should be protoDeploy.Config != null. But it always not null
 6              {
 7                  config = system.Serialization.Deserialize(
 8                      protoDeploy.Config.ToByteArray(),
 9                      protoDeploy.ConfigSerializerId,
10                      protoDeploy.ConfigManifest).AsInstanceOf<Config>();
11              }
12              else
13              {
14                  config = Config.Empty;
15              }
16  
17  
18              RouterConfig routerConfig;
19              if (protoDeploy.RouterConfigSerializerId >
20                  0) // TODO: should be protoDeploy.RouterConfig != null. But it always not null
21              {
22                  routerConfig = system.Serialization.Deserialize(
23                      protoDeploy.RouterConfig.ToByteArray(),
24                      protoDeploy.RouterConfigSerializerId,
25                      protoDeploy.RouterConfigManifest).AsInstanceOf<RouterConfig>();
26              }
27              else
28              {
29                  routerConfig = NoRouter.Instance;
30              }
31  
32              Scope scope;
33              if (protoDeploy.ScopeSerializerId > 0) // TODO: should be protoDeploy.Scope != null. But it always not null
34              {
35                  scope = system.Serialization.Deserialize(
36                      protoDeploy.Scope.ToByteArray(),
37                      protoDeploy.ScopeSerializerId,
38                      protoDeploy.ScopeManifest).AsInstanceOf<Scope>();
39              }
40              else
41              {
42                  scope = Deploy.NoScopeGiven;
43              }
44  
45              var dispatcher = !string.IsNullOrEmpty(protoDeploy.Dispatcher)
46                  ? protoDeploy.Dispatcher
47                  : Deploy.NoDispatcherGiven;
48  
49              // automatically covers backwards compat scenarios too - if the stash capacity is 0 (Protobuf default)
50              // it'll be set to -1 here, which is consistent with how defaults prior to v1.5.4 were handled.
51              var stashCapacity = protoDeploy.StashCapacity > 0 ? protoDeploy.StashCapacity : Deploy.NoStashSize;
52  
53              return stashCapacity == Deploy.NoStashSize
54                  ? new Deploy(protoDeploy.Path, config, routerConfig, scope, dispatcher)
55                  : new Deploy(protoDeploy.Path, config, routerConfig, scope, dispatcher)
56                      .WithStashCapacity(stashCapacity);
57          }

