 1          private async Task TargetFileAsync(
 2              Func<FileInfo, Task> block,
 3              ActorMaterializer materializer,
 4              bool create = true)
 5          {
 6              var targetFile = new FileInfo(Path.Combine(Path.GetTempPath(), $"synchronous-file-sink-{Guid.NewGuid()}.tmp"));
 7  
 8              if (!create)
 9                  targetFile.Delete();
10              else
11                  targetFile.Create().Dispose();
12  
13              try
14              {
15                  await block(targetFile);
16              }
17              finally
18              {
19                  // this is the proverbial stream kill switch, make sure that all streams
20                  // are dead so that the file handle would be released
21                  await this.AssertAllStagesStoppedAsync(() => { return Task.CompletedTask; }, materializer);
22  
23                  //give the system enough time to shutdown and release the file handle
24                  await Task.Delay(500);
25                  targetFile.Delete();
26              }
27          }

