 1      protected override bool Receive(object message)
 2      {
 3          switch (message)
 4          {
 5              case ClusterReceptionist.Ping:
 6                  // keep alive from client
 7                  return true;
 8  
 9              case ReceiveTimeout:
10                  _log.Debug("ClientResponseTunnel for client [{0}] stopped due to inactivity", _client.Path);
11                  Context.Stop(Self);
12                  return true;
13  
14              default:
15              {
16                  _client.Tell(message, ActorRefs.NoSender);
17                  if (IsAsk())
18                      Context.Stop(Self);
19                  return true;
20              }
21          }
22      }

