 1  function declension(scheme: DeclensionScheme, count: number): string {
 2    // scheme for count=1 exists
 3    if (scheme.one !== undefined && count === 1) {
 4      return scheme.one;
 5    }
 6  
 7    const rem10 = count % 10;
 8    const rem100 = count % 100;
 9  
10    // 1, 21, 31, ...
11    if (rem10 === 1 && rem100 !== 11) {
12      return scheme.singularNominative.replace("{{count}}", String(count));
13  
14      // 2, 3, 4, 22, 23, 24, 32 ...
15    } else if (rem10 >= 2 && rem10 <= 4 && (rem100 < 10 || rem100 > 20)) {
16      return scheme.singularGenitive.replace("{{count}}", String(count));
17  
18      // 5, 6, 7, 8, 9, 10, 11, ...
19    } else {
20      return scheme.pluralGenitive.replace("{{count}}", String(count));
21    }
22  }

