 1  export function tpDifferenceInISOWeekYears(
 2    laterDate: Temporal.ZonedDateTime,
 3    earlierDate: Temporal.ZonedDateTime,
 4  ): number {
 5    const sign = Temporal.ZonedDateTime.compare(laterDate, earlierDate);
 6    const laterWeekYear = laterDate.yearOfWeek;
 7    const earlierWeekYear = earlierDate.yearOfWeek;
 8    if (laterWeekYear === undefined || earlierWeekYear === undefined) return NaN;
 9    const diff = Math.abs(laterWeekYear - earlierWeekYear);
10  
11    const adjustedDate = tpAddISOWeekYears(laterDate, -sign * diff);
12  
13    const isLastISOWeekYearNotFull = Number(
14      Temporal.ZonedDateTime.compare(adjustedDate, earlierDate) === -sign,
15    );
16    const result = sign * (diff - isLastISOWeekYearNotFull);
17  
18    return result === 0 ? 0 : result;
19  }

