 1  export function addMonths<
 2    DateType extends Date,
 3    ResultDate extends Date = DateType,
 4  >(
 5    date: DateArg<DateType>,
 6    amount: number,
 7    options?: AddMonthsOptions<ResultDate> | undefined,
 8  ): ResultDate {
 9    const _date = toDate(date, options?.in);
10    if (isNaN(amount)) return constructFrom(options?.in || date, NaN);
11    if (!amount) {
12      // If 0 months, no-op to avoid changing times in the hour before end of DST
13      return _date;
14    }
15    const dayOfMonth = _date.getDate();
16  
17    // The JS Date object supports date math by accepting out-of-bounds values for
18    // month, day, etc. For example, new Date(2020, 0, 0) returns 31 Dec 2019 and
19    // new Date(2020, 13, 1) returns 1 Feb 2021.  This is *almost* the behavior we
20    // want except that dates will wrap around the end of a month, meaning that
21    // new Date(2020, 13, 31) will return 3 Mar 2021 not 28 Feb 2021 as desired. So
22    // we'll default to the end of the desired month by adding 1 to the desired
23    // month and using a date of 0 to back up one day to the end of the desired
24    // month.
25    const endOfDesiredMonth = constructFrom(options?.in || date, _date.getTime());
26    endOfDesiredMonth.setMonth(_date.getMonth() + amount + 1, 0);
27    const daysInMonth = endOfDesiredMonth.getDate();
28    if (dayOfMonth >= daysInMonth) {
29      // If we're already at the end of the month, then this is the correct date
30      // and we're done.
31      return endOfDesiredMonth;
32    } else {
33      // Otherwise, we now know that setting the original day-of-month value won't
34      // cause an overflow, so set the desired day-of-month. Note that we can't
35      // just set the date of `endOfDesiredMonth` because that object may have had
36      // its time changed in the unusual case where where a DST transition was on
37      // the last day of the month and its local time was in the hour skipped or
38      // repeated next to a DST transition.  So we use `date` instead which is
39      // guaranteed to still have the original time.
40      _date.setFullYear(
41        endOfDesiredMonth.getFullYear(),
42        endOfDesiredMonth.getMonth(),
43        dayOfMonth,
44      );
45      return _date;
46    }
47  }

