 1  export function getOverlappingDaysInIntervals(
 2    intervalLeft: Interval,
 3    intervalRight: Interval,
 4  ): number {
 5    const [leftStart, leftEnd] = [
 6      +toDate(intervalLeft.start),
 7      +toDate(intervalLeft.end),
 8    ].sort((a, b) => a - b);
 9    const [rightStart, rightEnd] = [
10      +toDate(intervalRight.start),
11      +toDate(intervalRight.end),
12    ].sort((a, b) => a - b);
13  
14    // Prevent NaN result if intervals don't overlap at all.
15    const isOverlapping = leftStart < rightEnd && rightStart < leftEnd;
16    if (!isOverlapping) return 0;
17  
18    // Remove the timezone offset to negate the DST effect on calculations.
19    const overlapLeft = rightStart < leftStart ? leftStart : rightStart;
20    const left = overlapLeft - getTimezoneOffsetInMilliseconds(overlapLeft);
21    const overlapRight = rightEnd > leftEnd ? leftEnd : rightEnd;
22    const right = overlapRight - getTimezoneOffsetInMilliseconds(overlapRight);
23  
24    // Ceil the number to include partial days too.
25    return Math.ceil((right - left) / millisecondsInDay);
26  }

