 1  export function eachQuarterOfInterval<
 2    IntervalType extends Interval,
 3    Options extends EachQuarterOfIntervalOptions | undefined = undefined,
 4  >(
 5    interval: IntervalType,
 6    options?: Options,
 7  ): EachQuarterOfIntervalResult<IntervalType, Options> {
 8    const { start, end } = normalizeInterval(options?.in, interval);
 9  
10    let reversed = +start > +end;
11    const endTime = reversed ? +startOfQuarter(start) : +startOfQuarter(end);
12    let date = reversed ? startOfQuarter(end) : startOfQuarter(start);
13  
14    let step = options?.step ?? 1;
15    if (!step) return [];
16    if (step < 0) {
17      step = -step;
18      reversed = !reversed;
19    }
20  
21    const dates: EachQuarterOfIntervalResult<IntervalType, Options> = [];
22  
23    while (+date <= endTime) {
24      dates.push(constructFrom(start, date));
25      date = addQuarters(date, step);
26    }
27  
28    return reversed ? dates.reverse() : dates;
29  }

