 1  export function lightFormat(
 2    date: DateArg<Date> & {},
 3    formatStr: string,
 4  ): string {
 5    const date_ = toDate(date);
 6  
 7    if (!isValid(date_)) {
 8      throw new RangeError("Invalid time value");
 9    }
10  
11    const tokens = formatStr.match(formattingTokensRegExp);
12  
13    // The only case when formattingTokensRegExp doesn't match the string is when it's empty
14    if (!tokens) return "";
15  
16    const result = tokens
17      .map((substring) => {
18        // Replace two single quote characters with one single quote character
19        if (substring === "''") {
20          return "'";
21        }
22  
23        const firstCharacter = substring[0];
24        if (firstCharacter === "'") {
25          return cleanEscapedString(substring);
26        }
27  
28        const formatter = lightFormatters[firstCharacter as Token];
29        if (formatter) {
30          return formatter(date_, substring);
31        }
32  
33        if (firstCharacter.match(unescapedLatinCharacterRegExp)) {
34          throw new RangeError(
35            "Format string contains an unescaped latin alphabet character `" +
36              firstCharacter +
37              "`",
38          );
39        }
40  
41        return substring;
42      })
43      .join("");
44  
45    return result;
46  }

