15  
16      if (!matchResult) {
17        return null;
18      }
19      const matchedString = matchResult[0];
20  
21      const parsePatterns =
22        (width && args.parsePatterns[width]) ||
23        args.parsePatterns[args.defaultParseWidth];
24  
25      const key = (
26        Array.isArray(parsePatterns)
27          ? findIndex(parsePatterns, (pattern) => pattern.test(matchedString))
28          : // [TODO] -- I challenge you to fix the type
29            findKey(parsePatterns, (pattern: any) => pattern.test(matchedString))
30      ) as Value extends LocaleDayPeriod ? string : number;
31  
32      let value: Value;
33  
34      value = (args.valueCallback ? args.valueCallback(key) : key) as Value;
35      value = options.valueCallback
36        ? // [TODO] -- I challenge you to fix the type
37          options.valueCallback(value as any)
38        : value;
39  
40      const rest = string.slice(matchedString.length);
41  
42      return { value, rest };
43    };
44  }

