 1  export function normalizeTwoDigitYear(
 2    twoDigitYear: number,
 3    currentYear: number,
 4  ): number {
 5    const isCommonEra = currentYear > 0;
 6    // Absolute number of the current year:
 7    // 1 -> 1 AC
 8    // 0 -> 1 BC
 9    // -1 -> 2 BC
10    const absCurrentYear = isCommonEra ? currentYear : 1 - currentYear;
11  
12    let result;
13    if (absCurrentYear <= 50) {
14      result = twoDigitYear || 100;
15    } else {
16      const rangeEnd = absCurrentYear + 50;
17      const rangeEndCentury = Math.trunc(rangeEnd / 100) * 100;
18      const isPreviousCentury = twoDigitYear >= rangeEnd % 100;
19      result = twoDigitYear + rangeEndCentury - (isPreviousCentury ? 100 : 0);
20    }
21  
22    return isCommonEra ? result : 1 - result;
23  }

