19    const sign = matchResult[1] === "+" ? 1 : -1;
20    const hours = matchResult[2] ? parseInt(matchResult[2], 10) : 0;
21    const minutes = matchResult[3] ? parseInt(matchResult[3], 10) : 0;
22    const seconds = matchResult[5] ? parseInt(matchResult[5], 10) : 0;
23  
24    return {
25      value:
26        sign *
27        (hours * millisecondsInHour +
28          minutes * millisecondsInMinute +
29          seconds * millisecondsInSecond),
30      rest: dateString.slice(matchResult[0].length),
31    };
32  }

