 3  ): Temporal.ZonedDateTime | Temporal.PlainDate {
 4    const weekYear = typeof date !== "number" ? date : date.yearOfWeek;
 5    if (weekYear === undefined)
 6      throw new Error("The date calendar does't have a well-defined week system");
 7  
 8    const fourthOfJanuary = Temporal.PlainDate.from({
 9      year: weekYear,
10      month: 1,
11      day: 4,
12    });
13    const result = fourthOfJanuary.subtract({
14      days: fourthOfJanuary.dayOfWeek - 1,
15    });
16  
17    if (typeof date === "number") return result;
18    return result.toZonedDateTime(date.timeZoneId);
19  }

