17    firstWeekOfNextYear.setFullYear(year + 1, 0, firstWeekContainsDate);
18    firstWeekOfNextYear.setHours(0, 0, 0, 0);
19    const startOfNextYear = startOfWeek(firstWeekOfNextYear, options);
20  
21    const firstWeekOfThisYear = constructFrom(options?.in || date, 0);
22    firstWeekOfThisYear.setFullYear(year, 0, firstWeekContainsDate);
23    firstWeekOfThisYear.setHours(0, 0, 0, 0);
24    const startOfThisYear = startOfWeek(firstWeekOfThisYear, options);
25  
26    if (+_date >= +startOfNextYear) {
