 1  export function eachHourOfInterval<
 2    IntervalType extends Interval,
 3    Options extends EachHourOfIntervalOptions | undefined = undefined,
 4  >(
 5    interval: IntervalType,
 6    options?: Options,
 7  ): EachHourOfIntervalResult<IntervalType, Options> {
 8    const { start, end } = normalizeInterval(options?.in, interval);
 9  
10    let reversed = +start > +end;
11    const endTime = reversed ? +start : +end;
12    const date = reversed ? end : start;
13    date.setMinutes(0, 0, 0);
14  
15    let step = options?.step ?? 1;
16    if (!step) return [];
17    if (step < 0) {
18      step = -step;
19      reversed = !reversed;
20    }
21  
22    const dates: EachHourOfIntervalResult<IntervalType, Options> = [];
23  
24    while (+date <= endTime) {
25      dates.push(constructFrom(start, date));
26      date.setHours(date.getHours() + step);
27    }
28  
29    return reversed ? dates.reverse() : dates;
30  }

