 1  export function tpEndOfWeek(
 2    date: Temporal.ZonedDateTime,
 3    weekStartsOn: number,
 4  ): Temporal.ZonedDateTime {
 5    const day = date.dayOfWeek % 7;
 6    const diff = (day < weekStartsOn ? -7 : 0) + 6 - (day - weekStartsOn);
 7    return date
 8      .toPlainDate()
 9      .add({ days: diff })
10      .toZonedDateTime({ timeZone: date.timeZoneId, plainTime: "23:59:59.999" });
11  }

