 2    date: DateArg<Date> & {},
 3    baseDate: DateArg<Date> & {},
 4    options?: FormatRelativeOptions,
 5  ): string {
 6    const [date_, baseDate_] = normalizeDates(options?.in, date, baseDate);
 7  
 8    const defaultOptions = getDefaultOptions();
 9    const locale = options?.locale ?? defaultOptions.locale ?? defaultLocale;
10    const weekStartsOn =
11      options?.weekStartsOn ??
12      options?.locale?.options?.weekStartsOn ??
13      defaultOptions.weekStartsOn ??
14      defaultOptions.locale?.options?.weekStartsOn ??
15      0;
16  
17    const diff = differenceInCalendarDays(date_, baseDate_);
18  
19    if (isNaN(diff)) {
20      throw new RangeError("Invalid time value");
21    }
22  
23    let token: FormatRelativeToken;
24    if (diff < -6) {
25      token = "other";
26    } else if (diff < -1) {
27      token = "lastWeek";
28    } else if (diff < 0) {
29      token = "yesterday";
30    } else if (diff < 1) {
31      token = "today";
32    } else if (diff < 2) {
33      token = "tomorrow";
34    } else if (diff < 7) {
35      token = "nextWeek";
36    } else {
37      token = "other";
38    }
39  
40    const formatStr = locale.formatRelative(token, date_, baseDate_, {
41      locale,
42      weekStartsOn,
43    });
44    return format(date_, formatStr, { locale, weekStartsOn });
45  }

