 2    try {
 3      const files = await readdir(dir, { withFileTypes: true });
 4      const promises: Promise<void>[] = [];
 5  
 6      for (const file of files) {
 7        const fullPath = join(dir, file.name);
 8  
 9        if (file.isDirectory()) {
10          promises.push(createCTSFiles(fullPath));
11        } else if (file.isFile() && file.name.endsWith(".d.ts")) {
12          const newFilePath = fullPath.replace(".d.ts", ".d.cts");
13          promises.push(copyFile(fullPath, newFilePath));
14        }
15      }
16  
17      await Promise.all(promises); // Wait for all promises to resolve
18    } catch (error) {
19      console.error("Error processing directory:", error);
20      process.exit(1);
21    }
22  }

