 1      private static bool TryGetCustomHost<THost>(
 2          Assembly startupAssembly,
 3          string factoryClassName,
 4          string factoryMethodName,
 5          out THost host)
 6      {
 7          // Scan the assembly for any types that match the provided naming convention
 8          var factoryTypes = startupAssembly.DefinedTypes
 9              .Where(t => t.Name == factoryClassName)
10              .ToList();
11  
12          if (factoryTypes.Count == 0)
13          {
14              host = default;
15              return false;
16          }
17          else if (factoryTypes.Count > 1)
18          {
19              throw new InvalidOperationException($"Multiple {factoryClassName} classes detected");
20          }
21  
22          var factoryMethod = factoryTypes
23              .Single()
24              .GetMethod(factoryMethodName, BindingFlags.Public | BindingFlags.Static);
25  
26          if (factoryMethod == null || factoryMethod.ReturnType != typeof(THost))
27          {
28              throw new InvalidOperationException(
29                  $"{factoryClassName} class detected but does not contain a public static method " +
30                  $"called {factoryMethodName} with return type {typeof(THost).Name}");
31          }
32  
33          host = (THost)factoryMethod.Invoke(null, null);
34          return true;
35      }

