 7          }
 8  
 9          if (type.IsConstructedFrom(typeof(IAsyncEnumerable<>), out constructedType))
10          {
11              itemType = constructedType.GenericTypeArguments[0];
12              return true;
13          }
14  
15          if (type.IsArray)
16          {
17              itemType = type.GetElementType();
18              return true;
19          }
20  
21          if (typeof(IEnumerable).IsAssignableFrom(type))
22          {
23              itemType = typeof(object);
24              return true;
25          }
26  
27          itemType = null;
28          return false;
29      }

