 1      private static string QualifiedNameFor(Type type, bool expandGenericArgs = false)
 2      {
 3          if (type.IsArray)
 4          {
 5              var elementType = type.GetElementType();
 6              return elementType.IsGenericParameter ? $"`{elementType.GenericParameterPosition}[]" : $"{QualifiedNameFor(type.GetElementType(), expandGenericArgs)}[]";
 7          }
 8  
 9  
10          var builder = new StringBuilder();
11  
12          if (!string.IsNullOrEmpty(type.Namespace))
13          {
14              builder.Append($"{type.Namespace}.");
15          }
16  
17          if (type.IsNested)
18          {
19              builder.Append($"{string.Join(".", GetNestedTypeNames(type))}.");
20          }
21  
22          if (type.IsConstructedGenericType && expandGenericArgs)
23          {
24              var nameSansGenericArgs = type.Name.Split('`').First();
25              builder.Append(nameSansGenericArgs);
26  
27              var genericArgsNames = type.GetGenericArguments().Select(t =>
28              {
29                  return t.IsGenericParameter
30                      ? $"`{t.GenericParameterPosition}"
31                      : QualifiedNameFor(t, true);
32              });
33  
34              builder.Append($"{{{string.Join(",", genericArgsNames)}}}");
35          }
36          else
37          {
38              builder.Append(type.Name);
39          }
40  
41          return builder.ToString();
42      }

