 1      private static string? CleanTemplate(string? result)
 2      {
 3          if (result == null)
 4          {
 5              return null;
 6          }
 7  
 8          // This is an invalid combined template, so we don't want to
 9          // accidentally clean it and produce a valid template. For that
10          // reason we ignore the clean up process for it.
11          if (result.Equals("//", StringComparison.Ordinal))
12          {
13              return result;
14          }
15  
16          var startIndex = 0;
17          if (result.StartsWith('/'))
18          {
19              startIndex = 1;
20          }
21          else if (result.StartsWith("~/", StringComparison.Ordinal))
22          {
23              startIndex = 2;
24          }
25  
26          // We are in the case where the string is "/" or "~/"
27          if (startIndex == result.Length)
28          {
29              return string.Empty;
30          }
31  
32          var subStringLength = result.Length - startIndex;
33          if (result.EndsWith('/'))
34          {
35              subStringLength--;
36          }
37  
38          return result.Substring(startIndex, subStringLength);
39      }

