24              // get all the newlines
25              while ((lineBreakPos = Array.IndexOf(buf, '\n', startPos, chunkLength - startPos)) >= 0 && startPos < chunkLength)
26              {
27                  var length = (lineBreakPos + 1) - startPos;
28                  _linesBuffer.Append(buf, startPos, length);
29                  OnCompleteLine(_linesBuffer.ToString());
30                  _linesBuffer.Clear();
31                  startPos = lineBreakPos + 1;
32              }
33  
34              // get the rest
35              if (lineBreakPos < 0 && startPos < chunkLength)
36              {
37                  _linesBuffer.Append(buf, startPos, chunkLength - startPos);
38              }
39          }
40      }

