 4          var completionLock = new object();
 5  
 6          OnReceivedLineHandler? onReceivedLineHandler = null;
 7          OnStreamClosedHandler? onStreamClosedHandler = null;
 8  
 9          void ResolveIfStillPending(Action applyResolution)
10          {
11              lock (completionLock)
12              {
13                  if (!tcs.Task.IsCompleted)
14                  {
15                      OnReceivedLine -= onReceivedLineHandler;
16                      OnStreamClosed -= onStreamClosedHandler;
17                      applyResolution();
18                  }
19              }
20          }
21  
22          onReceivedLineHandler = line =>
23          {
24              var match = regex.Match(line);
25              if (match.Success)
26              {
27                  ResolveIfStillPending(() => tcs.SetResult(match));
28              }
29          };
30  
31          onStreamClosedHandler = () =>
32          {
33              ResolveIfStillPending(() => tcs.SetException(new EndOfStreamException()));
34          };
35  
36          OnReceivedLine += onReceivedLineHandler;
37          OnStreamClosed += onStreamClosedHandler;
38  
39          return tcs.Task;
40      }

