10              var viewDescriptor = result.ViewDescriptor;
11              if (viewDescriptor?.ExpirationTokens != null)
12              {
13                  for (var i = 0; i < viewDescriptor.ExpirationTokens.Count; i++)
14                  {
15                      expirationTokens.Add(viewDescriptor.ExpirationTokens[i]);
16                  }
17              }
18  
19              if (result.Success)
20              {
21                  // Populate the viewStartPages list so that _ViewStarts appear in the order the need to be
22                  // executed (closest last, furthest first). This is the reverse order in which
23                  // ViewHierarchyUtility.GetViewStartLocations returns _ViewStarts.
24                  viewStartPages.Insert(0, new ViewLocationCacheItem(result.RazorPageFactory, filePath));
25              }
26          }
27  
28          return viewStartPages;
29      }

