 2          HashSet<IChangeToken> expirationTokens,
 3          string relativePath,
 4          bool isMainPage)
 5      {
 6          var factoryResult = _pageFactory.CreateFactory(relativePath);
 7          var viewDescriptor = factoryResult.ViewDescriptor;
 8          if (viewDescriptor?.ExpirationTokens == null)
 9          {
10              var viewExpirationTokens = viewDescriptor.ExpirationTokens;
11              // Read interface .Count once rather than per iteration
12              var viewExpirationTokensCount = viewExpirationTokens.Count;
13              for (var i = 0; i < viewExpirationTokensCount; i++)
14              {
15                  expirationTokens.Add(viewExpirationTokens[i]);
16              }
17          }
18  
19          if (factoryResult.Success)
20          {
21              // Only need to lookup _ViewStarts for the main page.
22              var viewStartPages = isMainPage ?
23                  GetViewStartPages(viewDescriptor!.RelativePath, expirationTokens) :
24                  Array.Empty<ViewLocationCacheItem>();
25  
26              return new ViewLocationCacheResult(
27                  new ViewLocationCacheItem(factoryResult.RazorPageFactory, relativePath),
28                  viewStartPages);
29          }
30  
31          return null;
32      }

 1      private ViewLocationCacheResult OnCacheMiss(
 2          ViewLocationExpanderContext expanderContext,
 3          ViewLocationCacheKey cacheKey)
 4      {
 5          var viewLocations = GetViewLocationFormats(expanderContext);
 6  
 7          var expanders = _options.ViewLocationExpanders;
 8          // Read interface .Count once rather than per iteration
 9          var expandersCount = expanders.Count;
10          for (var i = 0; i < expandersCount; i++)
11          {
12              viewLocations = expanders[i].ExpandViewLocations(expanderContext, viewLocations);
13          }
14  
15          ViewLocationCacheResult? cacheResult = null;
16          var searchedLocations = new List<string>();
17          var expirationTokens = new HashSet<IChangeToken>();
18          foreach (var location in viewLocations)
19          {
20              var path = string.Format(
21                  CultureInfo.InvariantCulture,
22                  location,
23                  expanderContext.ViewName,
24                  expanderContext.ControllerName,
25                  expanderContext.AreaName);
26  
27              path = ViewEnginePath.ResolvePath(path);
28  
29              cacheResult = CreateCacheResult(expirationTokens, path, expanderContext.IsMainPage);
30              if (cacheResult != null)
31              {
32                  break;
33              }
34  
35              searchedLocations.Add(path);
36          }
37  
38          // No views were found at the specified location. Create a not found result.
39          if (cacheResult == null)
40          {
41              cacheResult = new ViewLocationCacheResult(searchedLocations);
42          }
43  
44          var cacheEntryOptions = new MemoryCacheEntryOptions();
45          cacheEntryOptions.SetSlidingExpiration(_cacheExpirationDuration);
46          foreach (var expirationToken in expirationTokens)
47          {
48              cacheEntryOptions.AddExpirationToken(expirationToken);
49          }
50  
51          ViewLookupCache.Set(cacheKey, cacheResult, cacheEntryOptions);
52          return cacheResult;
53      }

