 1      internal IEnumerable<string> GetViewLocationFormats(ViewLocationExpanderContext context)
 2      {
 3          if (!string.IsNullOrEmpty(context.AreaName) &&
 4              !string.IsNullOrEmpty(context.ControllerName))
 5          {
 6              return _options.AreaViewLocationFormats;
 7          }
 8          else if (!string.IsNullOrEmpty(context.ControllerName))
 9          {
10              return _options.ViewLocationFormats;
11          }
12          else if (!string.IsNullOrEmpty(context.AreaName) &&
13              !string.IsNullOrEmpty(context.PageName))
14          {
15              return _options.AreaPageViewLocationFormats;
16          }
17          else if (!string.IsNullOrEmpty(context.PageName))
18          {
19              return _options.PageViewLocationFormats;
20          }
21          else
22          {
23              // If we don't match one of these conditions, we'll just treat it like regular controller/action
24              // and use those search paths. This is what we did in 1.0.0 without giving much thought to it.
25              return _options.ViewLocationFormats;
26          }
27      }

