 1      public string? GetAbsolutePath(string? executingFilePath, string? pagePath)
 2      {
 3          if (string.IsNullOrEmpty(pagePath))
 4          {
 5              // Path is not valid; no change required.
 6              return pagePath;
 7          }
 8  
 9          if (IsApplicationRelativePath(pagePath))
10          {
11              // An absolute path already; no change required.
12              return pagePath;
13          }
14  
15          if (!IsRelativePath(pagePath))
16          {
17              // A page name; no change required.
18              return pagePath;
19          }
20  
21          if (string.IsNullOrEmpty(executingFilePath))
22          {
23              // Given a relative path i.e. not yet application-relative (starting with "~/" or "/"), interpret
24              // path relative to currently-executing view, if any.
25              // Not yet executing a view. Start in app root.
26              var absolutePath = "/" + pagePath;
27              return ViewEnginePath.ResolvePath(absolutePath);
28          }
29  
30          return ViewEnginePath.CombinePath(executingFilePath, pagePath);
31      }

