22          Dictionary<string, string?>? expanderValues = null;
23  
24          var expanders = _options.ViewLocationExpanders;
25          // Read interface .Count once rather than per iteration
26          var expandersCount = expanders.Count;
27          if (expandersCount > 0)
28          {
29              expanderValues = new Dictionary<string, string?>(StringComparer.Ordinal);
30              expanderContext.Values = expanderValues;
31  
32              // Perf: Avoid allocations
