 1      private static IList<StringWithQualityHeaderValue> SortAfterSmall(IList<StringWithQualityHeaderValue> values)
 2      {
 3          var buffer = new IndexBuffer();
 4          Span<int> indices = buffer;
 5          var count = 0;
 6  
 7          for (var i = 0; i < values.Count; i++)
 8          {
 9              var value = values[i];
10              if (value.Quality == HeaderQuality.NoMatch)
11              {
12                  continue;
13              }
14  
15              var j = count;
16              while (j > 0 &&
17                  StringWithQualityHeaderValueComparer.QualityComparer.Compare(values[indices[j - 1]], value) <= 0)
18              {
19                  indices[j] = indices[j - 1];
20                  j--;
21              }
22  
23              indices[j] = i;
24              count++;
25          }
26  
27          var sorted = new List<StringWithQualityHeaderValue>(count);
28          for (var i = 0; i < count; i++)
29          {
30              sorted.Add(values[indices[i]]);
31          }
32  
33          return sorted;
34      }

