 1      private static Expression BindParameterFromBindAsync(ParameterInfo parameter, RequestDelegateFactoryContext factoryContext)
 2      {
 3          // We reference the boundValues array by parameter index here
 4          var isOptional = IsOptionalParameter(parameter, factoryContext);
 5  
 6          // Get the BindAsync method for the type.
 7          var bindAsyncMethod = ParameterBindingMethodCache.Instance.FindBindAsyncMethod(parameter);
 8          // We know BindAsync exists because there's no way to opt-in without defining the method on the type.
 9          Debug.Assert(bindAsyncMethod.Expression is not null);
10  
11          // Compile the delegate to the BindAsync method for this parameter index
12          var bindAsyncDelegate = Expression.Lambda<Func<HttpContext, ValueTask<object?>>>(bindAsyncMethod.Expression, HttpContextExpr).Compile();
13          factoryContext.ParameterBinders.Add(bindAsyncDelegate);
14  
15          // boundValues[index]
16          var boundValueExpr = Expression.ArrayIndex(BoundValuesArrayExpr, Expression.Constant(factoryContext.ParameterBinders.Count - 1));
17  
18          if (!isOptional)
19          {
20              var typeName = TypeNameHelper.GetTypeDisplayName(parameter.ParameterType, fullName: false);
21              var message = bindAsyncMethod.ParamCount == 2 ? $"{typeName}.BindAsync(HttpContext, ParameterInfo)" : $"{typeName}.BindAsync(HttpContext)";
22              var checkRequiredBodyBlock = Expression.Block(
23                      Expression.IfThen(
24                      Expression.Equal(boundValueExpr, Expression.Constant(null)),
25                          Expression.Block(
26                              Expression.Assign(WasParamCheckFailureExpr, Expression.Constant(true)),
27                              Expression.Call(LogRequiredParameterNotProvidedMethod,
28                                      HttpContextExpr,
29                                      Expression.Constant(typeName),
30                                      Expression.Constant(parameter.Name),
31                                      Expression.Constant(message),
32                                      Expression.Constant(factoryContext.ThrowOnBadRequest))
33                          )
34                      )
35                  );
36  
37              factoryContext.ParamCheckExpressions.Add(checkRequiredBodyBlock);
38          }
39  
40          // (ParameterType)boundValues[i]
41          return Expression.Convert(boundValueExpr, parameter.ParameterType);
42      }

