 1      private static Expression CreateDefaultValueExpression(object? defaultValue, Type parameterType)
 2      {
 3          if (defaultValue is null)
 4          {
 5              // For non-nullable value types (e.g., Guid, DateTime, TimeSpan), reflection reports
 6              // DefaultValue == null when the parameter default is `= default`. Using
 7              // Expression.Constant(null, valueType) would throw an ArgumentException because null
 8              // is not valid for a non-nullable value type. Use Expression.Default instead.
 9              if (parameterType.IsValueType && Nullable.GetUnderlyingType(parameterType) is null)
10              {
11                  return Expression.Default(parameterType);
12              }
13  
14              return Expression.Constant(null, parameterType);
15          }
16  
17          var underlyingType = Nullable.GetUnderlyingType(parameterType);
18          var isNullable = underlyingType != null;
19          var targetType = isNullable ? underlyingType! : parameterType;
20          var converted = defaultValue;
21  
22          // Apply a conversion for scenarios where the default value's type
23          // doesn't match the parameter type
24          if (targetType.IsEnum && defaultValue.GetType() != targetType)
25          {
26              converted = Enum.ToObject(targetType, defaultValue);
27          }
28          else if (!targetType.IsAssignableFrom(defaultValue.GetType()))
29          {
30              converted = Convert.ChangeType(defaultValue, targetType, CultureInfo.InvariantCulture);
31          }
32  
33          var constant = Expression.Constant(converted, targetType);
34          // Cast nullable types as needed
35          return isNullable ? Expression.Convert(constant, parameterType) : constant;
36      }

