20                  httpContext.Response.StatusCode = StatusCodes.Status400BadRequest;
21                  return (null, false);
22              }
23  
24              if (!httpContext.Request.HasFormContentType)
25              {
26                  Log.UnexpectedNonFormContentType(httpContext, httpContext.Request.ContentType, throwOnBadRequest);
27                  httpContext.Response.StatusCode = StatusCodes.Status415UnsupportedMediaType;
28                  return (null, false);
29              }
30  
31              try
32              {
33                  formValue = await httpContext.Request.ReadFormAsync();
34              }
35              catch (BadHttpRequestException ex)
36              {
37                  Log.RequestBodyIOException(httpContext, ex);
38                  httpContext.Response.StatusCode = ex.StatusCode;
39                  return (null, false);
40              }
41              catch (IOException ex)
42              {
43                  Log.RequestBodyIOException(httpContext, ex);
44                  httpContext.Response.StatusCode = StatusCodes.Status400BadRequest;
