 1      private static Func<object?, HttpContext, Task> HandleRequestBodyAndCompileRequestDelegate(Expression responseWritingMethodCall, RequestDelegateFactoryContext factoryContext)
 2      {
 3          if (factoryContext.JsonRequestBodyParameter is null && !factoryContext.ReadForm)
 4          {
 5              if (factoryContext.ParameterBinders.Count > 0)
 6              {
 7                  // We need to generate the code for reading from the custom binders calling into the delegate
 8                  var continuation = Expression.Lambda<Func<object?, HttpContext, object?[], Task>>(
 9                      responseWritingMethodCall, TargetExpr, HttpContextExpr, BoundValuesArrayExpr).Compile();
10  
11                  // Looping over arrays is faster
12                  var binders = factoryContext.ParameterBinders.ToArray();
13                  var count = binders.Length;
14  
15                  return async (target, httpContext) =>
16                  {
17                      var boundValues = new object?[count];
18  
19                      for (var i = 0; i < count; i++)
20                      {
21                          boundValues[i] = await binders[i](httpContext);
22                      }
23  
24                      await continuation(target, httpContext, boundValues);
25                  };
26              }
27  
28              return Expression.Lambda<Func<object?, HttpContext, Task>>(
29                  responseWritingMethodCall, TargetExpr, HttpContextExpr).Compile();
30          }
31  
32          if (factoryContext.ReadForm)
33          {
34              return HandleRequestBodyAndCompileRequestDelegateForForm(responseWritingMethodCall, factoryContext);
35          }
36          else
37          {
38              return HandleRequestBodyAndCompileRequestDelegateForJson(responseWritingMethodCall, factoryContext);
39          }
40      }

