 1      private static void PopulateBuiltInResponseTypeMetadata(Type returnType, RequestDelegateFactoryContext factoryContext)
 2      {
 3          if (returnType.IsByRefLike)
 4          {
 5              throw GetUnsupportedReturnTypeException(returnType);
 6          }
 7  
 8          if (CoercedAwaitableInfo.IsTypeAwaitable(returnType, out var coercedAwaitableInfo))
 9          {
10              returnType = coercedAwaitableInfo.AwaitableInfo.ResultType;
11          }
12  
13          // Skip void returns and IResults. IResults might implement IEndpointMetadataProvider but otherwise we don't know what it might do.
14          if (returnType == typeof(void) || typeof(IResult).IsAssignableFrom(returnType))
15          {
16              return;
17          }
18  
19          var builder = factoryContext.EndpointBuilder;
20  
21          if (returnType == typeof(string))
22          {
23              builder.Metadata.Add(ProducesResponseTypeMetadata.CreateUnvalidated(type: typeof(string), statusCode: 200, PlaintextContentType));
24          }
25          else
26          {
27              builder.Metadata.Add(ProducesResponseTypeMetadata.CreateUnvalidated(returnType, statusCode: 200, DefaultAcceptsAndProducesContentType));
28  
29              if (factoryContext.JsonRequestBodyParameter is null)
30              {
31                  // Since this endpoint responds with JSON, we assume its an API endpoint not intended for browser navigation,
32                  // but we don't want to bother adding this metadata twice if we've already inferred it based on the expected JSON request body.
33                  builder.Metadata.Add(DisableCookieRedirectMetadata.Instance);
34              }
35          }
36      }

