 1      private static Expression[] CreateArguments(ParameterInfo[]? parameters, RequestDelegateFactoryContext factoryContext)
 2      {
 3          if (parameters is null || parameters.Length == 0)
 4          {
 5              return Array.Empty<Expression>();
 6          }
 7  
 8          var args = new Expression[parameters.Length];
 9  
10          factoryContext.ArgumentTypes = new Type[parameters.Length];
11          factoryContext.BoxedArgs = new Expression[parameters.Length];
12          factoryContext.Parameters = new List<ParameterInfo>(parameters);
13  
14          for (var i = 0; i < parameters.Length; i++)
15          {
16              args[i] = CreateArgument(parameters[i], factoryContext, out var hasTryParse, out var hasBindAsync, out var isAsParameters);
17  
18              if (!isAsParameters)
19              {
20                  factoryContext.EndpointBuilder.Metadata.Add(new ParameterBindingMetadata(
21                      name: parameters[i].Name!,
22                      parameterInfo: parameters[i],
23                      hasTryParse: hasTryParse,
24                      hasBindAsync: hasBindAsync,
25                      isOptional: IsOptionalParameter(parameters[i], factoryContext)
26                  ));
27              }
28              factoryContext.ArgumentTypes[i] = parameters[i].ParameterType;
29              factoryContext.BoxedArgs[i] = Expression.Convert(args[i], typeof(object));
30          }
31  
32          if (factoryContext.HasInferredBody && factoryContext.DisableInferredFromBody)
33          {
34              var errorMessage = BuildErrorMessageForInferredBodyParameter(factoryContext);
35              throw new InvalidOperationException(errorMessage);
36          }
37  
38          if (factoryContext.JsonRequestBodyParameter is not null &&
39              factoryContext.FirstFormRequestBodyParameter is not null)
40          {
41              var errorMessage = BuildErrorMessageForFormAndJsonBodyParameters(factoryContext);
42              throw new InvalidOperationException(errorMessage);
43          }
44          if (factoryContext.HasMultipleBodyParameters)
45          {
46              var errorMessage = BuildErrorMessageForMultipleBodyParameters(factoryContext);
47              throw new InvalidOperationException(errorMessage);
48          }
49  
50          return args;
51      }

