18  
19              if (returnType == typeof(Task))
20              {
21                  return Expression.Call(ExecuteTaskWithEmptyResultMethod, methodCall);
22              }
23              else if (returnType == typeof(ValueTask))
24              {
25                  return Expression.Call(ExecuteValueTaskWithEmptyResultMethod, methodCall);
26              }
27              else if (returnType == typeof(ValueTask<object?>))
28              {
29                  return methodCall;
30              }
