20              ServiceProviderIsService = serviceProvider.GetService<IServiceProviderIsService>(),
21              RouteParameters = options?.RouteParameterNames,
22              ThrowOnBadRequest = options?.ThrowOnBadRequest ?? false,
23              DisableInferredFromBody = options?.DisableInferBodyFromParameters ?? false,
24              EndpointBuilder = endpointBuilder,
25              MetadataAlreadyInferred = metadataResult is not null,
26              JsonSerializerOptions = jsonSerializerOptions,
27              FormDataMapperOptions = formDataMapperOptions
28          };
29  
30          return factoryContext;
31      }

