 1      public static async Task<IImmutableSet<string>> DetectFeaturesAsync(
 2          Compilation compilation,
 3          CancellationToken cancellationToken = default)
 4      {
 5          var symbols = new StartupSymbols(compilation);
 6          if (!symbols.HasRequiredSymbols)
 7          {
 8              // Cannot find ASP.NET Core types.
 9              return ImmutableHashSet<string>.Empty;
10          }
11  
12          var features = ImmutableHashSet.CreateBuilder<string>();
13  
14          // Find configure methods in the project's assembly
15          var configureMethods = ConfigureMethodVisitor.FindConfigureMethods(symbols, compilation.Assembly);
16          for (var i = 0; i < configureMethods.Count; i++)
17          {
18              var configureMethod = configureMethods[i];
19  
20              // Handles the case where a method is using partial definitions. We don't expect this to occur, but still handle it correctly.
21              var syntaxReferences = configureMethod.DeclaringSyntaxReferences;
22              for (var j = 0; j < syntaxReferences.Length; j++)
23              {
24                  var semanticModel = compilation.GetSemanticModel(syntaxReferences[j].SyntaxTree);
25  
26                  var syntax = await syntaxReferences[j].GetSyntaxAsync(cancellationToken).ConfigureAwait(false);
27                  var operation = semanticModel.GetOperation(syntax, cancellationToken);
28  
29                  // Look for a call to one of the SignalR gestures that applies to the Configure method.
30                  if (operation
31                      .Descendants()
32                      .OfType<IInvocationOperation>()
33                      .Any(op => StartupFacts.IsSignalRConfigureMethodGesture(op.TargetMethod)))
34                  {
35                      features.Add(WellKnownFeatures.SignalR);
36                  }
37              }
38          }
39  
40          return features.ToImmutable();
41      }

