 1      private static string? TryFindMuxerPath()
 2      {
 3          // If not running on Helix, use a custom .NET host, if specified.
 4          // This allows test projects to use a .NET host with the custom-built
 5          // ASP.NET Core shared framework.
 6          if (string.IsNullOrEmpty(Environment.GetEnvironmentVariable("helix")))
 7          {
 8              var dotNetHostOverride = typeof(DotNetMuxer).Assembly.GetCustomAttributes<AssemblyMetadataAttribute>()
 9                  .SingleOrDefault(a => a.Key == "DotNetHostOverride")?.Value;
10              if (dotNetHostOverride is not null)
11              {
12                  return dotNetHostOverride;
13              }
14          }
15  
16          var expectedFileName = MuxerName;
17          if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
18          {
19              expectedFileName += ".exe";
20          }
21  
22          // If the currently running process is dotnet(.exe), return that path
23          var mainModuleFullPath = Process.GetCurrentProcess().MainModule?.FileName;
24          var mainModuleFileName = Path.GetFileName(mainModuleFullPath);
25          if (string.Equals(expectedFileName, mainModuleFileName, StringComparison.OrdinalIgnoreCase))
26          {
27              return mainModuleFullPath;
28          }
29  
30          // The currently running process may not be dotnet(.exe). For example,
31          // it might be "testhost(.exe)" when running tests.
32          // In this case, we can get the location where the CLR is installed,
33          // and find dotnet(.exe) relative to that path.
34          var runtimeDirectory = RuntimeEnvironment.GetRuntimeDirectory();
35          var candidateDotNetExePath = Path.Combine(runtimeDirectory, "..", "..", "..", expectedFileName);
36          if (File.Exists(candidateDotNetExePath))
37          {
38              var normalizedPath = Path.GetFullPath(candidateDotNetExePath);
39              return normalizedPath;
40          }
41  
42          return null;
43      }

