 1      public TValue GetOrCreateValue(TKey key, Func<TKey, TValue> valueFactory)
 2      {
 3          lock (_weakReferencedEntries)
 4          {
 5              var indexToSetTarget = -1;
 6              for (var i = 0; i < _weakReferencedEntries.Count; i++)
 7              {
 8                  var weakReferencedEntry = _weakReferencedEntries[i];
 9                  if (!weakReferencedEntry.TryGetTarget(out var cachedEntry) ||
10                      cachedEntry == null)
11                  {
12                      if (indexToSetTarget == -1)
13                      {
14                          indexToSetTarget = i;
15                      }
16  
17                      continue;
18                  }
19  
20                  if (Equals(cachedEntry.Key, key))
21                  {
22                      // Move the cache hit item to the end of the list
23                      // so it would be least likely to be evicted on next cache miss.
24                      _weakReferencedEntries.RemoveAt(i);
25                      _weakReferencedEntries.Add(weakReferencedEntry);
26                      return cachedEntry.Value;
27                  }
28              }
29  
30              if (indexToSetTarget == -1)
31              {
32                  indexToSetTarget = 0;
33              }
34  
35              var newEntry = new Entry(key, valueFactory(key));
36              _weakReferencedEntries[indexToSetTarget].SetTarget(newEntry);
37              return newEntry.Value;
38          }
39      }

