18              if (!stream.FinalBoundaryFound && !string.Equals(string.Empty, remainder, StringComparison.Ordinal))
19              {
20                  throw new IOException("Unexpected data found on the boundary line.");
21              }
22  
23              stream._finished = true;
24              return 0;
25          }

