 4  
 5          if (second.StartsWith('/'))
 6          {
 7              // "second" is already an app-rooted path. Return it as-is.
 8              return second;
 9          }
10  
11          string result;
12  
13          // Get directory name (including final slash) but do not use Path.GetDirectoryName() to preserve path
14          // normalization.
15          var index = first.LastIndexOf('/');
16          Debug.Assert(index >= 0);
17  
18          if (index == first.Length - 1)
