20              // If the first ends in a trailing slash e.g. "/Home/", assume it's a directory.
21              result = first + second;
22          }
23          else
24          {
25              result = string.Concat(first.AsSpan(0, index + 1), second);
26          }
27  
28          return ResolvePath(result);
29      }

