 1      private string GenerateComponentPath(int componentId)
 2      {
 3          // We are generating a path from the root component with component type names like:
 4          // App > Router > RouteView > LayoutView > Index > PartA
 5          // App > Router > RouteView > LayoutView > MainLayout > NavigationMenu
 6          // To help developers identify when they have multiple forms with the same handler.
 7          Stack<string> stack = new();
 8  
 9          for (var current = GetComponentState(componentId); current != null; current = current.ParentComponentState)
10          {
11              stack.Push(GetName(current));
12          }
13  
14          var builder = new StringBuilder();
15          builder.AppendJoin(" > ", stack);
16          return builder.ToString();
17  
18          static string GetName(ComponentState current) => current.Component.GetType().Name;
19      }

