 1      private ulong? FindEventHandlerIdForNamedEvent(string eventType, int componentId, int frameIndex)
 2      {
 3          var frames = GetCurrentRenderTreeFrames(componentId);
 4          ref var frame = ref frames.Array[frameIndex];
 5  
 6          if (frame.FrameType != RenderTreeFrameType.NamedEvent)
 7          {
 8              // This should not be possible, as the system doesn't create a way that the location could be wrong. But if it happens, we want to know.
 9              throw new InvalidOperationException($"The named value frame for component '{componentId}' at index '{frameIndex}' unexpectedly matches a frame of type '{frame.FrameType}'.");
10          }
11  
12          if (!string.Equals(frame.NamedEventType, eventType, StringComparison.Ordinal))
13          {
14              // This should not be possible, as currently we are only tracking name-values with the expected name. But if it happens, we want to know.
15              throw new InvalidOperationException($"Expected a named value with name '{eventType}' but found the name '{frame.NamedEventType}'.");
16          }
17  
18          for (var i = frameIndex - 1; i >= 0; i--)
19          {
20              ref var candidate = ref frames.Array[i];
21              if (candidate.FrameType == RenderTreeFrameType.Attribute)
22              {
23                  if (candidate.AttributeEventHandlerId > 0 && string.Equals(candidate.AttributeName, eventType, StringComparison.OrdinalIgnoreCase))
24                  {
25                      return candidate.AttributeEventHandlerId;
26                  }
27              }
28              else if (candidate.FrameType == RenderTreeFrameType.Element)
29              {
30                  break;
31              }
32          }
33  
34          // No match found
35          return default;
36      }

