 6          {
 7              case State.Ready:
 8                  if ((b & HeaderAcknowledgementMask) == HeaderAcknowledgementRepresentation)
 9                  {
10                      prefixInt = HeaderAcknowledgementPrefixMask & b;
11                      if (_integerDecoder.BeginTryDecode((byte)prefixInt, HeaderAcknowledgementPrefix, out intResult))
12                      {
13                          OnHeaderAcknowledgement(intResult);
14                      }
15                      else
16                      {
17                          _state = State.HeaderAckowledgement;
18                      }
19                  }
20                  else if ((b & StreamCancellationMask) == StreamCancellationRepresentation)
21                  {
22                      prefixInt = StreamCancellationPrefixMask & b;
23                      if (_integerDecoder.BeginTryDecode((byte)prefixInt, StreamCancellationPrefix, out intResult))
24                      {
25                          OnStreamCancellation(intResult);
26                      }
27                      else
28                      {
29                          _state = State.StreamCancellation;
30                      }
31                  }
32                  else if ((b & InsertCountIncrementMask) == InsertCountIncrementRepresentation)
33                  {
34                      prefixInt = InsertCountIncrementPrefixMask & b;
35                      if (_integerDecoder.BeginTryDecode((byte)prefixInt, InsertCountIncrementPrefix, out intResult))
36                      {
37                          OnInsertCountIncrement(intResult);
38                      }
39                      else
40                      {
41                          _state = State.InsertCountIncrement;
42                      }
43                  }
44                  break;
45          }
46      }

