 1      private static Func<IReadOnlyModificationCommand, (TColumn, bool)> CreateOriginalValueGetter<TColumn>(IColumn column)
 2          => c =>
 3          {
 4              if (c.Entries.Count > 0)
 5              {
 6                  var value = default(TColumn)!;
 7                  var valueFound = false;
 8                  for (var i = 0; i < c.Entries.Count; i++)
 9                  {
10                      var entry = c.Entries[i];
11                      if (entry.EntityState == EntityState.Added
12                          && entry.SharedIdentityEntry != null)
13                      {
14                          entry = entry.SharedIdentityEntry;
15                      }
16  
17                      var property = column.FindColumnMapping(entry.EntityType)?.Property;
18                      if (property == null)
19                      {
20                          continue;
21                      }
22  
23                      var providerValue = entry.GetOriginalProviderValue(property);
24                      if (providerValue == null)
25                      {
26                          return (value!, valueFound);
27                      }
28  
29                      value = (TColumn)providerValue!;
30                      valueFound = true;
31                      if (entry.EntityState == EntityState.Unchanged
32                          || (entry.EntityState == EntityState.Modified && !entry.IsModified(property)))
33                      {
34                          return (value, valueFound);
35                      }
36                  }
37  
38                  return (value, valueFound);
39              }
40  
41              var modification = c.ColumnModifications.FirstOrDefault(m => m.ColumnName == column.Name);
42              return modification == null
43                  ? (default!, false)
44                  : modification.OriginalValue == null
45                      ? (default!, false)
46                      : ((TColumn)modification.OriginalValue!, true);
47          };

