 1      protected override void ProcessSinglePropertyJsonUpdate(ref ColumnModificationParameters parameters)
 2      {
 3          var property = parameters.Property!;
 4  
 5          var propertyProviderClrType = (property.GetTypeMapping().Converter?.ProviderClrType ?? property.ClrType).UnwrapNullableType();
 6  
 7          // SQLite has no bool type, so if we simply sent the bool as-is, we'd get 1/0 in the JSON document.
 8          // To get an actual unquoted true/false value, we pass "true"/"false" string through the json() minifier, which does this.
 9          // See https://sqlite.org/forum/info/91d09974c3754ea6.
10          // Here we convert the .NET bool to a "true"/"false" string, and SqliteUpdateSqlGenerator will add the enclosing json().
11          if (propertyProviderClrType == typeof(bool))
12          {
13              var value = property.GetTypeMapping().Converter is { } converter
14                  ? converter.ConvertToProvider(parameters.Value)
15                  : parameters.Value;
16  
17              parameters = parameters with
18              {
19                  Value = value switch
20                  {
21                      true => "true",
22                      false => "false",
23                      _ => throw new UnreachableException()
24                  }
25              };
26  
27              return;
28          }
29  
30          base.ProcessSinglePropertyJsonUpdate(ref parameters);
31      }

