 1      private static string NavigationUniquifier(string proposedIdentifier, ICollection<string>? existingIdentifiers)
 2      {
 3          if (existingIdentifiers?.Contains(proposedIdentifier) != true)
 4          {
 5              return proposedIdentifier;
 6          }
 7  
 8          var finalIdentifier =
 9              string.Format(CultureInfo.CurrentCulture, NavigationNameUniquifyingPattern, proposedIdentifier);
10          var suffix = 1;
11          while (existingIdentifiers.Contains(finalIdentifier))
12          {
13              finalIdentifier = proposedIdentifier + suffix;
14              suffix++;
15          }
16  
17          return finalIdentifier;
18      }

