 1      protected virtual IndexBuilder? VisitIndex(EntityTypeBuilder builder, DatabaseIndex index)
 2      {
 3          var unmappedColumns = index.Columns
 4              .Where(_unmappedColumns.Contains)
 5              .Select(c => c.Name)
 6              .ToList();
 7          if (unmappedColumns.Count > 0)
 8          {
 9              _reporter.WriteWarning(
10                  DesignStrings.UnableToScaffoldIndexMissingProperty(
11                      index.Name,
12                      string.Join(CultureInfo.CurrentCulture.TextInfo.ListSeparator, unmappedColumns)));
13              return null;
14          }
15  
16          var propertyNames = index.Columns.Select(GetPropertyName).ToArray();
17          var indexBuilder = string.IsNullOrEmpty(index.Name)
18              ? builder.HasIndex(propertyNames)
19              : builder.HasIndex(propertyNames, index.Name);
20  
21          indexBuilder = indexBuilder.IsUnique(index.IsUnique);
22  
23          if (index.IsDescending.Any(desc => desc))
24          {
25              indexBuilder = indexBuilder.IsDescending(index.IsDescending.ToArray());
26          }
27  
28          if (index.Filter != null)
29          {
30              indexBuilder = indexBuilder.HasFilter(index.Filter);
31          }
32  
33          indexBuilder.Metadata.AddAnnotations(index.GetAnnotations());
34  
35          return indexBuilder;
36      }

