 3          var entityTypeName = GetEntityTypeName(table);
 4  
 5          var builder = modelBuilder.Entity(entityTypeName);
 6  
 7          var dbSetName = GetDbSetName(table);
 8          builder.Metadata.SetDbSetName(dbSetName);
 9  
10          if (table is DatabaseView)
11          {
12              builder.ToView(table.Name, table.Schema);
13          }
14          else
15          {
16              builder.ToTable(table.Name, table.Schema);
17          }
18  
19          if (table.Comment == null)
20          {
21              builder.Metadata.SetComment(table.Comment);
22          }
23  
24          VisitColumns(builder, table.Columns);
25  
26          if (table.PrimaryKey != null)
27          {
28              var keyBuilder = VisitPrimaryKey(builder, table);
29  
30              if (keyBuilder == null)
31              {
32                  _reporter.WriteWarning(DesignStrings.UnableToGenerateEntityType(table.DisplayName()));
33  
34                  modelBuilder.Model.RemoveEntityType(entityTypeName);
35                  return null;
36              }
37          }
38          else
39          {
40              builder.HasNoKey();
41          }
42  
43          VisitUniqueConstraints(builder, table.UniqueConstraints);
44          VisitIndexes(builder, table.Indexes);
45  
46          foreach (var trigger in table.Triggers)
47          {
48              builder.ToTable(
49                  table.Name, table.Schema, tb => tb
50                      .HasTrigger(trigger.Name)
51                      .Metadata.AddAnnotations(trigger.GetAnnotations()));
52          }
53  
54          builder.Metadata.AddAnnotations(table.GetAnnotations());
55  
56          return builder;
57      }

