26          var builder = sequenceType != null
27              ? modelBuilder.HasSequence(sequenceType, sequence.Name, sequence.Schema)
28              : modelBuilder.HasSequence(sequence.Name, sequence.Schema);
29  
30          if (sequence.IncrementBy.HasValue)
31          {
32              builder.IncrementsBy(sequence.IncrementBy.Value);
33          }
34  
35          if (sequence.MaxValue.HasValue)
36          {
37              builder.HasMax(sequence.MaxValue.Value);
