46          {
47              builder.StartsAt(sequence.StartValue.Value);
48          }
49  
50          if (sequence.IsCyclic.HasValue)
51          {
52              builder.IsCyclic(sequence.IsCyclic.Value);
53          }
54  
55          return builder;
