 6              .AppendLine()
 7              .Append("WHERE ");
 8  
 9          AppendRowsAffectedWhereCondition(commandStringBuilder, 1);
10  
11          if (operations.Count > 0)
12          {
13              commandStringBuilder
14                  .Append(" AND ")
15                  .AppendJoin(
16                      operations, (sb, v) =>
17                      {
18                          if (v is { IsKey: true, IsRead: false })
19                          {
20                              AppendWhereCondition(sb, v, v.UseOriginalValueParameter);
21                              return true;
22                          }
23  
24                          if (IsIdentityOperation(v))
25                          {
26                              AppendIdentityWhereCondition(sb, v);
27                              return true;
28                          }
29  
30                          return false;
31                      }, " AND ");
32          }
33      }

