 7              {
 8                  if (!TryPop(_warmPool, out connection)
 9                      && !TryPop(_coldPool, out connection)
10                      && (Count % 2 == 1 || !ReclaimLeakedConnections()))
11                  {
12                      connection = new SqliteConnectionInternal(_connectionOptions, this);
13  
14                      _connections.Add(connection);
15                  }
16              }
17          }
18          while (connection == null);
19  
20          return connection;
