 9  
10          Check.DebugAssert(
11              (entityType.BaseType is null && !entityType.GetDirectlyDerivedTypes().Any())
12              || entityType.FindDiscriminatorProperty() is not null,
13              "Found FromSql on a TPT entity type, but TPT isn't supported on Cosmos");
14  
15          return new FromSqlQueryRootExpression(
16              entityQueryRootExpression.QueryProvider!,
17              entityType,
18              sql,
19              Expression.Constant(arguments));
20      }

