 1      private static IReadOnlyList<IReadOnlyList<int?>?>? NormalizeCollectionIndices(
 2          IReadOnlyList<PropertyBase> properties,
 3          IReadOnlyList<IReadOnlyList<int?>?>? collectionIndices)
 4      {
 5          if (collectionIndices is null)
 6          {
 7              for (var i = 0; i < properties.Count; i++)
 8              {
 9                  if (InternalTypeBaseBuilder.CountComplexCollectionsInPath(properties[i]) > 0)
10                  {
11                      throw new ArgumentException(
12                          CoreStrings.InvalidNumberOfIndexCollectionIndices(
13                              properties.Format(), 0, properties.Count),
14                          nameof(collectionIndices));
15                  }
16              }
17  
18              return null;
19          }
20  
21          if (collectionIndices.Count != properties.Count)
22          {
23              throw new ArgumentException(
24                  CoreStrings.InvalidNumberOfIndexCollectionIndices(
25                      properties.Format(), collectionIndices.Count, properties.Count),
26                  nameof(collectionIndices));
27          }
28  
29          for (var i = 0; i < properties.Count; i++)
30          {
31              var entry = collectionIndices[i];
32              var expectedCount = InternalTypeBaseBuilder.CountComplexCollectionsInPath(properties[i]);
33              var actualCount = entry?.Count ?? 0;
34              if (actualCount != expectedCount)
35              {
36                  throw new ArgumentException(
37                      CoreStrings.InvalidCollectionIndicesEntryLength(
38                          properties[i].Name, properties.Format(), actualCount, expectedCount),
39                      nameof(collectionIndices));
40              }
41          }
42  
43          // Normalize all-null entries to a null top-level value.
44          return collectionIndices.All(static entry => entry is null) ? null : collectionIndices;
45      }

