 2  		{
 3  			if (data == null)
 4  			{
 5  				var normalizedImage = uiImage.NormalizeOrientation();
 6  
 7  				// First, apply resizing if needed
 8  				var workingImage = normalizedImage;
 9  				var originalSize = normalizedImage.Size;
10  				var newSize = CalculateResizedDimensions(originalSize.Width, originalSize.Height, maximumWidth, maximumHeight);
11  
12  				if (newSize.Width != originalSize.Width || newSize.Height != originalSize.Height)
13  				{
14  					// Resize the image. UIGraphicsImageRenderer (iOS 10+) replaces the
15  					// UIGraphics.BeginImageContext* APIs that are unsupported on iOS 17+.
16  					var rendererFormat = new UIGraphicsImageRendererFormat
17  					{
18  						Opaque = false,
19  						Scale = normalizedImage.CurrentScale,
20  					};
21  					var renderer = new UIGraphicsImageRenderer(newSize, rendererFormat);
22  					workingImage = renderer.CreateImage(_ =>
23  						normalizedImage.Draw(new CoreGraphics.CGRect(CoreGraphics.CGPoint.Empty, newSize)));
24  				}
25  
26  				// Then determine output format and apply compression
27  				bool usePng = ShouldUsePngFormat();
28  
29  				if (usePng)
30  				{
31  					// Use PNG format - lossless compression, supports transparency
32  					data = workingImage.AsPNG();
33  				}
34  				else
35  				{
36  					// Use JPEG with quality-based compression
37  					if (compressionQuality < 90)
38  					{
39  						// Use JPEG compression with quality setting for aggressive compression
40  						var qualityFloat = compressionQuality / 100.0f;
41  						data = workingImage.AsJPEG(qualityFloat);
42  					}
43  					else if (compressionQuality < 100)
44  					{
45  						// Use JPEG with high quality
46  						data = workingImage.AsJPEG(0.9f);
47  					}
48  					else
49  					{
50  						// Use JPEG with maximum quality
51  						data = workingImage.AsJPEG(0.95f);
52  					}
53  				}
54  			}
55  
56  			return Task.FromResult(data.AsStream());
57  		}

