 2  		{
 3  			var str = value?.ToString();
 4  
 5  			if (string.IsNullOrWhiteSpace(str))
 6  				return false;
 7  
 8  			// Any named colors are ok. Surrounding white spaces are ok.
 9  			if (knowValuesSet.Contains(str.Trim()))
10  				return true;
11  
12  			// Check for HEX Color string
13  			if (RxColorHex.Value.IsMatch(str))
14  				return true;
15  
16  			var match = RxFuncExpr.Value.Match(str);
17  
18  			var funcName = match?.Groups?["func"]?.Value;
19  			var funcValues = match?.Groups?["v"]?.Captures;
20  
21  			if (!string.IsNullOrEmpty(funcName) && funcValues != null)
22  			{
23  				// ie: argb() needs 4 parameters:
24  				if (funcValues.Count == funcName.Length)
25  					return true;
26  			}
27  
28  			return false;
29  		}

