 1  		void CompressVerticalLayout(LayoutInformation layout, double widthConstraint, double heightConstraint)
 2  		{
 3  			double yOffset = 0;
 4  
 5  			if (heightConstraint >= layout.Bounds.Height)
 6  			{
 7  				// no need to compress
 8  				return;
 9  			}
10  
11  			double requiredCompression = layout.Bounds.Height - heightConstraint;
12  			double compressionSpace = layout.CompressionSpace;
13  			double compressionPressure = (requiredCompression / layout.CompressionSpace).Clamp(0, 1);
14  
15  			for (var i = 0; i < layout.Plots.Length; i++)
16  			{
17  				var child = (View)LogicalChildrenInternal[i];
18  				if (!child.IsVisible)
19  					continue;
20  
21  				Size minimum = layout.Requests[i].Minimum;
22  
23  				layout.Plots[i].Y -= yOffset;
24  
25  				Rect plot = layout.Plots[i];
26  				double availableSpace = plot.Height - minimum.Height;
27  				if (availableSpace <= 0)
28  					continue;
29  
30  				compressionSpace -= availableSpace;
31  
32  				double compression = availableSpace * compressionPressure;
33  				yOffset += compression;
34  
35  				double newHeight = plot.Height - compression;
36  				SizeRequest newRequest = child.Measure(widthConstraint, newHeight, MeasureFlags.IncludeMargins);
37  
38  				layout.Requests[i] = newRequest;
39  
40  				plot.Width = newRequest.Request.Width;
41  
42  				if (newRequest.Request.Height < newHeight)
43  				{
44  					double delta = newHeight - newRequest.Request.Height;
45  					newHeight = newRequest.Request.Height;
46  					yOffset += delta;
47  					requiredCompression = requiredCompression - yOffset;
48  					compressionPressure = (requiredCompression / compressionSpace).Clamp(0, 1);
49  				}
50  				plot.Height = newHeight;
51  
52  				layout.Bounds.Width = Math.Max(layout.Bounds.Width, plot.Width);
53  
54  				layout.Plots[i] = plot;
55  			}
56  		}

