 1  		public int IndexOf(object item)
 2  		{
 3  			if (IsLoopingEnabled && CenterMode)
 4  			{
 5  				// The renderer will hit this on initial setup to move the ListView into the
 6  				// "middle" of the giant set of totally fake items. That way moving forward and
 7  				// backward in the list will appear to "loop" for a very long time
