11  				var roughlyTheMiddle = FakeCount / 2;
12  				var middleOffset = roughlyTheMiddle % _internal.Count;
13  				var adjustedMiddle = roughlyTheMiddle - middleOffset + 1;
14  				return adjustedMiddle + realIndex;
15  			}
16  
17  			return _internal.IndexOf(item);
18  		}

