 1  		public static void UpdateContentLayout(this MaterialButton materialButton, Button button)
 2  		{
 3  			var context = materialButton.Context;
 4  			if (context == null)
 5  				return;
 6  			var icon = materialButton.Icon;
 7  
 8  			if (icon == null)
 9  			{
10  				Drawable[] drawables = materialButton.GetCompoundDrawablesRelative();
11  				icon = drawables[3];
12  			}
13  
14  			if (icon != null &&
15  				!String.IsNullOrEmpty(button.Text))
16  			{
17  				var contentLayout = button.ContentLayout;
18  
19  				// IconPadding calls materialButton.CompoundDrawablePadding
20  				// Which is why we don't have to worry about calling setCompoundDrawablePadding
21  				// ourselves for our custom implemented IconGravityBottom
22  				materialButton.IconPadding = (int)context.ToPixels(contentLayout.Spacing);
23  
24  				switch (contentLayout.Position)
25  				{
26  					case ButtonContentLayout.ImagePosition.Top:
27  						materialButton.IconGravity = MaterialButton.IconGravityTop;
28  						break;
29  					case ButtonContentLayout.ImagePosition.Bottom:
30  						materialButton.IconGravity = MauiMaterialButton.IconGravityBottom;
31  						break;
32  					case ButtonContentLayout.ImagePosition.Left:
33  						materialButton.IconGravity = MaterialButton.IconGravityTextStart;
34  						break;
35  					case ButtonContentLayout.ImagePosition.Right:
36  						materialButton.IconGravity = MaterialButton.IconGravityTextEnd;
37  						break;
38  				}
39  			}
40  			else
41  			{
42  				// Don't remove this otherwise the button occasionally measures wrong
43  				// on first load
44  				materialButton.Icon = icon;
45  				materialButton.IconPadding = 0;
46  				materialButton.IconGravity = MaterialButton.IconGravityTextStart;
47  			}
48  		}

