 1  	static async Task<ASAuthorization> PerformAsync(ASAuthorizationRequest request, bool preferImmediatelyAvailable, CancellationToken cancellationToken)
 2  	{
 3  		cancellationToken.ThrowIfCancellationRequested();
 4  
 5  		var manager = new PasskeyAuthorizationManager(WindowStateManager.Default.GetCurrentUIWindow(true)!);
 6  		var controller = new ASAuthorizationController(new[] { request })
 7  		{
 8  			Delegate = manager,
 9  			PresentationContextProvider = manager,
10  		};
11  		var gate = new object();
12  		var started = false;
13  
14  		using (cancellationToken.Register(() =>
15  		{
16  			lock (gate)
17  			{
18  				if (started)
19  					controller.Cancel();
20  
21  				manager.TrySetCanceled();
22  			}
23  		}))
24  		{
25  			lock (gate)
26  			{
27  				cancellationToken.ThrowIfCancellationRequested();
28  
29  				if (preferImmediatelyAvailable)
30  					controller.PerformRequests(ASAuthorizationControllerRequestOptions.ImmediatelyAvailableCredentials);
31  				else
32  					controller.PerformRequests();
33  
34  				started = true;
35  			}
36  
37  			return await manager.Task;
38  		}
39  	}

