 4  		EnsureSupported();
 5  		cancellationToken.ThrowIfCancellationRequested();
 6  
 7  		var request = Deserialize(options.ToString(), WebAuthn.JsonContext.Default.RequestOptions, "request options");
 8  
 9  		var rpId = request.RpId
10  			?? throw new ArgumentException("The request options are missing the 'rpId'.", nameof(options));
11  		var challenge = WebAuthn.DecodeRequired(request.Challenge, "challenge");
12  
13  		var provider = new ASAuthorizationPlatformPublicKeyCredentialProvider(rpId);
14  		var assertionRequest = provider.CreateCredentialAssertionRequest(NSData.FromArray(challenge));
15  
16  		var userVerification = MapUserVerification(request.UserVerification);
17  		if (userVerification is not null)
18  			assertionRequest.UserVerificationPreference = userVerification;
19  
20  		var allowed = MapAllowedCredentials(request.AllowCredentials);
21  		if (allowed is not null)
22  			assertionRequest.AllowedCredentials = allowed;
23  
24  		var authorization = await PerformAsync(assertionRequest, options.PreferImmediatelyAvailable, cancellationToken);
25  
26  		var assertion = authorization.GetCredential<ASAuthorizationPlatformPublicKeyCredentialAssertion>();
27  		if (assertion is null)
28  			throw new InvalidOperationException("The authenticator did not return an assertion credential.");
29  
30  		var credentialId = assertion.CredentialId?.ToArray() ?? Array.Empty<byte>();
31  		var userHandle = assertion.UserId?.ToArray();
32  		var response = new WebAuthn.AssertionResponse
33  		{
34  			Id = Base64Url.EncodeToString(credentialId),
35  			RawId = Base64Url.EncodeToString(credentialId),
36  			Response = new WebAuthn.AssertionResponseData
37  			{
38  				ClientDataJson = Base64Url.EncodeToString(assertion.RawClientDataJson?.ToArray() ?? Array.Empty<byte>()),
39  				AuthenticatorData = Base64Url.EncodeToString(assertion.RawAuthenticatorData?.ToArray() ?? Array.Empty<byte>()),
40  				Signature = Base64Url.EncodeToString(assertion.Signature?.ToArray() ?? Array.Empty<byte>()),
41  				UserHandle = userHandle is { Length: > 0 } ? Base64Url.EncodeToString(userHandle) : null,
42  			},
43  		};
44  
45  		return new PasskeyAssertionResponse(JsonSerializer.Serialize(response, WebAuthn.JsonContext.Default.AssertionResponse));
46  	}

