 1          internal static UIViewController CreateForPage(Page page, IMauiContext mauiContext)
 2          {
 3              _ = page.ToPlatform(mauiContext);
 4  
 5              var parentingVC = new NavigationHandlerParentingViewController { Child = page };
 6  
 7              parentingVC.UpdateTitleArea();
 8  
 9              if (page.Handler is not IPlatformViewHandler pageHandler || pageHandler.ViewController is not UIViewController innerVC)
10              {
11                  return parentingVC;
12              }
13  
14              // Detach from any existing parent VC before re-parenting.
15              // This handles the case where a page is popped and then pushed again:
16              // the inner VC is still a child of the old (popped) pack, and UIKit
17              // requires the proper WillMove/Remove/Add/DidMove sequence.
18              if (innerVC.ParentViewController is not null)
19              {
20                  innerVC.WillMoveToParentViewController(null);
21                  innerVC.View?.RemoveFromSuperview();
22                  innerVC.RemoveFromParentViewController();
23              }
24  
25              if (parentingVC.View is UIView packView && innerVC.View is UIView innerView)
26              {
27                  packView.AddSubview(innerView);
28              }
29  
30              parentingVC.AddChildViewController(innerVC);
31              innerVC.DidMoveToParentViewController(parentingVC);
32  
33              return parentingVC;
34          }

