 1  	List<object> ComputeNewMultipleSelection()
 2  	{
 3  		// Extract actual items from platform selection (unwrapping ItemTemplateContext2)
 4  		var currentPlatformSelection = ExtractPlatformSelectedItems();
 5  		var previousSelection = new HashSet<object>(ItemsView.SelectedItems);
 6  		var newSelection = new List<object>();
 7  		var addedToSelection = new HashSet<object>();
 8  
 9  		// Keep existing items that are still selected (maintains their order)
10  		foreach (var existingItem in ItemsView.SelectedItems)
11  		{
12  			if (currentPlatformSelection.Contains(existingItem))
13  			{
14  				newSelection.Add(existingItem);
15  				addedToSelection.Add(existingItem);
16  			}
17  		}
18  
19  		// Append newly selected items (in platform but not in previous virtual selection)
20  		foreach (var item in currentPlatformSelection)
21  		{
22  			if (!previousSelection.Contains(item) && !addedToSelection.Contains(item))
23  			{
24  				newSelection.Add(item);
25  			}
26  		}
27  
28  		return newSelection;
29  	}

