 1  	void UpdateVisualStates()
 2  	{
 3  		if (PlatformView is null || ItemsView is null)
 4  			return;
 5  
 6  		var transparent = new WSolidColorBrush(Microsoft.UI.Colors.Transparent);
 7  
 8  		foreach (var itemContainer in PlatformView.GetChildren<ItemContainer>())
 9  		{
10  			if (itemContainer?.Child is ElementWrapper wrapper && wrapper.VirtualView is VisualElement visualElement)
11  			{
12  				var actualItem = visualElement.BindingContext;
13  				bool isSelected = object.Equals(ItemsView.SelectedItem, actualItem) || ItemsView.SelectedItems.Contains(actualItem);
14  				// Use IsItemSelected instead of GoToState directly so that ChangeVisualState()
15  				// has the correct selected state when a pointer-enter/leave or IsEnabled change
16  				// fires later. IsElementInSelectedState() reads IsItemSelected, so bypassing it
17  				// here (as was done before PR #35421) caused PointerOver-exit and re-enable
18  				// events to incorrectly transition the item to Normal instead of Selected.
19  				visualElement.IsItemSelected = isSelected;
20  
21  				// When the item template defines a "Selected" visual state, MAUI
22  				// handles the selection appearance. Suppress the native WinUI
23  				// selection border (PART_SelectionVisual) and selected background
24  				// fill on that container so the two don't overlap. Items without
25  				// a Selected visual state keep the default WinUI selection visuals.
26  				if (visualElement.HasVisualState(VisualStateManager.CommonStates.Selected))
27  				{
28  					itemContainer.Resources["ItemContainerSelectedBorderBrush"] = transparent;
29  					itemContainer.Resources["ItemContainerSelectedPointerOverBorderBrush"] = transparent;
30  					itemContainer.Resources["ItemContainerSelectedPressedBorderBrush"] = transparent;
31  					itemContainer.Resources["ItemContainerSelectionVisualBackground"] = transparent;
32  					itemContainer.Resources["ItemContainerSelectionVisualPointerOverBackground"] = transparent;
33  					itemContainer.Resources["ItemContainerSelectionVisualPressedBackground"] = transparent;
34  					itemContainer.Resources["ItemContainerSelectedInnerBorderBrush"] = transparent;
35  					// Also suppress the selected background fill so MAUI's VSM
36  					// is the only thing painting the selection appearance.
37  					itemContainer.Resources["ItemContainerSelectedBackground"] = transparent;
38  					itemContainer.Resources["ItemContainerSelectedPointerOverBackground"] = transparent;
39  					itemContainer.Resources["ItemContainerSelectedPressedBackground"] = transparent;
40  				}
41  			}
42  		}
43  	}

