 1      private List<ProxyMethodDescription> GetMethods()
 2      {
 3          var result = new List<ProxyMethodDescription>();
 4          foreach (var iface in GetAllInterfaces(InterfaceType))
 5          {
 6              foreach (var method in iface.GetDeclaredInstanceMembers<IMethodSymbol>())
 7              {
 8                  if (method.MethodKind == MethodKind.ExplicitInterfaceImplementation)
 9                  {
10                      // Explicit implementations can be ignored when generating a proxy.
11                      // Proxies must implement every method explicitly to ensure faithful reproduction of the interface behavior.
12                      // At the calling side, the explicit implementation will be called if it was not overridden by a derived type.
13                      continue;
14                  }
15  
16                  var methodDescription = GenerationContext.GetProxyMethodDescription(InterfaceType, method: method);
17                  result.Add(methodDescription);
18              }
19          }
20  
21          return result;
22  
23          static IEnumerable<INamedTypeSymbol> GetAllInterfaces(INamedTypeSymbol s)
24          {
25              if (s.TypeKind == TypeKind.Interface)
26              {
27                  yield return s;
28              }
29  
30              foreach (var i in s.AllInterfaces)
31  
