20          if (Name.IndexOfAny(FilteredNameChars) >= 0)
21          {
22              foreach (var c in FilteredNameChars)
23              {
24                  Name = Name.Replace(c, '_');
25              }
26          }
27  
28          GeneratedNamespace = InterfaceType.GetNamespaceAndNesting() switch
29          {
30              { Length: > 0 } ns => $"{GeneratedCodeUtilities.CodeGeneratorName}.{ns}",
31              _ => GeneratedCodeUtilities.CodeGeneratorName
32          };
33  
34          var names = new HashSet<string>(StringComparer.Ordinal);
35          TypeParameters = new List<(string Name, ITypeParameterSymbol Parameter)>();
36  
37          foreach (var tp in interfaceType.GetAllTypeParameters())
