 1      private static Action<OptionsBuilder<AzureQueueOptions>> GetQueueOptionBuilder(IConfigurationSection configurationSection)
 2      {
 3          return (OptionsBuilder<AzureQueueOptions> optionsBuilder) =>
 4          {
 5              optionsBuilder.Configure<IServiceProvider>((options, services) =>
 6              {
 7                  var queueNames = configurationSection.GetSection("QueueNames").Get<List<string>>();
 8                  if (queueNames != null)
 9                  {
10                      options.QueueNames = queueNames;
11                  }
12  
13                  if (configurationSection.GetValue<TimeSpan?>(nameof(options.MessageVisibilityTimeout)) is { } visibilityTimeout)
14                  {
15                      options.MessageVisibilityTimeout = visibilityTimeout;
16                  }
17  
18                  var serviceKey = configurationSection["ServiceKey"];
19                  if (!string.IsNullOrEmpty(serviceKey))
20                  {
21                      // Get a client by name.
22                      options.QueueServiceClient = services.GetRequiredKeyedService<QueueServiceClient>(serviceKey);
23                  }
24                  else
25                  {
26                      // Construct a connection multiplexer from a connection string.
27                      var connectionName = configurationSection["ConnectionName"];
28                      var connectionString = configurationSection["ConnectionString"];
29                      if (!string.IsNullOrEmpty(connectionName) && string.IsNullOrEmpty(connectionString))
30                      {
31                          var rootConfiguration = services.GetRequiredService<IConfiguration>();
32                          connectionString = rootConfiguration.GetConnectionString(connectionName);
33                      }
34  
35                      if (!string.IsNullOrEmpty(connectionString))
36                      {
37                          if (Uri.TryCreate(connectionString, UriKind.Absolute, out var uri))
38                          {
39                              if (!string.IsNullOrEmpty(uri.Query))
40                              {
41                                  // SAS URI
42                                  options.QueueServiceClient = new QueueServiceClient(uri);
43                              }
44                              else
45                              {
46                                  options.QueueServiceClient = new QueueServiceClient(uri, credential: new Azure.Identity.DefaultAzureCredential());
47                              }
48                          }
49                          else
50                          {
51                              options.QueueServiceClient = new QueueServiceClient(connectionString);
52                          }
53                      }
54                  }
55              });
56          };
57      }

