 1          public async Task ClearStateAsync<T>(string grainType, GrainId grainId, IGrainState<T> grainState, CancellationToken cancellationToken)
 2          {
 3              cancellationToken.ThrowIfCancellationRequested();
 4              if (this.storage == null) throw new ArgumentException("GrainState-Table property not initialized");
 5  
 6              string partitionKey = GetKeyString(grainId);
 7              LogTraceClearingGrainState(logger, grainType, partitionKey, grainId, grainState.ETag, this.options.DeleteStateOnClear, this.options.TableName);
 8  
 9              string rowKey = AWSUtils.ValidateDynamoDBRowKey(grainType);
10              var record = new GrainStateRecord
11              {
12                  GrainReference = partitionKey,
13                  ETag = string.IsNullOrWhiteSpace(grainState.ETag)
14                      ? 0
15                      : int.Parse(grainState.ETag, NumberStyles.Integer, CultureInfo.InvariantCulture),
16                  GrainType = rowKey
17              };
18  
19              var operation = "Clearing";
20              try
21              {
22                  if (this.options.DeleteStateOnClear)
23                  {
24                      operation = "Deleting";
25                      var keys = new Dictionary<string, AttributeValue>
26                      {
27                          { GRAIN_REFERENCE_PROPERTY_NAME, new AttributeValue(record.GrainReference) },
28                          { GRAIN_TYPE_PROPERTY_NAME, new AttributeValue(record.GrainType) }
29                      };
30                      var expression = $"attribute_not_exists({ETAG_PROPERTY_NAME})";
31                      Dictionary<string, AttributeValue>? conditionalValues = null;
32                      if (!string.IsNullOrWhiteSpace(grainState.ETag))
33                      {
34                          conditionalValues = new Dictionary<string, AttributeValue> { { CURRENT_ETAG_ALIAS, new AttributeValue { N = record.ETag.ToString(CultureInfo.InvariantCulture) } } };
35                          expression = $"{ETAG_PROPERTY_NAME} = {CURRENT_ETAG_ALIAS}";
36                      }
37  
38                      await this.storage.DeleteEntryAsync(this.options.TableName, keys, cancellationToken, expression, conditionalValues).ConfigureAwait(false);
39                      ResetGrainState(grainState);
40                  }
41                  else
42                  {
43                      await WriteStateInternal(grainState, record, cancellationToken, true);
44                      grainState.State = CreateInstance<T>();
45                      grainState.RecordExists = false;
46                  }
47              }
48              catch (ConditionalCheckFailedException exc)
49              {
50                  throw new InconsistentStateException($"Inconsistent grain state: {exc}");
51              }
52              catch (Exception exc) when (exc is not OperationCanceledException || !cancellationToken.IsCancellationRequested)
53              {
54                  LogErrorClearingGrainState(logger, exc, operation, grainType, grainId, grainState.ETag, this.options.TableName);
55                  throw;
56              }
57          }

