13                  {
14                      { GRAIN_REFERENCE_PROPERTY_NAME, new AttributeValue(partitionKey) },
15                      { GRAIN_TYPE_PROPERTY_NAME, new AttributeValue(rowKey) }
16                  },
17                  (fields) =>
18                  {
19                      return new GrainStateRecord
20                      {
21                          GrainType = fields[GRAIN_TYPE_PROPERTY_NAME].S,
22                          GrainReference = fields[GRAIN_REFERENCE_PROPERTY_NAME].S,
23                          ETag = int.Parse(fields[ETAG_PROPERTY_NAME].N, NumberStyles.Integer, CultureInfo.InvariantCulture),
24                          State = fields.TryGetValue(BINARY_STATE_PROPERTY_NAME, out var propertyName) ? propertyName.B?.ToArray() : null,
25                      };
26                  }, cancellationToken).ConfigureAwait(false);
27  
28              if (record != null)
29              {
30                  var loadedState = ConvertFromStorageFormat<T>(record);
