 1          private static void EnsureSufficientData<TInput>(ref Reader<TInput> reader, int[] lengths)
 2          {
 3              // A zero in any dimension makes the complete element count zero.
 4              if (Array.IndexOf(lengths, 0) >= 0)
 5              {
 6                  return;
 7              }
 8  
 9              var remaining = (ulong)reader.Remaining;
10              ulong elementCount = 1;
11              foreach (var length in lengths)
12              {
13                  if (length < 0)
14                  {
15                      return;
16                  }
17  
18                  if (elementCount > remaining / (uint)length)
19                  {
20                      ThrowInvalidSizeException(lengths, reader.Remaining);
21                  }
22  
23                  elementCount *= (uint)length;
24              }
25          }

