 1          public void WriteField<TBufferWriter>(ref Writer<TBufferWriter> writer, uint fieldIdDelta, [System.Diagnostics.CodeAnalysis.AllowNull] Type expectedType, [System.Diagnostics.CodeAnalysis.AllowNull] object? value) where TBufferWriter : IBufferWriter<byte>
 2          {
 3              if (ReferenceCodec.TryWriteReferenceField(ref writer, fieldIdDelta, expectedType, value!))
 4              {
 5                  return;
 6              }
 7  
 8              EnsureZeroLowerBounds((Array)value);
 9              writer.WriteFieldHeader(fieldIdDelta, expectedType, value!.GetType(), WireType.TagDelimited);
10  
11              var array = (Array)value;
12              var rank = array.Rank;
13  
14              var lengths = new int[rank];
15              var indices = new int[rank];
16  
17              // Write array lengths.
18              for (var i = 0; i < rank; i++)
19              {
20                  lengths[i] = array.GetLength(i);
21              }
22  
23              _intArrayCodec.WriteField(ref writer, 0, DimensionFieldType, lengths);
24  
25              var remaining = array.Length;
26              uint innerFieldIdDelta = 1;
27              while (remaining-- > 0)
28              {
29                  var element = array.GetValue(indices);
30                  _elementCodec.WriteField(ref writer, innerFieldIdDelta, CodecElementType, (T)element!);
31                  innerFieldIdDelta = 0;
32  
33                  // Increment the indices array by 1.
34                  if (remaining > 0)
35                  {
36                      var idx = rank - 1;
37                      while (idx >= 0 && ++indices[idx] >= lengths[idx])
38                      {
39                          indices[idx] = 0;
40                          --idx;
41                          if (idx < 0)
42                          {
43                              ThrowIndexOutOfRangeException(lengths);
44                          }
45                      }
46                  }
47              }
48  
49  
50              writer.WriteEndObject();
51          }

