 1          public static bool FlipBit(ref string writeVector, string Replica)
 2          {
 3              var pos = writeVector.IndexOf(Replica, StringComparison.Ordinal);
 4              if (pos > 0 && writeVector[pos - 1] == ',')
 5              {
 6                  var pos2 = writeVector.IndexOf(',', pos + 1);
 7                  if (pos2 == -1)
 8                      pos2 = writeVector.Length;
 9                  writeVector = writeVector.Remove(pos - 1, pos2 - pos + 1);
10                  return false;
11              }
12              else
13              {
14                  writeVector = string.Format(",{0}{1}", Replica, writeVector);
15                  return true;
16              }
17          }

