 1              async Task RegisterStreamAsync()
 2              {
 3                  try
 4                  {
 5                      await Task.CompletedTask.ConfigureAwait(ConfigureAwaitOptions.ContinueOnCapturedContext | ConfigureAwaitOptions.ForceYielding);
 6  
 7                      if (IsShutdown || cancellationToken.IsCancellationRequested)
 8                      {
 9                          return;
10                      }
11  
12                      var subscribers = await RegisterAsStreamProducer(streamId, cancellationToken);
13  
14                      if (IsShutdown || cancellationToken.IsCancellationRequested)
15                      {
16                          return;
17                      }
18  
19                      // Producer registration succeeded; the stream entry is now established.
20                      // Subscriber-handshake failures must not tear down the entry from here on.
21                      streamData.StreamRegistered = true;
22                      StreamingEvents.EmitPullingAgentStreamRegistered(streamProviderName, Silo, QueueId, streamId.StreamId, GrainId, subscribers.Count);
23  
24                      LogDebugGotBackSubscribers(subscribers.Count, streamId);
25  
26                      // Await all initial subscriber handshakes before releasing the pin cursor so
27                      // that the first batch cannot be purged from the cache before each subscriber
28                      // has established its own cursor.
29                      if (subscribers.Count > 0)
30                      {
31                          var addSubscriptionTasks = new List<Task>(subscribers.Count);
32                          foreach (PubSubSubscriptionState item in subscribers)
33                          {
34                              addSubscriptionTasks.Add(SubscribeWithIsolation(item));
35                          }
36  
37                          await Task.WhenAll(addSubscriptionTasks);
38                      }
39                  }
40                  catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
41                  {
42                      RemoveCanceledRegistration();
43                  }
44                  catch (Exception exception)
45                  {
46                      FailRegistration(exception);
47                  }
48                  finally
49                  {
50                      try
51                      {
52                          streamData.RegistrationTask = null;
53                          pinCursor?.Dispose();
54                      }
55                      finally
56                      {
57                          workAdmission.Exit();
58                      }
59                  }
60              }

