 1          private bool TryGetDeliveryProgress(out StreamSequenceToken? earliest)
 2          {
 3              earliest = null;
 4  
 5              foreach (var streamConsumers in pubSubCache.Values)
 6              {
 7                  if (streamConsumers.RegistrationTask is { IsCompleted: false })
 8                  {
 9                      return false;
10                  }
11  
12                  foreach (var consumer in streamConsumers.AllConsumers())
13                  {
14                      if (!consumer.IsRegistered || consumer.PendingHandshakes != 0 || consumer.HasUnresolvedHandshake)
15                      {
16                          return false;
17                      }
18  
19                      var current = consumer.LastProcessedToken;
20                      if (current is null)
21                      {
22                          return false;
23                      }
24  
25                      if (earliest is null)
26                      {
27                          earliest = current;
28                          continue;
29                      }
30  
31                      try
32                      {
33                          if (IsBefore(current, earliest))
34                          {
35                              earliest = current;
36                          }
37                      }
38                      catch (ArgumentOutOfRangeException exception) when (exception.ParamName == "other")
39                      {
40                          LogWarningIncompatibleDeliveryProgress(
41                              new(QueueId), consumer.SubscriptionId, consumer.StreamId, current, earliest, exception);
42                          earliest = null;
43                          return false;
44                      }
45                  }
46              }
47  
48              return true;
49          }

