 1          private async Task PumpQueue(QueueId queueId, CancellationToken cancellationToken)
 2          {
 3              try
 4              {
 5                  Task? localReceiverInitTask = receiverInitTask;
 6                  if (localReceiverInitTask != null)
 7                  {
 8                      await localReceiverInitTask;
 9                      receiverInitTask = null;
10                  }
11  
12                  if (IsShutdown || cancellationToken.IsCancellationRequested) return; // timer was already removed, last tick
13  
14                  // loop through the queue until it is empty.
15                  while (!IsShutdown && !cancellationToken.IsCancellationRequested) // shutdown sets IsShutdown and cancels the timer token.
16                  {
17                      int maxCacheAddCount = queueCache?.GetMaxAddCount() ?? QueueAdapterConstants.UNLIMITED_GET_QUEUE_MSG;
18                      if (maxCacheAddCount != QueueAdapterConstants.UNLIMITED_GET_QUEUE_MSG && maxCacheAddCount <= 0)
19                          return;
20  
21                      // If read succeeds and there is more data, we continue reading.
22                      // If read succeeds and there is no more data, we break out of loop
23                      // If read fails, we retry 6 more times, with backoff policy.
24                      //    we log each failure as warnings. After 6 times retry if still fail, we break out of loop and log an error
25                      bool moreData = await AsyncExecutorWithRetries.ExecuteWithRetries(
26                          i => ReadFromQueue(queueId, receiver, maxCacheAddCount, cancellationToken),
27                          ReadLoopRetryMax,
28                          ReadLoopRetryExceptionFilter,
29                          Timeout.InfiniteTimeSpan,
30                          queueReaderBackoffProvider,
31                          cancellationToken: cancellationToken);
32                      if (!moreData)
33                          return;
34                  }
35              }
36              catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
37              {
38                  receiverInitTask = null;
39              }
40              catch (Exception exc)
41              {
42                  receiverInitTask = null;
43                  LogErrorGivingUpReading(new(queueId), ReadLoopRetryMax, exc);
44              }
45  
46              bool ReadLoopRetryExceptionFilter(Exception e, int retryCounter)
47              {
48                  LogErrorRetrying(retryCounter, new(queueId), e);
49                  return !cancellationToken.IsCancellationRequested && !IsShutdown;
50              }
51          }

