 1          private static QueueCacheCursorMoveResult AdvanceCursorPastToken(
 2              IQueueCacheCursor cursor,
 3              StreamSequenceToken token,
 4              out IBatchContainer? pendingBatch)
 5          {
 6              pendingBatch = null;
 7              while (true)
 8              {
 9                  var result = cursor.MoveNextWithResult();
10                  if (result.Kind is QueueCacheCursorMoveResultKind.NoData or QueueCacheCursorMoveResultKind.CacheMiss)
11                  {
12                      return result;
13                  }
14  
15                  if (result.Kind != QueueCacheCursorMoveResultKind.Success)
16                  {
17                      throw new QueueCacheCursorContractException("The cursor move result is not initialized.");
18                  }
19  
20                  var batch = cursor.GetCurrent(out var exception);
21                  if (exception is not null)
22                  {
23                      throw exception;
24                  }
25  
26                  if (batch is null)
27                  {
28                      throw new QueueCacheCursorContractException("A successful cursor move did not produce a current item.");
29                  }
30  
31                  var comparison = EventSequenceTokenCompatibility.Compare(batch.SequenceToken, token);
32                  if (comparison >= 0)
33                  {
34                      pendingBatch = comparison > 0 ? batch : null;
35                      return result;
36                  }
37              }
38          }

