 1          private async Task AddSubscriber_Impl(
 2              GuidId subscriptionId,
 3              QualifiedStreamId streamId,
 4              GrainId streamConsumer,
 5              string? filterData,
 6              StreamSequenceToken? cacheToken)
 7          {
 8              using var admission = _workAdmission.TryEnter();
 9              if (!admission.Entered || IsShutdown) return;
10  
11              if (!pubSubCache.TryGetValue(streamId, out var streamDataCollection))
12              {
13                  // If stream is not in pubsub cache, then we've received no events on this stream, and will aquire the subscriptions from pubsub when we do.
14                  return;
15              }
16  
17              if (!streamDataCollection.TryGetConsumer(subscriptionId, out var data))
18              {
19                  var consumerReference = this.RuntimeClient.InternalGrainFactory
20                      .GetGrain(streamConsumer)
21                      .AsReference<IStreamConsumerExtension>();
22                  data = streamDataCollection.AddConsumer(subscriptionId, streamId, consumerReference, filterData, _timeProvider.GetUtcNow().UtcDateTime);
23                  StreamingEvents.EmitSubscriptionAdded(streamProviderName, streamId.StreamId, subscriptionId.Guid, streamConsumer, Silo);
24              }
25  
26              data.PendingHandshakes++;
27              var handshakeRequestId = ++data.HandshakeRequestId;
28              data.HasUnresolvedHandshake = true;
29              var handshakeSucceeded = false;
30              try
31              {
32                  handshakeSucceeded = await DoHandshakeWithConsumer(data, cacheToken, handshakeRequestId);
33                  if (handshakeSucceeded && handshakeRequestId == data.HandshakeRequestId)
34                  {
35                      data.LastProcessedToken = GetInitialDeliveryProgress(data.LastToken, data.LastProcessedToken);
36                      data.PendingStartToken = null;
37                      data.IsRegistered = true;
38                      StreamingEvents.EmitSubscriptionAttached(streamProviderName, streamId.StreamId, subscriptionId.Guid, streamConsumer, Silo);
39                      if (data.State == StreamConsumerDataState.Inactive)
40                          RunConsumerCursor(data).Ignore(); // Start delivering events if not actively doing so
41                  }
42              }
43              finally
44              {
45                  if (handshakeRequestId == data.HandshakeRequestId)
46                  {
47                      data.HasUnresolvedHandshake = !handshakeSucceeded;
48                  }
49                  data.PendingHandshakes--;
50              }
51          }

