 1              private async Task RunMessageLoop()
 2              {
 3                  while (true)
 4                  {
 5                      try
 6                      {
 7                          await _signal.WaitAsync();
 8  
 9                          if (IsDropped)
10                          {
11                              RejectDroppedClientMessages();
12                              continue;
13                          }
14  
15                          var connection = Volatile.Read(ref _connection);
16                          if (connection is null)
17                          {
18                              continue;
19                          }
20  
21                          // Send all pending messages.
22                          while (_pendingToSend.TryDequeue(out var message))
23                          {
24                              if (TrySend(connection, message))
25                              {
26                                  LogTraceSentQueuedMessage(_gateway.logger, message, Id);
27                              }
28                              else
29                              {
30                                  // Re-enqueue the message. It's ok that it is at the end of the queue: message ordering is not guaranteed.
31                                  _pendingToSend.Enqueue(message);
32                                  return;
33                              }
34                          }
35                      }
36                      catch (Exception exception)
37                      {
38                          LogWarningGatewayClientMessageLoopException(_gateway.logger, exception, Id);
39                      }
40                  }
41              }

