 1          internal void DropDisconnectedClients()
 2          {
 3              var trackDroppedClients = GatewayEvents.IsClientDroppedEnabled();
 4              List<(GrainId ClientId, TimeSpan DisconnectedDuration)>? droppedClients = null;
 5              foreach (var kv in clients)
 6              {
 7                  if (kv.Value.ReadyToDrop())
 8                  {
 9                      lock (clients)
10                      {
11                          if (clients.TryGetValue(kv.Key, out var client) && client.ReadyToDrop())
12                          {
13                              var disconnectedDuration = client.DisconnectedSince;
14                              LogInformationGatewayDroppingClient(logger, kv.Key, disconnectedDuration);
15  
16                              if (clients.TryRemove(kv.Key, out _))
17                              {
18                                  // Reject all pending messages from the client.
19                                  client.Drop();
20                                  if (trackDroppedClients)
21                                  {
22                                      droppedClients ??= [];
23                                      droppedClients.Add((kv.Key.GrainId, disconnectedDuration));
24                                  }
25                              }
26  
27                              clientsCollectionVersion++;
28                              _messagingInstruments.ConnectedClient.Add(-1);
29                          }
30                      }
31                  }
32              }
33  
34              if (droppedClients is not null)
35              {
36                  foreach (var droppedClient in droppedClients)
37                  {
38                      GatewayEvents.EmitClientDropped(siloAddress, droppedClient.ClientId, droppedClient.DisconnectedDuration);
39                  }
40              }
41          }

