 9              // So, if the TargetGrain is a SystemTarget we always trust the value from Message.TargetSilo and forward
10              // it to this address...
11              // EXCEPT if the value is equal to the current GatewayAddress: in this case we will return
12              // null and the local dispatcher will forward the Message to a local SystemTarget activation
13              if (msg.TargetGrain.IsSystemTarget() && !IsTargetingLocalGateway(msg.TargetSilo!))
14              {
15                  return msg.TargetSilo;
16              }
17  
18              // for responses from ClientAddressableObject to ClientGrain try to use clientsReplyRoutingCache for sending replies directly back.
19              if (!msg.SendingGrain.IsClient() || !msg.TargetGrain.IsClient())
20              {
21                  return null;
22              }
23  
24              if (msg.Direction == Message.Directions.Response)
25              {
26                  return null;
27              }
28  
29              if (clientsReplyRoutingCache.TryFindClientRoute(msg.TargetGrain, out var gateway))
30              {
31                  return gateway;
32              }
33  
34              return null;
35          }

