 1          internal ReadOnlySpan<byte> ToByteArray()
 2          {
 3              var extBytes = this.KeyExt != null ? Encoding.UTF8.GetBytes(KeyExt) : null;
 4              var extBytesLength = extBytes?.Length ?? 0;
 5              var sizeWithoutExtBytes = sizeof(ulong) * 3 + sizeof(int);
 6  
 7              var spanBytes = new byte[sizeWithoutExtBytes + extBytesLength].AsSpan();
 8  
 9              BinaryPrimitives.WriteUInt64LittleEndian(spanBytes, N0);
10              BinaryPrimitives.WriteUInt64LittleEndian(spanBytes.Slice(8, 8), N1);
11              BinaryPrimitives.WriteUInt64LittleEndian(spanBytes.Slice(16, 8), TypeCodeData);
12  
13              const int offset = sizeof(ulong) * 3;
14              // Copy KeyExt
15              if (extBytes != null)
16              {
17                  BinaryPrimitives.WriteInt32LittleEndian(spanBytes.Slice(offset, sizeof(int)), extBytesLength);
18                  extBytes.CopyTo(spanBytes[(offset + sizeof(int))..]);
19              }
20              else
21              {
22                  BinaryPrimitives.WriteInt32LittleEndian(spanBytes.Slice(offset, sizeof(int)), -1);
23              }
24  
25              return spanBytes;
26          }

