 1          private static UniqueKey ParseCore(ReadOnlySpan<char> input, bool trim)
 2          {
 3              const int minimumValidKeyLength = 48;
 4              if (trim)
 5              {
 6                  input = input.Trim();
 7              }
 8  
 9              if (input.Length >= minimumValidKeyLength)
10              {
11                  var n0 = ulong.Parse(input[..16].ToString(), NumberStyles.AllowHexSpecifier);
12                  var n1 = ulong.Parse(input.Slice(16, 16).ToString(), NumberStyles.AllowHexSpecifier);
13                  var typeCodeData = ulong.Parse(input.Slice(32, 16).ToString(), NumberStyles.AllowHexSpecifier);
14                  string? keyExt = null;
15                  if (input.Length > minimumValidKeyLength)
16                  {
17                      if (input[48] != '+') throw new InvalidDataException("UniqueKey hex string missing + separator.");
18                      keyExt = input[49..].ToString();
19                  }
20  
21                  return NewKey(n0, n1, typeCodeData, keyExt);
22              }
23  
24              // last, for convenience we attempt to parse the string using GUID syntax. this is needed by unit
25              // tests but i don't know if it's needed for production.
26              return NewKey(Guid.Parse(input.ToString()));
27          }

