 1      private async Task RequestExpiredLeaseCleanups()
 2      {
 3          Debug.Assert(_deadSiloLeaseDuration > TimeSpan.Zero);
 4  
 5          // We request cleanups periodically to not let expired leases linger in the directory for too long.
 6          // We do it here as opposed to in the partitions to avoid having 30 (by default, maybe more) timers.
 7          var period = 1.1 * _deadSiloLeaseDuration;
 8  
 9          if (period < TimeSpan.FromMinutes(1))
10          {
11              // We create a lower-bound to avoid creating too much overhead in the partitions.
12              period = TimeSpan.FromMinutes(1);
13          }
14  
15          using var timer = new PeriodicTimer(period, _timeProvider);
16  
17          try
18          {
19              while (await timer.WaitForNextTickAsync(_stoppedCts.Token))
20              {
21                  foreach (var partition in _partitions)
22                  {
23                      partition.CleanupExpiredLeases();
24                  }
25              }
26          }
27          catch (OperationCanceledException) when (_stoppedCts.IsCancellationRequested)
28          {
29              // Ignore
30          }
31      }

