15  
16          static Task NoOpStart(CancellationToken _) => Task.CompletedTask;
17  
18          Task OnRuntimeInitializeStart(CancellationToken cancellationToken)
19          {
20              using var _ = new ExecutionContextSuppressor();
21  
22              WorkItemGroup.QueueAction(() =>
23              {
24                  _runTask = ProcessMembershipUpdates();
25  
26                  if (_deadSiloLeaseDuration > TimeSpan.Zero)
27                  {
28                      _leaseCleanupTask = RequestExpiredLeaseCleanups();
29                  }
30              });
31  
32              return Task.CompletedTask;
33          }
34  
35          async Task OnRuntimeInitializeStop(CancellationToken cancellationToken)
36          {
37              _stoppedCts.Cancel();
38  
39              if (_runTask is { } task)
40              {
41                  // Try to wait for hand-off to complete.
42                  await this.RunOrQueueTask(async () => await task.WaitAsync(cancellationToken).SuppressThrowing());
43              }
44  
45              if (_leaseCleanupTask is { } cleanupTask)
46              {
47                  await cleanupTask.WaitAsync(cancellationToken).SuppressThrowing();
48              }
49          }
50  
51          async Task OnShuttingDown(CancellationToken token)
52          {
53              var tasks = new List<Task>(_partitions.Length);
54              foreach (var partition in _partitions)
55              {
56                  tasks.Add(partition.OnShuttingDown(token));
57              }
58              await Task.WhenAll(tasks).SuppressThrowing();
59          }
60      }

