 1      public ValueTask<Immutable<List<GrainAddress>>> GetRegisteredActivations(
 2          MembershipVersion membershipVersion,
 3          RingRange range,
 4          bool isValidation,
 5          CancellationToken cancellationToken)
 6      {
 7          cancellationToken.ThrowIfCancellationRequested();
 8          if (!isValidation)
 9          {
10              LogDebugCollectingRegisteredActivations(_logger, range, membershipVersion);
11          }
12  
13          var recoveryMembershipVersion = _recoveryMembershipVersion;
14          if (recoveryMembershipVersion < membershipVersion.Value)
15          {
16              // Ensure that the value is immediately visible to any thread registering an activation.
17              Interlocked.CompareExchange(ref _recoveryMembershipVersion, membershipVersion.Value, recoveryMembershipVersion);
18          }
19  
20          List<GrainAddress> result = [];
21          var skippedActivationCount = 0;
22          var stopwatch = CoarseStopwatch.StartNew();
23  
24          foreach (var (grainId, activation) in _localActivations)
25          {
26              cancellationToken.ThrowIfCancellationRequested();
27              var directory = GetGrainDirectory(activation, _grainDirectoryResolver!);
28              if (directory == this)
29              {
30                  var address = activation.Address;
31                  if (!range.Contains(address.GrainId))
32                  {
33                      continue;
34                  }
35  
36                  if (address.MembershipVersion == MembershipVersion.MinValue
37                      || activation is ActivationData { State: ActivationState.Deactivating or ActivationState.Invalid })
38                  {
39                      ++skippedActivationCount;
40                      continue;
41                  }
42                  else
43                  {
44                      if (!isValidation)
45                      {
46                          LogTraceSendingActivationForRecovery(_logger, activation.GrainId, range, membershipVersion);
47                      }
48  
49                      result.Add(activation.Address);
50                  }
51              }
52          }
53  
54          if (!isValidation)
55          {
56              LogDebugSubmittingRegisteredActivations(_logger, result.Count, range, membershipVersion, skippedActivationCount, stopwatch.ElapsedMilliseconds);
57          }
58  
59          return new(result.AsImmutable());
60      }

