 1      private async ValueTask<(DirectoryMembershipSnapshot View, SiloAddress Owner, IGrainDirectoryPartition PartitionReference)?> GetViewWithOwnerAsync(
 2          GrainId grainId,
 3          DirectoryMembershipSnapshot view,
 4          long minimumVersion,
 5          CancellationToken cancellationToken)
 6      {
 7          while (true)
 8          {
 9              if (view.Version.Value >= minimumVersion
10                  && view.TryGetOwner(grainId, out var owner, out var partitionReference))
11              {
12                  return (view, owner, partitionReference);
13              }
14  
15              // Cluster membership advances before the directory's asynchronous view. If the latest cluster view
16              // still has an active member, this empty directory view is stale; otherwise it is terminal, as on shutdown.
17              if (view.Members.Length == 0
18                  && view.Version.Value > 0
19                  && !HasActiveMembers(LatestClusterMembershipSnapshot))
20              {
21                  return null;
22              }
23  
24              var targetVersion = Math.Max(view.Version.Value + 1, minimumVersion);
25              view = await _membershipService.RefreshViewAsync(new(targetVersion), cancellationToken);
26          }
27      }

