 2          {
 3              cancellationToken.ThrowIfCancellationRequested();
 4              // validate the lock
 5              var (status, record) = await this.queue.RWLock.ValidateLock(transactionId, accessCount).WaitAsync(cancellationToken);
 6              var valid = status == TransactionalStatus.Ok;
 7  
 8              record.Timestamp = timeStamp;
 9              record.Role = CommitRole.ReadOnly;
10              record.PromiseForTA = new TaskCompletionSource<TransactionalStatus>(TaskCreationOptions.RunContinuationsAsynchronously);
11  
12              try
13              {
14                  if (!valid)
15                  {
16                      await this.queue.NotifyOfAbort(record, status, exception: null);
17                  }
18                  else
19                  {
20                      this.queue.Clock.Merge(record.Timestamp);
21                  }
22              }
23              finally
24              {
25                  this.queue.RWLock.Notify();
26              }
27  
28              return await record.PromiseForTA.Task.WaitAsync(cancellationToken);
29          }

