 4              if (attribute is null)
 5              {
 6                  return null;
 7              }
 8  
 9              // here
10              var callbackMethodName = attribute.CallbackMethodName;
11              var method = grainType.GetMethod(callbackMethodName, BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance | BindingFlags.FlattenHierarchy);
12              if (method == null)
