14                  throw new InvalidOperationException(
15                      $"Class {grainType.FullName} doesn't declare public method " +
16                      $"with name {callbackMethodName} specified in MayInterleave attribute");
17              }
18  
19              if (method.ReturnType != typeof(bool) ||
20                  method.GetParameters().Length != 1 ||
21                  method.GetParameters()[0].ParameterType != typeof(IInvokable))
22              {
23                  throw new InvalidOperationException(
24                      $"Wrong signature of callback method {callbackMethodName} " +
25                      $"specified in MayInterleave attribute for grain class {grainType.FullName}. \n" +
26                      $"Expected: public bool {callbackMethodName}(IInvokable req)");
27              }
28  
29              if (method.IsStatic)
30              {
31                  return new MayInterleaveStaticPredicate(method.CreateDelegate<Func<IInvokable, bool>>());
32              }
33  
34              var predicateType = typeof(MayInterleaveInstancedPredicate<>).MakeGenericType(grainType);
35              return (IMayInterleavePredicate?)Activator.CreateInstance(predicateType, method);
36          }

