 1  	buildSetOperationQuery({
 2  		leftSelect,
 3  		setOperator: { type, isAll, rightSelect, limit, orderBy, offset },
 4  	}: {
 5  		leftSelect: SQL;
 6  		setOperator: SingleStoreSelectConfig['setOperators'][number];
 7  	}): SQL {
 8  		const leftChunk = sql`(${leftSelect.getSQL()}) `;
 9  		const rightChunk = sql`(${rightSelect.getSQL()})`;
10  
11  		let orderBySql;
12  		if (orderBy && orderBy.length > 0) {
13  			const orderByValues: (SQL<unknown> | Name)[] = [];
14  
15  			// The next bit is necessary because the sql operator replaces ${table.column} with `table`.`column`
16  			// which is invalid SingleStore syntax, Table from one of the SELECTs cannot be used in global ORDER clause
17  			for (const orderByUnit of orderBy) {
18  				if (is(orderByUnit, SingleStoreColumn)) {
19  					orderByValues.push(
20  						sql.identifier(this.casing.getColumnCasing(orderByUnit)),
21  					);
22  				} else if (is(orderByUnit, SQL)) {
23  					for (let i = 0; i < orderByUnit.queryChunks.length; i++) {
24  						const chunk = orderByUnit.queryChunks[i];
25  
26  						if (is(chunk, SingleStoreColumn)) {
27  							orderByUnit.queryChunks[i] = sql.identifier(
28  								this.casing.getColumnCasing(chunk),
29  							);
30  						}
31  					}
32  
33  					orderByValues.push(sql`${orderByUnit}`);
34  				} else {
35  					orderByValues.push(sql`${orderByUnit}`);
36  				}
37  			}
38  
39  			orderBySql = sql` order by ${sql.join(orderByValues, sql`, `)} `;
40  		}
41  
42  		const limitSql = typeof limit === 'object' || (typeof limit === 'number' && limit >= 0)
43  			? sql` limit ${limit}`
44  			: undefined;
45  
46  		const operatorChunk = sql.raw(`${type} ${isAll ? 'all ' : ''}`);
47  
48  		const offsetSql = offset ? sql` offset ${offset}` : undefined;
49  
50  		return sql`${leftChunk}${operatorChunk}${rightChunk}${orderBySql}${limitSql}${offsetSql}`;
51  	}

