 1  	async migrate(
 2  		migrations: MigrationMeta[],
 3  		session: SingleStoreSession,
 4  		config: Omit<MigrationConfig, 'migrationsSchema'>,
 5  	): Promise<void> {
 6  		const migrationsTable = config.migrationsTable ?? '__drizzle_migrations';
 7  		const migrationTableCreate = sql`
 8  			create table if not exists ${sql.identifier(migrationsTable)} (
 9  				id serial primary key,
10  				hash text not null,
11  				created_at bigint
12  			)
13  		`;
14  		await session.execute(migrationTableCreate);
15  
16  		const dbMigrations = await session.all<{
17  			id: number;
18  			hash: string;
19  			created_at: string;
20  		}>(
21  			sql`select id, hash, created_at from ${sql.identifier(migrationsTable)} order by created_at desc limit 1`,
22  		);
23  
24  		const lastDbMigration = dbMigrations[0];
25  
26  		await session.transaction(async (tx) => {
27  			for (const migration of migrations) {
28  				if (
29  					!lastDbMigration
30  					|| Number(lastDbMigration.created_at) < migration.folderMillis
31  				) {
32  					for (const stmt of migration.sql) {
33  						await tx.execute(sql.raw(stmt));
34  					}
35  					await tx.execute(
36  						sql`insert into ${
37  							sql.identifier(
38  								migrationsTable,
39  							)
40  						} (\`hash\`, \`created_at\`) values(${migration.hash}, ${migration.folderMillis})`,
41  					);
42  				}
43  			}
44  		});
45  	}

