 2  	const migrationQueries: MigrationMeta[] = [];
 3  
 4  	for await (const journalEntry of journal.entries) {
 5  		const query = migrations[`m${journalEntry.idx.toString().padStart(4, '0')}`];
 6  
 7  		if (!query) {
 8  			throw new Error(`Missing migration: ${journalEntry.tag}`);
 9  		}
10  
11  		try {
12  			const result = query.split('--> statement-breakpoint').map((it) => {
13  				return it;
14  			});
15  
16  			migrationQueries.push({
17  				sql: result,
18  				bps: journalEntry.breakpoints,
19  				folderMillis: journalEntry.when,
20  				hash: '',
21  			});
22  		} catch {
23  			throw new Error(`Failed to parse migration: ${journalEntry.tag}`);
24  		}
25  	}
26  
27  	return migrationQueries;
28  }

