 1  export async function migrate<TSchema extends Record<string, unknown>>(
 2  	db: MySqlRemoteDatabase<TSchema>,
 3  	callback: ProxyMigrator,
 4  	config: MigrationConfig,
 5  ) {
 6  	const migrations = readMigrationFiles(config);
 7  
 8  	const migrationsTable = config.migrationsTable ?? '__drizzle_migrations';
 9  	const migrationTableCreate = sql`
10  		create table if not exists ${sql.identifier(migrationsTable)} (
11  			id serial primary key,
12  			hash text not null,
13  			created_at bigint
14  		)
15  	`;
16  	await db.execute(migrationTableCreate);
17  
18  	const dbMigrations = await db.select({
19  		id: sql.raw('id'),
20  		hash: sql.raw('hash'),
21  		created_at: sql.raw('created_at'),
22  	}).from(sql.identifier(migrationsTable).getSQL()).orderBy(
23  		sql.raw('created_at desc'),
24  	).limit(1);
25  
26  	const lastDbMigration = dbMigrations[0];
27  
28  	const queriesToRun: string[] = [];
29  
30  	for (const migration of migrations) {
31  		if (
32  			!lastDbMigration
33  			|| Number(lastDbMigration.created_at) < migration.folderMillis
34  		) {
35  			queriesToRun.push(
36  				...migration.sql,
37  				`insert into ${
38  					sql.identifier(migrationsTable).value
39  				} (\`hash\`, \`created_at\`) values('${migration.hash}', '${migration.folderMillis}')`,
40  			);
41  		}
42  	}
43  
44  	await callback(queriesToRun);
45  }

