 1  function handleColumns(
 2  	columns: Record<string, any>,
 3  	refinements: Record<string, any>,
 4  	conditions: Conditions,
 5  ): Type {
 6  	const columnSchemas: Record<string, Type> = {};
 7  
 8  	for (const [key, selected] of Object.entries(columns)) {
 9  		if (!is(selected, Column) && !is(selected, SQL) && !is(selected, SQL.Aliased) && typeof selected === 'object') {
10  			const columns = isTable(selected) || isView(selected) ? getColumns(selected) : selected;
11  			columnSchemas[key] = handleColumns(columns, refinements[key] ?? {}, conditions);
12  			continue;
13  		}
14  
15  		const refinement = refinements[key];
16  		if (
17  			refinement !== undefined
18  			&& (typeof refinement !== 'function' || (typeof refinement === 'function' && refinement.expression !== undefined))
19  		) {
20  			columnSchemas[key] = refinement;
21  			continue;
22  		}
23  
24  		const column = is(selected, Column) ? selected : undefined;
25  		const schema = column ? columnToSchema(column) : type.unknown;
26  		const refined = typeof refinement === 'function' ? refinement(schema) : schema;
27  
28  		if (conditions.never(column)) {
29  			continue;
30  		} else {
31  			columnSchemas[key] = refined;
32  		}
33  
34  		if (column) {
35  			if (conditions.nullable(column)) {
36  				columnSchemas[key] = columnSchemas[key]!.or(type.null);
37  			}
38  
39  			if (conditions.optional(column)) {
40  				columnSchemas[key] = columnSchemas[key]!.optional() as any;
41  			}
42  		}
43  	}
44  
45  	return type(columnSchemas);
46  }

