 1  export function toValueParam(value: any, typings?: QueryTypingsValue): { value: Field; typeHint?: TypeHint } {
 2  	const response: { value: Field; typeHint?: TypeHint } = {
 3  		value: {} as any,
 4  		typeHint: typingsToAwsTypeHint(typings),
 5  	};
 6  
 7  	if (value === null) {
 8  		response.value = { isNull: true };
 9  	} else if (typeof value === 'string') {
10  		switch (response.typeHint) {
11  			case TypeHint.DATE: {
12  				response.value = { stringValue: value.split('T')[0]! };
13  				break;
14  			}
15  			case TypeHint.TIMESTAMP: {
16  				response.value = { stringValue: value.replace('T', ' ').replace('Z', '') };
17  				break;
18  			}
19  			default: {
20  				response.value = { stringValue: value };
21  				break;
22  			}
23  		}
24  	} else if (typeof value === 'number' && Number.isInteger(value)) {
25  		response.value = { longValue: value };
26  	} else if (typeof value === 'number' && !Number.isInteger(value)) {
27  		response.value = { doubleValue: value };
28  	} else if (typeof value === 'boolean') {
29  		response.value = { booleanValue: value };
30  	} else if (value instanceof Date) { // eslint-disable-line no-instanceof/no-instanceof
31  		// TODO: check if this clause is needed? Seems like date value always comes as string
32  		response.value = { stringValue: value.toISOString().replace('T', ' ').replace('Z', '') };
33  	} else {
34  		throw new Error(`Unknown type for ${value}`);
35  	}
36  
37  	return response;
38  }

