 1  	async execute(placeholderValues: Record<string, unknown> | undefined = {}): Promise<T['execute']> {
 2  		const params = fillPlaceholders(this.params, placeholderValues);
 3  
 4  		this.logger.logQuery(this.queryString, params);
 5  
 6  		const {
 7  			fields,
 8  			client,
 9  			queryString,
10  			rawQuery,
11  			query,
12  			joinsNotNullableMap,
13  			customResultMapper,
14  			returningIds,
15  			generatedIds,
16  		} = this;
17  		if (!fields && !customResultMapper) {
18  			const res = await this.queryWithCache(queryString, params, async () => {
19  				return await client.execute(queryString, params, rawQuery);
20  			});
21  
22  			const insertId = Number.parseFloat(res.insertId);
23  			const affectedRows = res.rowsAffected;
24  
25  			// for each row, I need to check keys from
26  			if (returningIds) {
27  				const returningResponse = [];
28  				let j = 0;
29  				for (let i = insertId; i < insertId + affectedRows; i++) {
30  					for (const column of returningIds) {
31  						const key = returningIds[0]!.path[0]!;
32  						if (is(column.field, Column)) {
33  							// @ts-ignore
34  							if (column.field.primary && column.field.autoIncrement) {
35  								returningResponse.push({ [key]: i });
36  							}
37  							if (column.field.defaultFn && generatedIds) {
38  								// generatedIds[rowIdx][key]
39  								returningResponse.push({ [key]: generatedIds[j]![key] });
40  							}
41  						}
42  					}
43  					j++;
44  				}
45  				return returningResponse;
46  			}
47  			return res;
48  		}
49  		const { rows } = await this.queryWithCache(queryString, params, async () => {
50  			return await client.execute(queryString, params, query);
51  		});
52  
53  		if (customResultMapper) {
54  			return customResultMapper(rows as unknown[][]);
55  		}
56  
57  		return rows.map((row) => mapResultRow<T['execute']>(fields!, row as unknown[], joinsNotNullableMap));
58  	}

