 7  			PgBinaryVector<
 8  				ColumnBaseConfig<'string', 'PgBinaryVector'> & {
 9  					dimensions: number;
10  				}
11  			>
12  		>(column, ['PgBinaryVector'])
13  	) {
14  		return type(`/^[01]{${column.dimensions}}$/`)
15  			.describe(`a string containing ones or zeros while being ${column.dimensions} characters long`);
16  	}
