23  	} else if (
24  		isColumnType<MySqlVarChar<any> | SingleStoreVarChar<any>>(column, ['MySqlVarChar', 'SingleStoreVarChar'])
25  	) {
26  		max = column.length ?? CONSTANTS.INT16_UNSIGNED_MAX;
27  	} else if (isColumnType<MySqlText<any> | SingleStoreText<any>>(column, ['MySqlText', 'SingleStoreText'])) {
28  		if (column.textType === 'longtext') {
29  			max = CONSTANTS.INT32_UNSIGNED_MAX;
30  		} else if (column.textType === 'mediumtext') {
31  			max = CONSTANTS.INT24_UNSIGNED_MAX;
32  		} else if (column.textType === 'text') {
33  			max = CONSTANTS.INT16_UNSIGNED_MAX;
34  		} else {
35  			max = CONSTANTS.INT8_UNSIGNED_MAX;
36  		}
37  	}
38  
39  	if (
40  		isColumnType<PgChar<any> | MySqlChar<any> | SingleStoreChar<any>>(column, [
41  			'PgChar',
42  			'MySqlChar',
43  			'SingleStoreChar',
44  		])
45  	) {
