 1  export function mapRelationalRow(
 2  	tablesConfig: TablesRelationalConfig,
 3  	tableConfig: TableRelationalConfig,
 4  	row: unknown[],
 5  	buildQueryResultSelection: BuildRelationalQueryResult['selection'],
 6  	mapColumnValue: (value: unknown) => unknown = (value) => value,
 7  ): Record<string, unknown> {
 8  	const result: Record<string, unknown> = {};
 9  
10  	for (
11  		const [
12  			selectionItemIndex,
13  			selectionItem,
14  		] of buildQueryResultSelection.entries()
15  	) {
16  		if (selectionItem.isJson) {
17  			const relation = tableConfig.relations[selectionItem.tsKey]!;
18  			const rawSubRows = row[selectionItemIndex] as
19  				| unknown[]
20  				| null
21  				| [null]
22  				| string;
23  			const subRows = typeof rawSubRows === 'string'
24  				? (JSON.parse(rawSubRows) as unknown[])
25  				: rawSubRows;
26  			result[selectionItem.tsKey] = is(relation, One)
27  				? subRows
28  					&& mapRelationalRow(
29  						tablesConfig,
30  						tablesConfig[selectionItem.relationTableTsKey!]!,
31  						subRows,
32  						selectionItem.selection,
33  						mapColumnValue,
34  					)
35  				: (subRows as unknown[][]).map((subRow) =>
36  					mapRelationalRow(
37  						tablesConfig,
38  						tablesConfig[selectionItem.relationTableTsKey!]!,
39  						subRow,
40  						selectionItem.selection,
41  						mapColumnValue,
42  					)
43  				);
44  		} else {
45  			const value = mapColumnValue(row[selectionItemIndex]);
46  			const field = selectionItem.field!;
47  			let decoder;
48  			if (is(field, Column)) {
49  				decoder = field;
50  			} else if (is(field, SQL)) {
51  				decoder = field.decoder;
52  			} else {
53  				decoder = field.sql.decoder;
54  			}
55  			result[selectionItem.tsKey] = value === null ? null : decoder.mapFromDriverValue(value);
56  		}
57  	}
58  
59  	return result;
60  }

