 1  export async function migrate<TSchema extends Record<string, unknown>>(
 2  	db: SqliteRemoteDatabase<TSchema>,
 3  	callback: ProxyMigrator,
 4  	config: MigrationConfig,
 5  ) {
 6  	const migrations = readMigrationFiles(config);
 7  
 8  	const migrationsTable = typeof config === 'string'
 9  		? '__drizzle_migrations'
10  		: config.migrationsTable ?? '__drizzle_migrations';
11  
12  	const migrationTableCreate = sql`
13  		CREATE TABLE IF NOT EXISTS ${sql.identifier(migrationsTable)} (
14  			id SERIAL PRIMARY KEY,
15  			hash text NOT NULL,
16  			created_at numeric
17  		)
18  	`;
19  
20  	await db.run(migrationTableCreate);
21  
22  	const dbMigrations = await db.values<[number, string, string]>(
23  		sql`SELECT id, hash, created_at FROM ${sql.identifier(migrationsTable)} ORDER BY created_at DESC LIMIT 1`,
24  	);
25  
26  	const lastDbMigration = dbMigrations[0] ?? undefined;
27  
28  	const queriesToRun: string[] = [];
29  	for (const migration of migrations) {
30  		if (
31  			!lastDbMigration
32  			|| Number(lastDbMigration[2])! < migration.folderMillis
33  		) {
34  			queriesToRun.push(
35  				...migration.sql,
36  				`INSERT INTO \`${migrationsTable}\` ("hash", "created_at") VALUES('${migration.hash}', '${migration.folderMillis}')`,
37  			);
38  		}
39  	}
40  
41  	await callback(queriesToRun);
42  }

