 7  	] | [
 8  		TClient | string,
 9  		MySql2DrizzleConfig<TSchema>,
10  	] | [
11  		(
12  			& MySql2DrizzleConfig<TSchema>
13  			& ({
14  				connection: string | PoolOptions;
15  			} | {
16  				client: TClient;
17  			})
18  		),
19  	]
20  ): MySql2Database<TSchema> & {
21  	$client: AnyMySql2Connection extends TClient ? CallbackPool : TClient;
22  } {
23  	if (typeof params[0] === 'string') {
24  		const connectionString = params[0]!;
25  		const instance = createPool({
26  			uri: connectionString,
27  		});
28  
29  		return construct(instance, params[1]) as any;
30  	}
31  
32  	if (isConfig(params[0])) {
33  		const { connection, client, ...drizzleConfig } = params[0] as
34  			& { connection?: PoolOptions | string; client?: TClient }
35  			& MySql2DrizzleConfig<TSchema>;
36  
37  		if (client) return construct(client, drizzleConfig) as any;
38  
39  		const instance = typeof connection === 'string'
40  			? createPool({
41  				uri: connection,
