 1  export function buildArrayString(array: any[], sqlType: string): string {
 2  	sqlType = sqlType.split('[')[0];
 3  	const values = array
 4  		.map((value) => {
 5  			if (typeof value === 'number' || typeof value === 'bigint') {
 6  				return value.toString();
 7  			} else if (typeof value === 'boolean') {
 8  				return value ? 'true' : 'false';
 9  			} else if (Array.isArray(value)) {
10  				return buildArrayString(value, sqlType);
11  			} else if (value instanceof Date) {
12  				if (sqlType === 'date') {
13  					return `"${value.toISOString().split('T')[0]}"`;
14  				} else if (sqlType === 'timestamp') {
15  					return `"${value.toISOString().replace('T', ' ').slice(0, 23)}"`;
16  				} else {
17  					return `"${value.toISOString()}"`;
18  				}
19  			} else if (typeof value === 'object') {
20  				return `"${JSON.stringify(value).replaceAll('"', '\\"')}"`;
21  			}
22  
23  			return `"${value}"`;
24  		})
25  		.join(',');
26  
27  	return `{${values}}`;
28  }

