 1  export async function migrate<TSchema extends Record<string, unknown>>(
 2  	db: DrizzleD1Database<TSchema>,
 3  	config: MigrationConfig,
 4  ) {
 5  	const migrations = readMigrationFiles(config);
 6  	const migrationsTable = config.migrationsTable ?? '__drizzle_migrations';
 7  
 8  	const migrationTableCreate = sql`
 9  		CREATE TABLE IF NOT EXISTS ${sql.identifier(migrationsTable)} (
10  			id SERIAL PRIMARY KEY,
11  			hash text NOT NULL,
12  			created_at numeric
13  		)
14  	`;
15  	await db.session.run(migrationTableCreate);
16  
17  	const dbMigrations = await db.values<[number, string, string]>(
18  		sql`SELECT id, hash, created_at FROM ${sql.identifier(migrationsTable)} ORDER BY created_at DESC LIMIT 1`,
19  	);
20  
21  	const lastDbMigration = dbMigrations[0] ?? undefined;
22  
23  	const statementToBatch = [];
24  
25  	for (const migration of migrations) {
26  		if (!lastDbMigration || Number(lastDbMigration[2])! < migration.folderMillis) {
27  			for (const stmt of migration.sql) {
28  				statementToBatch.push(db.run(sql.raw(stmt)));
29  			}
30  
31  			statementToBatch.push(
32  				db.run(
33  					sql`INSERT INTO ${sql.identifier(migrationsTable)} ("hash", "created_at") VALUES(${
34  						sql.raw(`'${migration.hash}'`)
35  					}, ${sql.raw(`${migration.folderMillis}`)})`,
36  				),
37  			);
38  		}
39  	}
40  
41  	if (statementToBatch.length > 0) {
42  		await db.session.batch(statementToBatch);
43  	}
44  }

