 1  	async migrate(migrations: MigrationMeta[], session: PgSession, config: string | MigrationConfig): Promise<void> {
 2  		const migrationsTable = typeof config === 'string'
 3  			? '__drizzle_migrations'
 4  			: config.migrationsTable ?? '__drizzle_migrations';
 5  		const migrationsSchema = typeof config === 'string' ? 'drizzle' : config.migrationsSchema ?? 'drizzle';
 6  		const migrationTableCreate = sql`
 7  			CREATE TABLE IF NOT EXISTS ${sql.identifier(migrationsSchema)}.${sql.identifier(migrationsTable)} (
 8  				id SERIAL PRIMARY KEY,
 9  				hash text NOT NULL,
10  				created_at bigint
11  			)
12  		`;
13  		await session.execute(sql`CREATE SCHEMA IF NOT EXISTS ${sql.identifier(migrationsSchema)}`);
14  		await session.execute(migrationTableCreate);
15  
16  		const dbMigrations = await session.all<{ id: number; hash: string; created_at: string }>(
17  			sql`select id, hash, created_at from ${sql.identifier(migrationsSchema)}.${
18  				sql.identifier(migrationsTable)
19  			} order by created_at desc limit 1`,
20  		);
21  
22  		const lastDbMigration = dbMigrations[0];
23  		await session.transaction(async (tx) => {
24  			for await (const migration of migrations) {
25  				if (
26  					!lastDbMigration
27  					|| Number(lastDbMigration.created_at) < migration.folderMillis
28  				) {
29  					for (const stmt of migration.sql) {
30  						await tx.execute(sql.raw(stmt));
31  					}
32  					await tx.execute(
33  						sql`insert into ${sql.identifier(migrationsSchema)}.${
34  							sql.identifier(migrationsTable)
35  						} ("hash", "created_at") values(${migration.hash}, ${migration.folderMillis})`,
36  					);
37  				}
38  			}
39  		});
40  	}

