 1  function stringColumnToSchema(column: Column, t: typeof typebox): TSchema {
 2  	if (isColumnType<PgUUID<ColumnBaseConfig<'string', 'PgUUID'>>>(column, ['PgUUID'])) {
 3  		return t.String({ format: 'uuid' });
 4  	} else if (
 5  		isColumnType<PgBinaryVector<ColumnBaseConfig<'string', 'PgBinaryVector'> & { dimensions: number }>>(column, [
 6  			'PgBinaryVector',
 7  		])
 8  	) {
 9  		return t.RegExp(/^[01]+$/, column.dimensions ? { maxLength: column.dimensions } : undefined);
10  	}
11  
12  	let max: number | undefined;
13  	let fixed = false;
14  
15  	if (isColumnType<PgVarchar<any> | SQLiteText<any>>(column, ['PgVarchar', 'SQLiteText'])) {
16  		max = column.length;
17  	} else if (
18  		isColumnType<MySqlVarChar<any> | SingleStoreVarChar<any>>(column, ['MySqlVarChar', 'SingleStoreVarChar'])
19  	) {
20  		max = column.length ?? CONSTANTS.INT16_UNSIGNED_MAX;
21  	} else if (isColumnType<MySqlText<any> | SingleStoreText<any>>(column, ['MySqlText', 'SingleStoreText'])) {
22  		if (column.textType === 'longtext') {
23  			max = CONSTANTS.INT32_UNSIGNED_MAX;
24  		} else if (column.textType === 'mediumtext') {
25  			max = CONSTANTS.INT24_UNSIGNED_MAX;
26  		} else if (column.textType === 'text') {
27  			max = CONSTANTS.INT16_UNSIGNED_MAX;
28  		} else {
29  			max = CONSTANTS.INT8_UNSIGNED_MAX;
30  		}
31  	}
32  
33  	if (
34  		isColumnType<PgChar<any> | MySqlChar<any> | SingleStoreChar<any>>(column, [
35  			'PgChar',
36  			'MySqlChar',
37  			'SingleStoreChar',
38  		])
39  	) {
40  		max = column.length;
41  		fixed = true;
42  	}
43  
44  	const options: Partial<StringOptions> = {};
45  
46  	if (max !== undefined && fixed) {
47  		options.minLength = max;
48  		options.maxLength = max;
49  	} else if (max !== undefined) {
50  		options.maxLength = max;
51  	}
52  
53  	return t.String(Object.keys(options).length > 0 ? options : undefined);
54  }

