 1          private void SetDescription(ServerDescription newDescription, bool forceClearConnectionPool)
 2          {
 3              // Current assumption is SetDescription is always synchronized under _monitor.Lock.
 4              // This synchronization technically can be violated by calling server.Invalidate not under _monitor.Lock.
 5              // Therefore _currentDescription and ConnectionPool state can get out of sync.
 6  
 7              var serverDescriptionChangedEvent = new ServerDescriptionChangedEventArgs(_currentDescription, newDescription);
 8              _currentDescription = newDescription;
 9  
10              if (newDescription.HeartbeatException != null || forceClearConnectionPool)
11              {
12                  // propagate event to upper levels
13                  TriggerServerDescriptionChanged(this, serverDescriptionChangedEvent);
14  
15                  // pool must be cleared on after cluster update
16                  var closeInUseConnections = newDescription.HeartbeatException is MongoConnectionException mongoConnectionException && mongoConnectionException.ContainsTimeoutException;
17                  ConnectionPool.Clear(closeInUseConnections);
18              }
19              else
20              {
21                  if (newDescription.IsDataBearing ||
22                      (newDescription.Type != ServerType.Unknown && DirectConnection))
23                  {
24                      // The spec requires to check (server.type != Unknown and newTopologyDescription.type == Single)
25                      // in C# driver servers in single topology will be only selectable if direct connection was requested
26                      // therefore it is sufficient to check whether the connection mode is directConnection.
27                      ConnectionPool.SetReady();
28                  }
29  
30                  // propagate event to upper levels
31                  TriggerServerDescriptionChanged(this, serverDescriptionChangedEvent);
32              }
33          }

