 1          private void OnMonitorDescriptionChanged(object sender, ServerDescriptionChangedEventArgs e)
 2          {
 3              var currentDescription = _currentDescription;
 4  
 5              var heartbeatException = e.NewServerDescription.HeartbeatException;
 6              // The heartbeat command is hello (or legacy hello). This command will throw a MongoCommandException on
 7              // {ok: 0}, but a reply (with a potential topologyVersion) will still have been received.
 8              // Not receiving a reply to the heartbeat commands implies a network error or a "HeartbeatFailed" type
 9              // exception (i.e. ServerDescription.WithHeartbeatException was called), in which case we should immediately
10              // set the description to "Unknown"// (which is what e.NewServerDescription will be in such a case)
11              var heartbeatReplyNotReceived = heartbeatException != null && !(heartbeatException is MongoCommandException);
12  
13              // We cannot use FresherThan(e.NewServerDescription.TopologyVersion, currentDescription.TopologyVersion)
14              // because due to how TopologyVersions comparisons are defined, IsStalerThanOrEqualTo(x, y) does not imply
15              // FresherThan(y, x)
16              if (heartbeatReplyNotReceived ||
17                  TopologyVersion.IsStalerThanOrEqualTo(currentDescription.TopologyVersion, e.NewServerDescription.TopologyVersion))
18              {
19                  SetDescription(e.NewServerDescription, forceClearConnectionPool: false);
20              }
21          }

