12                  _ => (invalidateAndClear: (connectionException.IsNetworkException || connectionException.ContainsTimeoutException) && !connectionException.HasErrorLabel("SystemOverloadedError"),
13                        cancelCheck: connectionException.IsNetworkException && !connectionException.ContainsTimeoutException)
