 1          public static AstFilter Translate(TranslationContext context, MethodCallExpression expression)
 2          {
 3              var method = expression.Method;
 4              var arguments = expression.Arguments;
 5  
 6              if (method.Is(LinqExtensionsMethod.Inject))
 7              {
 8                  var filterExpression = arguments[0];
 9                  var filterDefinition = filterExpression.GetConstantValue<object>(expression);
10                  var filterDefinitionType = filterDefinition.GetType(); // we KNOW it's a FilterDefinition<TDocument> because of the Inject method signature
11                  var filterDefinitionDocumentType = filterDefinitionType.GetGenericArguments()[0];
12  
13                  var rootSymbol = context.SymbolTable.Symbols.SingleOrDefault(s => s.Ast.IsRootVar());
14                  if (rootSymbol == null)
15                  {
16                      throw new ExpressionNotSupportedException(expression, because: "there is no current root symbol");
17                  }
18                  var documentSerializer = rootSymbol.Serializer;
19                  if (filterDefinitionDocumentType != documentSerializer.ValueType)
20                  {
21                      throw new ExpressionNotSupportedException(expression, because: $"FilterDefinition TDocument type: {filterDefinitionDocumentType} does not match document type {documentSerializer.ValueType} ");
22                  }
23                  var serializerRegistry = context.SerializationDomain.SerializerRegistry;
24  
25                  var renderFilterMethod = __renderFilterMethodInfo.MakeGenericMethod(filterDefinitionDocumentType);
26                  var renderedFilter = (BsonDocument)renderFilterMethod.Invoke(null, new[] { filterDefinition, documentSerializer, serializerRegistry, context.TranslationOptions });
27  
28                  return AstFilter.Raw(renderedFilter);
29              }
30  
31              throw new ExpressionNotSupportedException(expression);
32          }

