 1          public static ISecurityContext InitializeSecurityContext(string serviceName, string hostname, string realm, string authorizationId, SecureString password)
 2          {
 3              var operatingSystemPlatform = OperatingSystemHelper.CurrentOperatingSystem;
 4              switch (operatingSystemPlatform)
 5              {
 6                  case OperatingSystemPlatform.Windows:
 7                      {
 8                          SspiSecurityCredential credential = null;
 9                          try
10                          {
11                              var servicePrincipalName = $"{serviceName}/{hostname}";
12                              if (!string.IsNullOrEmpty(realm))
13                              {
14                                  servicePrincipalName += $"@{realm}";
15                              }
16                              credential = SspiSecurityCredential.Acquire(SspiPackage.Kerberos, authorizationId, password);
17                              return new SspiSecurityContext(servicePrincipalName, credential);
18                          }
19                          catch (Win32Exception)
20                          {
21                              credential?.Dispose();
22                              throw;
23                          }
24                      }
25                  case OperatingSystemPlatform.Linux:
26                      {
27                          GssapiServicePrincipalName servicePrincipalName = null;
28                          GssapiSecurityCredential credential = null;
29                          try
30                          {
31                              servicePrincipalName = GssapiServicePrincipalName.Create(serviceName, hostname, realm);
32                              credential = GssapiSecurityCredential.Acquire(authorizationId, password);
33                              return new GssapiSecurityContext(servicePrincipalName, credential);
34                          }
35                          catch (LibgssapiException)
36                          {
37                              servicePrincipalName?.Dispose();
38                              credential?.Dispose();
39                              throw;
40                          }
41                      }
42                  default:
43                      throw new NotSupportedException($"GSSAPI is not supported on {operatingSystemPlatform}.");
44              }
45          }

