10        if (stream.destroyed) {
11          return resolve(ABORTED);
12        }
13        let aborted = false;
14        let calledBack = false;
15        const abort = () => {
16          if (calledBack) {
17            return;
18          }
19          aborted = true;
20          resolve(ABORTED);
21          const partial = file as unknown as UploadedMultipartFile;
22          if (partial.path) {
23            removeFiles(storage, req, [partial]).catch(() => undefined);
24          }
25        };
26        const onClose = () => {
27          if (stream.readableEnded) {
28            return;
29          }
30          const reason = stream.errored;
31          if (!reason) {
32            return abort();
33          }
34          // The parts iterator fails with this very error when the parser
35          // destroyed the stream; it stays pending when the engine did.
36          readAhead().then(
37            () => undefined,
38            err => err === reason && abort(),
39          );
40        };
41        stream.once('close', onClose);
