43          calledBack = true;
44          stream.off('close', onClose);
45          if (!aborted) {
46            return err ? reject(err) : resolve(info ?? {});
47          }
48          const stored = Object.assign(
49            file,
50            err ? {} : info,
51          ) as unknown as UploadedMultipartFile;
52          if (!err || stored.path) {
53            removeFiles(storage, req, [stored]).catch(() => undefined);
54          }
55        });
56      },
57    );
58  }

