11        const sendOptions = {
12          persistent: this.getOptionsProp(
13            this.options,
14            'persistent',
15            RMQ_DEFAULT_PERSISTENT,
16          ),
17          ...options,
18          headers: this.mergeHeaders(options?.headers, metadata),
19        };
20        const errorCallback = (err: unknown) =>
21          err ? reject(err as Error) : resolve();
22  
23        return this.options.wildcards || this.options.exchangeType === 'fanout'
24          ? this.channel!.publish(
25              // The exchange is the same as the queue when wildcards are enabled
26              // and the exchange is not explicitly set
27              this.getOptionsProp(this.options, 'exchange', this.queue),
28              this.normalizePattern(packet.pattern),
29              content,
30              sendOptions,
31              errorCallback,
32            )
33          : this.channel!.sendToQueue(
34              this.queue,
35              content,
36              sendOptions,
37              errorCallback,
38            );
39      });
40    }

