 1    public async handleMessage(
 2      packet: unknown,
 3      options:
 4        Record<string, unknown> | ((packet: WritePacket) => any) | undefined,
 5      callback?: (packet: WritePacket) => any,
 6    ): Promise<void> {
 7      if (isFunction(options)) {
 8        callback = options as (packet: WritePacket) => any;
 9        options = undefined;
10      }
11  
12      let incomingResponse: IncomingResponse;
13      try {
14        incomingResponse = await this.deserializer.deserialize(packet, options);
15      } catch (error) {
16        // Nobody awaits this listener, so a rejection would crash the process.
17        return callback?.({ err: error, isDisposed: true });
18      }
19      const { err, response, isDisposed } = incomingResponse;
20      if (isDisposed || err) {
21        return callback?.({
22          err,
23          response,
24          isDisposed: true,
25        });
26      }
27      callback?.({
28        err,
29        response,
30      });
31    }

