 1  function parsePath(key: string): PathStep[] {
 2    const failure = (): PathStep[] => [{ type: 'object', key, last: true }];
 3    const firstKey = /^[^[]*/.exec(key)![0];
 4    if (!firstKey) {
 5      return failure();
 6    }
 7  
 8    let pos = firstKey.length;
 9    let tail: PathStep = { type: 'object', key: firstKey };
10    const steps = [tail];
11  
12    while (pos < key.length) {
13      if (key[pos] === '[' && key[pos + 1] === ']') {
14        pos += 2;
15        tail.append = true;
16        if (pos !== key.length) {
17          return failure();
18        }
19        continue;
20      }
21      const rest = key.substring(pos);
22      let match = /^\[(\d+)\]/.exec(rest);
23      if (match) {
24        pos += match[0].length;
25        tail.nextType = 'array';
26        tail = { type: 'array', key: parseInt(match[1], 10) };
27        steps.push(tail);
28        continue;
29      }
30      match = /^\[([^\]]+)\]/.exec(rest);
31      if (match) {
32        pos += match[0].length;
33        tail.nextType = 'object';
34        tail = { type: 'object', key: match[1] };
35        steps.push(tail);
36        continue;
37      }
38      return failure();
39    }
40    tail.last = true;
41    return steps;
42  }

