 1    private matchNatsSubject(pattern: string, subject: string) {
 2      const patternTokens = pattern.split('.');
 3      const subjectTokens = subject.split('.');
 4      for (let i = 0; i < patternTokens.length; i++) {
 5        if (patternTokens[i] === '>') {
 6          return subjectTokens.length > i;
 7        }
 8        if (patternTokens[i] !== '*' && patternTokens[i] !== subjectTokens[i]) {
 9          return false;
10        }
11      }
12      return patternTokens.length === subjectTokens.length;
13    }

