 5              return -1;
 6  
 7          using var registration = _connector.StartNestedCancellableOperation(cancellationToken);
 8  
 9          // Consume and advance any active column.
10          if (_column >= 0)
11          {
12              if (async)
13                  await PgReader.CommitAsync().ConfigureAwait(false);
