27          else if (_column != BeforeRow)
28              ThrowHelper.ThrowInvalidOperationException("Already in the middle of a row");
29  
30          await _buf.Ensure(2, async).ConfigureAwait(false);
31  
32          var numColumns = _buf.ReadInt16();
33          if (numColumns == -1)
34          {
35              Expect<CopyDoneMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
36              Expect<CommandCompleteMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
37              Expect<ReadyForQueryMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
38              _column = BeforeRow;
39              _state = ExporterState.Consumed;
40              return -1;
41          }
42  
43          Debug.Assert(numColumns == NumColumns);
44  
45          _column = BeforeColumn;
46          _rowsExported++;
47          return NumColumns;
48      }

