 3          var msg = await _connector.ReadMessage(async).ConfigureAwait(false);
 4          _endOfMessagePos = _buf.CumulativeReadPosition + Expect<CopyDataMessage>(msg, _connector).Length;
 5          var headerLen = NpgsqlRawCopyStream.BinarySignature.Length + 4 + 4;
 6          await _buf.Ensure(headerLen, async).ConfigureAwait(false);
 7  
 8          foreach (var t in NpgsqlRawCopyStream.BinarySignature)
 9              if (_buf.ReadByte() != t)
10                  throw new NpgsqlException("Invalid COPY binary signature at beginning!");
11  
12          var flags = _buf.ReadInt32();
13          if (flags == 0)
14              throw new NotSupportedException("Unsupported flags in COPY operation (OID inclusion?)");
15  
16          _buf.ReadInt32();   // Header extensions, currently unused
17      }

 1      internal async Task Init(string copyToCommand, bool async, CancellationToken cancellationToken = default)
 2      {
 3          Debug.Assert(_activity is null);
 4          _activity = _connector.TraceCopyStart(copyToCommand, "COPY TO");
 5  
 6          try
 7          {
 8              await _connector.WriteQuery(copyToCommand, async, cancellationToken).ConfigureAwait(false);
 9              await _connector.Flush(async, cancellationToken).ConfigureAwait(false);
10  
11              using var registration = _connector.StartNestedCancellableOperation(cancellationToken, attemptPgCancellation: false);
12  
13              CopyOutResponseMessage copyOutResponse;
14              var msg = await _connector.ReadMessage(async).ConfigureAwait(false);
15              switch (msg.Code)
16              {
17              case BackendMessageCode.CopyOutResponse:
18                  copyOutResponse = (CopyOutResponseMessage)msg;
19                  if (!copyOutResponse.IsBinary)
20                  {
21                      throw _connector.Break(
22                          new ArgumentException("copyToCommand triggered a text transfer, only binary is allowed",
23                              nameof(copyToCommand)));
24                  }
25                  break;
26              case BackendMessageCode.CommandComplete:
27                  // The command completed without copying through the client (e.g. COPY to or from a file on the server).
28                  // Consume the ReadyForQuery that follows, so that the connection stays usable.
29                  Expect<ReadyForQueryMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
30                  throw new InvalidOperationException(
31                      "This API only supports import/export from the client, i.e. COPY commands containing TO/FROM STDIN. " +
32                      "To import/export with files on your PostgreSQL machine, simply execute the command with ExecuteNonQuery. " +
33                      "Note that your data has been successfully imported/exported.");
34              default:
35                  throw _connector.UnexpectedMessageReceived(msg.Code);
36              }
37  
38              _state = ExporterState.Ready;
39              NumColumns = copyOutResponse.NumColumns;
40              _conversionContextCache = new ReadConversionContext[NumColumns];
41              _rowsExported = 0;
42              _endOfMessagePos = _buf.CumulativeReadPosition;
43              await ReadHeader(async).ConfigureAwait(false);
44          }

