 1      public override int IndexOf(string parameterName)
 2      {
 3          if (parameterName is null)
 4              return -1;
 5  
 6          if (parameterName.Length > 0 && (parameterName[0] == ':' || parameterName[0] == '@'))
 7              parameterName = parameterName.Remove(0, 1);
 8  
 9          // Using a dictionary is always faster after around 10 items when matched against reference equality.
10          // For string equality this is the case after ~3 items so we take a decent compromise going with 5.
11          if (LookupEnabled && parameterName.Length != 0)
12          {
13              if (_caseInsensitiveLookup is null)
14                  BuildLookup();
15  
16              if (TwoPassCompatMode && _caseSensitiveLookup!.TryGetValue(parameterName, out var indexCs))
17                  return indexCs;
18  
19              if (_caseInsensitiveLookup!.TryGetValue(parameterName, out var indexCi))
20                  return indexCi;
21  
22              return -1;
23          }
24  
25          // Start with case-sensitive search in two pass mode.
26          if (TwoPassCompatMode)
27          {
28              for (var i = 0; i < InternalList.Count; i++)
29              {
30                  var name = InternalList[i].TrimmedName;
31                  if (string.Equals(parameterName, name))
32                      return i;
33              }
34          }
35  
36          // Then do case-insensitive search.
37          for (var i = 0; i < InternalList.Count; i++)
38          {
39              var name = InternalList[i].TrimmedName;
40              if (ReferenceEquals(parameterName, name) || string.Equals(parameterName, name, StringComparison.OrdinalIgnoreCase))
41                  return i;
42          }
43  
44          return -1;
45  
46          void BuildLookup()
47          {
48              if (TwoPassCompatMode)
49                  _caseSensitiveLookup = new Dictionary<string, int>(InternalList.Count);
50  
51              _caseInsensitiveLookup = new Dictionary<string, int>(InternalList.Count, StringComparer.OrdinalIgnoreCase);
52  
53              for (var i = 0; i < InternalList.Count; i++)
54              {
55                  var item = InternalList[i];
56                  if (!item.IsPositional)
57                      LookupAdd(item.TrimmedName, i);
58              }
59          }
60      }

