 1      internal IEnumerable<KeyValuePair<string, string?>> GetOptionPairs()
 2      {
 3          // PublicationNames can still be emptied after the constructor's check, and pgoutput would take an empty list as no
 4          // publication at all
 5          if (PublicationNames.Count == 0)
 6              throw new InvalidOperationException("PublicationNames must contain at least one publication name.");
 7  
 8          yield return new KeyValuePair<string, string?>("proto_version", ((ulong)ProtocolVersion).ToString(CultureInfo.InvariantCulture));
 9          yield return new KeyValuePair<string, string?>("publication_names", QuoteIdentifierList(PublicationNames));
10  
11          if (Binary != null)
12              yield return new KeyValuePair<string, string?>("binary", Binary.Value ? "on" : "off");
13          if (StreamingMode != null)
14          {
15              yield return new KeyValuePair<string, string?>("streaming", StreamingMode.Value switch
16              {
17                  PgOutputStreamingMode.Off => "off",
18                  PgOutputStreamingMode.On => "on",
19                  PgOutputStreamingMode.Parallel => "parallel",
20                  _ => throw new ArgumentOutOfRangeException($"Unknown {nameof(PgOutputStreamingMode)} value: {StreamingMode.Value}")
21              });
22          }
23          if (Messages != null)
24              yield return new KeyValuePair<string, string?>("messages", Messages.Value ? "on" : "off");
25          if (TwoPhase != null)
26              yield return new KeyValuePair<string, string?>("two_phase", TwoPhase.Value ? "on" : "off");
27      }

