 1      internal static string QuoteName(string name)
 2      {
 3          name = name.Trim(ScannerWhitespace);
 4  
 5          // Names that callers quoted themselves (the only way to use slot names starting with a digit as long as Npgsql
 6          // didn't quote them) keep working, since the server took them as they are. Quotes inside such a name have to be
 7          // doubled, so that it is a single quoted identifier.
 8          if (name.Length >= 2 && name[0] == '"' && name[^1] == '"' && QuotesAreDoubled(name.AsSpan(1, name.Length - 2)))
 9              return name;
10  
11          // The server lowercases non-ASCII letters too, but only in single-byte database encodings and as its locale says
12          // (downcase_identifier), so a name with them is sent unquoted if the server reads it as one identifier. Keywords are
13          // ASCII-only, so it can't be one.
14          if (IsIdentifierWithNonAsciiLetters(name))
15              return name;
16  
17          return QuoteIdentifier(FoldName(name));
18  
19          // The replication command scanner's identifier: [A-Za-z\200-\377_][A-Za-z\200-\377_0-9$]* (repl_scanner.l)
20          static bool IsIdentifierWithNonAsciiLetters(string name)
21          {
22              var nonAscii = false;
23              for (var i = 0; i < name.Length; i++)
24              {
25                  var c = name[i];
26                  if (c > '\x7f')
27                      nonAscii = true;
28                  else if (!(c is >= 'a' and <= 'z' or >= 'A' and <= 'Z' or '_' || i > 0 && c is >= '0' and <= '9' or '$'))
29                      return false;
30              }
31  
32              return nonAscii;
33          }
34  
35          static bool QuotesAreDoubled(ReadOnlySpan<char> s)
36          {
37              for (var i = 0; i < s.Length; i++)
38              {
39                  if (s[i] == '"' && (++i == s.Length || s[i] != '"'))
40                      return false;
41              }
42  
43              return true;
44          }
45  
46          static string FoldName(string name)
47          {
48              if (name.AsSpan().IndexOfAnyInRange('A', 'Z') < 0)
49                  return name;
50  
51              return string.Create(name.Length, name, static (span, name) =>
52              {
53                  for (var i = 0; i < span.Length; i++)
54                  {
55                      var c = name[i];
56                      span[i] = c is >= 'A' and <= 'Z' ? (char)(c + ('a' - 'A')) : c;
57                  }
58              });
59          }
60      }

