 2          PgSerializerOptions options, PgTypeId timestampTz, PgTypeId timestamp, bool dateTimeInfinityConversions)
 3          where T : IList<TElement> where TElement : notnull
 4      {
 5          if (typeof(TElement) != typeof(NpgsqlRange<DateTime>))
 6              ThrowHelper.ThrowNotSupportedException("Unsupported element type");
 7  
 8          return new DateTimeTypeInfoProvider<T>(options, static (provider, context, value, ref writeState) =>
 9          {
