11              if (value is null)
12                  return null;
13  
14              foreach (var element in (IList<NpgsqlRange<DateTime>>)value)
15              {
16                  PgConcreteTypeInfo? result;
17                  if (!element.LowerBoundInfinite)
18                  {
19                      result = provider.Get(context, element.LowerBound, validateOnly: concreteTypeInfo is not null);
20                      if (concreteTypeInfo is null && result is not null)
21                      {
22                          concreteTypeInfo = result;
23                          context = context with { ExpectedPgTypeId = concreteTypeInfo.PgTypeId };
24                      }
25                  }
26                  if (!element.UpperBoundInfinite)
27                  {
28                      result = provider.Get(context, element.UpperBound, validateOnly: concreteTypeInfo is not null);
29                      if (concreteTypeInfo is null && result is not null)
30                      {
31                          concreteTypeInfo = result;
32                          context = context with { ExpectedPgTypeId = concreteTypeInfo.PgTypeId };
33                      }
34                  }
35              }
36              return concreteTypeInfo;
37          }, pgTypeId =>
38          {
39              if (pgTypeId == timestampTz)
40                  return new MultirangeConverter<T, TElement>(
41                      (PgConverter<TElement>)(object)new RangeConverter<DateTime>(new DateTimeConverter(dateTimeInfinityConversions, DateTimeKind.Utc)));
42              if (pgTypeId == timestamp)
43                  return new MultirangeConverter<T, TElement>(
44                      (PgConverter<TElement>)(object)new RangeConverter<DateTime>(new DateTimeConverter(dateTimeInfinityConversions, DateTimeKind.Unspecified)));
45  
46              throw new NotSupportedException();
47          }, timestampTz, timestamp, dateTimeInfinityConversions);
48      }

