 1      public static IAsyncEnumerable<XLogDataMessage> StartLogicalReplication(
 2          this LogicalReplicationConnection connection,
 3          LogicalReplicationSlot slot,
 4          CancellationToken cancellationToken,
 5          NpgsqlLogSequenceNumber? walLocation = null,
 6          IEnumerable<KeyValuePair<string, string?>>? options = null,
 7          bool bypassingStream = false)
 8      {
 9          return StartLogicalReplicationInternal(connection, slot, cancellationToken, walLocation, options, bypassingStream);
10  
11          // Local method to avoid having to add the EnumeratorCancellation attribute to the public signature.
12          static async IAsyncEnumerable<XLogDataMessage> StartLogicalReplicationInternal(
13              LogicalReplicationConnection connection,
14              LogicalReplicationSlot slot,
15              [EnumeratorCancellation] CancellationToken cancellationToken,
16              NpgsqlLogSequenceNumber? walLocation,
17              IEnumerable<KeyValuePair<string, string?>>? options,
18              bool bypassingStream)
19          {
20              var builder = new StringBuilder("START_REPLICATION ")
21                  .Append("SLOT ").Append(QuoteName(slot.Name))
22                  .Append(" LOGICAL ")
23                  .Append(walLocation ?? slot.ConsistentPoint);
24  
25              var opts = new List<KeyValuePair<string, string?>>(options ?? Array.Empty<KeyValuePair<string, string?>>());
26              // The plugin name as the server reads it, so that every spelling of pgoutput gets the check below
27              var isPgOutput = string.Equals(
28                  QuoteName(slot.OutputPlugin), "\"pgoutput\"", StringComparison.OrdinalIgnoreCase);
29              if (opts.Count > 0)
30              {
31                  builder.Append(" (");
32                  var stringOptions = new string[opts.Count];
33                  for (var i = 0; i < opts.Count; i++)
34                  {
35                      var kv = opts[i];
36                      if (kv.Key is null)
37                          throw new ArgumentException("Option names can't be null.", nameof(options));
38  
39                      // pgoutput reads the values of these options without checking whether there is one (strVal(NULL)),
40                      // so sending one of them without a value crashes the walsender, which makes the postmaster terminate
41                      // all sessions.
42                      if (kv.Value is null && isPgOutput && kv.Key is "proto_version" or "publication_names")
43                          throw new ArgumentException($"The pgoutput option '{kv.Key}' requires a value.", nameof(options));
44  
45                      stringOptions[i] = QuoteIdentifier(kv.Key) +
46                                         (kv.Value is null ? "" : " " + QuoteLiteral(kv.Value, replicationParser: true));
47                  }
48                  builder.Append(string.Join(", ", stringOptions));
49                  builder.Append(')');
50              }
51  
52              var command = builder.ToString();
53  
54              LogMessages.StartingLogicalReplication(connection.ReplicationLogger, slot.Name, command, connection.Connector.Id);
55  
56              var enumerator = connection.StartReplicationInternalWrapper(command, bypassingStream, cancellationToken);
57              while (await enumerator.MoveNextAsync().ConfigureAwait(false))
58                  yield return enumerator.Current;
59          }
60      }

