 1      async ValueTask DisposeAsync(bool disposing, bool async)
 2      {
 3          if (_state == CopyStreamState.Disposed || !disposing)
 4              return;
 5  
 6          try
 7          {
 8              _connector.CurrentCopyOperation = null;
 9  
10              if (CanWrite)
11              {
12                  try
13                  {
14                      await FlushAsync(async).ConfigureAwait(false);
15                      _writeBuf.EndCopyMode();
16                      await _connector.WriteCopyDone(async).ConfigureAwait(false);
17                      await _connector.Flush(async).ConfigureAwait(false);
18                      Expect<CommandCompleteMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
19                      Expect<ReadyForQueryMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
20                      TraceStop();
21                  }
22                  catch (Exception e)
23                  {
24                      TraceSetException(e);
25                      throw;
26                  }
27              }
28              else
29              {
30                  try
31                  {
32                      if (_state != CopyStreamState.Consumed && _state != CopyStreamState.Uninitialized)
33                      {
