 1      async ValueTask<int> ReadCore(int count, bool async, CancellationToken cancellationToken = default)
 2      {
 3          if (_state == CopyStreamState.Consumed)
 4              return 0;
 5  
 6          using var registration = _connector.StartNestedCancellableOperation(cancellationToken, attemptPgCancellation: false);
 7  
 8          if (_leftToReadInDataMsg == 0)
 9          {
10              IBackendMessage msg;
11              try
12              {
13                  // We've consumed the current DataMessage (or haven't yet received the first),
14                  // read the next message
15                  msg = await _connector.ReadMessage(async).ConfigureAwait(false);
16              }
17              catch (Exception e)
18              {
19                  if (_state != CopyStreamState.Disposed)
20                  {
21                      TraceSetException(e);
22                      Cleanup();
23                  }
24                  throw;
25              }
26  
27              switch (msg.Code)
28              {
29              case BackendMessageCode.CopyData:
30                  _leftToReadInDataMsg = ((CopyDataMessage)msg).Length;
31                  break;
32              case BackendMessageCode.CopyDone:
33                  Expect<CommandCompleteMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
34                  Expect<ReadyForQueryMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
35                  _state = CopyStreamState.Consumed;
36                  return 0;
37              default:
38                  throw _connector.UnexpectedMessageReceived(msg.Code);
39              }
40          }
41  
42          Debug.Assert(_leftToReadInDataMsg > 0);
43  
44          // If our buffer is empty, read in more. Otherwise return whatever is there, even if the
45          // user asked for more (normal socket behavior)
46          if (_readBuf.ReadBytesLeft == 0)
47              await _readBuf.ReadMore(async).ConfigureAwait(false);
48  
49          Debug.Assert(_readBuf.ReadBytesLeft > 0);
50  
51          var maxCount = Math.Min(_readBuf.ReadBytesLeft, _leftToReadInDataMsg);
52          if (count > maxCount)
53              count = maxCount;
54  
55          _leftToReadInDataMsg -= count;
56          return count;
57      }

