 1      internal async Task Init(string copyCommand, bool async, bool? forExport, CancellationToken cancellationToken = default)
 2      {
 3          Debug.Assert(_activity is null);
 4          _activity = _connector.TraceCopyStart(copyCommand, forExport switch
 5          {
 6              true => "COPY TO",
 7              false => "COPY FROM",
 8              null => "COPY",
 9          });
10  
11          try
12          {
13              await _connector.WriteQuery(copyCommand, async, cancellationToken).ConfigureAwait(false);
14              await _connector.Flush(async, cancellationToken).ConfigureAwait(false);
15  
16              using var registration = _connector.StartNestedCancellableOperation(cancellationToken, attemptPgCancellation: false);
17  
18              var msg = await _connector.ReadMessage(async).ConfigureAwait(false);
19              switch (msg.Code)
20              {
21              case BackendMessageCode.CopyInResponse:
22                  _state = CopyStreamState.Ready;
23                  var copyInResponse = (CopyInResponseMessage)msg;
24                  IsBinary = copyInResponse.IsBinary;
25                  _canWrite = true;
26                  _writeBuf.StartCopyMode();
27                  TraceSetImport();
28                  break;
29              case BackendMessageCode.CopyOutResponse:
30                  _state = CopyStreamState.Ready;
31                  var copyOutResponse = (CopyOutResponseMessage)msg;
32                  IsBinary = copyOutResponse.IsBinary;
33                  _canRead = true;
34                  TraceSetExport();
35                  break;
36              case BackendMessageCode.CommandComplete:
37                  // The command completed without copying through the client (e.g. COPY to or from a file on the server).
38                  // Consume the ReadyForQuery that follows, so that the connection stays usable.
39                  Expect<ReadyForQueryMessage>(await _connector.ReadMessage(async).ConfigureAwait(false), _connector);
40                  throw new InvalidOperationException(
41                      "This API only supports import/export from the client, i.e. COPY commands containing TO/FROM STDIN. " +
42                      "To import/export with files on your PostgreSQL machine, simply execute the command with ExecuteNonQuery. " +
43                      "Note that your data has been successfully imported/exported.");
44              default:
45                  throw _connector.UnexpectedMessageReceived(msg.Code);
46              }
47          }

