 1          public IEnumerable<T> GenerateRange(T start, T end, Step step)
 2          {
 3              var startToEnd = Compare(start, end);
 4  
 5              if (startToEnd == 0)
 6              {
 7                  yield return start;
 8              }
 9              else if ((startToEnd < 0 && !step.IsPositive) || (startToEnd > 0 && !step.IsNegative))
10              {
11                  throw new ArgumentException("Step must be in the direction of the end.");
12              }
13              else
14              {
15                  for (var current = start; ;)
16                  {
17                      yield return current;
18  
19                      T next;
20                      try
21                      {
22                          next = step.Apply(current);
23                      }
24                      catch (OverflowException)
25                      {
26                          // We overflowed which means we tried to step past the end.
27                          break;
28                      }
29  
30                      if (startToEnd < 0)
31                      {
32                          if (Compare(next, end) > 0)
33                              break; // We stepped past the end of the range.
34  
35                          if (Compare(next, current) <= 0)
36                              throw new InvalidOperationException("The step must strictly increase.");
37                      }
38                      else
39                      {
40                          if (Compare(next, end) < 0)
41                              break; // We stepped past the end of the range.
42  
43                          if (Compare(next, current) >= 0)
44                              throw new InvalidOperationException("The step must strictly decrease.");
45                      }
46  
47                      current = next;
48                  }
49              }
50          }

