 1          public static EqualMethodResult Equal(object x, object y, ref Tolerance tolerance, ComparisonState state, NUnitEqualityComparer equalityComparer)
 2          {
 3              if (x is not IDictionary xDictionary || y is not IDictionary yDictionary)
 4                  return EqualMethodResult.TypesNotSupported;
 5  
 6              if (xDictionary.Count != yDictionary.Count)
 7                  return EqualMethodResult.ComparedNotEqual;
 8  
 9              var tally = new CollectionTally<object>(xDictionary.Keys, equalityComparer);
10              tally.TryRemove(yDictionary.Keys);
11              if ((tally.Result.MissingItems.Count > 0) || (tally.Result.ExtraItems.Count > 0))
12                  return EqualMethodResult.ComparedNotEqual;
13  
14              ComparisonState comparisonState = state.PushComparison(x, y);
15              foreach (object key in xDictionary.Keys)
16              {
17                  EqualMethodResult result = equalityComparer.AreEqual(xDictionary[key], yDictionary[key], ref tolerance, comparisonState);
18                  if (result != EqualMethodResult.ComparedEqual)
19                      return result;
20              }
21  
22              return EqualMethodResult.ComparedEqual;
23          }

