 1          private static void AdjustArgumentIfNeeded<T>(ref T arg)
 2          {
 3              if (arg is not null)
 4              {
 5                  Type argType = arg.GetType();
 6                  Type? genericTypeDefinition = argType.IsGenericType ? argType.GetGenericTypeDefinition() : null;
 7  
 8                  if (genericTypeDefinition == typeof(ArraySegment<>) &&
 9                      argType.GetProperty("Array")?.GetValue(arg, null) is null)
10                  {
11                      var elementType = argType.GetGenericArguments()[0];
12                      var array = Array.CreateInstance(elementType, 0);
13                      var ctor = argType.GetConstructor(new[] { array.GetType() })!;
14                      arg = (T)ctor.Invoke(new object[] { array });
15                  }
16              }
17          }

