 1          internal static WorkItem? CreateWorkItem(ITest test, ITestFilter filter, IDebugger debugger, bool recursive = false, bool root = true)
 2          {
 3              // Run filter on leaf nodes only
 4              // use the presence of leaf nodes as an indicator that parent need to be created
 5              // Always create a workitem for the root node
 6              if (test is not TestSuite suite)
 7              {
 8                  if (root || filter.Pass(test))
 9                  {
10                      return new SimpleWorkItem((TestMethod)test, filter, debugger);
11                  }
12                  return null;
13              }
14  
15              CompositeWorkItem? work = root ? new CompositeWorkItem(suite, filter) : null;
16  
17              if (recursive)
18              {
19                  var manager = TestDependencyManager.Create(suite);
20                  var testDependencies = manager?.PrepareTestDependencies(suite);
21                  var children = testDependencies is null ? suite.Tests : TopologicalSort(suite.Tests, testDependencies);
22                  HashSet<ITest>? dependencyClosure = testDependencies is null ? null : GetDependencyClosure(suite.Tests, testDependencies, filter);
23  
24                  int countOrderedItems = 0;
25  
26                  foreach (var childTest in children)
27                  {
28                      // Always include tests that are dependencies of other tests, even if they don't match the filter
29                      var matchesFilter = filter.Pass(childTest);
30                      var forceIncludeTest = !matchesFilter && dependencyClosure?.Contains(childTest) == true;
31                      var childFilter = forceIncludeTest ? TestFilter.Empty : filter;
32  
33                      var childItem = CreateWorkItem(childTest, childFilter, debugger, recursive, root: false);
34                      if (childItem is null)
35                          continue;
36  
37                      work ??= new CompositeWorkItem(suite, filter);
38  
39                      if (childItem.TargetApartment == ApartmentState.Unknown && work.TargetApartment != ApartmentState.Unknown)
40                          childItem.TargetApartment = work.TargetApartment;
41  
42                      if (childTest.Properties.ContainsKey(PropertyNames.Order))
43                      {
44                          work.Children.Insert(0, childItem);
45                          countOrderedItems++;
46                      }
47                      else
48                      {
49                          work.Children.Add(childItem);
50                      }
51                  }
52  
53                  if (countOrderedItems > 1)
54                      work!.Children.Sort(0, countOrderedItems, new WorkItemOrderComparer());
55              }
56  
57              return work;
58          }

