 1      private static string ExtractFramework(XDocument xml, XNamespace ns)
 2      {
 3          // Look for codeBase attribute in UnitTest elements which contains the assembly path
 4          var codeBases = xml.Descendants(ns + "UnitTest")
 5              .Select(ut => ut.Attribute("storage")?.Value)
 6              .Where(s => !string.IsNullOrEmpty(s))
 7              .Select(s => s!);
 8  
 9          foreach (var codeBase in codeBases)
10          {
11              var match = FrameworkPattern.Match(codeBase);
12              if (match.Success)
13              {
14                  return match.Groups[1].Value;
15              }
16          }
17  
18          // Also try TestMethod codeBase
19          var testMethods = xml.Descendants(ns + "TestMethod")
20              .Select(tm => tm.Attribute("codeBase").Value)
21              .Where(s => !string.IsNullOrEmpty(s))
22              .Select(s => s!);
23  
24          foreach (var codeBase in testMethods)
25          {
26              var match = FrameworkPattern.Match(codeBase);
27              if (match.Success)
28              {
29                  return match.Groups[1].Value;
30              }
31          }
32  
33          return "";
34      }

