 1      public static DetailedTestResultsSummary ParseTrxFilesDetailed(string resultsDirectory)
 2      {
 3          int totalTests = 0, totalPassed = 0, totalFailed = 0, totalSkipped = 0;
 4          var frameworkResults = new Dictionary<string, (int Total, int Passed, int Failed, int Skipped)>();
 5  
 6          var trxFiles = System.IO.Directory.GetFiles(resultsDirectory, "*.trx", System.IO.SearchOption.AllDirectories);
 7  
 8          foreach (var trxFile in trxFiles)
 9          {
10              var (total, passed, failed, skipped, framework) = ParseTrxFileWithFramework(trxFile);
