12              totalPassed += passed;
13              totalFailed += failed;
14              totalSkipped += skipped;
15  
16              if (!string.IsNullOrEmpty(framework))
17              {
18                  if (frameworkResults.TryGetValue(framework, out var existing))
19                  {
20                      frameworkResults[framework] = (
21                          existing.Total + total,
22                          existing.Passed + passed,
23                          existing.Failed + failed,
24                          existing.Skipped + skipped);
25                  }
26                  else
27                  {
28                      frameworkResults[framework] = (total, passed, failed, skipped);
29                  }
30              }
31          }
32  
33          var byFramework = frameworkResults
34              .OrderBy(kv => kv.Key)
35              .Select(kv => new FrameworkTestResult(kv.Key, kv.Value.Total, kv.Value.Passed, kv.Value.Failed, kv.Value.Skipped))
36              .ToList();
37  
38          return new DetailedTestResultsSummary(totalTests, totalPassed, totalFailed, totalSkipped, byFramework);
39      }

