 1          private static string GetNameFromExpression<TExpression>(Expression<Func<TExpression, object?>> expression)
 2          {
 3              Expression body = expression.Body;
 4  
 5              // We only expect a single member access, but it might include in implicit cast to object.
 6              if (body is UnaryExpression unaryExpresion &&
 7                  unaryExpresion.NodeType == ExpressionType.Convert &&
 8                  unaryExpresion.Type == typeof(object))
 9              {
10                  body = unaryExpresion.Operand;
11              }
12  
13              if (body is MemberExpression memberExpression)
14                  return memberExpression.Member.Name;
15  
16              throw new ArgumentException("Expression must be a member expression", nameof(expression));
17          }

