 1              public override bool TryCreateStep(object value, [NotNullWhen(true)] out ValueGenerator.Step? step)
 2              {
 3                  if (value is double dValue)
 4                  {
 5                      step = new ComparableStep<double>(dValue, (prev, stepValue) =>
 6                      {
 7                          var next = prev + stepValue;
 8                          if (stepValue > 0 ? next <= prev : prev <= next)
 9                              throw new ArithmeticException($"Not enough precision to represent the next step; {prev:r} + {stepValue:r} = {next:r}.");
10                          return next;
11                      });
12                      return true;
13                  }
14  
15                  return base.TryCreateStep(value, out step);
16              }

