 1          public T? Dequeue(bool blockWhenEmpty)
 2          {
 3              SpinWait sw = new SpinWait();
 4  
 5              do
 6              {
 7                  int cachedRemoveId = _removeId;
 8                  int cachedAddId = _addId;
 9  
10                  // Empty case
11                  if (cachedRemoveId == cachedAddId)
12                  {
13                      if (!blockWhenEmpty || _stopped != 0)
14                          return default(T);
15  
16                      // Spin a few times to see if something changes
17                      if (sw.Count <= SpinCount)
18                      {
19                          sw.SpinOnce();
20                      }
21                      else
22                      {
23                          // Reset to wait for an enqueue
24                          _mreAdd.Reset();
25  
26                          // Recheck for an enqueue to avoid a Wait
27                          if (cachedRemoveId != _removeId || cachedAddId != _addId)
28                          {
29                              // Queue is not empty, set the event
30                              _mreAdd.Set();
31                              continue;
32                          }
33  
34                          // Wait for something to happen
35                          _mreAdd.Wait(500);
36                      }
37  
38                      continue;
39                  }
40  
41                  // Validate that we are the current dequeuer
42                  if (Interlocked.CompareExchange(ref _removeId, cachedRemoveId + 1, cachedRemoveId) != cachedRemoveId)
43                      continue;
44  
45                  // Dequeue our work item
46                  T? e;
47                  while (!_queue.TryDequeue(out e))
48                  {
49                      if (!blockWhenEmpty || _stopped != 0)
50                          return default(T);
51                  }
52  
53                  return e;
54              }
55              while (true);
56          }

