 1              private static ResultState Worst(ResultState overall, ResultState iterationResult)
 2              {
 3                  // Unfortunately TestStatus is not ordered from good to bad, so we have to do this the hard way.
 4                  // Inconclusive means nothing happened, so if either is inconclusive, return the other.
 5                  // Anything is worse than passed, so if either is passed, return the other.
 6                  // Otherwise, return the one with the higher status value.
 7                  if (overall.Status is TestStatus.Inconclusive or TestStatus.Passed)
 8                      return iterationResult;
 9                  if (iterationResult.Status is TestStatus.Inconclusive or TestStatus.Passed)
10                      return overall;
11                  if (overall.Status > iterationResult.Status)
12                      return overall;
13                  return iterationResult;
14              }

