 1          public static string GetAssemblyPathFromCodeBase(string codeBase)
 2          {
 3              // Skip over the file:// part
 4              int start = UriSchemeFile.Length + SchemeDelimiter.Length;
 5  
 6              if (codeBase[start] == '/') // third slash means a local path
 7              {
 8                  // Handle Windows Drive specifications
 9                  if (codeBase[start + 2] == ':')
10                      ++start;
11                  // else leave the last slash so path is absolute
12              }
13              else // It's either a Windows Drive spec or a share
14              {
15                  if (codeBase[start + 1] != ':')
16                      start -= 2; // Back up to include two slashes
17              }
18  
19              return codeBase.Substring(start);
20          }

