 1  export function getValidatorMsg(
 2    msgArg: j.CallExpression['arguments'][number] | null
 3  ) {
 4    if (msgArg === null) {
 5      return null;
 6    }
 7    if (msgArg.type !== 'ObjectExpression') {
 8      return msgArg;
 9    }
10    const msgVals = msgArg.properties
11      .map((p) =>
12        p.type === 'ObjectProperty' &&
13        p.key.type === 'Identifier' &&
14        p.key.name === 'message'
15          ? p.value
16          : null
17      )
18      .filter((v) => v !== null);
19    const msgVal = msgVals.at(0);
20    return msgVal === undefined ||
21      msgVal.type === 'RestElement' ||
22      msgVal.type === 'SpreadElementPattern' ||
23      msgVal.type === 'PropertyPattern' ||
24      msgVal.type === 'ObjectPattern' ||
25      msgVal.type === 'ArrayPattern' ||
26      msgVal.type === 'AssignmentPattern' ||
27      msgVal.type === 'SpreadPropertyPattern' ||
28      msgVal.type === 'TSParameterProperty'
29      ? null
30      : msgVal;
31  }

