 1  function checkForObjectModifierInChain(
 2    cur: j.ASTPath<j.CallExpression>
 3  ): ObjectModifier {
 4    let parent = cur.parentPath;
 5    let latestModifier: ObjectModifier = null;
 6  
 7    while (parent) {
 8      if (
 9        parent.value.type === 'CallExpression' &&
10        parent.value.callee.type === 'MemberExpression' &&
11        parent.value.callee.property.type === 'Identifier'
12      ) {
13        const methodName = parent.value.callee.property.name;
14        if (methodName === 'strict' || methodName === 'passthrough' || methodName === 'strip') {
15          latestModifier = methodName;
16        }
17      }
18      if (
19        parent.value.type === 'MemberExpression' &&
20        parent.value.property.type === 'Identifier' &&
21        parent.parentPath?.value.type === 'CallExpression'
22      ) {
23        const methodName = parent.value.property.name;
24        if (methodName === 'strict' || methodName === 'passthrough' || methodName === 'strip') {
25          latestModifier = methodName;
26        }
27      }
28      parent = parent.parentPath;
29    }
30    return latestModifier;
31  }

