 1  export function _isPartiallyTyped(
 2    dataset: OutputDataset<unknown, BaseIssue<unknown>>,
 3    paths: Paths
 4  ): boolean {
 5    // If issues exist, check if a specified path matches path of a schema issue
 6    if (dataset.issues) {
 7      for (const path of paths) {
 8        for (const issue of dataset.issues) {
 9          // Hint: We also mark the data as untyped if there are validation
10          // issues, since the data could potentially be untyped if a pipeline
11          // contains a transformation action.
12  
13          // Create typed variable
14          let typed = false;
15  
16          // Calculate bound of match check
17          const bound = Math.min(path.length, issue.path?.length ?? 0);
18  
19          // Mark data as typed if any path items of same index do not match
20          for (let index = 0; index < bound; index++) {
21            if (
22              // @ts-expect-error
23              path[index] !== issue.path[index].key &&
24              // @ts-expect-error
25              (path[index] !== '$' || issue.path[index].type !== 'array')
26            ) {
27              typed = true;
28              break;
29            }
30          }
31  
32          // Return false if untyped
33          if (!typed) {
34            return false;
35          }
36        }
37      }
38    }
39  
40    // Return true if typed
41    return true;
42  }

