 1  export function _isLuhnAlgo(input: string): boolean {
 2    // Create necessary variables
 3    let index = input.length;
 4    let bit = 1;
 5    let sum = 0;
 6  
 7    // Calculate sum of algorithm
 8    while (index) {
 9      const charCode = input.charCodeAt(--index);
10      if (charCode >= 48 && charCode <= 57) {
11        const value = charCode - 48;
12        bit ^= 1;
13        sum += bit ? (value > 4 ? value * 2 - 9 : value * 2) : value;
14      }
15    }
16  
17    // Return whether its valid
18    return sum % 10 === 0;
19  }

