 1  export async function serveMarkdown(
 2    env: Env,
 3    request: Request,
 4    path: string
 5  ): Promise<Response | undefined> {
 6    // Always fetch the complete asset with GET and without a Range header, as
 7    // the full body is needed to compute our token count estimate
 8    const assetHeaders = new Headers(request.headers);
 9    assetHeaders.delete('Range');
10    const response = await env.ASSETS.fetch(new URL(path, request.url).href, {
11      headers: assetHeaders,
12      redirect: 'manual',
13    });
14  
15    // Pass revalidation responses through with our negotiation headers. This
16    // check must come first as 304 is also matched by the redirect range.
17    if (response.status === 304) {
18      return withHeaders(response, {
19        'Content-Location': path,
20        Vary: 'Accept',
21      });
22    }
23  
24    // Pass redirects (e.g. from our `_redirects` file) through to the client
25    // so that it can request the Markdown file at its new location. As the
26    // redirect target depends on the `Accept` header, caches must vary on it.
27    if (response.status >= 300 && response.status < 400) {
28      return withHeaders(response, { Vary: 'Accept' });
29    }
30  
31    if (response.ok) {
32      // Copy headers to keep validation and caching headers (e.g. ETag) and
33      // remove those that no longer apply to the new response body
34      const headers = new Headers(response.headers);
35      headers.delete('Content-Encoding');
36      headers.delete('Content-Length');
37      headers.set('Content-Type', 'text/markdown; charset=utf-8');
38      headers.set('Content-Location', path);
39      setHeader(headers, 'Vary', 'Accept');
40  
41      // Add rough estimate of the token count of the Markdown content
42      const markdown = await response.text();
43      headers.set('X-Markdown-Tokens', `${Math.ceil(markdown.length / 4)}`);
44  
45      // Return response without body for HEAD requests
46      if (request.method === 'HEAD') {
47        return new Response(null, { headers });
48      }
49      return new Response(markdown, { headers });
50    }
51  }

