 1  function getQuality(accept: string, mediaType: string): number {
 2    for (const part of accept.split(',')) {
 3      const [type, ...params] = part.trim().split(';');
 4      if (type.trim().toLowerCase() === mediaType) {
 5        for (const param of params) {
 6          const [key, value] = param.trim().split('=');
 7          if (key === 'q') {
 8            return parseFloat(value) || 0;
 9          }
10        }
11        return 1;
12      }
13    }
14    return 0;
15  }

