 1  function getActionCreatorObjects(
 2    state: unknown,
 3    actionCreators: ActionCreators<Record<string, unknown>>,
 4  ): ActionCreatorObject[] {
 5    const actions = new Map<string, ActionCreatorObject>()
 6  
 7    // Sort matchers by specificity
 8    const matchers = Object.entries(actionCreators)
 9      .map(([key, picked]) => ({
10        matcher: maskToRegex(key),
11        picked,
12        key,
13      }))
14      .sort((a, b) => {
15        const aIsDoubleWildcard = a.key.includes('**')
16        const bIsDoubleWildcard = b.key.includes('**')
17        if (aIsDoubleWildcard !== bIsDoubleWildcard) {
18          return aIsDoubleWildcard ? -1 : 1
19        }
20  
21        const aIsSingleWildcard = a.key.includes('*') && !aIsDoubleWildcard
22        const bIsSingleWildcard = b.key.includes('*') && !bIsDoubleWildcard
23        if (aIsSingleWildcard !== bIsSingleWildcard) {
24          return aIsSingleWildcard ? -1 : 1
25        }
26  
27        return a.key.length - b.key.length
28      })
29  
30    for (const [name, func] of getStateFunctions(state)) {
31      for (const { matcher, picked } of matchers) {
32        if (matcher.test(name)) {
33          if (picked === false) {
34            actions.delete(name)
35            continue
36          }
37  
38          actions.set(name, createActionCreatorObject(name, func))
39        }
40      }
41    }
42  
43    // Functions in the option replace the ones in the state or add new ones
44    for (const [name, picked] of Object.entries(actionCreators)) {
45      if (typeof picked === 'function') {
46        actions.set(name, createActionCreatorObject(name, picked))
47      }
48    }
49  
50    return Array.from(actions.values())
51  }

