 1  export function ssrSafe<
 2    T extends object,
 3    U extends object,
 4    Mps extends [StoreMutatorIdentifier, unknown][] = [],
 5    Mcs extends [StoreMutatorIdentifier, unknown][] = [],
 6  >(
 7    config: StateCreator<T, Mps, Mcs, U>,
 8    isSSR: boolean = typeof window === 'undefined',
 9  ): StateCreator<T, Mps, Mcs, U> {
10    return (set, get, api) => {
11      if (!isSSR) {
12        return config(set, get, api)
13      }
14      const ssrSet = () => {
15        throw new Error('Cannot set state of Zustand store in SSR')
16      }
17      api.setState = ssrSet
18      return config(ssrSet as never, get, api)
19    }
20  }

