 1  export function shallow<T>(valueA: T, valueB: T): boolean {
 2    if (Object.is(valueA, valueB)) {
 3      return true
 4    }
 5    if (
 6      typeof valueA !== 'object' ||
 7      valueA === null ||
 8      typeof valueB !== 'object' ||
 9      valueB === null
10    ) {
11      return false
12    }
13    if (Object.getPrototypeOf(valueA) !== Object.getPrototypeOf(valueB)) {
14      return false
15    }
16    if (isIterable(valueA) && isIterable(valueB)) {
17      if (hasIterableEntries(valueA) && hasIterableEntries(valueB)) {
18        return compareEntries(valueA, valueB)
19      }
20      return compareIterables(valueA, valueB)
21    }
22    // assume plain objects
23    return compareEntries(
24      { entries: () => Object.entries(valueA) },
25      { entries: () => Object.entries(valueB) },
26    )
27  }

