 1  export function createJSONStorage<S, R = unknown>(
 2    getStorage: () => StateStorage<R>,
 3    options?: JsonStorageOptions,
 4  ): PersistStorage<S, unknown> | undefined {
 5    let storage: StateStorage<R> | undefined
 6    try {
 7      storage = getStorage()
 8    } catch {
 9      // prevent error if the storage is not defined (e.g. when server side rendering a page)
10      return
11    }
12    const persistStorage: PersistStorage<S, R> = {
13      getItem: (name) => {
14        const parse = (str: string | null) => {
15          if (str === null) {
16            return null
17          }
18          return JSON.parse(str, options?.reviver) as StorageValue<S>
19        }
20        const str = storage.getItem(name) ?? null
21        if (isPromiseLike(str)) {
22          return str.then(parse)
23        }
24        return parse(str)
25      },
26      setItem: (name, newValue) =>
27        storage.setItem(name, JSON.stringify(newValue, options?.replacer)),
28      removeItem: (name) => storage.removeItem(name),
29    }
30    return persistStorage
31  }

