23        `Collection method contribution "${contribution.id}" returned no object of methods for model "${view.name}".`,
24        {
25          why: "A contribution returns an object holding a model's methods by name, empty when it gives the model none.",
26          fix: `Fix or remove the extension that contributes "${contribution.id}".`,
27          meta: { model: view.name, contribution: contribution.id },
28        },
29      );
30    }
31    for (const [name, body] of Object.entries(methods)) {
32      if (typeof body !== 'function') {
33        throw ormError(
34          'ORM.ARGUMENT_INVALID',
35          `Collection method "${name}" that contribution "${contribution.id}" gives model "${view.name}" is not a function.`,
36          {
