38            fix: `Fix or remove the extension that contributes "${contribution.id}".`,
39            meta: { model: view.name, method: name, contribution: contribution.id },
40          },
41        );
42      }
43    }
44    return blindCast<
45      Readonly<Record<string, CollectionMethodBody>>,
46      "each value was checked to be a function; its parameters are the type half's to declare"
47    >(methods);
48  }

