 1  function modelViews(context: ExecutionContext): Array<[string, CollectionMethodModel]> {
 2    const { contract } = context;
 3    const views: Array<[string, CollectionMethodModel]> = [];
 4    for (const [namespaceId, namespace] of Object.entries(contract.domain.namespaces)) {
 5      for (const [name, model] of Object.entries(namespace.models)) {
 6        const tableName = model.storage['table'];
 7        const resolved =
 8          typeof tableName === 'string'
 9            ? resolveTableForContract(contract, namespaceId, tableName)
10            : undefined;
11        if (resolved === undefined) {
12          throw new InternalError(
13            `Model "${name}" in namespace "${namespaceId}" has no storage table the contract declares.`,
14          );
15        }
16        views.push([
17          modelKey(namespaceId, name),
18          {
19            target: contract.target,
20            name,
21            fields: model.fields,
22            relations: model.relations,
23            table: resolved.table,
24          },
25        ]);
26      }
27    }
28    return views;
29  }

