 1  function inferredExtensionBlocks(
 2    tree: PostgresDatabaseSchemaNode,
 3    describedContracts: readonly SqlDescribedContractSpace[],
 4  ): ReadonlyMap<string, readonly PslExtensionBlock[]> {
 5    const packExtensions = new Set(
 6      describedContracts.flatMap(({ contract }) =>
 7        Object.values(contract.storage.namespaces).flatMap((namespace) =>
 8          Object.keys(namespace.entries['extension'] ?? {}),
 9        ),
10      ),
11    );
12    const blocksBySchema = new Map<string, PslExtensionBlock[]>();
13    for (const extension of tree.extensions) {
14      if (extension.name === ALWAYS_INSTALLED_EXTENSION || packExtensions.has(extension.name)) {
15        continue;
16      }
17      if (!isPslIdentifier(extension.name)) {
18        throw postgresError(
19          'CONTRACT.INFER_UNSUPPORTED',
20          `contract infer: extension "${extension.name}" is installed, and its name cannot be written as a PSL block name. Declare it in a TypeScript contract with extension("${extension.name}").`,
21          { meta: { extensionName: extension.name } },
22        );
23      }
24      invariant(
25        extension.location.kind === 'installed',
26        `contract infer reads extension "${extension.name}" from the database, so it has an installed schema`,
27      );
28      const { schemaName } = extension.location;
29      const blocks = blocksBySchema.get(schemaName) ?? [];
30      blocks.push(buildExtensionBlock(extension.name));
31      blocksBySchema.set(schemaName, blocks);
32    }
33    return blocksBySchema;
34  }

