 1  export function validateMysqlUrl(url: string): string {
 2    const trimmed = url.trim();
 3    if (trimmed.length === 0) {
 4      throw invalidUrl('MySQL URL must be a non-empty string', { reason: 'empty url' });
 5    }
 6    let parsed: URL;
