 1  function validatorDiagnostic(
 2    refusal: MongoContractRefusal,
 3    sites: SchemaSites,
 4  ): PslDiagnostic | ContractSourceDiagnostic {
 5    switch (refusal.kind) {
 6      case 'enumBsonType':
 7      case 'enumNotListable':
 8      case 'enumMemberNotListable': {
 9        const site = sites.enums.get(refusal.enumName);
10        if (site === undefined) throw new InternalError(`Enum "${refusal.enumName}" has a site.`);
11        const subject = `enum "${refusal.enumName}"`;
12        const base = { code: 'PSL_EXTENSION_INVALID_VALUE', sourceId: site.block.sourceId };
13        if (refusal.kind !== 'enumBsonType') {
14          return { ...base, message: `${subject} ${refusal.refusal.reason}`, span: site.codecSpan };
15        }
16        if (refusal.kind === 'enumNotListable') {
17          return {
18            ...base,
19            message: `${subject} @@type codec "${refusal.codecId}" ${refusal.reason}`,
20            span: site.codecSpan,
21          };
22        }
23        return {
24          ...base,
25          message: `${subject} member "${refusal.member}" ${refusal.reason}`,
26          span: site.block.memberSpans[refusal.member] ?? site.codecSpan,
27        };
28      }
29      case 'fieldBsonType':
30      case 'documentId': {
31        const owner = refusal.kind === 'fieldBsonType' ? refusal.owner.name : refusal.modelName;
32        const field = fieldSiteOf(sites, {
33          kind: 'field',
34          owner: { kind: 'model', name: owner },
35          field: refusal.fieldName,
36        });
37        return atField(
38          field,
39          refusal.kind === 'fieldBsonType' ? 'PSL_UNSUPPORTED_FIELD_TYPE' : 'PSL_MONGO_ID_INVALID',
40          `Field "${owner}.${field.symbol.name}" ${refusal.kind === 'fieldBsonType' ? refusal.refusal.reason : refusal.reason}`,
41        );
42      }
43      case 'embeddedModelHasVariants':
44        throw new InternalError('A PSL schema writes no embed relations.');
45    }
46  }

