 1  export function newVariantsOfBase(
 2    origin: ContractWithDomain,
 3    destination: ContractWithDomain,
 4    variant: ModelCoordinate,
 5    renamedTo: readonly ModelCoordinate[],
 6  ): readonly ModelCoordinate[] {
 7    const base = modelOf(origin, variant)?.base;
 8    if (base === undefined) return [];
 9    const baseCoordinate = { namespaceId: base.namespace, model: base.model };
10    const models = (contract: ContractWithDomain) =>
11      Object.values(modelOf(contract, baseCoordinate)?.variants ?? {}).map((each) => ({
12        namespaceId: each.namespace,
13        model: each.model,
14      }));
15    const before = models(origin);
16    const same =
17      (left: { readonly namespaceId: string; readonly model: string }) =>
18      (right: { readonly namespaceId: string; readonly model: string }) =>
19        left.namespaceId === right.namespaceId && left.model === right.model;
20    return models(destination)
21      .filter((each) => !before.some(same(each)) && !renamedTo.some(same(each)))
22      .map((each) => ({ ...each, namespaceId: asNamespaceId(each.namespaceId) }));
23  }

