 1  function detectIndent(text: string): number {
 2    // Look at the first indented line. A 2-space indent (the TS default)
 3    // is by far the most common; we fall back to 2 when nothing useful
 4    // is detectable (e.g. a single-line tsconfig).
 5    const match = text.match(/^([ \t]+)\S/m);
 6    if (match === null) {
 7      return 2;
 8    }
 9    const indent = match[1] ?? '';
10    if (indent.startsWith('\t')) {
11      return 1;
12    }
13    return indent.length || 2;
14  }

