 1  export function mergeTsConfig(existing: string): string {
 2    const { config } = parseTsConfigText(existing);
 3  
 4    // Match the indentation / line-ending style of the existing file so
 5    // the merged output diffs cleanly against it. `jsonc-parser` uses
 6    // these only when it has to insert a brand-new object node;
 7    // existing-key edits replace the value in place.
 8    const formattingOptions = {
 9      tabSize: detectIndent(existing),
10      insertSpaces: true,
11      eol: existing.includes('\r\n') ? '\r\n' : '\n',
12    };
13  
14    let result = existing;
15    for (const [key, value] of Object.entries(REQUIRED_COMPILER_OPTIONS)) {
16      const edits = modify(result, ['compilerOptions', key], value, { formattingOptions });
17      result = applyEdits(result, edits);
18    }
19  
20    const existingTypes = (config['compilerOptions'] as Record<string, unknown> | undefined)?.[
21      'types'
22    ];
23    const mergedTypes = mergeTypesArray(existingTypes);
24    const typesEdits = modify(result, ['compilerOptions', 'types'], mergedTypes, {
25      formattingOptions,
26    });
27    result = applyEdits(result, typesEdits);
28  
29    return result;
30  }

