 1  export function assertExecutionStackContractRequirements(
 2    contract: Contract<SqlStorage>,
 3    stack: SqlExecutionStack,
 4  ): void {
 5    const providedComponentIds = new Set<string>([
 6      stack.target.id,
 7      stack.adapter.id,
 8      ...stack.extensions.map((pack) => pack.id),
 9    ]);
10  
11    const result = checkContractComponentRequirements({
12      contract,
13      expectedTargetFamily: 'sql',
14      expectedTargetId: stack.target.targetId,
15      providedComponentIds,
16    });
17  
18    if (result.familyMismatch) {
19      throw runtimeError(
20        'RUNTIME.CONTRACT_FAMILY_MISMATCH',
21        `Contract target family '${result.familyMismatch.actual}' does not match runtime family '${result.familyMismatch.expected}'.`,
22        {
23          actual: result.familyMismatch.actual,
24          expected: result.familyMismatch.expected,
25        },
26      );
27    }
28  
29    if (result.targetMismatch) {
30      throw runtimeError(
31        'RUNTIME.CONTRACT_TARGET_MISMATCH',
32        `Contract target '${result.targetMismatch.actual}' does not match runtime target descriptor '${result.targetMismatch.expected}'.`,
33        {
34          actual: result.targetMismatch.actual,
35          expected: result.targetMismatch.expected,
36        },
37      );
38    }
39  
40    if (result.missingExtensionPackIds.length > 0) {
41      const packIds = result.missingExtensionPackIds;
42      const packList = packIds.map((id) => `'${id}'`).join(', ');
43      throw runtimeError(
44        'RUNTIME.MISSING_EXTENSION_PACK',
45        `Contract requires extension pack(s) ${packList}, but runtime descriptors do not provide matching component(s).`,
46        { packIds },
47      );
48    }
49  }

