 1  export function evaluateRawGuardrails(
 2    plan: RawGuardrailPlan,
 3    config?: RawGuardrailConfig,
 4  ): RawGuardrailResult {
 5    const lints: LintFinding[] = [];
 6    const budgets: BudgetFinding[] = [];
 7  
 8    const normalized = normalizeWhitespace(plan.sql);
 9    const statementType = classifyStatement(normalized);
10  
11    if (statementType === 'select') {
12      if (SELECT_STAR_REGEX.test(normalized)) {
13        lints.push(
14          createLint('LINT.SELECT_STAR', 'error', 'Raw SQL plan selects all columns via *', {
15            sql: snippet(plan.sql),
16          }),
17        );
18      }
19  
20      if (!LIMIT_REGEX.test(normalized)) {
21        const severity = config?.budgets?.unboundedSelectSeverity ?? 'error';
22        lints.push(
23          createLint('LINT.NO_LIMIT', 'warn', 'Raw SQL plan omits LIMIT clause', {
24            sql: snippet(plan.sql),
25          }),
26        );
27  
28        budgets.push(
29          createBudget(
30            'BUDGET.ROWS_EXCEEDED',
31            severity,
32            'Raw SQL plan is unbounded and may exceed row budget',
33            {
34              sql: snippet(plan.sql),
35              ...(config?.budgets?.estimatedRows !== undefined
36                ? { estimatedRows: config.budgets.estimatedRows }
37                : {}),
38            },
39          ),
40        );
41      }
42    }
43  
44    if (isMutationStatement(statementType) && isReadOnlyIntent(plan.meta)) {
45      lints.push(
46        createLint(
47          'LINT.READ_ONLY_MUTATION',
48          'error',
49          'Raw SQL plan mutates data despite read-only intent',
50          {
51            sql: snippet(plan.sql),
52            intent: plan.meta.annotations?.['intent'],
53          },
54        ),
55      );
56    }
57  
58    return { lints, budgets, statement: statementType };
59  }

