 1  export function createOperationRegistry<
 2    T extends OperationEntry = OperationEntry,
 3  >(): OperationRegistry<T> {
 4    const operations: Record<string, T> = Object.create(null);
 5  
 6    return {
 7      register(name: string, descriptor: OperationDescriptor<T>) {
 8        if (name in operations) {
 9          throw contractError(
10            'CONTRACT.PACK_CONTRIBUTION_INVALID',
11            `Operation "${name}" is already registered`,
12            { meta: { operation: name } },
13          );
14        }
15        if (descriptor.self) {
16          const hasCodecId = descriptor.self.codecId !== undefined;
17          const hasTraits = descriptor.self.traits !== undefined && descriptor.self.traits.length > 0;
18          const targetsMany = descriptor.self.many === true;
19          if (!hasCodecId && !hasTraits && !targetsMany) {
20            throw contractError(
21              'CONTRACT.PACK_CONTRIBUTION_INVALID',
22              `Operation "${name}" self has none of codecId, traits, or many`,
23              { meta: { operation: name } },
24            );
25          }
26          if (hasCodecId && hasTraits) {
27            throw contractError(
28              'CONTRACT.PACK_CONTRIBUTION_INVALID',
29              `Operation "${name}" self has both codecId and traits`,
30              { meta: { operation: name } },
31            );
32          }
33        }
34        operations[name] = descriptor;
35      },
36      entries() {
37        return Object.freeze({ ...operations });
38      },
39    };
40  }

