 1  export function castTypedValue(
 2    support: DataTypeSupport,
 3    receivingType: DataTypeId,
 4    receivingParams: DataTypeParams,
 5    value: DataTypeValue,
 6  ): Result<DataTypeValue, CastRefusal> {
 7    const refusedByType = (message: string): CastRefusal => ({
 8      kind: 'refused-by-type',
 9      receivingType,
10      message,
11    });
12    if (value.type === receivingType) {
13      return valueOfType(support, receivingType, () => value.value, receivingParams, refusedByType);
14    }
15    const declaration = support.lookup.get(receivingType);
16    const cast = declaration?.casts[value.type];
17    if (cast === undefined) {
18      return notOk({
19        kind: 'no-cast',
20        receivingType,
21        receivingParams,
22        valueType: value.type,
23        casts: Object.keys(declaration?.casts ?? {}),
24      });
25    }
26    const source = support.lookup.get(value.type);
27    if (source === undefined) {
28      throw new InternalError(
29        `A value of "${value.type}" was cast, and this stack does not register it.`,
30      );
31    }
32    let json: JsonValue;
33    try {
34      json = cast(source.toContract(value));
35    } catch (error) {
36      if (isInternalError(error)) throw error;
37      return notOk({ kind: 'unreadable', message: messageOf(error) });
38    }
39    return valueOfType(support, receivingType, () => json, receivingParams, refusedByType);
40  }

