 1  export function exactRewrite(
 2    support: DataTypeSupport,
 3    receiving: { readonly receivingType: DataTypeId; readonly receivingParams: DataTypeParams },
 4    written: WrittenScalar,
 5  ): string | undefined {
 6    if (written.kind !== 'string') return undefined;
 7    const castOf = (candidate: WrittenScalar): DataTypeValue | undefined => {
 8      const read = readWrittenValue(support, candidate);
 9      if (!read.ok) return undefined;
10      const cast = castTypedValue(
11        support,
12        receiving.receivingType,
13        receiving.receivingParams,
14        read.value,
15      );
16      return cast.ok ? cast.value : undefined;
17    };
18    const admits = (candidate: WrittenScalar): boolean => castOf(candidate) !== undefined;
19    const [tag] = admittedTags(support, receiving.receivingType);
20    if (
21      tag !== undefined &&
22      printedTaggedLiteralReadsBack(written.text) &&
23      admits({ kind: 'tag', tag, text: written.text })
24    ) {
25      return printTaggedLiteral(tag, written.text);
26    }
27    if (NUMBER_TEXT.test(written.text)) {
28      const stored = castOf({ kind: 'number', text: written.text });
29      if (stored !== undefined && sameNumber(written.text, stored.value)) return written.text;
30    }
31    if (
32      (written.text === 'true' || written.text === 'false') &&
33      admits({ kind: 'boolean', value: written.text === 'true' })
34    ) {
35      return written.text;
36    }
37    return undefined;
38  }

