 1  function verboseIntervalFields(text: string): PgInterval | undefined {
 2    if (!text.startsWith('@ ')) return undefined;
 3    const ago = text.endsWith(' ago');
 4    const body = text.slice(2, ago ? -4 : undefined);
 5    if (body === '0') return ZERO_INTERVAL;
 6    const words = body.split(' ');
 7    if (words.length === 0 || words.length % 2 !== 0) return undefined;
 8    let months = 0;
 9    let days = 0;
10    let micros = 0n;
11    for (let index = 0; index < words.length; index += 2) {
12      const match = VERBOSE_FIELD.exec(`${words[index]} ${words[index + 1]}`);
13      if (match === null) return undefined;
14      const [, sign = '', whole = '0', fraction, unit] = match;
15      if (fraction !== undefined && unit !== 'sec') return undefined;
16      const negative = sign === '-';
17      const count = signed(negative, Number(whole));
18      if (unit === 'year') months += count * 12;
19      else if (unit === 'mon') months += count;
20      else if (unit === 'day') days += count;
21      else if (unit === 'hour') micros += BigInt(count) * 3_600n * MICROS_PER_SECOND;
22      else if (unit === 'min') micros += BigInt(count) * 60n * MICROS_PER_SECOND;
23      else micros += timeMicros(negative, '0', '0', whole, fraction ?? '');
24    }
25    const fields = { months, days, micros };
26    return ago ? negated(fields) : fields;
27  }

