 1    async function updateWatchedFiles(viteServer: ViteDevServer): Promise<void> {
 2      const newWatchedFiles = await resolveWatchedFiles(viteServer);
 3  
 4      // Find files to add and remove
 5      const toAdd: string[] = [];
 6      const toRemove: string[] = [];
 7  
 8      for (const file of newWatchedFiles) {
 9        if (!watchedFiles.has(file)) {
10          toAdd.push(file);
11        }
12      }
13  
14      for (const file of watchedFiles) {
15        if (!newWatchedFiles.has(file)) {
16          toRemove.push(file);
17        }
18      }
19  
20      // Update the watcher
21      for (const file of toAdd) {
22        viteServer.watcher.add(file);
23      }
24      for (const file of toRemove) {
25        viteServer.watcher.unwatch(file);
26      }
27  
28      // Replace the watched files set
29      watchedFiles.clear();
30      for (const file of newWatchedFiles) {
31        watchedFiles.add(file);
32      }
33  
34      if (toAdd.length > 0 || toRemove.length > 0) {
35        log(`Updated watched files: +${toAdd.length} -${toRemove.length}`, 'debug');
36      }
37    }

