 1    async function collectModuleGraphFiles(
 2      viteServer: ViteDevServer,
 3      roots: readonly string[],
 4    ): Promise<Set<string>> {
 5      const files = new Set<string>();
 6      const uniqueRoots = [...new Set(roots)];
 7  
 8      for (const root of uniqueRoots) {
 9        try {
10          await viteServer.ssrLoadModule(root);
11        } catch (error) {
12          if (root === absoluteConfigPath) {
13            logError('Failed to load config module graph root:', error);
14          } else {
15            log(`Skipped module-graph root after load failure: ${root}`, 'debug');
16          }
17        }
18      }
19  
20      try {
21        const visited = new Set<string>();
22        const queue = [...uniqueRoots];
23  
24        while (queue.length > 0) {
25          const current = queue.shift();
26          if (current === undefined || visited.has(current)) continue;
27          visited.add(current);
28  
29          const mod = viteServer.moduleGraph.getModuleById(current);
30          if (!mod) continue;
31  
32          // Add file to watched set if it's a file path
33          if (mod.file) {
34            files.add(mod.file);
35          }
36  
37          // Add imported modules to queue
38          for (const imported of mod.importedModules) {
39            if (imported.id && !visited.has(imported.id)) {
40              queue.push(imported.id);
41            }
42          }
43        }
44      } catch (error) {
45        logError('Failed to collect watched files:', error);
46      }
47  
48      return files;
49    }

