 1  export function readExpressionAs(
 2    support: DataTypeSupport,
 3    dataType: DataTypeId,
 4    expression: ExpressionAst,
 5  ): Result<DataTypeValue, DataTypeValueRefusal> {
 6    if (!support.lookup.has(dataType)) {
 7      throw new InternalError(
 8        `An argument receives data type "${dataType}", which this stack does not register.`,
 9      );
10    }
11    const forms = admittedForms(support, [dataType]);
12    if (forms.length === 0) {
13      throw new InternalError(
14        `An argument receives data type "${dataType}", which nothing in this stack writes.`,
15      );
16    }
17  
18    const literal = readWrittenScalar(expression);
19    if (!literal.ok) {
20      return literal.reason === 'not-a-literal'
21        ? notOk({
22            code: 'PSL_INVALID_ATTRIBUTE_SYNTAX',
23            message: `${describeExpected(forms)}; got ${literal.found}`,
24          })
25        : notOk({
26            code: TAGGED_LITERAL_FAILURE_CODES[literal.reason],
27            message: describeTaggedLiteralFailure(literal.reason),
28          });
29    }
30  
31    return readWrittenValueAs(support, dataType, literal.written);
32  }

