 1  export function buildPostgresPlanDiff(input: {
 2    readonly contract: Contract<SqlStorage>;
 3    readonly actualSchema: SqlSchemaIRNode;
 4    readonly frameworkComponents: ReadonlyArray<TargetBoundComponentDescriptor<'sql', string>>;
 5    /**
 6     * The DDL schemas the plan's origin contract declares. Their live objects are this plan's too,
 7     * so a schema the destination no longer declares reaches the diff as extras to drop.
 8     */
 9    readonly originSchemas?: readonly string[];
10    /** The extensions the plan's origin contract declares: one the destination no longer declares is dropped. */
11    readonly originExtensions?: readonly string[];
12  }): PostgresPlanDiff {
13    const postgresContract = blindCast<
14      PostgresContract,
15      'buildPostgresPlanDiff is only called with a postgres contract'
16    >(input.contract);
17    PostgresDatabaseSchemaNode.assert(input.actualSchema);
18    const actual = input.actualSchema;
19    const types = sqlTypeLookupsOf(input.frameworkComponents);
20    const projectionOptions = {
21      annotationNamespace: 'pg',
22      dataTypeLookup: types.dataTypeLookup,
23      codecLookup: types.codecLookup,
24      resolveDefault: postgresResolveDefault,
25    };
26    const fullExpected = contractToPostgresDatabaseSchemaNode(postgresContract, projectionOptions);
27    const expected = pruneTableLessNamespaces(fullExpected);
28    const paddedActual = padActualNamespaces(expected, actual);
29    const originSchemas = input.originSchemas ?? [];
30    const originExtensions = new Set(input.originExtensions ?? []);
31    const relationalOwned = new Set([...ownedSchemaNames(expected), ...originSchemas]);
32    const structuralOwned = new Set([...ownedSchemaNames(fullExpected), ...originSchemas]);
33    const issues = blindCast<
34      readonly SchemaDiffIssue<SqlSchemaDiffNode>[],
35      'both trees are PostgresDatabaseSchemaNodes, so every diff-issue node is a SqlSchemaDiffNode'
36    >(diffSchemas(expected, paddedActual)).filter((issue) => {
37      const extensionName = undeclaredExtensionName(issue);
38      if (extensionName !== undefined) return originExtensions.has(extensionName);
39      if (issueOutcome(issue) !== 'not-expected') return true;
40      if (isClusterScopedIssue(issue)) return true;
41      const granularity = classifyDiffSubjectGranularity(issue, postgresDiffSubjectGranularity);
42      const namespaceSegment = issue.path[1];
43      if (namespaceSegment === undefined) return true;
44      const owned = granularity === 'structural' ? structuralOwned : relationalOwned;
45      return owned.has(namespaceSegment);
46    });
47    return { expected, actual: paddedActual, issues };
48  }

