19        ...(select.having === undefined ? [] : [select.having]),
20        ...(select.distinctOn ?? []),
21        ...(select.joins ?? []).flatMap((join) =>
22          join.on.kind === 'eq-col-join-on' ? [join.on.left, join.on.right] : [join.on],
23        ),
24      ],
