 6      return undefined;
 7    }
 8    const args: unknown[] = [];
 9    for (const [key, template] of Object.entries(descriptor.output.typeParams ?? {})) {
10      const value = output.typeParams?.[key];
11      if (value !== undefined && isAuthoringArgRef(template)) {
12        args[template.index] = value;
