14    }
15    const requiredArgs = (descriptor.args ?? []).filter((arg) => arg.optional !== true).length;
16    if (args.length < requiredArgs || Array.from(args).includes(undefined)) return undefined;
17    try {
18      return sameAuthoringTypeConstructorOutput(
19        instantiateAuthoringTypeConstructor(descriptor, args),
20        output,
21      )
22        ? args
23        : undefined;
24    } catch {
25      return undefined;
26    }
27  }

