 1  function resolveRequestedTarget(
 2    to: string | undefined,
 3    context: RefResolutionContext,
 4  ): Result<RequestedTarget, CliStructuredError> {
 5    if (to === undefined) {
 6      return ok(EMITTED_CONTRACT_TARGET);
 7    }
 8    const resolved = resolveContractRef(to, context);
 9    if (!resolved.ok) {
10      return notOk(normalizeError(resolved.failure));
11    }
12    if (resolved.value.provenance.kind === 'reserved-contract') {
13      return ok(EMITTED_CONTRACT_TARGET);
14    }
15    if (resolved.value.provenance.kind !== 'ref') {
16      return ok({ entry: { hash: resolved.value.hash, invariants: [] }, refName: undefined });
17    }
18    const refName = resolved.value.provenance.refName;
19    return ok({ entry: context.refs[refName], refName });
20  }

