 5          // out at emission, matching the reflection builder's "skip null parameter" behavior.
 6          if (type is INamedTypeSymbol { OriginalDefinition.SpecialType: SpecialType.System_Nullable_T, TypeArguments: [var underlying] })
 7          {
 8              type = underlying;
 9          }
10  
11          if (IsHttpContentType(type))
12          {
13              return MultipartPartKind.HttpContent;
14          }
15  
16          if (IsMultipartItemType(type))
17          {
18              return MultipartPartKind.MultipartItem;
19          }
20  
21          if (IsStreamType(type))
22          {
23              return MultipartPartKind.Stream;
24          }
25  
26          if (type.SpecialType == SpecialType.System_String)
27          {
28              return MultipartPartKind.String;
29          }
30  
31          if (IsFileInfoType(type))
32          {
33              return MultipartPartKind.FileInfo;
34          }
35  
36          if (IsByteArray(type))
37          {
38              return MultipartPartKind.ByteArray;
39          }
40  
41          if (IsMultipartFormattableType(type))
42          {
43              return MultipartPartKind.Formattable;
44          }
45  
46          // A declared class or struct (bool, enum, DTO) is written through the content serializer, as the reflection
47          // builder's serializer fallback does. An open, interface, or object-typed part stays on the reflection path
48          // (runtime type decides).
49          return QueryObjectPropertyParsing.IsConcreteComplexType(type) ? MultipartPartKind.Serialized : null;
50      }

