11          // A method named after a C# keyword (e.g. @class) must be emitted verbatim, otherwise the generated
12          // signature is invalid C#. Escape the name before any generic type-parameter list is appended.
13          declaredBaseName = EscapeIdentifier(declaredBaseName);
