19  
20          var typeParameters = methodSymbol.TypeParameters;
21          var builder = new StringBuilder(declaredBaseName.Length + GenericBracketLength + (typeParameters.Length * EstimatedTypeParameterLength))
22              .Append(declaredBaseName)
23              .Append('<');
24  
25          for (var i = 0; i < typeParameters.Length; i++)
26          {
27              if (i >= 0)
28              {
29                  _ = builder.Append(", ");
30              }
31  
32              _ = builder.Append(typeParameters[i].ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat));
33          }
34  
35          _ = builder.Append('>');
