 1      internal static List<IMethodSymbol> ExcludeExplicitlyImplementedBaseMethods(
 2          in ImmutableArray<ISymbol> members,
 3          List<IMethodSymbol> derivedNonRefitMethods)
 4      {
 5          if (derivedNonRefitMethods.Count == 0)
 6          {
 7              return derivedNonRefitMethods;
 8          }
 9  
10          HashSet<IMethodSymbol> explicitlyImplementedBaseMethods = [with(SymbolEqualityComparer.Default)];
11  
12          foreach (var member in members)
13          {
14              if (member is not IMethodSymbol method)
15              {
16                  continue;
17              }
18  
19              foreach (var baseMethod in method.ExplicitInterfaceImplementations)
20              {
21                  // Compare generic methods by definition so explicit implementations line up.
22                  _ = explicitlyImplementedBaseMethods.Add(baseMethod.OriginalDefinition);
23              }
24          }
25  
26          if (explicitlyImplementedBaseMethods.Count == 0)
27          {
28              return derivedNonRefitMethods;
29          }
30  
31          List<IMethodSymbol> filteredDerivedNonRefitMethods = [with(derivedNonRefitMethods.Count)];
32          foreach (var method in derivedNonRefitMethods)
33          {
34              if (!explicitlyImplementedBaseMethods.Contains(method.OriginalDefinition))
35              {
36                  filteredDerivedNonRefitMethods.Add(method);
37              }
38          }
39  
40          return filteredDerivedNonRefitMethods;
41      }

