 1      internal static bool CollectDerivedMembers(
 2          INamedTypeSymbol interfaceSymbol,
 3          in InterfaceGenerationContext context,
 4          List<IMethodSymbol> derivedRefitMethods,
 5          List<IMethodSymbol> derivedNonRefitMethods,
 6          List<IPropertySymbol> inheritedProperties)
 7      {
 8          // Walk all inherited interfaces (and each base's members) exactly once: pull out the IDisposable.Dispose
 9          // method, split the remaining methods into Refit and non-Refit sets, and collect inherited emittable
10          // properties in the same pass. Methods and properties were previously two separate AllInterfaces walks.
11          var disposableInterfaceSymbol = context.Symbols.DisposableInterfaceSymbol;
12          var hasDispose = false;
13  
14          // Most interfaces inherit no emittable properties (and the common no-base interface inherits nothing at all),
15          // so the de-duplicating set is created only once one is found rather than on every interface.
16          HashSet<IPropertySymbol>? seenInheritedProperties = null;
17          foreach (var baseInterface in interfaceSymbol.AllInterfaces)
18          {
19              foreach (var member in baseInterface.GetMembers())
20              {
21                  switch (member)
22                  {
23                      case IMethodSymbol method when IsDisposeMethod(method, disposableInterfaceSymbol):
24                          {
25                              hasDispose = true;
26                              break;
27                          }
28  
29                      case IMethodSymbol method when IsRefitMethod(method, context.Symbols.HttpMethodBaseAttributeSymbol):
30                          {
31                              derivedRefitMethods.Add(method);
32                              break;
33                          }
34  
35                      case IMethodSymbol method:
36                          {
37                              // Each inherited interface contributes its own members once across AllInterfaces, so a method
38                              // symbol never repeats here and no per-method de-duplication is needed.
39                              derivedNonRefitMethods.Add(method);
40                              break;
41                          }
42  
43                      case IPropertySymbol property
44                          when InterfaceMemberParsing.IsEmittableProperty(property)
45                               && (seenInheritedProperties ??= [with(comparer: SymbolEqualityComparer.Default)]).Add(property):
46                          {
47                              inheritedProperties.Add(property);
48                              break;
49                          }
50                  }
51              }
52          }
53  
54          return hasDispose;
55      }

