 1      internal static List<IMethodSymbol> CollectDirectNonRefitMethods(
 2          in ImmutableArray<ISymbol> members,
 3          List<IMethodSymbol> refitMethods)
 4      {
 5          // Get any other (non-Refit) methods declared directly on the interface. LINQ is avoided throughout because
 6          // it runs for every interface on every generator pass. An interface declares a handful of methods, so the two
 7          // membership checks are linear scans over the small method lists instead of two throwaway per-interface
 8          // HashSets (each with its own bucket array), while keeping the de-duplicating semantics of the previous
 9          // Except/Distinct: a member is kept only when it is not a Refit method and not already collected.
10          List<IMethodSymbol> nonRefitMethods = [with(members.Length)];
11          foreach (var member in members)
12          {
13              if (
14                  member is IMethodSymbol method
15                  && !ContainsSymbol(
16                      refitMethods,
17                      method)
18                  && !ContainsSymbol(
19                      nonRefitMethods,
20                      method)
21              )
22              {
23                  nonRefitMethods.Add(method);
24              }
25          }
26  
27          return nonRefitMethods;
28      }

