 1      internal static InterfaceNames ComputeInterfaceNames(
 2          INamedTypeSymbol interfaceSymbol)
 3      {
 4          // Start with the interface display name including type parameters, then strip the namespace.
 5          var className = interfaceSymbol.ToDisplayString();
 6          var lastDot = className.LastIndexOf('.');
 7          if (lastDot > 0)
 8          {
 9              className = className[(lastDot + 1)..];
10          }
11  
12          var classDeclaration = (interfaceSymbol.ContainingType?.Name) + className;
13  
14          // Use the simple interface name for the generated class suffix.
15          var classSuffix = (interfaceSymbol.ContainingType?.Name) + interfaceSymbol.Name;
16          var ns = interfaceSymbol.ContainingNamespace.ToDisplayString();
17  
18          // Keep generated names stable for interfaces declared in the global namespace.
19          if (interfaceSymbol.ContainingNamespace.IsGlobalNamespace)
20          {
21              ns = string.Empty;
22          }
23  
24          // Flatten dots out of the namespace for generated identifiers.
25          ns = ns.Replace(".", string.Empty);
26          var interfaceDisplayName = interfaceSymbol.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
27  
28          return new(className, classDeclaration, classSuffix, ns, interfaceDisplayName);
29      }

