 2          IDictionary dictionary,
 3          string? delimiter = null,
 4          CollectionFormat? collectionFormat = null)
 5      {
 6          List<QueryMapEntry> kvps = [];
 7  
 8          foreach (var key in dictionary.Keys)
 9          {
10              var obj = dictionary[key];
11              if (obj is null)
12              {
13                  continue;
14              }
15  
16              var keyType = key.GetType();
17              var formattedKey = GeneratedRequestRunner.FormatUrlParameter(_settings, key, GetCachedAttributeProvider(keyType), keyType);
18  
19              if (string.IsNullOrWhiteSpace(formattedKey)) // blank keys can't be put in the query string
20              {
21                  continue;
22              }
23  
24              if (DoNotConvertToQueryMap(obj))
25              {
26                  kvps.Add(new(formattedKey!, obj));
27              }
28              else
29              {
30                  var nestedQueryMap = BuildQueryMap(obj, delimiter, null, collectionFormat);
31                  for (var i = 0; i < nestedQueryMap.Count; i++)
32                  {
33                      var keyValuePair = nestedQueryMap[i];
34                      kvps.Add(
35                          new(
36                              formattedKey + delimiter + keyValuePair.Key,
37                              keyValuePair.Value));
38                  }
39              }
40          }
41  
42          return kvps;
43      }

