27              }
28  
29              position = segmentEnd + 1;
30          }
31  
32          if (parsed is null)
33          {
34              return;
35          }
36  
37          queryParamsToAdd ??= [];
38          for (var i = 0; i < parsed.Count; i++)
39          {
