 8          var error = TryResolveMemberPath(pageType, next, out var access, out var nextType);
 9          if (error is not null)
10          {
11              return error;
12          }
13  
14          if (!CanBeNull(nextType))
15          {
16              return $"'{next}' must be nullable so that the last page can end the sequence.";
17          }
18  
19          if (!SymbolEqualityComparer.Default.Equals(UnwrapNullable(nextType), UnwrapNullable(tokenParameter.Type)))
20          {
21              return $"'{next}' is a '{nextType.ToDisplayString()}', but the [PageToken] parameter is a '{tokenParameter.Type.ToDisplayString()}'.";
22          }
23  
24          var isNullableValue = nextType.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T
25                                && tokenParameter.Type.OriginalDefinition.SpecialType != SpecialType.System_Nullable_T;
26          var source = isNullableValue ? PagingNextSource.NullableProperty : PagingNextSource.Property;
27          continuation = new(source, access, false, PagingOrigin.None, []);
28          return null;
29      }

