 1      internal static string? TryResolveMemberPath(
 2          ITypeSymbol root,
 3          string path,
 4          out string access,
 5          out ITypeSymbol memberType)
 6      {
 7          var builder = new StringBuilder();
 8          var current = root;
 9          var isFirst = true;
10          foreach (var segment in path.Split('.'))
11          {
12              var name = segment.Trim();
13              var member = FindReadableMember(current, name);
14              if (member is null)
15              {
16                  access = string.Empty;
17                  memberType = root;
18                  return $"'{name}' is not a readable public or internal property or field of '{current.ToDisplayString()}'.";
19              }
20  
21              // Members reached through a reference or a nullable value are read with ?. so an absent parent yields null.
22              _ = builder.Append(!isFirst && CanBeNull(current) ? "?." : ".").Append('@').Append(member.Name);
23              current = GetMemberType(member);
24              isFirst = false;
25          }
26  
27          access = builder.ToString();
28          memberType = current;
29          return null;
30      }

