 1      internal static string? InferItems(
 2          ITypeSymbol pageType,
 3          ITypeSymbol itemType,
 4          out string? access)
 5      {
 6          access = null;
 7          var holder = pageType;
 8          var prefix = string.Empty;
 9          if (pageType is INamedTypeSymbol { TypeArguments.Length: 1 } response && RequestParsing.IsApiResponseType(response))
10          {
11              holder = response.TypeArguments[0];
12              prefix = ".@Content";
13  
14              // A response whose content is itself the list of items, such as a bare JSON array, is read through Content.
15              if (IsSequenceOf(holder, itemType))
16              {
17                  access = prefix;
18                  return null;
19              }
20          }
21  
22          ISymbol? found = null;
23          foreach (var member in EnumerateReadableMembers(holder))
24          {
25              if (!IsSequenceOf(GetMemberType(member), itemType))
26              {
27                  continue;
28              }
29  
30              if (found is not null)
31              {
32                  return $"'{holder.ToDisplayString()}' has more than one member that is a sequence of '{itemType.ToDisplayString()}'; name the one to read with Items.";
33              }
34  
35              found = member;
36          }
37  
38          if (found is null)
39          {
40              return $"'{holder.ToDisplayString()}' has no member that is a sequence of '{itemType.ToDisplayString()}'; name the member with Items.";
41          }
42  
43          access = $"{prefix}{(prefix.Length > 0 ? "?." : ".")}@{found.Name}";
44          return null;
45      }

