 1      internal void AppendDynamicRouteFragment(
 2          ref ValueStringBuilder vsb,
 3          RestMethodInfoInternal restMethod,
 4          object[] paramList,
 5          ParameterFragment fragment,
 6          RestMethodParameterInfo parameterMapValue)
 7      {
 8          var param = paramList[fragment.ArgumentIndex];
 9          var parameterInfo = restMethod.ParameterInfoArray[fragment.ArgumentIndex];
10  
11          if (parameterMapValue.Type == ParameterType.Normal)
12          {
13              AppendNormalRouteFragment(ref vsb, param, parameterInfo, fragment.IsOptional);
14              return;
15          }
16  
17          // If round tripping, split the value's string form on '/' (ToString for a non-string, so any type is
18          // supported) and format+escape each segment independently, preserving the separators.
19          Debug.Assert(parameterMapValue.Type == ParameterType.RoundTripping, "Dynamic route fragments must be Normal or RoundTripping.");
20          var paramValue = RoundTripStringValue(param);
21  
22          if (paramValue is null)
23          {
24              vsb.Append(
25                  StringHelpers.EscapeDataString(
26                      GeneratedRequestRunner.FormatUrlParameter(
27                          _settings,
28                          paramValue,
29                          GetCachedAttributeProvider(parameterInfo),
30                          parameterInfo.ParameterType) ?? string.Empty));
31              return;
32          }
33  
34          var sectionStart = 0;
35          for (var i = 0; i <= paramValue.Length; i++)
36          {
37              if (i != paramValue.Length && paramValue[i] != '/')
38              {
39                  continue;
40              }
41  
42              if (sectionStart > 0)
43              {
44                  vsb.Append('/');
45              }
46  
47              var section = paramValue.Substring(sectionStart, i - sectionStart);
48              vsb.Append(
49                  StringHelpers.EscapeDataString(
50                      GeneratedRequestRunner.FormatUrlParameter(
51                          _settings,
52                          section,
53                          GetCachedAttributeProvider(parameterInfo),
54                          parameterInfo.ParameterType) ?? string.Empty));
55              sectionStart = i + 1;
56          }
57      }

