30          _ = builder.Services.AddKeyedTransient(
31              serviceKey,
32              (s, _) =>
33              {
34                  var httpClientFactory = s.GetRequiredService<IHttpClientFactory>();
35                  var httpClient = httpClientFactory.CreateClient(builder.Name);
36                  return RestService.ForGenerated<T>(
37                      httpClient,
38                      s.GetRequiredKeyedService<SettingsFor<T>>(serviceKey).Settings ?? new RefitSettings());
39              });
40  
41          return builder;
42      }

