 1      internal static string ConstantValueToString(
 2          TypedConstant argument,
 3          in InterfaceGenerationContext context)
 4      {
 5          var result = string.Empty;
 6  
 7          if (!argument.IsNull)
 8          {
 9              // A non-null attribute argument is always one of Enum, Type, Array or Primitive; the primitive rendering
10              // doubles as the fallback so no unreachable throwing arm is needed.
11              result = argument.Kind switch
12              {
13                  TypedConstantKind.Enum => $"({AssemblyAliasQualification.QualifyType(argument.Type!, context)}){argument.Value!}",
14                  TypedConstantKind.Type => $"typeof({AssemblyAliasQualification.QualifyType((ITypeSymbol)argument.Value!, context)})",
15                  TypedConstantKind.Array => RenderConstantArray(argument, context),
16                  _ => SymbolDisplay.FormatPrimitive(argument.Value!, true, false)!
17              };
18          }
19  
20          return result is { Length: > 0 } ? result : "null";
21      }

