 1      internal static ParameterAttributeModel[] BuildParameterAttributes(
 2          IParameterSymbol parameter,
 3          in InterfaceGenerationContext context)
 4      {
 5          var attributes = parameter.GetAttributes();
 6          if (attributes.IsEmpty)
 7          {
 8              return [];
 9          }
10  
11          // Every attribute yields a model and every argument yields an entry (nothing is filtered), so the counts are
12          // known up front. Fill exact-sized arrays and wrap them without a copy instead of growing lists and copying
13          // each into fresh backing storage, which allocated a list object plus a duplicate array per collection.
14          var models = new ParameterAttributeModel[attributes.Length];
15          for (var a = 0; a < attributes.Length; a++)
16          {
17              var attribute = attributes[a];
18              models[a] = new(
19                  AssemblyAliasQualification.QualifyType(attribute.AttributeClass!, context),
20                  BuildConstructorArgumentExpressions(attribute.ConstructorArguments, context),
21                  BuildNamedArgumentExpressions(attribute.NamedArguments, context));
22          }
23  
24          return models;
25      }

