 1      internal static void ClassifySequenceInterface(
 2          ITypeSymbol candidate,
 3          ref ITypeSymbol? asyncElement,
 4          ref int asyncCount,
 5          ref ITypeSymbol? syncElement,
 6          ref int syncCount,
 7          ref bool implementsEnumerable)
 8      {
 9          if (candidate.SpecialType == SpecialType.System_Collections_IEnumerable)
10          {
11              implementsEnumerable = true;
12              return;
13          }
14  
15          if (candidate is not INamedTypeSymbol { IsGenericType: true, TypeArguments: [var element] } named)
16          {
17              return;
18          }
19  
20          if (named.OriginalDefinition.SpecialType == SpecialType.System_Collections_Generic_IEnumerable_T)
21          {
22              syncElement = element;
23              syncCount++;
24          }
25          else if (named is { Name: "IAsyncEnumerable", TypeKind: TypeKind.Interface }
26                   && RequestParameterParsingHelpers.IsInNamespace(named, "System.Collections.Generic"))
27          {
28              asyncElement = element;
29              asyncCount++;
30          }
31      }

