 1      internal static ITypeSymbol? FindJsonLinesElementType(
 2          ITypeSymbol type,
 3          out bool isAsync)
 4      {
 5          isAsync = false;
 6          if (type.SpecialType == SpecialType.System_String
 7              || type is ITypeParameterSymbol
 8              || type.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T)
 9          {
10              return null;
11          }
12  
13          ITypeSymbol? asyncElement = null;
14          ITypeSymbol? syncElement = null;
15          var syncCount = 0;
16          var asyncCount = 0;
17          var implementsEnumerable = type.SpecialType == SpecialType.System_Collections_IEnumerable;
18          ClassifySequenceInterface(type, ref asyncElement, ref asyncCount, ref syncElement, ref syncCount, ref implementsEnumerable);
19          foreach (var implemented in type.AllInterfaces)
20          {
21              ClassifySequenceInterface(implemented, ref asyncElement, ref asyncCount, ref syncElement, ref syncCount, ref implementsEnumerable);
22          }
23  
24          if (asyncCount == 1 && !implementsEnumerable)
25          {
26              isAsync = true;
27              return asyncElement;
28          }
29  
30          return syncCount == 1 && syncElement is { IsValueType: true } or { IsSealed: true, TypeKind: not TypeKind.TypeParameter }
31              ? syncElement
32              : null;
33      }

