 2      {
 3          var document = JsonDocument.Parse(json);
 4          var colors = new List<ColorModel>();
 5          var nameCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
 6  
 7          foreach (var element in document.RootElement.EnumerateArray())
 8          {
 9              var number = element.GetProperty("number").GetInt32();
10              var name = element.GetProperty("name").GetString()
11                  ?? throw new InvalidOperationException($"Color {number} has null name");
12              var rgb = element.GetProperty("rgb");
13              var r = (byte)rgb.GetProperty("r").GetInt32();
14              var g = (byte)rgb.GetProperty("g").GetInt32();
15              var b = (byte)rgb.GetProperty("b").GetInt32();
16  
17              // Track name occurrences for deduplication
18              var uniqueName = GetUniqueName(name, nameCounts);
19              colors.Add(new ColorModel(number, uniqueName, r, g, b, IsAlias: false));
20  
21              // Process aliases
22              if (element.TryGetProperty("aliases", out var aliases))
23              {
24                  foreach (var alias in aliases.EnumerateArray())
25                  {
26                      var aliasName = alias.GetString()
27                          ?? throw new InvalidOperationException($"Color {number} has null alias");
28                      var uniqueAliasName = GetUniqueName(aliasName, nameCounts);
29                      colors.Add(new ColorModel(number, uniqueAliasName, r, g, b, IsAlias: true));
30                  }
31              }
32          }
33  
34          return new EquatableArray<ColorModel>(colors);
35      }

