 1      private static void ProcessGenericType(StringBuilder builder, Type type, Type[] genericArguments, int length,
 2          DisplayNameOptions options)
 3      {
 4          var offset = 0;
 5          if (type.IsNested && type.DeclaringType is not null)
 6          {
 7              offset = type.DeclaringType.GetGenericArguments().Length;
 8          }
 9  
10          if (options.FullName)
11          {
12              if (type.IsNested && type.DeclaringType is not null)
13              {
14                  ProcessGenericType(builder, type.DeclaringType, genericArguments, offset, options);
15                  builder.Append('+');
16              }
17              else if (!string.IsNullOrEmpty(type.Namespace))
18              {
19                  builder.Append(type.Namespace);
20                  builder.Append('.');
21              }
22          }
23  
24          var genericPartIndex = type.Name.IndexOf('`');
25          if (genericPartIndex <= 0)
26          {
27              builder.Append(type.Name);
28              return;
29          }
30  
31          if (type.Assembly.GetName().Name == "FSharp.Core.dll"
32              && FSharpTypeNames.TryGetValue(type.Name, out var builtInName))
33          {
34              builder.Append(builtInName);
35          }
36          else
37          {
38              builder.Append(type.Name, 0, genericPartIndex);
39          }
40  
41          builder.Append('<');
42          for (var i = offset; i < length; i++)
43          {
44              ProcessType(builder, genericArguments[i], options);
45              if (i + 1 == length)
46              {
47                  continue;
48              }
49  
50              builder.Append(',');
51              if (options.IncludeGenericParameterNames || !genericArguments[i + 1].IsGenericParameter)
52              {
53                  builder.Append(' ');
54              }
55          }
56  
57          builder.Append('>');
58      }

