 1      private static Color Closest(ColorSystem system, Color color)
 2      {
 3          if (system == ColorSystem.TrueColor)
 4          {
 5              return color;
 6          }
 7  
 8          var palette = system switch
 9          {
10              ColorSystem.Legacy => Legacy,
11              ColorSystem.Standard => Standard,
12              ColorSystem.EightBit => EightBit,
13              _ => throw new NotSupportedException(),
14          };
15  
16          // https://stackoverflow.com/a/9085524
17          static double Distance(Color first, Color second)
18          {
19              var rmean = ((float)first.R + second.R) / 2;
20              var r = first.R - second.R;
21              var g = first.G - second.G;
22              var b = first.B - second.B;
23              return Math.Sqrt(
24                  ((int)((512 + rmean) * r * r) >> 8)
25                  + (4 * g * g)
26                  + ((int)((767 - rmean) * b * b) >> 8));
27          }
28  
29          return Enumerable.Range(0, int.MaxValue)
30              .Zip(palette, (id, other) => (Distance: Distance(other, color), Id: id, Color: other))
31              .OrderBy(x => x.Distance)
32              .FirstOrDefault().Color;
33      }

