 1      public static void AlignHorizontally<T>(T segments, HorizontalAlignment alignment, int maxWidth)
 2          where T : List<Segment>
 3      {
 4          var width = Segment.CellCount(segments);
 5          if (width >= maxWidth)
 6          {
 7              return;
 8          }
 9  
10          switch (alignment)
11          {
12              case HorizontalAlignment.Left:
13                  {
14                      var diff = maxWidth - width;
15                      segments.Add(Segment.Padding(diff));
16                      break;
17                  }
18  
19              case HorizontalAlignment.Right:
20                  {
21                      var diff = maxWidth - width;
22                      segments.Insert(0, Segment.Padding(diff));
23                      break;
24                  }
25  
26              case HorizontalAlignment.Center:
27                  {
28                      // Left side.
29                      var diff = (maxWidth - width) / 2;
30                      segments.Insert(0, Segment.Padding(diff));
31  
32                      // Right side
33                      segments.Add(Segment.Padding(diff));
34                      var remainder = (maxWidth - width) % 2;
35                      if (remainder != 0)
36                      {
37                          segments.Add(Segment.Padding(remainder));
38                      }
39  
40                      break;
41                  }
42  
43              default:
44                  throw new NotSupportedException("Unknown alignment");
45          }
46      }

