 1      private static List<int> CollapseWidths(List<int> widths, List<bool> wrappable, int maxWidth)
 2      {
 3          var totalWidth = widths.Sum();
 4          var excessWidth = totalWidth - maxWidth;
 5  
 6          if (wrappable.AnyTrue())
 7          {
 8              while (totalWidth != 0 && excessWidth > 0)
 9              {
10                  var maxColumn = widths.Zip(wrappable, (first, second) => (width: first, allowWrap: second))
11                      .Where(x => x.allowWrap)
12                      .Max(x => x.width);
13  
14                  var secondMaxColumn = widths.Zip(wrappable, (width, allowWrap) => allowWrap && width != maxColumn ? width : 0).Max();
15                  var columnDifference = maxColumn - secondMaxColumn;
16  
17                  var ratios = widths.Zip(wrappable, (width, allowWrap) => width == maxColumn && allowWrap ? 1 : 0).ToList();
18                  if (!ratios.Any(x => x != 0) || columnDifference <= 0)
19                  {
20                      break;
21                  }
22  
23                  var maxReduce = widths.Select(_ => Math.Min(excessWidth, columnDifference)).ToList();
24                  widths = Ratio.Reduce(excessWidth, ratios, maxReduce, widths);
25  
26                  totalWidth = widths.Sum();
27                  excessWidth = totalWidth - maxWidth;
28              }
29          }
30  
31          return widths;
32      }

