 1      public List<int> CalculateColumnWidths(int maxWidth)
 2      {
 3          var width_ranges = Columns.Select(column => MeasureColumn(column, maxWidth)).ToArray();
 4          var widths = width_ranges.Select(range => range.Max).ToList();
 5  
