10              widths = CollapseWidths(widths, wrappable, maxWidth);
11              tableWidth = widths.Sum();
12  
13              // last resort, reduce columns evenly
14              if (tableWidth > maxWidth)
15              {
16                  var excessWidth = tableWidth - maxWidth;
17                  widths = Ratio.Reduce(excessWidth, widths.Select(_ => 1).ToList(), widths, widths);
18                  tableWidth = widths.Sum();
19              }
20          }
21  
22          if (tableWidth < maxWidth && Expand)
23          {
24              var flexibleColumns = Columns.Select(column => column.Width == null).ToList();
25              if (flexibleColumns.Any(isFlexible => isFlexible))
26              {
27                  var ratios = widths.Select((width, index) => flexibleColumns[index] ? Math.Max(width, 1) : 0).ToList();
28                  var padWidths = Ratio.Distribute(maxWidth - tableWidth, ratios);
29                  widths = widths.Zip(padWidths, (a, b) => (a, b)).Select(f => f.a + f.b).ToList();
30              }
31          }
32  
33          return widths;
34      }

