20                  output ??= new StringBuilder();
21                  output.AppendSpan(span[..(index - 1)]);
22                  output.Append(emojiValue);
23  
24                  span = span.Slice(nextColonPos + 1);
25                  index = 0;
26              }
27              else
28              {
29                  index = nextColonPos + 1;
30              }
31          }
32  
33          if (output == null)
34          {
35              return value;
36          }
37  
38          output.AppendSpan(span);
39          return output.ToString();
40      }

