 1      private static string Pascalize(string input)
 2      {
 3          if (string.IsNullOrEmpty(input))
 4          {
 5              return input;
 6          }
 7  
 8          var result = new StringBuilder();
 9          var capitalizeNext = true;
10  
11          foreach (var c in input)
12          {
13              if (c == '_')
14              {
15                  capitalizeNext = true;
16              }
17              else if (char.IsLetterOrDigit(c))
18              {
19                  result.Append(capitalizeNext ? char.ToUpperInvariant(c) : c);
20                  capitalizeNext = false;
21              }
22              else
23              {
24                  capitalizeNext = true;
25              }
26          }
27  
28          return result.ToString();
29      }

