 1      public static EquatableArray<EmojiModel> ParseAll(string json)
 2      {
 3          var document = JsonDocument.Parse(json);
 4          var emojis = new List<EmojiModel>();
 5  
 6          foreach (var element in document.RootElement.EnumerateArray())
 7          {
 8              var label = element.GetProperty("label").GetString()
 9                  ?? throw new InvalidOperationException("Emoji has null label");
10              var hexcode = element.GetProperty("hexcode").GetString()
11                  ?? throw new InvalidOperationException("Emoji has null hexcode");
12              var emoji = element.GetProperty("emoji").GetString()
13                  ?? throw new InvalidOperationException("Emoji has null emoji");
14  
15              // Skip anything that is not a single code point for now
16              if (hexcode.Contains("-"))
17              {
18                  continue;
19              }
20  
21              // Transform hexcode to Unicode escape sequence
22              var code = TransformToUnicode(hexcode);
23  
24              // If the emoji does not have the Emoji_Presentation=Yes property,
25              // then it doesn't have a Variation Selector-16 suffix, and we should add it.
26              var codepoint = int.Parse(hexcode, NumberStyles.HexNumber, CultureInfo.InvariantCulture);
27              if (!HasEmojiPresentation(codepoint))
28              {
29                  code += "\\uFE0F";
30              }
31  
32              // Transform label to identifier (snake_case)
33              var identifier = TransformName(label);
34  
35              // Transform identifier to name (PascalCase)
36              var name = identifier
37                  .Replace("1st", "first")
38                  .Replace("2nd", "second")
39                  .Replace("3rd", "third");
40              name = Pascalize(name);
41  
42              // Create description
43              var description = Humanize(label);
44  
45              emojis.Add(new EmojiModel(identifier, name, code, emoji, description));
46          }
47  
48          // Sort by name for consistent output
49          return new EquatableArray<EmojiModel>(emojis.OrderBy(e => e.Name, StringComparer.OrdinalIgnoreCase));
50      }

