 1      public void Initialize(IncrementalGeneratorInitializationContext context)
 2      {
 3          // Find spinners_default.json
 4          // Step 1: Extract text (cached by string value equality)
 5          // Step 2: Wrap in EquatableArray for value equality when combining
 6          var defaultSpinners = context.AdditionalTextsProvider
 7              .Where(static file => file.Path.EndsWith("spinners_default.json", StringComparison.OrdinalIgnoreCase))
 8              .Select(static (file, ct) =>
 9                  file.GetText(ct)?.ToString()
10                  ?? throw new InvalidOperationException($"Failed to read spinners_default.json at {file.Path}"))
11              .Collect()
12              .Select(static (arr, _) => new EquatableArray<string>(arr));
13  
14          // Find spinners_sindresorhus.json
15          var sindreSpinners = context.AdditionalTextsProvider
16              .Where(static file => file.Path.EndsWith("spinners_sindresorhus.json", StringComparison.OrdinalIgnoreCase))
17              .Select(static (file, ct) =>
18                  file.GetText(ct)?.ToString()
19                  ?? throw new InvalidOperationException($"Failed to read spinners_sindresorhus.json at {file.Path}"))
20              .Collect()
21              .Select(static (arr, _) => new EquatableArray<string>(arr));
22  
23          // Combine both JSON files and parse in the pipeline (for caching)
24          // EquatableArray has value equality, so this step is properly cached
25          var spinners = defaultSpinners.Combine(sindreSpinners)
26              .Select(static (data, _) =>
27              {
28                  var (defaultJsonFiles, sindreJsonFiles) = data;
29                  if (defaultJsonFiles.IsEmpty || sindreJsonFiles.IsEmpty)
30                  {
31                      return EquatableArray<SpinnerModel>.Empty;
32                  }
33  
34                  var parsedSpinners = SpinnerParser.ParseAll(defaultJsonFiles[0], sindreJsonFiles[0]);
35                  var validSpinners = parsedSpinners
36                      .Where(IsValidSpinner)
37                      .ToArray();
38  
39                  return new EquatableArray<SpinnerModel>(validSpinners);
40              });
41  
42          context.RegisterSourceOutput(spinners, static (spc, models) =>
43          {
44              if (models.IsEmpty)
45              {
46                  return;
47              }
48  
49              var source = SpinnerEmitter.Emit(models);
50              spc.AddSource("Spinner.Generated.g.cs", SourceText.From(source, Utf8NoBom));
51          });
52      }

