 1  export function resolveExport(
 2    exports: Record<string, string>,
 3    subpath: string,
 4  ): string | undefined {
 5    const exact = exports[subpath];
 6    if (exact !== undefined) {
 7      return exact;
 8    }
 9    for (const [key, target] of Object.entries(exports)) {
10      const [prefix, suffix, ...rest] = key.split('*');
11      if (prefix === undefined || suffix === undefined || rest.length > 0) {
12        continue;
13      }
14      if (
15        subpath.length >= prefix.length + suffix.length &&
16        subpath.startsWith(prefix) &&
17        subpath.endsWith(suffix)
18      ) {
19        const match = subpath.slice(
20          prefix.length,
21          subpath.length - suffix.length,
22        );
23        return target.replaceAll('*', match);
24      }
25    }
26    return undefined;
27  }

