 1  export function standalonePackageJson(
 2    pkg: PackageJson,
 3    catalogs: Catalogs,
 4    added: ReadonlyMap<string, string> = new Map(),
 5  ): PackageJson {
 6    const result: PackageJson = { ...pkg };
 7    for (const field of dependencyFields) {
 8      const deps = pkg[field];
 9      if (deps === undefined) {
10        continue;
11      }
12      result[field] = Object.fromEntries(
13        Object.entries(deps)
14          .filter(([name]) => name !== sharedUi)
15          .map(([name, version]) => [
16            name,
17            standaloneVersion(name, version, catalogs),
18          ]),
19      );
20    }
21    if (pkg.dependenciesMeta?.[sharedUi] !== undefined) {
22      const { [sharedUi]: _, ...rest } = pkg.dependenciesMeta;
23      if (Object.keys(rest).length > 0) {
24        result.dependenciesMeta = rest;
25      } else {
26        delete result.dependenciesMeta;
27      }
28    }
29    const missing = [...added].filter(
30      ([name]) => !dependencyFields.some((field) => result[field]?.[name]),
31    );
32    if (missing.length > 0) {
33      const dependencies = { ...result.dependencies };
34      for (const [name, version] of missing) {
35        dependencies[name] = standaloneVersion(name, version, catalogs);
36      }
37      result.dependencies = Object.fromEntries(
38        Object.entries(dependencies).sort(([a], [b]) => a.localeCompare(b)),
39      );
40    }
41    return result;
42  }

