 1  export function standaloneVersion(
 2    name: string,
 3    version: string,
 4    catalogs: Catalogs,
 5  ) {
 6    if (name.startsWith('@trpc/')) {
 7      return 'canary';
 8    }
 9    if (version.startsWith('catalog:')) {
10      const catalog = version.slice('catalog:'.length) || 'default';
11      const resolved = catalogs.get(catalog)?.get(name);
12      if (resolved === undefined) {
13        throw new StandaloneError({
14          message: `${name}@${version}: not in the ${catalog} catalog`,
15        });
16      }
17      return resolved;
18    }
19    if (version.startsWith('workspace:')) {
20      throw new StandaloneError({
21        message: `${name}@${version} only resolves in the monorepo`,
22      });
23    }
24    return version;
25  }

