 2    const style = node.properties['style'];
 3    // Shiki's colours are never quoted. A quoted value can hold a `;`, which
 4    // splitting would cut, so a style with quotes is left as it is.
 5    if (typeof style !== 'string' || /["']/.test(style)) {
 6      return undefined;
 7    }
