11      const colon = declaration.indexOf(':');
12      if (colon !== -1) {
13        colors.set(
14          declaration.slice(0, colon).trim(),
15          declaration
16            .slice(colon + 1)
17            .trim()
18            .toLowerCase(),
19        );
20      }
21    }
22    return colors;
23  }

