 2    schema,
 3    pathParts,
 4    description,
 5    schemas,
 6  }: {
 7    schema: SchemaObject;
 8    pathParts: string[];
 9    description: string;
10    schemas?: Record<string, SchemaObject>;
11  }): void {
12    if (pathParts.length === 0) return;
13  
14    const [head, ...rest] = pathParts;
15    if (!head) return;
16  
17    // `[]` means "array items" — navigate to the `items` sub-schema
18    if (head === '[]') {
19      const items = getArrayItemsSchema(schema);
20      if (!items) return;
21      if (rest.length === 0) {
22        setLeafDescription(items, description);
23      } else {
24        const target = resolveSchemaRef(items, schemas) ?? items;
25        setNestedDescription({
26          schema: target,
27          pathParts: rest,
28          description,
29          schemas,
30        });
31      }
32      return;
33    }
34  
35    const propSchema = getPropertySchema(schema, head);
36    if (!propSchema) return;
37  
38    if (rest.length === 0) {
39      // Leaf — Zod .describe() takes priority over JSDoc
40      setLeafDescription(propSchema, description);
41    } else {
42      // For arrays, step through `items` transparently
43      const target = getArrayItemsSchema(propSchema) ?? propSchema;
44      const resolvedTarget = resolveSchemaRef(target, schemas) ?? target;
45      setNestedDescription({
46        schema: resolvedTarget,
47        pathParts: rest,
48        description,
49        schemas,
50      });
51    }
52  }

