 6    // Unwrap router to its record; plain RouterRecords are used as-is.
 7    const record: TRPCRouterRecord = isRouterInstance(routerOrRecord)
 8      ? routerOrRecord._def.record
 9      : routerOrRecord;
10  
11    for (const [key, value] of Object.entries(record)) {
12      const fullPath = prefix ? `${prefix}.${key}` : key;
13  
14      if (isProcedure(value)) {
15        // Procedure — extract descriptions from input and output Zod schemas
16        const def = value._def;
17        let inputDescs: DescriptionMap | null = null;
18        for (const input of def.inputs) {
19          const descs = extractZodDescriptions(input);
20          if (descs) {
21            // Merge multiple .input() descriptions (last wins for conflicts)
22            inputDescs ??= { properties: new Map() };
23            inputDescs.self = descs.self ?? inputDescs.self;
24            for (const [p, d] of descs.properties) {
25              inputDescs.properties.set(p, d);
26            }
27          }
28        }
29  
30        let outputDescs: DescriptionMap | null = null;
31        // `output` exists at runtime on the procedure def (from the builder)
32        // but is not part of the public Procedure type.
33        const outputParser = (def as Record<string, unknown>)['output'];
34        if (outputParser) {
