 1  export function findRouterExport(
 2    mod: Record<string, unknown>,
 3    exportName: string,
 4  ): AnyTRPCRouter | null {
 5    // 1. Exact match
 6    if (isRouterInstance(mod[exportName])) {
 7      return mod[exportName];
 8    }
 9  
10    // 2. lcfirst variant (e.g. AppRouter → appRouter)
11    const lcFirst = exportName.charAt(0).toLowerCase() + exportName.slice(1);
12    if (lcFirst !== exportName && isRouterInstance(mod[lcFirst])) {
13      return mod[lcFirst];
14    }
15  
16    // 3. Any export that looks like a router
17    for (const value of Object.values(mod)) {
18      if (isRouterInstance(value)) {
19        return value;
20      }
21    }
22  
23    return null;
24  }

