 1  export function extractZodDescriptions(schema: unknown): DescriptionMap | null {
 2    if (!isZodSchema(schema)) return null;
 3    const registry = getZodGlobalRegistry();
 4    if (!registry) return null;
 5  
 6    const map: DescriptionMap = { properties: new Map() };
 7    let hasAny = false;
 8  
 9    // Check top-level description
10    const topMeta = registry.get(schema);
11    if (topMeta?.description) {
12      map.self = topMeta.description;
13      hasAny = true;
14    }
15  
16    // Walk object shape
17    walkZodShape(schema, '', { registry, map, seenLazy: new Set() });
18    if (map.properties.size > 0) hasAny = true;
19  
20    return hasAny ? map : null;
21  }

