 1  export function publishedVersions(
 2    packages: ReadonlyArray<WorkspacePackage>,
 3    version: string,
 4  ): ReadonlyMap<string, string> {
 5    const byName = new Map(
 6      packages
 7        .filter(({ pkg }) => pkg.private !== true)
 8        .map((workspacePackage) => [workspacePackage.name, workspacePackage]),
 9    );
10    const ordered = new Map<string, string>();
11    const visiting = new Set<string>();
12    const visit = (name: string) => {
13      const workspacePackage = byName.get(name);
14      if (workspacePackage === undefined || ordered.has(name)) {
15        return;
16      }
17      if (visiting.has(name)) {
18        throw new Error(
19          `${name} is in a dependency cycle between public packages, so no order publishes each after what it needs`,
20        );
21      }
22      visiting.add(name);
23      for (const field of runtimeDependencyFields) {
24        const deps = workspacePackage.pkg[field] as
25          | Record<string, string>
26          | undefined;
27        Object.keys(deps ?? {}).forEach(visit);
28      }
29      ordered.set(name, packageVersion(name, version));
30    };
31    [...byName.keys()].forEach(visit);
32    return ordered;
33  }

