 1  export function section(markdown: string, anchor: string) {
 2    const lines = markdown.split('\n');
 3    const fenced = inFences(lines);
 4    const slugger = new GithubSlugger();
 5    let start = -1;
 6    let level = 0;
 7    for (const [index, line] of lines.entries()) {
 8      const heading = fenced[index] ? null : /^(#{1,6}) (.*)$/.exec(line);
 9      if (!heading?.[1]) continue;
10      if (start >= 0 && heading[1].length <= level) {
11        return lines.slice(start, index).join('\n').trim();
12      }
13      const text = heading[2] ?? '';
14      const id = headingId.exec(text)?.[1] ?? slugger.slug(text);
15      if (start < 0 && id === anchor) {
16        start = index;
17        level = heading[1].length;
18      }
19    }
20    return start >= 0 ? lines.slice(start).join('\n').trim() : undefined;
21  }

