 1  export function startSentry(
 2    release: string | undefined,
 3    router: AnyRouter | undefined,
 4  ): Capture {
 5    init({
 6      ...sentryOptions,
 7      release,
 8      // The site's own scripts' errors, not browser extensions'.
 9      allowUrls: [window.location.origin],
10      // What others' code throws without a stack for `allowUrls` to check.
11      ignoreErrors: [
12        // Outlook's link scanner, opening a link from an email.
13        'Object Not Found Matching Id:',
14        // A crypto wallet extension setting its address, which the site
15        // doesn't read: "(evaluating 'window.ethereum.selectedAddress = …')".
16        /\(evaluating 'window\.ethereum\./,
17      ],
18      integrations: (defaults) => [
19        // No session per page load: Sentry hears from a visitor only for an
20        // error or a sampled trace.
21        ...defaults.filter(
22          (integration) => integration.name !== 'BrowserSession',
23        ),
24        ...(router ? [tanstackRouterBrowserTracingIntegration(router)] : []),
25      ],
26    });
27    return (reported) => {
28      const mechanism = mechanisms[reported.source];
29      if (reported.componentStack === undefined) {
30        captureException(reported.error, { mechanism });
31      } else {
32        captureReactException(
33          reported.error,
34          { componentStack: reported.componentStack },
35          { mechanism },
36        );
37      }
38    };
39  }

