 1  export async function hydratePages(
 2    dehydrated: DehydratedPages,
 3    reload: () => void,
 4  ) {
 5    await Promise.all(
 6      dehydrated.pages.map(async (key) => {
 7        const load = modules.get(key);
 8        if (!load) {
 9          throw new Error(`${key} isn't a registered page`);
10        }
11        try {
12          await loadPage(key, load).catch(() => loadPage(key, load));
13        } catch (error) {
14          if (!reloadOnce(key, reload)) {
15            throw error;
16          }
17          // The page is going away; hydrating it would be wasted.
18          await new Promise<never>(() => {});
19        }
20        forgetReload(key);
21      }),
22    );
23  }

