 1  export function dehydratePages(router: {
 2    readonly state: {
 3      readonly matches: ReadonlyArray<{ readonly loaderData?: unknown }>;
 4    };
 5  }): DehydratedPages {
 6    return {
 7      pages: router.state.matches.flatMap((match) => {
 8        const data: unknown = match.loaderData;
 9        return typeof data === 'object' && data !== null
10          ? Object.values(data).flatMap(htmlKeyOf)
11          : [];
12      }),
13    };
14  }

