 1  export function createUseQueries<TRouter extends AnyRouter>(
 2    client: TRPCUntypedClient<TRouter> | TRPCClient<TRouter>,
 3  ) {
 4    const untypedClient: TRPCUntypedClient<TRouter> =
 5      client instanceof TRPCUntypedClient ? client : getUntypedClient(client);
 6  
 7    return createRecursiveProxy<
 8      UseQueriesProcedureRecord<
 9        TRouter['_def']['_config']['$types'],
10        TRouter['_def']['record']
11      >
12    >((opts) => {
13      const arrayPath = opts.path;
14      const dotPath = arrayPath.join('.');
15      const [input, _opts] = opts.args as [
16        unknown,
17        Partial<QueryOptions> & TRPCUseQueryBaseOptions,
18      ];
19  
20      const options: QueryOptions = {
21        queryKey: getQueryKeyInternal(arrayPath, input, 'query'),
22        queryFn: () => {
23          return untypedClient.query(dotPath, input, _opts?.trpc);
24        },
25        ..._opts,
26      };
27  
28      return options;
29    });
30  }

