 1  function appsOf(
 2    markdown: string,
 3    options: Omit<RenderOptions, 'twoslashCache'>,
 4  ) {
 5    if (!markdown.includes('twoslash')) {
 6      return '';
 7    }
 8    const apps = new Set(
 9      Array.from(
10        markdown.matchAll(/^\/\/ @filename: ([^/\n]+)\//gm),
11        (match) => match[1],
12      ),
13    );
14    return [
15      options.inlineApp ?? '',
16      ...[...apps].toSorted((a = '', b = '') => a.localeCompare(b)),
17    ].join(' ');
18  }

