 1  export function isSameSponsor(
 2    backer: Pick<OpenCollectiveBacker, 'githubLogin' | 'websiteUrl'>,
 3    sponsor: {
 4      readonly githubLogin: string | null;
 5      readonly websiteUrl: string | null;
 6    },
 7  ) {
 8    if (
 9      backer.githubLogin !== null &&
10      backer.githubLogin.toLowerCase() === sponsor.githubLogin?.toLowerCase()
11    ) {
12      return true;
13    }
14    const site =
15      backer.websiteUrl === null ? undefined : siteOf(backer.websiteUrl);
16    return (
17      site !== undefined &&
18      sponsor.websiteUrl !== null &&
19      site === siteOf(sponsor.websiteUrl)
20    );
21  }

