 1  function siteOf(website: string) {
 2    const withScheme = /^https?:\/\//i.test(website)
 3      ? website
 4      : `https://${website}`;
 5    if (!URL.canParse(withScheme)) {
 6      return undefined;
 7    }
 8    const url = new URL(withScheme);
 9    for (const key of [...url.searchParams.keys()]) {
10      if (key === 'ref' || key.startsWith('utm_')) {
11        url.searchParams.delete(key);
12      }
13    }
14    url.searchParams.sort();
15    const host = url.host.toLowerCase().replace(/^www\./, '');
16    return `${host}${url.pathname.replace(/\/+$/, '')}${url.search}`;
17  }

