 1  export function trackingLink(website: string) {
 2    const withScheme = /^https?:\/\//i.test(website)
 3      ? website
 4      : `https://${website}`;
 5    if (!URL.canParse(withScheme)) {
 6      return undefined;
 7    }
 8    const url = new URL(withScheme);
 9    if (!url.searchParams.has('ref')) {
10      url.searchParams.set('ref', 'trpc');
11    }
12    url.searchParams.set('utm_source', 'github');
13    url.searchParams.set('utm_medium', 'referral');
14    url.searchParams.set('utm_campaign', 'trpc');
15    return url.toString();
16  }

