 1  export function takePopups(tree: Root): ReadonlyArray<string> {
 2    const popups: Array<string> = [];
 3    const indexes = new Map<string, number>();
 4    visit(tree, 'element', (node) => {
 5      const classes = classNames(node);
 6      if (
 7        !classes.includes('twoslash-hover') ||
 8        classes.includes('twoslash-query-persisted')
 9      ) {
10        return;
11      }
12      const container = node.children.find(
13        (child) =>
14          child.type === 'element' &&
15          classNames(child).includes('twoslash-popup-container'),
16      );
17      if (container?.type !== 'element') {
18        return;
19      }
20      const html = toHtml({ type: 'root', children: container.children });
21      let index = indexes.get(html);
22      if (index === undefined) {
23        index = popups.length;
24        popups.push(html);
25        indexes.set(html, index);
26      }
27      node.children = node.children.filter((child) => child !== container);
28      node.properties['dataPopup'] = String(index);
29    });
30    return popups;
31  }

