 1  export function createReactQueryUtils<TRouter extends AnyRouter, TSSRContext>(
 2    context: TRPCContextState<AnyRouter, TSSRContext>,
 3  ) {
 4    type CreateReactUtilsReturnType = CreateReactUtils<TRouter, TSSRContext>;
 5  
 6    const clientProxy = createTRPCClientProxy(context.client);
 7  
 8    const proxy = createRecursiveUtilsProxy(
 9      context,
10    ) as CreateReactUtilsReturnType;
11  
12    return createFlatProxy<CreateReactUtilsReturnType>((key) => {
13      const contextName = key as (typeof contextProps)[number];
14      if (contextName === 'client') {
15        return clientProxy;
16      }
17      if (contextProps.includes(contextName)) {
18        return context[contextName];
19      }
20  
21      return proxy[key];
22    });
23  }

