 1  export function paidFromActivities(
 2    activities: ReadonlyArray<Activity>,
 3    now: number,
 4  ): Array<LifetimeValue> {
 5    const dollars = new Map<string, number>();
 6    const monthly = new Map<string, { dollars: number; since: number }>();
 7    const add = (login: string, amount: number) =>
 8      dollars.set(login, (dollars.get(login) ?? 0) + amount);
 9    const close = (login: string, at: number) => {
10      const held = monthly.get(login);
11      if (held === undefined) {
12        return;
13      }
14      monthly.delete(login);
15      add(login, held.dollars * monthlyCharges(held.since, at));
16    };
17    for (const activity of activities) {
18      if (activity.sponsor === null) {
19        continue;
20      }
21      const login = activity.sponsor.login;
22      const at = Date.parse(activity.timestamp);
23      const tier = activity.sponsorsTier;
24      switch (activity.action) {
25        case 'NEW_SPONSORSHIP':
26        case 'TIER_CHANGE': {
27          if (tier === null) {
28            break;
29          }
30          if (tier.isOneTime) {
31            add(login, tier.monthlyPriceInDollars);
32            break;
33          }
34          close(login, at);
35          monthly.set(login, { dollars: tier.monthlyPriceInDollars, since: at });
36          break;
37        }
38        case 'CANCELLED_SPONSORSHIP': {
39          close(login, at);
40          break;
41        }
42        case 'REFUND': {
43          if (tier !== null) {
44            add(login, -tier.monthlyPriceInDollars);
45          }
46          break;
47        }
48      }
49    }
50    for (const login of monthly.keys()) {
51      close(login, now);
52    }
53    return [...dollars].map(([login, amount]) => ({
54      cents: Math.round(Math.max(0, amount) * 100),
55      login,
56    }));
57  }

