 5      (end.getUTCFullYear() - start.getUTCFullYear()) * 12 +
 6      (end.getUTCMonth() - start.getUTCMonth());
 7    const last = new Date(since);
 8    last.setUTCMonth(start.getUTCMonth() + months);
 9    if (last.getTime() <= until) {
10      months += 1;
11    }
12    return Math.max(1, months);
13  }

