 1  function entryPoints(directory: string): ReadonlyArray<string> {
 2    const pkg = JSON.parse(
 3      readFileSync(`${packagesDir}/${directory}/package.json`, 'utf8'),
 4    ) as { exports: Record<string, ExportEntry | string> };
 5    return Object.values(pkg.exports)
 6      .flatMap((value) => (typeof value === 'string' ? [] : [value]))
 7      .map((value) =>
 8        value.import.default.replace('./dist/', '').replace('.mjs', '.ts'),
 9      )
10      .filter((entry) => {
11        if (entry.includes('unstable')) {
12          return false;
13        }
14        switch (directory) {
15          case 'next':
16            return entry === 'index.ts';
17          case 'server':
18            // `shared.ts` only re-exports, deprecated.
19            return entry !== 'shared.ts';
20          default:
21            return true;
22        }
23      });
24  }

