 1  export function wsLink<TRouter extends AnyRouter>(
 2    opts: WebSocketLinkOptions<TRouter>,
 3  ): TRPCLink<TRouter> {
 4    const { client } = opts;
 5    const transformer = getTransformer(opts.transformer);
 6    return () => {
 7      return ({ op }) => {
 8        return observable((observer) => {
 9          let connStateSubscription: Unsubscribable | null = null;
10          if (op.type === 'subscription') {
11            // The current state is sent during `subscribe`, and a throwing
12            // `onConnectionStateChange` must not stop the request below from
13            // being sent. The client guards the states it sends later.
14            let isSubscribing = true;
15            connStateSubscription = client.connectionState.subscribe({
16              next(result) {
17                const emit = () =>
18                  observer.next({
19                    result,
20                    context: op.context,
21                  });
22                if (isSubscribing) {
23                  callUserCallback(emit);
24                } else {
25                  emit();
26                }
27              },
28            });
29            isSubscribing = false;
30          }
31  
32          const requestSubscription = client
33            .request({
34              op,
35              transformer,
36            })
37            .subscribe(observer);
38  
39          return () => {
40            requestSubscription.unsubscribe();
41            connStateSubscription?.unsubscribe();
42          };
43        });
44      };
45    };
46  }

