 1  export async function filterIgnored(files: readonly SourceFile[]) {
 2    let stdout = '';
 3    let stderr = '';
 4    try {
 5      const result = await execa('git check-ignore **/*');
 6      stdout = result.stdout;
 7      stderr = result.stderr;
 8    } catch (error) {
 9      log.error('Error executing git check-ignore:', error);
10      stdout = '';
11    }
12  
13    const ignores = stdout.split('\n');
14  
15    if (process.env['VERBOSE']) {
16      log.info(`cwd: ${process.cwd()}`);
17      log.info(
18        `All files in program: ${files.map((file) => file.fileName).join(', ')}`,
19      );
20      log.info(`Ignored files: ${ignores.join(', ')}`);
21    }
22  
23    // Ignore "common files"
24    const filteredSourcePaths = files
25      .filter(
26        (source) =>
27          source.fileName.startsWith(resolve()) && // only look ahead of current directory
28          !source.fileName.includes('/trpc/packages/') && // relative paths when running codemod locally
29          !source.fileName.includes('/node_modules/') && // always ignore node_modules
30          !ignores.includes(source.fileName), // ignored files
31      )
32      .map((source) => source.fileName);
33  
34    if (process.env['VERBOSE']) {
35      log.info(`Filtered files: ${filteredSourcePaths.join(', ')}`);
36    }
37  
38    return filteredSourcePaths;
39  }

