 1  export function makePageRenderer(
 2    cacheOptions: TwoslashCacheOptions | undefined,
 3  ) {
 4    const twoslashCache = cacheOptions && makeTwoslashCache(cacheOptions);
 5    let building = false;
 6    return {
 7      configResolved: (config: ResolvedConfig) => {
 8        building = config.command === 'build';
 9      },
10      render: (
11        markdown: string,
12        options: Omit<RenderOptions, 'twoslashCache'>,
13      ) => {
14        if (!building) {
15          return renderMarkdown(markdown, { ...options, twoslashCache });
16        }
17        renderPool ??= makeRenderPool();
18        return Effect.map(
19          renderPool.render(markdown, options, cacheOptions),
20          (output) => {
21            if (twoslashCache) {
22              twoslashCache.stats.hits += output.stats.hits;
23              twoslashCache.stats.misses += output.stats.misses;
24            }
25            return output.rendered;
26          },
27        );
28      },
29      /** Blocks read from the cache and blocks compiled, in this process or the build's render processes. */
30      stats: twoslashCache?.stats,
31    };
32  }

