 2    text: string,
 3    match: SearchMatch,
 4  ): ReadonlyArray<TextRun> {
 5    const ranges: Array<[number, number]> = [];
 6    const mark = (start: number, length: number) => {
 7      const last = ranges.at(-1);
 8      if (last && start <= last[1]) {
 9        last[1] = Math.max(last[1], start + length);
10      } else if (length > 0) {
11        ranges.push([start, start + length]);
12      }
13    };
14    for (const found of text.matchAll(word)) {
15      mark(found.index, markedLength(found[0], match));
16      let at = found.index;
17      for (const part of found[0].split(camelBoundary)) {
18        mark(at, markedLength(part, match));
19        at += part.length;
20      }
21    }
22    const runs: Array<TextRun> = [];
23    let at = 0;
24    for (const [start, end] of ranges) {
25      if (start > at) {
26        runs.push({ marked: false, text: text.slice(at, start) });
27      }
28      runs.push({ marked: true, text: text.slice(start, end) });
29      at = end;
30    }
31    if (at < text.length) {
32      runs.push({ marked: false, text: text.slice(at) });
33    }
34    return runs;
35  }

