 1  export function searchDocs(
 2    docs: ReadonlyArray<DocMeta>,
 3    query: string,
 4    limit: number,
 5  ): ReadonlyArray<SearchHit> {
 6    const index = indexOf(docs);
 7    if (query.trim() === '') {
 8      return index.pages
 9        .filter((entry) => !entry.experimental)
10        .slice(0, Math.min(8, limit))
11        .map((entry) => ({ entry, match: noMatch }));
12    }
13    const queried = wordsOf(query);
14    const matchOf = (entry: SearchEntry) =>
15      namesMatch(index.names.get(entry.id) ?? [], queried);
16    const found = index.search.search(query).flatMap((result) => {
17      const entry = index.byId.get(String(result.id));
18      return entry
19        ? [
20            {
21              entry,
22              level: matchOf(entry).level,
23              match: {
24                queryTerms: result.queryTerms,
25                terms: new Set(result.terms),
26              },
27              score: result.score,
28            },
29          ]
30        : [];
31    });
32    const foundIds = new Set(found.map((hit) => hit.entry.id));
33    // A page named for the query that the index missed: `batching` for
34    // `httpBatchLink`, which it only finds by prefix and with typos.
35    const named = index.pages.flatMap((entry) => {
36      if (foundIds.has(entry.id)) {
37        return [];
38      }
39      const { level, terms } = matchOf(entry);
40      return level > 0
41        ? [
42            {
43              entry,
44              level,
45              match: { queryTerms: [...new Set(queried.whole)], terms },
46              score: 0,
47            },
48          ]
49        : [];
50    });
51    return [...found, ...named]
52      .toSorted(
53        (a, b) =>
54          tierOf(b.entry, b.level) - tierOf(a.entry, a.level) ||
55          b.level - a.level ||
56          b.score - a.score,
57      )
58      .slice(0, limit)
59      .map(({ entry, match }) => ({ entry, match }));
60  }

