 1  function nameMatch(name: Words, query: Words) {
 2    if (query.whole.length === 0) {
 3      return 0;
 4    }
 5    const pairs = [
 6      [name.whole, query.whole],
 7      [name.parts, query.parts],
 8    ] as const;
 9    if (
10      pairs.some(
11        ([names, queried]) =>
12          names.length === queried.length &&
13          queried.every((one, at) => sameWord(one, names[at] ?? '')),
14      )
15    ) {
16      return 3;
17    }
18    if (
19      pairs.some(([names, queried]) =>
20        queried.every((one, at) => {
21          const named = names[at] ?? '';
22          return (
23            sameWord(one, named) ||
24            (at === queried.length - 1 && named.startsWith(one))
25          );
26        }),
27      )
28    ) {
29      return 2;
30    }
31    const all = [...name.whole, ...name.parts];
32    // `queryOptions`'s parts only in that order: not `inferQueryProcedureOptions`.
33    const hasParts = name.parts.some((_, start) =>
34      query.parts.every((one, at) => sameWord(one, name.parts[start + at] ?? '')),
35    );
36    return hasParts ||
37      query.whole.every((one) => all.some((named) => sameWord(one, named)))
38      ? 1
39      : 0;
40  }

