 1  function stems(lower: string): ReadonlySet<string> {
 2    const cached = stemsOf.get(lower);
 3    if (cached) {
 4      return cached;
 5    }
 6    const singular = [lower];
 7    if (lower.length > 4 && lower.endsWith('ies')) {
 8      singular.push(`${lower.slice(0, -3)}y`);
 9    }
10    if (/(?:s|x|z|ch|sh)es$/.test(lower)) {
11      singular.push(lower.slice(0, -2));
12    }
13    if (lower.length > 3 && lower.endsWith('s') && !lower.endsWith('ss')) {
14      singular.push(lower.slice(0, -1));
15    }
16    const found = new Set(
17      singular.flatMap((one) =>
18        one.length > 6 && one.endsWith('ing') ? [one, one.slice(0, -3)] : [one],
19      ),
20    );
21    stemsOf.set(lower, found);
22    return found;
23  }

