 1  function entriesOf(docs: ReadonlyArray<DocMeta>): ReadonlyArray<SearchEntry> {
 2    const bySlug = new Map(docs.map((doc) => [doc.slug, doc]));
 3    const parentsOf = (doc: DocMeta): ReadonlyArray<string> => {
 4      const parent = bySlug.get(doc.parent ?? '');
 5      return parent && parent !== doc
 6        ? [...parentsOf(parent), nameOf(parent)]
 7        : [];
 8    };
 9    return docs.flatMap((doc) => {
10      const parents = parentsOf(doc);
11      const experimental = doc.experiment !== undefined;
12      const entries: Array<SearchEntry> = [
13        {
14          description: doc.description,
15          experimental,
16          hash: undefined,
17          id: doc.slug,
18          section: doc.section,
19          slug: doc.slug,
20          text: nameOf(doc),
21          trail: parents,
22        },
23      ];
24      let h2: string | undefined;
25      for (const heading of doc.headings) {
26        if (heading.depth === 2) {
27          h2 = heading.text;
28        }
29        entries.push({
30          description: '',
31          experimental,
32          hash: heading.id,
33          id: `${doc.slug}#${heading.id}`,
34          section: doc.section,
35          slug: doc.slug,
36          text: heading.text,
37          trail: [
38            ...parents,
39            nameOf(doc),
40            ...(heading.depth === 3 && h2 !== undefined ? [h2] : []),
41          ],
42        });
43      }
44      return entries;
45    });
46  }

