 1  export function transformResult<TRouter extends AnyRouter, TOutput>(
 2    response:
 3      | TRPCResponse<TOutput, inferRouterError<TRouter>>
 4      | TRPCResponseMessage<TOutput, inferRouterError<TRouter>>,
 5    transformer: DataTransformer,
 6  ): ReturnType<typeof transformResultInner> {
 7    let result: ReturnType<typeof transformResultInner>;
 8    try {
 9      // Use the data transformers on the JSON-response
10      result = transformResultInner(response, transformer);
11    } catch {
12      throw new TransformResultError();
13    }
14  
15    // check that output of the transformers is a valid TRPCResponse
16    if (
17      !result.ok &&
18      (!isObject(result.error.error) ||
19        typeof result.error.error['code'] !== 'number')
20    ) {
21      throw new TransformResultError();
22    }
23    if (result.ok && !isObject(result.result)) {
24      throw new TransformResultError();
25    }
26    return result;
27  }

