 1  function transformResultInner<TRouter extends AnyRouter, TOutput>(
 2    response:
 3      | TRPCResponse<TOutput, inferRouterError<TRouter>>
 4      | TRPCResponseMessage<TOutput, inferRouterError<TRouter>>,
 5    transformer: DataTransformer,
 6  ) {
 7    if ('error' in response) {
 8      const error = transformer.deserialize(
 9        response.error,
10      ) as inferRouterError<TRouter>;
11      return {
12        ok: false,
13        error: {
14          ...response,
15          error,
16        },
17      } as const;
18    }
19  
20    const result = {
21      ...response.result,
22      ...((!response.result.type || response.result.type === 'data') && {
23        type: 'data',
24        data: transformer.deserialize(response.result.data),
25      }),
26    } as TRPCResultMessage<TOutput>['result'];
27    return { ok: true, result } as const;
28  }

