 2    all: ReadonlyArray<Sponsor>,
 3    now: number,
 4  ): {
 5    readonly kind: 'latest' | 'new';
 6    readonly sponsors: ReadonlyArray<Sponsor>;
 7  } {
 8    const newestFirst = all
 9      .filter((sponsor) => sponsor.createdAt <= now)
10      .toSorted((a, b) => {
11        const [keyA, keyB] = [sponsorKey(a), sponsorKey(b)];
12        // Not `localeCompare`, whose order can differ between the server and a browser.
13        return (
14          b.createdAt - a.createdAt || (keyA < keyB ? -1 : keyA > keyB ? 1 : 0)
15        );
16      });
17    const started = newestFirst.filter(
18      (sponsor) => sponsor.createdAt > now - newSponsorMs,
19    );
20    return started.length > 0
21      ? { kind: 'new', sponsors: started }
22      : { kind: 'latest', sponsors: newestFirst.slice(0, latestSponsorCount) };
23  }

