 1  export function withOwnIncludes(markdown: string) {
 2    const problems: Array<string> = [];
 3    const taken = takeIncludes(markdown.split('\n'));
 4    const lines = [...taken.lines];
 5    for (const fence of fencesOf(taken.lines).toReversed()) {
 6      if (!/\btwoslash\b/.test(fence.info)) {
 7        continue;
 8      }
 9      const body = taken.lines
10        .slice(fence.start + 1, fence.end)
11        .map((line) =>
12          line.startsWith(fence.indent) ? line.slice(fence.indent.length) : line,
13        )
14        .join('\n');
15      lines.splice(
16        fence.start + 1,
17        fence.end - fence.start - 1,
18        ...expandIncludes(body, taken.includes, problems)
19          .split('\n')
20          .map((line) => (line === '' ? '' : `${fence.indent}${line}`)),
21      );
22    }
23    return { markdown: lines.join('\n'), problems };
24  }

