 1  function convertFences(
 2    lines: ReadonlyArray<string>,
 3    includes: ReadonlyMap<string, string>,
 4    twoslash: boolean,
 5    problems: Array<string>,
 6  ) {
 7    const output = [...lines];
 8    for (const fence of fencesOf(lines).toReversed()) {
 9      const info = fenceInfo(fence.info);
