22      const code = twoslash
23        ? withoutHiddenQueries(expandIncludes(body, includes, problems))
24        : plainCode(body, includes, problems);
25      output.splice(
26        fence.start,
27        fence.end - fence.start + 1,
28        opening(
29          twoslash ? info : info.replaceAll(/[ \t]*\btwoslash\b/g, '').trim(),
30        ),
31        ...code
32          .split('\n')
33          .map((line) => (line === '' ? '' : `${fence.indent}${line}`)),
