 1  function takeIncludes(lines: ReadonlyArray<string>) {
 2    const includes = new Map<string, string>();
 3    const drop = new Set<number>();
 4    for (const fence of fencesOf(lines)) {
 5      const name = /^twoslash include (\S+)/.exec(fence.info)?.[1];
 6      if (!name) {
 7        continue;
 8      }
 9      includes.set(name, lines.slice(fence.start + 1, fence.end).join('\n'));
10      for (let index = fence.start; index <= fence.end; index++) {
11        drop.add(index);
12      }
13      if (lines[fence.end + 1]?.trim() === '') {
14        drop.add(fence.end + 1);
15      }
16    }
17    return {
18      includes,
19      lines: lines.filter((_line, index) => !drop.has(index)),
20    };
21  }

