 1  export function expandIncludes(
 2    code: string,
 3    includes: ReadonlyMap<string, string>,
 4    problems: Array<string>,
 5  ) {
 6    let expanded = code;
 7    for (let depth = 0; depth < 5; depth++) {
 8      expanded = expanded.replaceAll(
 9        /^[ \t]*\/\/ @include: (\S+)[ \t]*$/gm,
10        (line, name: string) => {
11          const included = includes.get(name);
12          if (included === undefined) {
13            problems.push(`\`${line.trim()}\`: no \`twoslash include ${name}\``);
14            return '';
15          }
16          return included.replace(/\n$/, '');
17        },
18      );
19    }
20    return trimBlankLines(expanded.split('\n')).join('\n');
21  }

