 1  export function commentsOf(lines: ReadonlyArray<string>) {
 2    const comments: Array<{ readonly start: number; readonly end: number }> = [];
 3    let fence: string | undefined;
 4    let start: number | undefined;
 5    for (const [index, line] of lines.entries()) {
 6      if (start !== undefined) {
 7        if (line.includes('-->')) {
 8          comments.push({ end: index, start });
 9          start = undefined;
10        }
11        continue;
12      }
13      if (fence !== undefined) {
14        const close = /^[ \t]*(`{3,}|~{3,})[ \t]*$/.exec(line)?.[1];
15        if (
16          close !== undefined &&
17          close[0] === fence[0] &&
18          close.length >= fence.length
19        ) {
20          fence = undefined;
21        }
22        continue;
23      }
24      const open = /^ {0,3}<!--/.exec(line);
25      if (open) {
26        if (!line.includes('-->', open[0].length)) {
27          start = index;
28        } else {
29          comments.push({ end: index, start: index });
30        }
31        continue;
32      }
33      fence = fenceOpen.exec(line)?.[2];
34    }
35    if (start !== undefined) {
36      comments.push({ end: lines.length - 1, start });
37    }
38    return comments;
39  }

