 1  export function fencesOf(lines: ReadonlyArray<string>): ReadonlyArray<Fence> {
 2    const fences: Array<Fence> = [];
 3    let index = 0;
 4    while (index < lines.length) {
 5      const open = fenceOpen.exec(lines[index] ?? '');
 6      const marker = open?.[2];
 7      if (!open || marker === undefined) {
 8        index++;
 9        continue;
10      }
11      const start = index;
12      index++;
13      while (index < lines.length) {
14        const close = /^[ \t]*(`{3,}|~{3,})[ \t]*$/.exec(lines[index] ?? '');
15        if (
16          close?.[1] &&
17          close[1][0] === marker[0] &&
18          close[1].length >= marker.length
19        ) {
20          break;
21        }
22        index++;
23      }
24      fences.push({
25        end: Math.min(index, lines.length - 1),
26        indent: open[1] ?? '',
27        info: (open[3] ?? '').trim(),
28        marker,
29        start,
30      });
31      index++;
32    }
33    return fences;
34  }

