 1  export function loggerLink<TRouter extends AnyRouter = AnyRouter>(
 2    opts: LoggerLinkOptions<TRouter> = {},
 3  ): TRPCLink<TRouter> {
 4    const { enabled = () => true } = opts;
 5  
 6    const colorMode =
 7      opts.colorMode ?? (typeof window === 'undefined' ? 'ansi' : 'css');
 8    const withContext = opts.withContext ?? colorMode === 'css';
 9    const {
10      logger = defaultLogger({ c: opts.console, colorMode, withContext }),
11    } = opts;
12  
13    return () => {
14      return ({ op, next }) => {
15        return observable((observer) => {
16          // ->
17          if (enabled({ ...op, direction: 'up' })) {
18            logger({
19              ...op,
20              direction: 'up',
21            });
22          }
23          const requestStartTime = Date.now();
24          function logResult(
25            result:
26              | OperationResultEnvelope<unknown, TRPCClientError<TRouter>>
27              | TRPCClientError<TRouter>,
28          ) {
29            const elapsedMs = Date.now() - requestStartTime;
30  
31            if (enabled({ ...op, direction: 'down', result })) {
32              logger({
33                ...op,
34                direction: 'down',
35                elapsedMs,
36                result,
37              });
38            }
39          }
40          return next(op)
41            .pipe(
42              tap({
43                next(result) {
44                  logResult(result);
45                },
46                error(result) {
47                  logResult(result);
48                },
49              }),
50            )
51            .subscribe(observer);
52        });
53      };
54    };
55  }

