 1  function buildOpenAPIDocument(
 2    procedures: ProcedureInfo[],
 3    options: GenerateOptions & { pathSeparator: TRPCPathSeparator },
 4    meta: RouterMeta = { errorSchema: null },
 5  ): Document {
 6    const paths: PathsObject = {};
 7    const included = procedures.filter((proc) =>
 8      shouldIncludeProcedureInOpenAPI(proc.type),
 9    );
10  
11    const schemas = meta.schemas ?? {};
12    const { responses: errorResponses, refByProcedurePath } = buildErrorResponses(
13      included,
14      meta.errorSchema ?? DEFAULT_ERROR_SCHEMA,
15      schemas,
16    );
17  
18    for (const proc of included) {
19      const opPath = `/${proc.path.split('.').join(options.pathSeparator)}`;
20      const method = proc.type === 'query' ? 'get' : 'post';
21  
22      const pathItem: PathItemObject = paths[opPath] ?? {};
23      paths[opPath] = pathItem;
24      pathItem[method] = buildProcedureOperation(
25        proc,
26        method,
27        refByProcedurePath.get(proc.path) ?? '#/components/responses/Error',
28      ) as PathItemObject[typeof method];
29    }
30  
31    const hasNamedSchemas = Object.keys(schemas).length > 0;
32  
33    return {
34      openapi: '3.1.1',
35      jsonSchemaDialect: 'https://spec.openapis.org/oas/3.1/dialect/base',
36      info: {
37        title: options.title ?? 'tRPC API',
38        version: options.version ?? '0.0.0',
39      },
40      ...(options.servers?.length ? { servers: options.servers } : {}),
41      paths,
42      components: {
43        ...(hasNamedSchemas ? { schemas } : {}),
44        responses: errorResponses,
45      },
46    };
47  }

