 1  function buildErrorResponses(
 2    procedures: ProcedureInfo[],
 3    routerErrorSchema: SchemaObject,
 4    schemas: Record<string, SchemaObject>,
 5  ): {
 6    responses: Record<string, ResponseObject>;
 7    refByProcedurePath: Map<string, string>;
 8  } {
 9    const responses: Record<string, ResponseObject> = {
10      Error: buildErrorResponse(routerErrorSchema),
11    };
12    const shapeKey = (schema: SchemaObject) =>
13      canonicalize(resolveBareRef(schema, schemas));
14    const refByShape = new Map<string, string>([
15      [shapeKey(routerErrorSchema), '#/components/responses/Error'],
16    ]);
17    const refByProcedurePath = new Map<string, string>();
18  
19    for (const proc of procedures) {
20      if (!proc.errorSchema) {
21        continue;
22      }
23  
24      const key = shapeKey(proc.errorSchema);
25      let ref = refByShape.get(key);
26      if (!ref) {
27        // A shape that already is a component needs no second name for it.
28        const name = `${pascalCasePath(proc.path) || 'Procedure'}Error`;
29        const shape = isBareRef(proc.errorSchema)
30          ? proc.errorSchema
31          : registerSchema(`${name}Shape`, proc.errorSchema, schemas);
32        const responseName = ensureUniqueName(name, responses);
33        responses[responseName] = buildErrorResponse(shape);
34        ref = `#/components/responses/${responseName}`;
35        refByShape.set(key, ref);
36      }
37      refByProcedurePath.set(proc.path, ref);
38    }
39  
40    return { responses, refByProcedurePath };
41  }

