30        {
31          name: 'input',
32          in: 'query',
33          required: true,
34          // FIXME: OAS 3.1.1 says a parameter MUST use either schema+style OR content, not both.
35          // style should be removed here, but hey-api requires it to generate a correct query serializer.
36          style: 'deepObject',
37          content: { 'application/json': { schema: proc.inputSchema } },
38        },
39      ];
40    } else {
41      operation.requestBody = {
42        required: true,
43        content: { 'application/json': { schema: proc.inputSchema } },
44      };
45    }
