 1  function getJsDocComment(
 2    sym: ts.Symbol,
 3    checker: ts.TypeChecker,
 4  ): string | undefined {
 5    const normalize = (filePath: string): string => filePath.replace(/\\/g, '/');
 6  
 7    const declarations = sym.declarations ?? [];
 8    const isExternalNodeModulesDeclaration =
 9      declarations.length > 0 &&
10      declarations.every((declaration) => {
11        const sourceFile = declaration.getSourceFile();
12        if (!sourceFile.isDeclarationFile) {
13          return false;
14        }
15  
16        const declarationPath = normalize(sourceFile.fileName);
17        if (!declarationPath.includes('/node_modules/')) {
18          return false;
19        }
20  
21        try {
22          const realPath = normalize(fs.realpathSync.native(sourceFile.fileName));
23          // Keep JSDoc for workspace packages linked into node_modules
24          // (e.g. monorepos using pnpm/yarn workspaces). The resolved target
25          // may sit outside the current cwd, so avoid cwd-based checks here.
26          if (!realPath.includes('/node_modules/')) {
27            return false;
28          }
29        } catch {
30          // Fall back to treating the declaration as external.
31        }
32  
33        return true;
34      });
35    if (isExternalNodeModulesDeclaration) {
36      return undefined;
37    }
38  
39    const parts = sym.getDocumentationComment(checker);
40    if (parts.length === 0) {
41      return undefined;
42    }
43    const text = parts.map((p) => p.text).join('');
44    return text || undefined;
45  }

