 1  function addsNothingToRouterErrorType(
 2    errorType: ts.Type,
 3    routerErrorType: ts.Type | null,
 4    checker: ts.TypeChecker,
 5  ): boolean {
 6    if (!routerErrorType) {
 7      return false;
 8    }
 9    if (errorType === routerErrorType) {
10      return true;
11    }
12  
13    const describe = (type: ts.Type) =>
14      checker.typeToString(
15        type,
16        undefined,
17        ts.TypeFormatFlags.NoTruncation |
18          ts.TypeFormatFlags.UseFullyQualifiedType,
19      );
20    const unionMembers = (type: ts.Type) =>
21      type.isUnion() ? type.types : [type];
22  
23    const routerMembers = new Set(unionMembers(routerErrorType).map(describe));
24  
25    return unionMembers(errorType).every((member) =>
26      routerMembers.has(describe(member)),
27    );
28  }

