25                  column.generatedType ?? "VIRTUAL"
26              }`
27          } else {
28              if (column.charset) c += ' CHARACTER SET "' + column.charset + '"'
29              if (column.collation) c += ' COLLATE "' + column.collation + '"'
30          }
31  
32          if (!column.isNullable) c += " NOT NULL"
33          if (
34              !column.isGenerated &&
35              column.default !== undefined &&
36              column.default !== null
37          )
38              c += " DEFAULT " + column.default
39  
40          return c
41      }

