 3    fixes: Map<string, LintCodeAction[]>,
 4    editor: Monaco.editor.IStandaloneCodeEditor,
 5  ): ErrorGroup[] {
 6    const result: Record<string, ErrorGroup> = {};
 7    for (const marker of markers) {
 8      const code = normalizeCode(marker.code);
 9      const uri = createURI(marker);
10  
11      const fixers =
12        fixes.get(uri)?.map(item => ({
13          fix(): void {
14            const model = editor.getModel();
15            if (model) {
16              editor.executeEdits('eslint', [createEditOperation(model, item)]);
17            }
18          },
19          isPreferred: item.isPreferred,
20          message: item.message,
21        })) ?? [];
22  
23      const group =
24        marker.owner === 'eslint'
25          ? code.value
26          : marker.owner === 'typescript'
27            ? 'TypeScript'
28            : marker.owner;
29  
30      // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
31      result[group] ||= {
32        group,
33        items: [],
34        uri: code.target,
35      };
36  
37      result[group].items.push({
38        fixer: fixers.find(item => item.isPreferred),
39        location: `${marker.startLineNumber}:${marker.startColumn} - ${marker.endLineNumber}:${marker.endColumn}`,
40        message:
41          (marker.owner !== 'eslint' && marker.owner !== 'json' && code.value
42            ? `${code.value}: `
43            : '') + marker.message,
44        severity: marker.severity,
45        suggestions: fixers.filter(item => !item.isPreferred),
46      });
47    }
48  
49    return Object.values(result).sort((a, b) => a.group.localeCompare(b.group));
50  }

