 1  export function describeFilePath(
 2    filePath: string,
 3    tsconfigRootDir: string,
 4  ): string {
 5    // If the TSConfig root dir is a parent of the filePath, use
 6    // `<tsconfigRootDir>` as a prefix for the path.
 7    const relative = path.relative(tsconfigRootDir, filePath);
 8    if (relative && !relative.startsWith('..') && !path.isAbsolute(relative)) {
 9      return `<tsconfigRootDir>/${relative}`;
10    }
11  
12    // Root-like Mac/Linux (~/*, ~*) or Windows (C:/*, /) paths that aren't
13    // relative to the TSConfig root dir should be fully described.
14    // This avoids strings like <tsconfigRootDir>/../../../../repo/file.ts.
15    // https://github.com/typescript-eslint/typescript-eslint/issues/6289
16    if (/^[(\w+:)\\/~]/.test(filePath)) {
17      return filePath;
18    }
19  
20    // Similarly, if the relative path would contain a lot of ../.., then
21    // ignore it and print the file path directly.
22    if (/\.\.[/\\]\.\./.test(relative)) {
23      return filePath;
24    }
25  
26    // Lastly, since we've eliminated all special cases, we know the cleanest
27    // path to print is probably the prefixed relative one.
28    return `<tsconfigRootDir>/${relative}`;
29  }

