 1  export function injectQuery(url: string, queryToInject: string): string {
 2    // skip urls that won't be handled by vite
 3    if (url[0] !== '.' && url[0] !== '/') {
 4      return url
 5    }
 6  
 7    // can't use pathname from URL since it may be relative like ../
 8    const pathname = url.replace(/[?#].*$/, '')
 9    const { search, hash } = new URL(url, 'http://vite.dev')
10  
11    return `${pathname}?${queryToInject}${search ? `&` + search.slice(1) : ''}${
12      hash || ''
13    }`
14  }

