 1  function waitForSuccessfulPing(socketUrl: string) {
 2    if (typeof SharedWorker === 'undefined') {
 3      const visibilityManager: VisibilityManager = {
 4        currentState: document.visibilityState,
 5        listeners: new Set(),
 6      }
 7      const onVisibilityChange = () => {
 8        visibilityManager.currentState = document.visibilityState
 9        for (const listener of visibilityManager.listeners) {
10          listener(visibilityManager.currentState)
11        }
12      }
13      document.addEventListener('visibilitychange', onVisibilityChange)
14      return waitForSuccessfulPingInternal(socketUrl, visibilityManager)
15    }
16  
17    // needs to be inlined to
18    //   - load the worker after the server is closed
19    //   - make it work with backend integrations
20    const blob = new Blob(
21      [
22        '"use strict";',
23        `const waitForSuccessfulPingInternal = ${waitForSuccessfulPingInternal.toString()};`,
24        `const fn = ${pingWorkerContentMain.toString()};`,
25        `fn(${JSON.stringify(socketUrl)})`,
26      ],
27      { type: 'application/javascript' },
28    )
29    const objURL = URL.createObjectURL(blob)
30    const sharedWorker = new SharedWorker(objURL)
31    return new Promise<void>((resolve, reject) => {
32      const onVisibilityChange = () => {
33        sharedWorker.port.postMessage({ visibility: document.visibilityState })
34      }
35      document.addEventListener('visibilitychange', onVisibilityChange)
36  
37      sharedWorker.port.addEventListener('message', (event) => {
38        document.removeEventListener('visibilitychange', onVisibilityChange)
39        sharedWorker.port.close()
40  
41        const data: { type: 'success' } | { type: 'error'; error: Error } =
42          event.data
43        if (data.type === 'error') {
44          reject(data.error)
45          return
46        }
47        resolve()
48      })
49  
50      onVisibilityChange()
51      sharedWorker.port.start()
52    })
53  }

