 1  export function serveRawFsMiddleware(
 2    server: ViteDevServer,
 3  ): Connect.NextHandleFunction {
 4    const serveFromRoot = sirv(
 5      '/',
 6      sirvOptions({
 7        config: server.config,
 8        getHeaders: () => server.config.server.headers,
 9      }),
10    )
11  
12    // Keep the named function. The name is visible in debug logs via `DEBUG=connect:dispatcher ...`
13    return function viteServeRawFsMiddleware(req, res, next) {
14      // In some cases (e.g. linked monorepos) files outside of root will
15      // reference assets that are also out of served root. In such cases
16      // the paths are rewritten to `/@fs/` prefixed paths and must be served by
17      // searching based from fs root.
18      if (req.url!.startsWith(FS_PREFIX)) {
19        const url = new URL(req.url!, 'http://example.com')
20        const pathname = decodeURIIfPossible(url.pathname)
21        if (pathname === undefined) {
22          return next()
23        }
24  
25        let newPathname = pathname.slice(FS_PREFIX.length)
26        if (isWindows) newPathname = newPathname.replace(/^[A-Z]:/i, '')
27        url.pathname = encodeURI(newPathname)
28        req.url = url.href.slice(url.origin.length)
29  
30        try {
31          serveFromRoot(req, res, next)
32        } catch (e) {
33          if (e && 'code' in e && e.code === ERR_DENIED_FILE) {
34            respondWithAccessDenied(e.path, server, res)
35            return
36          }
37          throw e
38        }
39      } else {
40        next()
41      }
42    }
43  }

