 1  export function applyStaticAlias(
 2    pathname: string,
 3    aliases: Alias[],
 4  ): string | undefined {
 5    for (const { find, replacement } of aliases) {
 6      const matches =
 7        typeof find === 'string'
 8          ? pathname === find || pathname.startsWith(`${find}/`)
 9          : find.test(pathname)
10      if (matches) {
11        if (typeof find === 'string') {
12          return replacement + pathname.slice(find.length)
13        }
14        return pathname.replace(find, replacement)
15      }
16    }
17  }

