 1  export function servePublicMiddleware(
 2    server: ViteDevServer,
 3    publicFiles?: Set<string>,
 4  ): Connect.NextHandleFunction {
 5    const dir = server.config.publicDir
 6    const serve = sirv(
 7      dir,
 8      sirvOptions({
 9        config: server.config,
10        getHeaders: () => server.config.server.headers,
11        disableFsServeCheck: true,
12      }),
13    )
14  
15    const toFilePath = (url: string) => {
16      let filePath = cleanUrl(url)
17      if (filePath.includes('%')) {
18        try {
19          filePath = decodeURI(filePath)
20        } catch {
21          /* malform uri */
22        }
23      }
24      return normalizePath(filePath)
25    }
26  
27    // Keep the named function. The name is visible in debug logs via `DEBUG=connect:dispatcher ...`
28    return function viteServePublicMiddleware(req, res, next) {
29      // To avoid the performance impact of `existsSync` on every request, we check against an
30      // in-memory set of known public files. This set is updated on restarts.
31      // also skip import request and internal requests `/@fs/ /@vite-client` etc...
32      if (
33        (publicFiles && !publicFiles.has(toFilePath(req.url!))) ||
34        isImportRequest(req.url!) ||
35        isInternalRequest(req.url!) ||
36        // for `/public-file.js?url` to be transformed
37        urlRE.test(req.url!)
38      ) {
39        return next()
40      }
41      serve(req, res, next)
42    }
43  }

