 1  export function perEnvironmentState<State>(
 2    initial: (environment: Environment) => State,
 3  ): (context: PluginContext) => State {
 4    const stateMap = new WeakMap<Environment, State>()
 5    return function (context: PluginContext) {
 6      const { environment } = context
 7      if (!stateMap.has(environment)) {
 8        stateMap.set(environment, initial(environment))
 9      }
10      return stateMap.get(environment)!
11    }
12  }

