 2    node: Directive | Statement,
 3  ): ImportBindings | undefined {
 4    if (node.type === 'ImportDeclaration') {
 5      return {
 6        id: node.source.value,
 7        bindings: node.specifiers.map((s) =>
 8          s.type === 'ImportDefaultSpecifier'
 9            ? 'default'
10            : s.type === 'ImportNamespaceSpecifier'
11              ? '*'
12              : stringifyModuleExportName(s.imported),
13        ),
14        locals: node.specifiers.map((s) => s.local.name),
15      }
16    }
17    if (node.type === 'ExportNamedDeclaration') {
18      if (!node.source) return undefined
19      return {
20        id: node.source.value,
21        bindings: node.specifiers.map((s) => stringifyModuleExportName(s.local)),
22        locals: [],
23      }
24    }
25    if (node.type === 'ExportAllDeclaration') {
26      if (!node.source) return undefined
27      return { id: node.source.value, bindings: ['*'], locals: [] }
28    }
29  }

