 1  function extractWorkerTypeFromAst(
 2    expression: ESTree.Expression,
 3    optsStartIndex: number,
 4  ): 'classic' | 'module' | undefined {
 5    if (expression.type !== 'ObjectExpression') {
 6      return
 7    }
 8  
 9    let lastSpreadElementIndex = -1
10    let typeProperty = null
11    let typePropertyIndex = -1
12  
13    for (let i = 0; i < expression.properties.length; i++) {
14      const property = expression.properties[i]
15  
16      if (property.type === 'SpreadElement') {
17        lastSpreadElementIndex = i
18        continue
19      }
20  
21      if (
22        property.type === 'Property' &&
23        ((property.key.type === 'Identifier' && property.key.name === 'type') ||
24          (property.key.type === 'Literal' && property.key.value === 'type'))
25      ) {
26        typeProperty = property
27        typePropertyIndex = i
28      }
29    }
30  
31    if (typePropertyIndex === -1 && lastSpreadElementIndex === -1) {
32      // No type property or spread element in use. Assume safe usage and default to classic
33      return 'classic'
34    }
35  
36    if (typePropertyIndex < lastSpreadElementIndex) {
37      throw err(
38        'Expected object spread to be used before the definition of the type property. ' +
39          'Vite needs a static value for the type property to correctly infer it.',
40        optsStartIndex,
41      )
42    }
43  
44    if (typeProperty?.value.type !== 'Literal') {
45      throw err(
46        'Expected worker options type property to be a literal value.',
47        optsStartIndex,
48      )
49    }
50  
51    // Silently default to classic type like the getWorkerType method
52    return typeProperty?.value.value === 'module' ? 'module' : 'classic'
53  }

