 1    getLiveAssetFileNames(
 2      rootBundleId: BundleId,
 3      rootLiveModuleIds: Set<string>,
 4    ): Set<string> {
 5      const liveBundles = new Set<string>()
 6      const queue: [BundleId, Set<string>][] = [[rootBundleId, rootLiveModuleIds]]
 7      while (queue.length > 0) {
 8        const [bundleId, moduleIds] = queue.shift()!
 9        const referencesByModule = this.bundleReferences.get(bundleId)
10        if (!referencesByModule) continue
11        for (const moduleId of moduleIds) {
12          const childBundleIds = referencesByModule.get(moduleId)
13          if (!childBundleIds) continue
14          for (const childBundleId of childBundleIds) {
15            if (liveBundles.has(childBundleId)) continue
16            liveBundles.add(childBundleId)
17            const childBundle = this.bundles.get(childBundleId)
18            if (childBundle) {
19              queue.push([childBundleId, childBundle.moduleIds])
20            }
21          }
22        }
23      }
24  
25      const liveFileNames = new Set<string>()
26      for (const inputId of liveBundles) {
27        const wb = this.bundles.get(inputId)
28        if (!wb) continue
29        liveFileNames.add(wb.entryFilename)
30        for (const fileName of wb.referencedAssets) {
31          liveFileNames.add(fileName)
32        }
33      }
34      return liveFileNames
35    }

