 1  export function classifyImportRef(
 2    ref: ConfigImportRef,
 3    resolvedId: string | null,
 4    file: string,
 5  ): NativeConfigIncompatibility | undefined {
 6    const { specifier, line, column } = ref
 7    const base = { file, line, column, specifier }
 8  
 9    if (specifier.endsWith('.json')) {
10      if (!ref.hasTypeJsonAttribute) {
11        return { type: 'json-without-attributes', ...base }
12      }
13      if (ref.namedImportLoc) {
14        return {
15          type: 'json-named-import',
16          file,
17          line: ref.namedImportLoc.line,
18          column: ref.namedImportLoc.column,
19          specifier,
20        }
21      }
22      return undefined
23    }
24  
25    if (!resolvedId) return undefined
26  
27    if (resolvedId.endsWith('.json')) {
28      if (!ref.hasTypeJsonAttribute) {
29        return { type: 'json-without-attributes', ...base }
30      }
31      if (ref.namedImportLoc) {
32        return {
33          type: 'json-named-import',
34          file,
35          line: ref.namedImportLoc.line,
36          column: ref.namedImportLoc.column,
37          specifier,
38        }
39      }
40    }
41  
42    const lastSegment = lastSegmentOf(specifier)
43    const specifierNamesIndex =
44      lastSegment === 'index' || indexFileRE.test(lastSegment)
45  
46    if (indexFileRE.test(path.basename(resolvedId)) && !specifierNamesIndex) {
47      return { type: 'directory-index-import', ...base }
48    }
49    if (!jsTsExtRE.test(lastSegment)) {
50      return { type: 'extensionless-import', ...base }
51    }
52    return undefined
53  }

