 1  export function setClientErrorHandler(
 2    server: HttpServer,
 3    logger: Logger,
 4  ): void {
 5    server.on('clientError', (err, socket) => {
 6      // https://github.com/nodejs/node/blob/v26.2.0/lib/_http_server.js#L992
 7      let msg
 8      switch ((err as any).code) {
 9        case 'HPE_HEADER_OVERFLOW': {
10          msg = '431 Request Header Fields Too Large'
11          logger.warn(
12            colors.yellow(
13              'Server responded with status code 431. ' +
14                'See https://vite.dev/guide/troubleshooting.html#_431-request-header-fields-too-large.',
15            ),
16          )
17          break
18        }
19        case 'HPE_CHUNK_EXTENSIONS_OVERFLOW': {
20          msg = '413 Payload Too Large'
21          break
22        }
23        case 'ERR_HTTP_REQUEST_TIMEOUT': {
24          msg = '408 Request Timeout'
25          break
26        }
27        default: {
28          msg = '400 Bad Request'
29          break
30        }
31      }
32      if ((err as any).code === 'ECONNRESET' || !socket.writable) {
33        return
34      }
35      socket.end(`HTTP/1.1 ${msg}\r\nConnection: close\r\n\r\n`)
36    })
37  }

