 1  async function tryBindServer(
 2    httpServer: HttpServer,
 3    port: number,
 4    host: string | undefined,
 5  ): Promise<
 6    { success: true } | { success: false; error: NodeJS.ErrnoException }
 7  > {
 8    return new Promise((resolve) => {
 9      const onError = (e: NodeJS.ErrnoException) => {
10        httpServer.off('error', onError)
11        httpServer.off('listening', onListening)
12        resolve({ success: false, error: e })
13      }
14      const onListening = () => {
15        httpServer.off('error', onError)
16        httpServer.off('listening', onListening)
17        resolve({ success: true })
18      }
19  
20      httpServer.on('error', onError)
21      httpServer.on('listening', onListening)
22  
23      httpServer.listen(port, host)
24    })
25  }

