 1  async function getAvailableEphemeralPort(
 2    specifiedHost: string | undefined,
 3  ): Promise<number | null> {
 4    for (let attempt = 0; attempt < 3; attempt++) {
 5      // Passing 0 asks the OS for a new candidate on every attempt.
 6      // We assume that the OS will return a different candidate on every attempt,
 7      // which does not always hold true, but it should be fine for most cases.
 8      let port = 0
 9      let available = true
10      for (const host of [...wildcardHosts, specifiedHost]) {
11        // Gracefully handle errors (e.g., IPv6 disabled on the system)
12        const availablePort = await tryListen(port, host).catch(() => port)
13        if (availablePort == null) {
14          available = false
15          break
16        }
17        port = availablePort
18      }
19      if (available) return port
20    }
21    return null
22  }

