 1  async function _shouldExternalize(
 2    id: string,
 3    options?: ExternalizeOptions,
 4  ): Promise<string | false | undefined> {
 5    if (isBuiltin(id)) {
 6      return id
 7    }
 8  
 9    // data: should be processed by native import,
10    // since it is a feature of ESM.
11    // also externalize network imports since nodejs allows it when --experimental-network-imports
12    if (id.startsWith('data:') || /^(?:https?:)?\/\//.test(id)) {
13      return id
14    }
15  
16    const moduleDirectories = options?.moduleDirectories || ['/node_modules/']
17  
18    if (matchPattern(id, moduleDirectories, options?.inline)) {
19      return false
20    }
21    if (options?.inlineFiles && options?.inlineFiles.includes(id)) {
22      return false
23    }
24    if (matchPattern(id, moduleDirectories, options?.external)) {
25      return id
26    }
27  
28    // Unless the user explicitly opted to inline them, externalize Vite deps.
29    // They are too big to inline by default.
30    if (options?.cacheDir && id.includes(options.cacheDir)) {
31      return id
32    }
33  
34    const isLibraryModule = moduleDirectories.some((dir) => id.includes(dir))
35    const guessCJS = isLibraryModule && options?.fallbackCJS
36    id = guessCJS ? guessCJSversion(id) || id : id
37  
38    if (matchPattern(id, moduleDirectories, defaultInline)) {
39      return false
40    }
41    if (matchPattern(id, moduleDirectories, depsExternal)) {
42      return id
43    }
44  
45    if (isLibraryModule && (await isValidNodeImport(id))) {
46      return id
47    }
48  }

