 1  export async function detectModuleType(
 2    file: string | null,
 3    code: string,
 4    loadSource?: () => Promise<string | null>,
 5  ): Promise<ModuleType> {
 6    if (file) {
 7      const filepath = cleanUrl(file)
 8      const extension = extname(filepath)
 9      if (extension === '.cjs' || extension === '.cts') {
10        return 'cjs'
11      }
12      if (extension === '.mjs' || extension === '.mts') {
13        return 'esm'
14      }
15      const scopeType = lookupPackageScopeType(dirname(filepath))
16      if (scopeType !== 'none') {
17        return scopeType
18      }
19    }
20    if (!ESM_SYNTAX_MARKERS.some((marker) => code.includes(marker))) {
21      return 'cjs'
22    }
23    // a false "esm" verdict can only break modules that reference the CommonJS
24    // variables, so the source is read and lexed only when both signals appear
25    if (!CJS_GLOBALS_REFERENCE_RE.test(code)) {
26      return 'esm'
27    }
28    const source = loadSource ? await loadSource() : null
29    if (source != null) {
30      try {
31        await esModuleLexer.init
32        const [, , , hasModuleSyntax] = esModuleLexer.parse(source)
33        if (!hasModuleSyntax) {
34          return 'cjs'
35        }
36      } catch {
37        // the lexer cannot parse TypeScript types or non-JS sources,
38        // trust the markers
39      }
40    }
41    return 'esm'
42  }

