 1  async function isValidNodeImport(id: string) {
 2    // clean url to strip off `?v=...` query etc.
 3    // node can natively import files with query params, so externalizing them is safe.
 4    id = cleanUrl(id)
 5  
 6    const extension = extname(id)
 7  
 8    if (BUILTIN_EXTENSIONS.has(extension)) {
 9      return true
10    }
11  
12    if (extension !== '.js') {
13      return false
14    }
15  
16    id = id.replace('file:///', '')
17  
18    if (lookupPackageScopeType(dirname(id)) === 'esm') {
19      return true
20    }
21  
22    if (/\.(?:\w+-)?esm?(?:-\w+)?\.js$|\/esm?\//.test(id)) {
23      return false
24    }
25  
26    try {
27      await esModuleLexer.init
28      const code = await fsp.readFile(id, 'utf8')
29      const [, , , hasModuleSyntax] = esModuleLexer.parse(code)
30      return !hasModuleSyntax
31    } catch {
32      return false
33    }
34  }

