15  
16        const currentExecution = this.executionStack.pop()
17  
18        if (currentExecution == null) {
19          throw new Error('Execution stack is empty, this should never happen')
20        }
21  
22        const selfTime = duration - currentExecution.subImportTime
23  
24        if (this.executionStack.length > 0) {
