 1  async function takeSnapshot(serializedLocator?: SerializedLocator): Promise<BrowserTraceSnapshot> {
 2    const { snapshot, createMirror } = await getOrchestratorState().loadBrowserTraceDomSnapshot!()
 3    const traceView = getBrowserState().config.browser.traceView
 4    const engine = getBrowserState().selectorEngine!
 5    const mirror = createMirror()
 6    const serialized = snapshot(document, {
 7      mirror,
 8      inlineImages: traceView.inlineImages,
 9      recordCanvas: traceView.recordCanvas,
10    })
11    const result: BrowserTraceSnapshot = {
12      serialized,
13      viewport: {
14        width: window.innerWidth,
15        height: window.innerHeight,
16      },
17      scroll: {
18        x: window.scrollX,
19        y: window.scrollY,
20      },
21      pseudoClassIds: {},
22    }
23    if (traceView.ariaSnapshot) {
24      const { generateAriaTree, renderAriaTree } = getBrowserState().aria
25      result.ariaSnapshot = renderAriaTree(generateAriaTree(document.body))
26    }
27    for (const className of PSEUDO_CLASS_NAMES) {
28      const elements = document.querySelectorAll(className)
29      const ids = Array.from(elements, (el) => mirror.getId(el)).filter((id) => id !== -1)
30      result.pseudoClassIds[className] = ids
31    }
32    if (serializedLocator) {
33      try {
34        const elements = engine.querySelectorAll(
35          engine.parseSelector(serializedLocator._pwSelector ?? serializedLocator.selector),
36          document.documentElement,
37        )
38        const ids = elements.map((el) => mirror.getId(el)).filter((id) => id !== -1)
39        if (ids.length > 0) {
40          result.selectorIds = ids
41          result.selectorResolution = 'matched'
42        } else {
43          result.selectorResolution = 'missing'
44        }
45      } catch (error) {
46        result.selectorResolution = 'error'
47        result.selectorError = error instanceof Error ? error.message : String(error)
48      }
49    }
50    return result
51  }

