 1  export async function recordBrowserTraceEntry(
 2    task: Task,
 3    options: Omit<BrowserTraceEntry, 'snapshot' | 'startTime'>,
 4  ): Promise<void> {
 5    // An un-awaited action can settle after its attempt ended.
 6    const attemptInfo = getBrowserState().browserTraceAttempts.get(task.id)
 7    if (!attemptInfo) {
 8      return
 9    }
10    const relativeStartTime = now() - attemptInfo.startTime
11    const failureOnly = getBrowserState().config.browser.traceView.mode === 'failure-only'
12    // in 'failure-only', only the end of a failed test is snapshotted and sent,
13    // so passing tests stay free and their entries are dropped with the attempt
14    const isFailedTestEnd = options.kind === 'lifecycle' && options.status === 'fail'
15    const shouldSnapshot = failureOnly ? isFailedTestEnd : true
16    const entry: BrowserTraceEntry = {
17      ...options,
18      startTime: relativeStartTime,
19      ...(shouldSnapshot ? { snapshot: await takeSnapshot(options.element) } : {}),
20    }
21    if (!failureOnly) {
22      await sendBrowserTraceEntries(task, attemptInfo, [entry])
23      return
24    }
25    const entries = (attemptInfo.entries ??= [])
26    entries.push(entry)
27    if (isFailedTestEnd) {
28      await sendBrowserTraceEntries(task, attemptInfo, entries)
29    }
30  }

