 1    private findAffectedInProject(
 2      project: TestProject,
 3      specs: TestSpecification[],
 4      related: string[],
 5    ): TestSpecification[] {
 6      if (
 7        dependsOnConfig(project.vite.config.configFileDependencies, related) ||
 8        dependsOnConfig(getEnvFiles(project), related)
 9      ) {
10        return specs
11      }
12  
13      const dependencies = this.vitest.cache._dependencies.get(project)
14      if (!dependencies) {
15        return specs
16      }
17  
18      const changed = new Set<number>()
19      for (const file of related) {
20        const index = dependencies.moduleIndex.get(file)
21        if (index !== undefined) {
22          changed.add(index)
23        }
24      }
25      if (project.config.globalSetup.length) {
26        const globalSetup = dependencies.globalSetup
27        if (!globalSetup || globalSetup.deps.some((index) => changed.has(index))) {
28          return specs
29        }
30      }
31  
32      const root = this.vitest.config.root
33      return specs.filter((spec) => {
34        const record = dependencies.files.get(getRootRelativePath(root, spec.moduleId))
35        return !record || record.deps.some((index) => changed.has(index))
36      })
37    }

