 1    async getDependencies(): Promise<ModuleDependency[]> {
 2      await this.vitest.cache._dependencies.read()
 3      const root = this.vitest.config.root
 4      const recordedAt = new Map<string, number | undefined>()
 5      const add = (dependencies: ProjectDependencies, record: DependencyRecord) => {
 6        for (const index of record.deps) {
 7          const file = dependencies.modules[index]
 8          const previous = recordedAt.get(file)
 9          if (!recordedAt.has(file) || (previous !== undefined && record.at < previous)) {
10            recordedAt.set(file, record.at)
11          }
12        }
13      }
14      for (const [project, specs] of this.specsByProject) {
15        const dependencies = this.vitest.cache._dependencies.get(project)
16        if (dependencies?.config) {
17          add(dependencies, dependencies.config)
18        }
19        if (dependencies?.globalSetup) {
20          add(dependencies, dependencies.globalSetup)
21        }
22        for (const spec of specs) {
23          const record = dependencies?.files.get(getRootRelativePath(root, spec.moduleId))
24          if (record && dependencies) {
25            add(dependencies, record)
26          } else if (!recordedAt.has(spec.moduleId)) {
27            // a test file without a record has no known time, so it always runs
28            recordedAt.set(spec.moduleId, undefined)
29          }
30        }
31      }
32      return Array.from(recordedAt, ([file, at]) => ({ file, recordedAt: at }))
33    }

