 1  function findFile(mockFolder: string, baseOriginal: string): string | null {
 2    const files = readdirSync(mockFolder)
 3    for (const file of files) {
 4      const baseFile = basename(file, extname(file))
 5      if (baseFile === baseOriginal) {
 6        const path = resolve(mockFolder, file)
 7        // if the same name, return the file
 8        if (statSync(path).isFile()) {
 9          return path
10        } else {
11          // find folder/index.{js,ts}
12          const indexFile = findFile(path, 'index')
13          if (indexFile) {
14            return indexFile
15          }
16        }
17      }
18    }
19    return null
20  }

