 1  export function resolveTokenFromPath(tokenPath: string): { token: string; tokenCreated: boolean } {
 2    const published = readPublishedToken(tokenPath)
 3    if (published) {
 4      return { token: published, tokenCreated: false }
 5    }
 6  
 7    const dir = dirname(tokenPath)
 8    mkdirSync(dir, { recursive: true, mode: 0o700 })
 9  
10    const token = crypto.randomUUID()
11    const pendingPath = join(dir, `${API_TOKEN_FILE}.${process.pid}.${crypto.randomUUID()}`)
12    writeFileSync(pendingPath, `${token}\n`, { mode: 0o600 })
13  
14    let tokenCreated = true
15    try {
16      // linking fails when another process already published, which keeps a single winner
17      linkSync(pendingPath, tokenPath)
18    } catch (error) {
19      if ((error as NodeJS.ErrnoException).code === 'EEXIST') {
20        tokenCreated = false
21      } else {
22        renameSync(pendingPath, tokenPath)
23      }
24    } finally {
25      rmSync(pendingPath, { force: true })
26    }
27  
28    const winner = readPublishedToken(tokenPath)
29    if (!tokenCreated && !winner) {
30      writeFileSync(tokenPath, `${token}\n`, { mode: 0o600 })
31      tokenCreated = true
32    }
33  
34    try {
35      chmodSync(dir, 0o700)
36      chmodSync(tokenPath, 0o600)
37    } catch {}
38    return { token: (tokenCreated ? token : winner) ?? token, tokenCreated }
39  }

