 1  function deepEqual(a: any, b: any): boolean {
 2    if (a === b) {
 3      return true
 4    }
 5    if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) {
 6      return false
 7    }
 8  
 9    const keysA = Object.keys(a)
10    const keysB = Object.keys(b)
11    if (keysA.length !== keysB.length) {
12      return false
13    }
14  
15    for (const key of keysA) {
16      if (!Object.hasOwn(b, key) || !deepEqual(a[key], b[key])) {
17        return false
18      }
19    }
20    return true
21  }

