 1  export function lookupPackageScopeType(directory: string): 'cjs' | 'esm' | 'none' {
 2    const visited: string[] = []
 3    let result: 'cjs' | 'esm' | 'none' = 'none'
 4    let current = directory
 5    while (current) {
 6      const cached = packageScopeTypeCache.get(current)
 7      if (cached) {
 8        result = cached
 9        break
10      }
11      if (basename(current) === 'node_modules') {
12        break
13      }
14      visited.push(current)
15      const packageJsonPath = join(current, 'package.json')
16      if (tryStatSync(packageJsonPath)?.isFile()) {
17        try {
18          const packageJson = JSON.parse(stripBomTag(fs.readFileSync(packageJsonPath, 'utf8')))
19          if (packageJson.type === 'module') {
20            result = 'esm'
21          } else if (packageJson.type === 'commonjs') {
22            result = 'cjs'
23          }
24        } catch {
25          // ignore malformed package.json and fall back to "none"
26        }
27        break
28      }
29  
30      const parent = dirname(current)
31      if (parent === current) {
32        break
33      }
34      current = parent
35    }
36  
37    visited.forEach((dir) => packageScopeTypeCache.set(dir, result))
38    return result
39  }

