 1  function raceWith<A, B>(
 2    promise: Promise<A>,
 3    other?: Promise<B>,
 4  ): Promise<{ ok: true; value: A } | { ok: false; value: B }> {
 5    const left = promise.then((value) => ({ ok: true as const, value }))
 6    if (!other) {
 7      return left
 8    }
 9    return Promise.race([left, other.then((value) => ({ ok: false as const, value }))])
10  }

