 9      // happens because browsers fire microtask ticks between event propagation.
10      // this no longer happens for templates in Vue 3, but could still be
11      // theoretically possible for hand-written render functions.
12      // the solution: we save the timestamp when a handler is attached,
13      // and also attach the timestamp to any event that was handled by vue
14      // for the first time (to avoid inconsistent event timestamp implementations
15      // or events fired from iframes, e.g. #2513)
16      // The handler would only fire if the event passed to it was fired
17      // AFTER it was attached.
18      if (!e._vts) {
19        e._vts = Date.now()
20      } else if (e._vts <= invoker.attached) {
21        return
22      }
23      const value = invoker.value
24      if (isArray(value)) {
25        const originalStop = e.stopImmediatePropagation
