27          originalStop.call(e)
28          ;(e as any)._stopped = true
29        }
30        const handlers = value.slice()
31        const args = [e]
32        for (let i = 0; i < handlers.length; i++) {
33          if ((e as any)._stopped) {
34            break
35          }
36          const handler = handlers[i]
37          if (handler) {
38            callWithAsyncErrorHandling(
39              handler,
40              instance,
41              ErrorCodes.NATIVE_EVENT_HANDLER,
42              args,
43            )
44          }
45        }
46      } else {
47        callWithAsyncErrorHandling(
48          value,
49          instance,
50          ErrorCodes.NATIVE_EVENT_HANDLER,
51          [e],
52        )
53      }
54    }
55    invoker.value = initialValue
56    invoker.attached = getNow()
57    return invoker
58  }

