 1  	void ThreadWorker(object? _)
 2  	{
 3  		// Fire the loop approximately every 1/10th of our delay time, but no more frequently than every
 4  		// second (so we don't over-fire the timer). This should give us reasonable precision for the
 5  		// requested delay time, without going crazy to check for long-running tests.
 6  
 7  		var delayTime = (int)Math.Max(1000, options.LongRunningTestTime.TotalMilliseconds / 10);
 8  
 9  		while (true)
10  		{
11  			if (WaitForStopEvent(delayTime))
12  			{
13  				workerFinished?.SafeSet();
14  				return;
15  			}
16  
17  			var now = UtcNow;
18  			if (now - lastTestActivity >= options.LongRunningTestTime)
19  			{
20  				SendLongRunningMessage();
21  				lastTestActivity = now;
22  			}
23  		}
24  	}

