 1  	void SendLongRunningMessage()
 2  	{
 3  		if (executingTestCases is null)
 4  			return;
 5  
 6  		Dictionary<ITestCaseMetadata, TimeSpan> longRunningTestCases;
 7  		lock (executingTestCases)
 8  		{
 9  			var now = UtcNow;
10  			longRunningTestCases =
11  				executingTestCases
12  					.Where(kvp => (now - kvp.Value.StartTime) >= options.LongRunningTestTime)
13  					.ToDictionary(kvp => kvp.Value.TestCaseMetadata, kvp => now - kvp.Value.StartTime);
14  		}
15  
16  		if (longRunningTestCases.Count > 0)
17  		{
18  			if (options.LongRunningTestCallback is not null)
19  				options.LongRunningTestCallback(new LongRunningTestsSummary(options.LongRunningTestTime, longRunningTestCases));
20  
21  			options.DiagnosticMessageSink?.OnMessage(
22  				new DiagnosticMessage(
23  					string.Join(
24  						Environment.NewLine,
25  						longRunningTestCases.Select(pair => string.Format(CultureInfo.CurrentCulture, @"[Long Running Test] '{0}', Elapsed: {1:hh\:mm\:ss}", pair.Key.TestCaseDisplayName, pair.Value))
26  					)
27  				)
28  			);
29  		}
30  	}

