 2  		this Task task,
 3  		int milliseconds)
 4  	{
 5  		var spin = default(SpinWait);
 6  		var stopwatch = Stopwatch.StartNew();
 7  
 8  		while (true)
 9  		{
10  			if (task.IsCompleted)
11  				return true;
12  
13  			if (stopwatch.ElapsedMilliseconds > milliseconds)
14  				return false;
15  
16  			spin.SpinOnce();
17  		}
18  	}

