29  
30  		var foreachAwait = theoryDataInfo.IsAsyncEnumerable ? "await " : "";
31  		var dataRowAwait = theoryDataInfo.IsAsync ? "await " : "";
32  		var asyncClassDataInit =
33  			classDataType.ImplementsInterface(Types.Xunit.IAsyncLifetime)
34  				? "await ((global::Xunit.IAsyncLifetime)classData).InitializeAsync();\n\t"
35  				: string.Empty;
36  
37  		result.Factories.Add(new($$"""
38  			async disposalTracker => {
39  				var attr = {{dataAttributeRegistration}};
40  				var dataRows = new global::System.Collections.Generic.List<global::Xunit.ITheoryDataRow>();
41  				var classData = new {{classDataType.ToCSharp()}}();
