 1  export function fromJSONSchema(schema: JSONSchema.JSONSchema | boolean, params?: FromJSONSchemaParams): ZodType {
 2    // Handle boolean schemas
 3    if (typeof schema === "boolean") {
 4      return schema ? z.any() : z.never();
 5    }
 6  
 7    // Normalize input via a JSON round-trip. This guarantees the converter walks a plain, finite, JSON-valid object graph: cyclic inputs fail here, getter/Proxy-based properties are materialized into static values, and class instances collapse to plain objects.
 8    let normalized: JSONSchema.JSONSchema;
 9    try {
10      normalized = JSON.parse(JSON.stringify(schema));
11    } catch {
12      throw new Error("fromJSONSchema input is not valid JSON (possibly cyclic); use $defs/$ref for recursive schemas");
13    }
14  
15    const version = detectVersion(normalized, params?.defaultTarget);
16    const defs = (normalized.$defs || normalized.definitions || {}) as Record<string, JSONSchema.JSONSchema>;
17  
18    const ctx: ConversionContext = {
19      version,
20      defs,
21      refs: new Map(),
22      processing: new Set(),
23      rootSchema: normalized,
24      registry: params?.registry ?? globalRegistry,
25    };
26  
27    return convertSchema(normalized, ctx);
28  }

