 1  function canonicalKey(value: unknown, seen: Set<object>): string | null {
 2    if (value === null) return "z";
 3    const type = typeof value;
 4    if (type !== "object") {
 5      if (type === "number" && Number.isNaN(value)) return null;
 6      const raw = String(value);
 7      return `${type[0]}${raw.length}:${raw}`;
 8    }
 9    if (seen.has(value as object)) return null;
10    seen.add(value as object);
11    try {
12      if (Array.isArray(value)) {
13        const parts: string[] = [];
14        for (const item of value) {
15          const key = canonicalKey(item, seen);
16          if (key === null) return null;
17          parts.push(key);
18        }
19        return `a${parts.length}:[${parts.join(",")}]`;
20      }
21      const keys = Object.keys(value as object).sort();
22      const parts: string[] = [];
23      for (const k of keys) {
24        const key = canonicalKey((value as any)[k], seen);
25        if (key === null) return null;
26        parts.push(`${k.length}:${k}=${key}`);
27      }
28      return `o${parts.length}:{${parts.join(",")}}`;
29    } finally {
30      seen.delete(value as object);
31    }
32  }

