 1  function checkObjectGuards(
 2    objectSchema: ZodType,
 3    guards: { keySchema?: ZodType | undefined; minProperties?: number | undefined; maxProperties?: number | undefined }
 4  ): ZodType {
 5    // An identity transform, not z.any(), so `toJSONSchema` reports the object on both the input and the output side of the pipe.
 6    const guard = z
 7      .transform((value: unknown) => value)
 8      .check((payload) => {
 9        const value = payload.value;
