11        const keys = Object.getOwnPropertyNames(value);
12        if (guards.minProperties !== undefined && keys.length < guards.minProperties) {
13          payload.issues.push({
14            origin: "object",
15            code: "too_small",
16            minimum: guards.minProperties,
17            inclusive: true,
18            message: `Too small: expected object to have >=${guards.minProperties} properties`,
19            input: value,
20            inst: objectSchema,
21            continue: true,
22          });
23        }
24        if (guards.maxProperties !== undefined && keys.length > guards.maxProperties) {
25          payload.issues.push({
26            origin: "object",
27            code: "too_big",
28            maximum: guards.maxProperties,
29            inclusive: true,
30            message: `Too big: expected object to have <=${guards.maxProperties} properties`,
31            input: value,
32            inst: objectSchema,
33            continue: true,
34          });
35        }
36        if (guards.keySchema) {
37          for (const key of keys) {
38            const result = guards.keySchema.safeParse(key);
39            if (result.success) continue;
40            payload.issues.push({
41              code: "invalid_key",
42              origin: "record",
43              issues: result.error.issues,
44              input: key,
45              path: [key],
46              continue: true,
47            });
48          }
49        }
50      });
51    return guard.pipe(objectSchema);
52  }

