 3    for (const kind of ["issues", "prs"] as const) {
 4      const dir = path.join(outDir, kind);
 5      if (!fs.existsSync(dir)) continue;
 6      for (const entry of fs.readdirSync(dir)) {
 7        const file = path.join(dir, entry, "results.md");
 8        if (!fs.existsSync(file)) continue;
 9        const fm = fs.readFileSync(file, "utf8").split(/^---\s*$/m)[1] ?? "";
10        map.set(`${kind === "issues" ? "issue" : "pr"}:${entry}`, {
11          verdict: /^verdict:\s*(.+)$/m.exec(fm)?.[1].trim() ?? "—",
12          status: /^status:\s*(.+)$/m.exec(fm)?.[1].trim() ?? "—",
13        });
14      }
15    }
16    return map;
17  }

