 1  function findClusters(items: Scored[], threshold = 0.5): Scored[][] {
 2    const toks = items.map((i) => titleTokens(i.title));
 3    const parent = items.map((_, i) => i);
 4    const find = (x: number): number => {
 5      while (parent[x] !== x) {
 6        parent[x] = parent[parent[x]];
 7        x = parent[x];
 8      }
 9      return x;
10    };
11    for (let i = 0; i < items.length; i++) {
12      for (let j = i + 1; j < items.length; j++) {
13        if (jaccard(toks[i], toks[j]) >= threshold) parent[find(i)] = find(j);
14      }
15    }
16    const groups = new Map<number, Scored[]>();
17    for (let i = 0; i < items.length; i++) {
18      const root = find(i);
19      if (!groups.has(root)) groups.set(root, []);
20      groups.get(root)!.push(items[i]);
21    }
22    return [...groups.values()]
23      .filter((g) => g.length > 1)
24      .map((g) => g.sort((a, b) => b.score - a.score))
25      .sort((a, b) => b.length - a.length || b[0].score - a[0].score);
26  }

