 1  function score(item: Item, now: number): Scored {
 2    // Each channel is log-compressed independently so a single 200-comment thread can't outrank broad, quiet demand — and reactions stay the dominant term.
 3    const voices = Math.max(0, item.participants - 1);
 4    const discussion = item.comments + (item.reviews ?? 0);
 5    const engagement =
 6      W.upvote * Math.log1p(item.upvotes) +
 7      W.softReaction * Math.log1p(item.softReactions) +
 8      W.voice * Math.log1p(voices) +
 9      W.comment * Math.log1p(discussion);
10  
11    const monthsIdle = (now - Date.parse(item.updatedAt)) / MS_PER_MONTH;
12    const decay = DECAY_FLOOR + (1 - DECAY_FLOOR) * 0.5 ** (monthsIdle / DECAY_HALF_LIFE_MONTHS);
13  
14    let penalty = 1;
15    if (item.isDraft) penalty *= PENALTY.draft;
16    if (item.authorIsBot) penalty *= PENALTY.bot;
17    for (const l of item.labels) {
18      const p = (PENALTY as Record<string, number>)[l];
19      if (p !== undefined) penalty *= p;
20    }
21  
22    const vuln = detectVuln(item);
23    const bonus = vuln.level === "confirmed" ? SECURITY_BONUS : vuln.level === "possible" ? SECURITY_MAYBE_BONUS : 0;
24  
25    const baseScore = engagement * decay * penalty;
26    return { ...item, engagement, decay, penalty, vuln, baseScore, score: baseScore + bonus };
27  }

