 1  function detectVuln(item: Item): VulnVerdict {
 2    const confirmed: string[] = [];
 3    for (const l of item.labels) {
 4      if (VULN_LABEL.test(l)) confirmed.push(`label:${l}`);
 5    }
 6    // Only the leading slice of the body is scanned. Full bodies drag in stack traces and quoted source that trip every keyword.
 7    const title = item.title;
 8    const body = item.body.slice(0, 3000);
 9    const hay = `${title}\n${body}`;
10  
11    for (const [re, name] of VULN_STRONG) {
12      if (re.test(hay)) confirmed.push(name);
13    }
14  
15    const inTitle: string[] = [];
16    const inBody: string[] = [];
17    for (const [re, name] of VULN_CONTEXTUAL) {
18      if (re.test(title)) inTitle.push(name);
19      else if (re.test(body)) inBody.push(name);
20    }
21    confirmed.push(...inTitle);
22    // Two different contextual terms in one body is a report, not a passing mention.
23    if (inBody.length >= 2) confirmed.push(...inBody);
24  
25    if (confirmed.length) return { level: "confirmed", reasons: dedupe(confirmed) };
26  
27    const weak = [...inBody];
28    for (const [re, name] of VULN_WEAK) {
29      if (re.test(hay)) weak.push(name);
30    }
31    if (weak.length) return { level: "possible", reasons: dedupe(weak) };
32    return { level: "none", reasons: [] };
33  }

