15          // Accessor pairs defined per-instance are distinct function objects.
16          perInstance = dB && (d.get !== dB.get || d.set !== dB.set) ? "YES" : "no";
17        } else {
18          const v = d.value;
19          kind = typeof v === "function" ? "function" : Array.isArray(v) ? `array[${v.length}]` : typeof v;
20          perInstance = dB && typeof v === "object" && v !== null ? (v !== dB.value ? "YES" : "no") : "";
21          if (typeof v === "function") perInstance = dB && v !== dB.value ? "YES" : "no";
22        }
23        report.push({ where, key: String(key), kind, perInstance });
24      }
25    }
26  
27    const closures = report.filter(
28      (r) => (r.kind === "function" || r.kind.startsWith("accessor")) && r.perInstance === "YES"
29    );
30    const objects = report.filter((r) => r.kind === "object" && r.perInstance === "YES");
