 1      string JoinOrdinalScaleCount(long count, SouthSlavicScale scale, string ordinal)
 2      {
 3          var prefixes = scale.OrdinalCountPrefixes.Split('|');
 4          var onePrefix = prefixes[0];
 5          var twoPrefix = prefixes.Length > 1 ? prefixes[1] : string.Empty;
 6          if (count == 2 && twoPrefix.Length > 0)
 7          {
 8              return twoPrefix + ordinal;
 9          }
10  
11          var countWords = ConvertPositive((ulong)count, scale.Gender);
12          var terminalPrefix = (count % 10) switch
13          {
14              1 when count % 100 != 11 => onePrefix,
15              2 when count % 100 != 12 => twoPrefix,
16              _ => string.Empty
17          };
18          var lastSpace = countWords.LastIndexOf(' ');
19          if (terminalPrefix.Length > 0 && lastSpace >= 0)
20          {
21              countWords = countWords[..(lastSpace + 1)] + terminalPrefix;
22          }
23  
24          return countWords.Replace(" ", "") + ordinal;
25      }

