14          {
15              return formattedDate.Substring(0, dayStart) + renderedDay + formattedDate.Substring(markerIndex + DayMarker.Length);
16          }
17  #else
18          if (dayStart >= 0 && formattedDate.AsSpan(dayStart, dayText.Length).SequenceEqual(dayText.AsSpan()))
19          {
20              return string.Concat(formattedDate.AsSpan(0, dayStart), renderedDay.AsSpan(), formattedDate.AsSpan(markerIndex + DayMarker.Length));
21          }
22  #endif
23  
24          // Fallback: just replace the marker.
