 7  
 8              // Skip whitespace and common date-pattern punctuation (e.g., "25. MMMM", "25, MMMM").
 9              if (c is ' ' or '.' or ',' or '-' or '/')
10              {
11                  i += backward ? -1 : 1;
12                  continue;
13              }
14  
15              if (c == '\'')
16              {
17                  // Skip through quoted literal.
18                  i += backward ? -1 : 1;
19                  while (backward ? i >= 0 : i < formatString.Length)
20                  {
21                      if (formatString[i] == '\'')
22                      {
23                          i += backward ? -1 : 1;
24                          break;
25                      }
26  
27                      i += backward ? -1 : 1;
28                  }
29  
30                  continue;
31              }
32  
33              if (c == 'd')
34              {
35                  // Count consecutive 'd' characters to distinguish d/dd (day-of-month)
36                  // from ddd/dddd (day-of-week).
37                  var dCount = 1;
38                  var probe = i + (backward ? -1 : 1);
39                  while ((backward ? probe >= 0 : probe < formatString.Length) && formatString[probe] == 'd')
40                  {
41                      dCount++;
42                      probe += backward ? -1 : 1;
43                  }
44  
45                  // d or dd = day-of-month (genitive context), ddd+ = day-of-week (not genitive).
46                  return dCount <= 2;
47              }
48  
49              break;
50          }
51  
52          return false;
53      }

