 1      static (BigInteger Numerator, BigInteger Denominator) LimitDenominator(
 2          BigInteger numerator,
 3          BigInteger denominator,
 4          int maxDenominator)
 5      {
 6          var originalNumerator = numerator;
 7          var originalDenominator = denominator;
 8          BigInteger previousNumerator = 0;
 9          BigInteger previousDenominator = 1;
10          BigInteger currentNumerator = 1;
11          BigInteger currentDenominator = 0;
12  
13          while (!denominator.IsZero)
14          {
15              var quotient = numerator / denominator;
16              var nextDenominator = previousDenominator + quotient * currentDenominator;
17              if (nextDenominator > maxDenominator)
18                  break;
19  
20              (previousNumerator, currentNumerator) =
21                  (currentNumerator, previousNumerator + quotient * currentNumerator);
22              (previousDenominator, currentDenominator) = (currentDenominator, nextDenominator);
23              (numerator, denominator) = (denominator, numerator - quotient * denominator);
24          }
25  
26          if (denominator.IsZero)
27              return (currentNumerator, currentDenominator);
28  
29          var multiplier = (maxDenominator - previousDenominator) / currentDenominator;
30          var first = (
31              previousNumerator + multiplier * currentNumerator,
32              previousDenominator + multiplier * currentDenominator);
33          var second = (currentNumerator, currentDenominator);
34  
35          var firstError = BigInteger.Abs(
36              first.Item1 * originalDenominator - originalNumerator * first.Item2);
37          var secondError = BigInteger.Abs(
38              second.Item1 * originalDenominator - originalNumerator * second.Item2);
39          var comparison = (firstError * second.Item2).CompareTo(secondError * first.Item2);
40  
41          if (comparison != 0)
42              return comparison < 0 ? first : second;
43  
44          if (first.Item2 != second.Item2)
45              return first.Item2 < second.Item2 ? first : second;
46  
47          return first.Item1 > second.Item1 ? first : second;
48      }

