 1      static (BigInteger Numerator, BigInteger Denominator) ToFraction(decimal value)
 2      {
 3          var bits = decimal.GetBits(value);
 4          var numerator =
 5              (BigInteger)(uint)bits[0] |
 6              (BigInteger)(uint)bits[1] << 32 |
 7              (BigInteger)(uint)bits[2] << 64;
 8          var denominator = BigInteger.Pow(10, (bits[3] >> 16) & 0x7F);
 9          var divisor = BigInteger.GreatestCommonDivisor(numerator, denominator);
10  
11          if (bits[3] < 0)
12              numerator = -numerator;
13  
14          return (numerator / divisor, denominator / divisor);
15      }

