16          if (result.All(c => c is ' ' or '&' || char.IsUpper(c)) && result.Contains(' '))
17          {
18              result = result.ToLower();
19          }
20  
21          if (result.Length > 0 && result[0] == '&')
22          {
23              var firstWordIndex = 1;
