 1      public string Humanize<T>(IEnumerable<T> collection, Func<T, string?> objectFormatter, string separator)
 2      {
 3          ArgumentNullException.ThrowIfNull(collection);
 4          ArgumentNullException.ThrowIfNull(objectFormatter);
 5  
 6          StringBuilder? head = null;
 7          string? lastItem = null;
 8          var count = 0;
 9  
10          foreach (var item in collection)
11          {
12              var formatted = objectFormatter(item)?.Trim();
13              if (string.IsNullOrWhiteSpace(formatted))
14              {
15                  continue;
16              }
17  
18              if (count == 0)
19              {
20                  // Hold the first visible item separately so the 0- and 1-item paths stay allocation-free.
21                  lastItem = formatted;
22                  count = 1;
23                  continue;
24              }
25  
26              if (count == 1)
27              {
28                  // Once we have two visible items, build the comma-separated head and keep the tail isolated.
29                  head = new StringBuilder(lastItem);
30                  lastItem = formatted;
31                  count = 2;
32                  continue;
33              }
34  
35              // The penultimate item belongs in the comma-separated head; the last item stays separate so the
36              // locale-specific conjunction can decide whether it needs to cliticize the previous word.
37              head!.Append(", ");
38              head.Append(lastItem);
39              lastItem = formatted;
40              count++;
41          }
42  
43          return count switch
44          {
45              0 => string.Empty,
46              1 => lastItem!,
47              _ => string.Concat(head, " ", separator, lastItem)
48          };
49      }

