 1      string ApplyDayPeriod(string basePhrase, int hour, bool usesNextHour)
 2      {
 3          if (profile.EarlyMorning.Length == 0 && profile.Morning.Length == 0 &&
 4              profile.Afternoon.Length == 0 && profile.Evening.Length == 0 && profile.Night.Length == 0)
 5          {
 6              return basePhrase;
 7          }
 8  
 9          // For relative-hour style locales (ca, es), templates that reference {nextHour}
10          // mean the phrasing is relative to the next hour (e.g., "twenty to five"),
11          // so the day period should be based on the next hour's time slot.
12          // For locales that say "current hour + minutes" (ar, fa, ku), the period
13          // must always reflect the current hour.
14          var periodHour = usesNextHour ? hour + 1 : hour;
15          var period = GetDayPeriod(periodHour);
16          if (period.Length == 0)
17          {
18              return basePhrase;
19          }
20  
21          return profile.DayPeriodPosition == PhraseClockDayPeriodPosition.Prefix
22              ? period + " " + basePhrase
23              : basePhrase + " " + period;
24      }

