 1      static string ExtractNextWordResolvingPlaceholders(
 2          string template, int startIndex,
 3          string article, string nextArticle, string minuteSuffix, string dayPeriod)
 4      {
 5          var i = startIndex;
 6          while (i < template.Length)
 7          {
 8              // Skip spaces.
 9              while (i < template.Length && template[i] == ' ')
10              {
11                  i++;
12              }
13  
14              if (i >= template.Length)
15              {
16                  return "";
17              }
18  
19              if (template[i] == '{')
20              {
21                  var closeBrace = template.IndexOf('}', i);
22                  if (closeBrace < 0)
23                  {
24                      return "";
25                  }
26  
27                  var name = template.AsSpan(i + 1, closeBrace - i - 1);
28  
29                  // Resolve non-number placeholders to get their first word.
30                  var resolved = ResolveNonNumberPlaceholder(name, article, nextArticle, minuteSuffix, dayPeriod);
31                  if (resolved.Length > 0)
32                  {
33                      // Return the first word of the resolved value.
34                      var spaceIdx = resolved.IndexOf(' ');
35                      return spaceIdx >= 0 ? resolved[..spaceIdx] : resolved;
36                  }
37  
38                  // Skip number placeholders and continue looking.
39                  i = closeBrace + 1;
40                  continue;
41              }
42  
43              // Extract the literal word until space or placeholder.
44              var wordStart = i;
45              while (i < template.Length && template[i] != ' ' && template[i] != '{')
46              {
47                  i++;
48              }
49  
50              return template[wordStart..i];
51          }
52  
53          return "";
54      }

