 1      ReadOnlySpan<char> ApplyEifelerToValue(
 2          string value, string template, int afterIndex,
 3          string article, string nextArticle, string minuteSuffix, string dayPeriod)
 4      {
 5          if (!profile.ApplyEifelerRule || value.Length == 0)
 6          {
 7              return value;
 8          }
 9  
10          var nextWord = ExtractNextWordResolvingPlaceholders(template, afterIndex, article, nextArticle, minuteSuffix, dayPeriod);
11          if (nextWord.Length == 0)
12          {
13              return value;
14          }
15  
16          // Apply the Eifeler rule to the last word of the resolved number value.
17          var lastSpace = value.LastIndexOf(' ');
18          if (lastSpace >= 0)
19          {
20              var lastWord = value[(lastSpace + 1)..];
21              var eifeled = EifelerRule.ApplyIfNeeded(lastWord, nextWord);
22              if (ReferenceEquals(eifeled, lastWord))
23              {
24                  return value;
25              }
26  
27              return string.Concat(value.AsSpan(0, lastSpace + 1), eifeled);
28          }
29  
30          return EifelerRule.ApplyIfNeeded(value, nextWord);
31      }

