12          if (placeholder == TemplatePlaceholder.NextArticle)
13          {
14              return nextArticle;
15          }
16  
17          if (placeholder == TemplatePlaceholder.MinuteSuffix)
18          {
19              return minuteSuffix;
20          }
21  
22          if (placeholder == TemplatePlaceholder.DayPeriod)
23          {
24              return dayPeriod;
25          }
26  
27          // Number placeholders: apply Eifeler rule when enabled.
28          string value;
29          if (placeholder == TemplatePlaceholder.Hour)
30          {
31              value = hour;
32          }
33          else if (placeholder == TemplatePlaceholder.NextHour)
34          {
35              value = nextHour;
36          }
