 1      string ExpandTemplate(string template, int hour, int normalizedMinutes, string minuteSuffix)
 2      {
 3          var plan = GetTemplatePlan(template);
 4          var hourWords = plan.UsesHour ? ResolveHourExpression(hour) : "";
 5          var nextHourWords = plan.UsesNextHour ? ResolveHourExpression(hour + 1) : "";
 6          var minuteWords = plan.UsesMinutes ? ResolveMinuteExpression(normalizedMinutes) : "";
 7          var reverseMinuteWords = plan.UsesMinutesReverse && normalizedMinutes > 0 ? ResolveMinuteWords(60 - normalizedMinutes) : "";
 8          var halfMinuteWords = plan.UsesMinutesFromHalf ? ResolveHalfMinuteWords(normalizedMinutes) : "";
 9          var article = plan.UsesArticle ? ResolveArticle(hour) : "";
10          var nextArticle = plan.UsesNextArticle ? ResolveArticle(hour + 1) : "";
11          var dayPeriod = plan.UsesDayPeriod ? GetDayPeriod(hour) : "";
12  
13          // Single-pass expansion: scan the template once, resolve placeholders inline,
14          // skip double spaces, and trim — producing only the final return string.
15          var maxLen = plan.LiteralLength
16              + hourWords.Length + nextHourWords.Length + minuteWords.Length
17              + reverseMinuteWords.Length + halfMinuteWords.Length
18              + article.Length + nextArticle.Length + minuteSuffix.Length + dayPeriod.Length;
19  
20          Span<char> buf = stackalloc char[maxLen];
21          var pos = 0;
22          foreach (var segment in plan.Segments)
23          {
24              if (segment.Literal is not null)
25              {
26                  AppendString(buf, ref pos, segment.Literal);
27              }
28              else
29              {
30                  var replacement = ResolveTemplatePlaceholder(
31                      segment.Placeholder, template, segment.AfterIndex,
32                      hourWords, nextHourWords, minuteWords, reverseMinuteWords, halfMinuteWords,
33                      article, nextArticle, minuteSuffix, dayPeriod);
34  
35                  replacement.CopyTo(buf[pos..]);
36                  pos += replacement.Length;
37              }
38          }
39  
40          // Trim leading/trailing spaces from the result span.
41          var result = buf[..pos];
42          result = result.Trim();
43          return new string(result);
44      }

