 1      static List<string> TableBody(string dialect, SchemaTable table, bool asCreated = false)
 2      {
 3          List<string> body = table.Columns
 4              .Where(c => !asCreated || c.AddedBy is null)
 5              .Select(c => $"{c.Name} {c.Definition[dialect]}".TrimEnd())
 6              .ToList();
 7  
 8          body.Add($"{PrimaryKeyName(dialect, table)}PRIMARY KEY ({string.Join(",", table.PrimaryKey)})");
 9  
10          if (ForeignKeyOn(dialect, table) is { } foreignKey)
11          {
12              string name = ForeignKeyName(dialect, table, foreignKey);
13              string cascade = foreignKey.Cascade && dialect is "sqlServer" or "postgres" or "sqlite"
14                  ? " ON DELETE CASCADE"
15                  : "";
16  
17              body.Add($"{name}FOREIGN KEY ({string.Join(",", foreignKey.Columns)}) "
18                       + $"REFERENCES {{0}}{foreignKey.ReferencedTable} ({string.Join(",", foreignKey.ReferencedColumns)}){cascade}");
19          }
20  
21          if (dialect == "mysql_innodb")
22          {
23              body.AddRange(AllSchemaIndexes(dialect)
24                  .Where(i => IndexTable(i) == table.Name && (!asCreated || i.AddedBy is null))
25                  .Select(i => $"KEY IDX_{{1}}{IndexSuffix(i)} ({TightColumns(i.Columns)})"));
26          }
27  
28          return body;
29      }

