 1      static List<(string Path, string Content)> BuildSchemaScripts()
 2      {
 3          List<(string, string)> files = [];
 4  
 5          foreach (string dialect in Dialects)
 6          {
 7              List<string> statements = [SchemaHeader(dialect)];
 8  
 9              foreach (SchemaTable table in SchemaTables)
10              {
11                  statements.Add($"-- {{0}}{table.Name}\n" + CreateTableIfMissing(dialect, table));
12              }
13  
14              if (dialect == "sqlite")
15              {
16                  foreach ((string trigger, string child) in SqliteDeleteTriggers)
17                  {
18                      statements.Add($"-- {{0}}{trigger}\n" + CreateSqliteDeleteTrigger(trigger, child));
19                  }
20              }
21  
22              // MySQL declares its indexes inside CREATE TABLE, so it has none to add here. See
23              // TableBody for why.
24              foreach (IndexDef index in SchemaIndexes(dialect))
25              {
26                  statements.Add($"-- IDX_{{1}}{IndexSuffix(index)}\n" + CreateIndexIfMissing(dialect, index));
27              }
28  
29              files.Add(($"create_{dialect}.sql",
30                  string.Join($"\n{StatementSeparator}\n", statements)));
31          }
32  
33          return files;
34      }

