 1      public async Task<(SchemaSnapshot Schema, List<string> Details)> ReadAsync(string prefix = "QRTZ_")
 2      {
 3          await using FbConnection connection = new(ConnectionString);
 4          await connection.OpenAsync();
 5  
 6          SchemaSnapshot snapshot = await SchemaSnapshot.ReadAsync(connection, "firebird", prefix);
 7  
 8          List<string> details = [];
 9  
10          await using (FbCommand columns = new(ColumnsSql, connection))
11          {
12              columns.Parameters.Add("@prefix", prefix);
13              await using FbDataReader reader = await columns.ExecuteReaderAsync();
14              while (await reader.ReadAsync())
15              {
16                  object[] cells = new object[reader.FieldCount];
17                  reader.GetValues(cells);
18                  string defaultSource = cells[^1] is string text ? NormalizeDefault(text) : "";
19                  details.Add("COL " + string.Join("|", cells[..^1].Select(Text)) + "|" + defaultSource);
20              }
21          }
22  
23          Dictionary<string, List<(int Position, string Column)>> segments = new(StringComparer.Ordinal);
24          await using (FbCommand indexes = new(IndexesSql, connection))
25          {
26              indexes.Parameters.Add("@prefix", prefix);
27              await using FbDataReader reader = await indexes.ExecuteReaderAsync();
28              while (await reader.ReadAsync())
29              {
30                  string key = string.Join("|", Enumerable.Range(0, 10).Select(i => Text(reader.GetValue(i))));
31                  if (!segments.TryGetValue(key, out List<(int, string)>? list))
32                  {
33                      segments[key] = list = [];
34                  }
35  
36                  list.Add((Convert.ToInt32(reader.GetValue(10), CultureInfo.InvariantCulture), Text(reader.GetValue(11))));
37              }
38          }
39  
40          details.AddRange(segments.Select(x => "IX " + x.Key + "|" + string.Join(",", x.Value.OrderBy(s => s.Position).Select(s => s.Column))));
41          details.Sort(StringComparer.Ordinal);
42  
43          return (snapshot, details);
44      }

