 9          {
10              case NodeNone:
11                  requested = PreferredNode.None;
12                  break;
13              case NodeAuto:
14                  requested = PreferredNode.Auto;
15                  break;
16              case NodeNamed:
17                  try
18                  {
19                      requested = PreferredNode.For(PreferredNodeName);
