25                  }
26  
27                  break;
28              default:
29                  errors.Add("Preferred node: '" + mode + "' is not a choice.");
30                  return;
31          }
32  
33          // An automatic pin a node has claimed is still the automatic pin, so leaving the choice on auto is
34          // leaving it alone rather than asking for the claim to be released.
35          bool unchanged = mode == currentMode
36              && (mode != NodeNamed || string.Equals(requested.Node, current.Node, StringComparison.Ordinal));
37          if (unchanged)
38          {
39              return;
40          }
41  
42          update.WithPreferredNode(requested);
43          changes.Add(Changed("preferred node", Describe(current), Describe(requested)));
