 6  
 7          TriggerQuery query = new() { Group = matcher, State = TriggerState.Error, Take = PagedQuery.All };
 8          PagedResult<TriggerHeader> failed = await QueryTriggers(query, cancellationToken).ConfigureAwait(false);
 9          if (failed.Items.Count == 0)
