 1      public static async ValueTask<WindowLiveness> Read(IScheduler scheduler, CancellationToken cancellationToken = default)
 2      {
 3          ArgumentNullException.ThrowIfNull(scheduler);
 4  
 5          List<ClusterNode> nodes = await scheduler.QueryClusterNodes(cancellationToken).ConfigureAwait(false);
 6  
 7          int live = 0;
 8          foreach (ClusterNode node in nodes)
 9          {
10              if (node.State != ClusterNodeState.Failed)
11              {
12                  live++;
13              }
14          }
15  
16          SchedulerStatus status = live > 0
17              ? SchedulerStatus.Running
18              : nodes.Count > 0
19                  ? SchedulerStatus.Shutdown
20                  : SchedulerStatus.Unknown;
21  
22          return new WindowLiveness(status, live, nodes.Count);
23      }

