 1      public virtual async ValueTask Execute(IJobExecutionContext context, CancellationToken cancellationToken = default)
 2      {
 3          JobDataMap data = context.MergedJobDataMap;
 4  
 5          SendMailOptions options = SendMailOptions.FromJobData(data);
 6          MailMessage message = BuildMessage(options);
 7  
 8          // Outside the try, so that a refusal to hand a credential to a host nobody vouched for reaches
 9          // the operator as itself rather than as "unable to send mail".
10          NetworkCredential? resolved = ResolveCredentials(data, options);
11  
12          try
13          {
14              var info = new MailInfo
15              {
16                  MailMessage = message,
17                  SmtpHost = options.SmtpHost,
18                  SmtpPort = options.SmtpPort,
19                  EnableSsl = options.EnableSsl,
20                  Credentials = resolved
21              };
22              await Send(info, cancellationToken).ConfigureAwait(false);
23          }
24          catch (Exception ex)
25          {
26              throw new JobExecutionException($"Unable to send mail: {GetMessageDescription(message)}", ex);
