 1      private static string? RoundTrip(SystemTextJsonObjectSerializer serializer, string name, object value)
 2      {
 3          try
 4          {
 5              byte[] written = serializer.Serialize(value);
 6              object? restored = Read(serializer, value, written);
 7  
 8              if (restored is null)
 9              {
10                  return $"FAIL {name}: came back as null.";
11              }
12  
13              byte[] rewritten = serializer.Serialize(restored);
14              if (!written.AsSpan().SequenceEqual(rewritten))
15              {
16                  return $"FAIL {name}: came back different.{Environment.NewLine}  wrote:   {Encoding.UTF8.GetString(written)}{Environment.NewLine}  rewrote: {Encoding.UTF8.GetString(rewritten)}";
17              }
18  
19              return null;
20          }
21          catch (Exception e)
22          {
23              return $"FAIL {name}: {e.GetType().FullName}: {e.Message}{Environment.NewLine}{e}";
24          }
25      }

