 1      private static string Line(List<Column> columns, Func<Column, double> y, List<Point> dots)
 2      {
 3          StringBuilder path = new();
 4          int runStart = 0;
 5  
 6          for (int i = 0; i <= columns.Count; i++)
 7          {
 8              bool broken = i == columns.Count || (i > 0 && columns[i].Slot != columns[i - 1].Slot + 1);
 9              if (!broken)
10              {
11                  continue;
12              }
13  
14              if (i - runStart == 1)
15              {
16                  dots.Add(new Point(columns[runStart].Centre, y(columns[runStart])));
17              }
18              else
19              {
20                  for (int j = runStart; j < i; j++)
21                  {
22                      path.Append(j == runStart ? 'M' : 'L').Append(Number(columns[j].Centre)).Append(',').Append(Number(y(columns[j])));
23                  }
24              }
25  
26              runStart = i;
27          }
28  
29          return path.ToString();
30      }

