 1      private static List<Segment> Segments(ExecutionStatisticsBucket bucket, double left, double width, long runsTop)
 2      {
 3          List<Segment> segments = [];
 4          double baseline = PlotTop + RunsPlotHeight;
 5          double bottom = baseline;
 6  
 7          foreach (JobRunResult result in StackOrder)
 8          {
 9              long count = bucket.CountOf(result);
10              if (count == 0)
11              {
12                  continue;
13              }
14  
15              double height = Math.Max(MinSegmentHeight, count / (double) runsTop * RunsPlotHeight);
16              segments.Add(new Segment(result, count, bottom - height, bottom));
17              bottom -= height;
18          }
19  
20          List<Segment> drawn = new(segments.Count);
21          for (int i = 0; i < segments.Count; i++)
22          {
23              Segment segment = segments[i];
24  
25              // The gap is taken from the segment above it, never from the baseline.
26              double lower = i > 0 && segment.Bottom - segment.Top > SegmentGap + 1 ? segment.Bottom - SegmentGap : segment.Bottom;
27              double radius = i == segments.Count - 1 ? Math.Min(CornerRadius, Math.Min(width / 2, lower - segment.Top)) : 0;
28  
29              drawn.Add(segment with { Bottom = lower, Path = RoundedTop(left, segment.Top, width, lower, radius) });
30          }
31  
32          return drawn;
33      }

