 1      internal static long NiceCeiling(long value)
 2      {
 3          if (value <= 1)
 4          {
 5              return 1;
 6          }
 7  
 8          long magnitude = 1;
 9          while (magnitude * 10 <= value)
10          {
11              magnitude *= 10;
12          }
13  
14          foreach (long multiple in NiceMultiples)
15          {
16              if (multiple * magnitude >= value)
17              {
18                  return multiple * magnitude;
19              }
20          }
21  
22          return 10 * magnitude;
23      }

