 4          for (int i = 0; i < args.Length;)
 5          {
 6              string name = args[i].StartsWith("--", StringComparison.Ordinal) ? args[i][2..] : "";
 7  
 8              if (Switches.Contains(name, StringComparer.Ordinal))
 9              {
10                  values[name] = "true";
11                  i++;
12                  continue;
13              }
14  
15              if (name.Length == 0 || i + 1 >= args.Length)
16              {
17                  throw new ArgumentException($"Expected '--name value' pairs or a switch, got '{args[i]}'.");
18              }
19  
20              values[name] = args[i + 1];
21              i += 2;
22          }
23  
24          string Required(string name) => values.TryGetValue(name, out string? value) && value.Length > 0
25              ? value
26              : throw new ArgumentException($"--{name} is required.");
27  
28          NodeOptions options = new()
29          {
30              InstanceId = Required("instance-id"),
31              SchedulerName = Required("scheduler-name"),
32              ConnectionString = Required("connection-string"),
33              TablePrefix = Required("table-prefix"),
34              RunsTable = Required("runs-table"),
35              LogLevel = values.TryGetValue("log-level", out string? level) ? Enum.Parse<LogLevel>(level, ignoreCase: true) : LogLevel.Warning,
36              History = values.ContainsKey("history"),
37              LockFreeRounds = !values.TryGetValue("lock-free", out string? lockFree) || bool.Parse(lockFree)
38          };
39  
40          // Both names are written into SQL text, so they are held to what an unquoted identifier may be.
41          foreach (string identifier in (string[]) [options.TablePrefix, options.RunsTable])
