 1      internal static bool IsRoutableDashboardPath(string? path)
 2      {
 3          if (string.IsNullOrWhiteSpace(path))
 4          {
 5              // the empty/whitespace case is reported by the "must start with '/'" validation
 6              return true;
 7          }
 8  
 9          string trimmed = path.Trim().Trim('/');
10          if (trimmed.Length == 0)
11          {
12              // normalizes to the default "/quartz"
13              return true;
14          }
15  
16          foreach (string segment in trimmed.Split('/'))
17          {
18              if (segment.Length == 0
19                  || segment == "."
20                  || segment == ".."
21                  || segment.IndexOfAny(InvalidDashboardPathChars) >= 0)
22              {
23                  return false;
24              }
25          }
26  
27          return true;
28      }

