 1      public ExecutionLimits Build()
 2      {
 3          ExecutionGroupPrefixAllowance[] ordered = new ExecutionGroupPrefixAllowance[prefixes.Count];
 4          int i = 0;
 5          foreach (KeyValuePair<string, ExecutionGroupAllowance> pair in prefixes)
 6          {
 7              ordered[i++] = new ExecutionGroupPrefixAllowance(pair.Key, pair.Value);
 8          }
 9  
10          // Longest first, so the first prefix a group starts with is the one that governs it. Ties cannot
11          // match the same group, so their order only has to be stable.
12          Array.Sort(ordered, static (left, right) =>
13          {
14              int byLength = right.Prefix.Length.CompareTo(left.Prefix.Length);
15              return byLength != 0 ? byLength : string.CompareOrdinal(left.Prefix, right.Prefix);
16          });
17  
18          return new ExecutionLimits(
19              new Dictionary<string, ExecutionGroupAllowance>(limits, StringComparer.Ordinal),
20              ordered,
21              useTriggerGroupWhenUnset);
22      }

