 1      private async ValueTask<bool> AcquireLockCore(
 2          Guid requestorId,
 3          string lockName,
 4          bool isDebugEnabled,
 5          CancellationToken cancellationToken)
 6      {
 7          if (isDebugEnabled)
 8          {
 9              logger.LockBeingObtained(lockName, requestorId);
10          }
11  
12          try
13          {
14              await globalLock.WaitAsync(cancellationToken).ConfigureAwait(false);
15          }
16          catch (OperationCanceledException)
17          {
18              // Reported as itself rather than answered with false. False is the store's word for "you
19              // already hold this, do not release it", so a cancelled wait dressed up as false would send
20              // the caller on to run its guarded operation with no lock at all - see the contract on
21              // ILockHandler.AcquireLock. The gate itself is untouched: a cancelled WaitAsync does not
22              // take the count it was cancelled out of, so currentOwner and lockCount stay as they were.
23              if (isDebugEnabled)
24              {
25                  logger.LockNotObtained(lockName, requestorId);
26              }
27  
28              throw;
29          }
30  
31          lock (syncRoot)
32          {
33              currentOwner = requestorId;
34              lockCount = 1;
35          }
36  
37          if (isDebugEnabled)
38          {
39              logger.LockGiven(lockName, requestorId);
40          }
41  
42          return true;
43      }

