 1          public HashSet<string> Groups(string prefix)
 2          {
 3              var seen = new HashSet<string>(StringComparer.Ordinal);
 4              var start = prefix + ".";
 5              foreach (var key in properties.AllKeys)
 6              {
 7                  if (key is null || !key.StartsWith(start, StringComparison.Ordinal))
 8                  {
 9                      continue;
10                  }
11  
12                  var remainder = key[start.Length..];
13                  var separator = remainder.IndexOf('.');
14                  var group = separator < 0 ? remainder : remainder[..separator];
15                  if (group.Length > 0)
16                  {
17                      seen.Add(group);
18                  }
19              }
20  
21              return seen;
22          }

