 1      private static void RegisterJobStore(
 2          IServiceCollection services,
 3          PropertyReader parser,
 4          string? schedulerName,
 5          bool persistent,
 6          Func<IServiceProvider, object?, IJobStore> build)
 7      {
 8          if (persistent)
 9          {
10              // A persistent store needs the same companions the code-first path registers; configuring it
11              // by properties must not leave it half-built.
12              var dataSourceName = parser.String("quartz.jobStore.dataSource") ?? "quartz";
13              RegisterConfigured<IDbProvider>(services, schedulerName, (provider, _) =>
14              {
15                  var dataSource = provider.GetRequiredService<IOptionsMonitor<DataSourceOptions>>().Get(dataSourceName);
16                  var connectionString = dataSource.ConnectionString;
17  
18                  if (string.IsNullOrWhiteSpace(connectionString) && !string.IsNullOrWhiteSpace(dataSource.ConnectionStringName))
19                  {
20                      connectionString = provider.GetService<IConfiguration>()?.GetConnectionString(dataSource.ConnectionStringName);
21                  }
22  
23                  if (string.IsNullOrWhiteSpace(connectionString))
24                  {
25                      Throw.SchedulerConfigException($"No connection string configured for data source '{dataSourceName}'.");
26                  }
27  
28                  var metadata = provider.GetRequiredService<DbMetadataResolver>().Resolve(dataSource.Provider);
29                  return new DbProvider(metadata, connectionString!);
30              });
31  
32              // The driver delegate and serializer fallbacks are registered with the rest of the defaults,
33              // after everything explicit, so a configured one is never beaten to the registration by the
34              // fallback it was meant to replace. There is deliberately no lock handler fallback either:
35              // left unregistered, the store chooses between database row locks and an in-process monitor
36              // itself, once it knows how it is clustered and which database it is talking to.
37          }
38  
39          RegisterConfigured(services, schedulerName, build);
40      }

