 1      private static void RegisterJobStore(
 2          IServiceCollection services,
 3          PropertyReader parser,
 4          string? schedulerName)
 5      {
 6          // The delegate and lock handler stand on their own: an application that has moved store
 7          // selection into code can still be naming its driver delegate in a configuration file, and
 8          // returning early on a missing quartz.jobStore.type would drop it.
 9          RegisterDriverDelegate(services, parser, schedulerName);
10  
11          RegisterConnectionProvider(services, parser, schedulerName);
12  
13          RegisterInitStringTriggerPersistenceDelegates(services, parser, schedulerName);
14  
15          RegisterLockHandler(services, parser, schedulerName);
16  
17          var configured = parser.String(LegacyPropertyKeys.JobStoreType);
18          if (configured is null)
19          {
20              return;
21          }
22  
23          if (TryMatchBuiltIn(configured, builtInJobStores, out Func<IServiceProvider, object?, IJobStore>? build))
24          {
25              RegisterJobStore(services, parser, schedulerName, persistent: false, build);
26              return;
27          }
28  
29          if (FeatureSwitches.IsLegacyComponentKeysSupported)
30          {
31              RegisterJobStoreByName(services, parser, schedulerName);
32              return;
33          }
34  
35          // A persistent store the application already chose in code, rather than a default an earlier
36          // registration filled in: the key would have lost the TryAdd to that registration, so it names what
37          // code named and is left at that. Nothing chosen in code means the key alone was to build the store,
38          // which this publish cannot do.
39          if (TryMatchBuiltIn(configured, shippedPersistentStores, out string? _)
40              && SchedulerParts.IsChosen(services, typeof(IJobStore), schedulerName))
41          {
42              return;
43          }
44  
45          Throw.SchedulerConfigException(LegacyPropertyKeys.ComponentKeyRefused(LegacyPropertyKeys.JobStoreType));
46      }

