 1      private static bool TryMatchBuiltIn<T>(string configured, (string Name, T Value)[] builtIn, [NotNullWhen(true)] out T? value)
 2          where T : class
 3      {
 4          List<string> candidates = [configured];
 5          candidates.AddRange(SimpleTypeLoader.LegacyNameCandidates(configured));
 6  
 7          foreach (string candidate in candidates)
 8          {
 9              string spelling = ObjectExtensions.WithoutAssemblyVersion(candidate).Trim();
10              if (!spelling.Contains(','))
11              {
12                  // Bare, as Type.GetType would have read it against the calling assembly - this one.
13                  spelling += ", Quartz";
14              }
15  
16              foreach ((string name, T builtInValue) in builtIn)
17              {
18                  if (string.Equals(name, spelling, StringComparison.OrdinalIgnoreCase))
19                  {
20                      value = builtInValue;
21                      return true;
22                  }
23              }
24          }
25  
26          value = null;
27          return false;
28      }

