 1          private static JsonConverter? FindConverter(Type type, JsonSerializerOptions options)
 2          {
 3              IList<JsonConverter> converters = options.Converters;
 4              for (int i = 0; i < converters.Count; i++)
 5              {
 6                  JsonConverter converter = converters[i];
 7                  if (!converter.CanConvert(type))
 8                  {
 9                      continue;
10                  }
11  
12                  // A factory is asked for the converter it would make; Quartz registers none, but an
13                  // application is free to, and handing the factory itself to CreateValueInfo would throw.
14                  return converter is JsonConverterFactory factory ? factory.CreateConverter(type, options) : converter;
15              }
16  
17              return null;
18          }

