 1      public static SchedulerRolesRequirement From(SchedulerRoles roles)
 2      {
 3          ArgumentNullException.ThrowIfNull(roles);
 4  
 5          string[] viewers = Checked(roles.Viewers, nameof(SchedulerRoles.Viewers));
 6          string[] operators = Checked(roles.Operators, nameof(SchedulerRoles.Operators));
 7          string[] administrators = Checked(roles.Administrators, nameof(SchedulerRoles.Administrators));
 8  
 9          if (viewers.Length + operators.Length + administrators.Length == 0)
10          {
11              throw new ArgumentException(
12                  "Name at least one role in Viewers, Operators or Administrators: a policy that grants nobody anything refuses every request, reads included.",
13                  nameof(roles));
14          }
15  
16          Dictionary<string, SchedulerAccess> operations = new(StringComparer.OrdinalIgnoreCase);
17          foreach ((string name, SchedulerAccess access) in roles.Operations)
18          {
19              WireRoute route = SchedulerRoutes.Find(name)
20                  ?? throw new ArgumentException($"Operations names '{name}', which is no operation of the HTTP API. The names are its operation ids: PauseJob, AddCalendar, Shutdown.", nameof(roles));
21  
22              if (!route.Mutates)
23              {
24                  throw new ArgumentException($"Operations names '{route.Name}', which is a read: every role may call it, so there is nothing to move.", nameof(roles));
25              }
26  
27              if (access is not (SchedulerAccess.Operate or SchedulerAccess.Administer))
28              {
29                  throw new ArgumentException($"Operations['{route.Name}'] is {access}; an operation that changes something needs Operate or Administer.", nameof(roles));
30              }
31  
32              operations[route.Name] = access;
33          }
34  
35          return new SchedulerRolesRequirement(viewers, operators, administrators, operations.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase));
36      }

