 1      public static void RegisterTheStoreOverARegisteredDataSource(IServiceCollection services)
 2      {
 3          #region sample_trimming_registered_data_source
 4  
 5          services.AddQuartz(q => q.UsePersistentStore(store =>
 6          {
 7              // What UseSqlite(db => db.UseRegisteredDataSource = true) registers, as the two calls it makes.
 8              // The data source hands over every connection, so only the type-free half of the driver
 9              // description is read and nothing is resolved from a string.
10              store.UseDriverDelegate<SQLiteDelegate>();
11              store.UseDataSource(db =>
12              {
13                  db.Provider = DataSourceOptions.Providers.Sqlite;
14                  db.UseRegisteredDataSource = true;
15              });
16          }));
17  
18          #endregion
19      }

